begin;
-- Candidate only: AC-309 / FR-335. Not applied. Published migrations are immutable.
-- Requisition save is deliberately separate from workflow submission/approval.
create table procurement.requisitions (
  id uuid primary key,
  tenant_id uuid not null references core.tenants(id),
  legal_entity_id uuid not null,
  branch_id uuid not null,
  requester_id uuid not null references auth.users(id),
  need_by date not null,
  justification text not null check (length(trim(justification)) between 1 and 4000),
  currency_code text not null references core.currencies(code),
  estimated_total numeric(20,6) not null check (estimated_total >= 0),
  status text not null default 'draft' check (status in ('draft','pending_approval','approved','rejected','cancelled')),
  version bigint not null default 1 check (version > 0),
  created_by uuid not null references auth.users(id),
  updated_by uuid not null references auth.users(id),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (tenant_id, legal_entity_id, id),
  foreign key (tenant_id, legal_entity_id) references core.legal_entities(tenant_id,id),
  foreign key (tenant_id, branch_id) references core.branches(tenant_id,id)
);
create table procurement.requisition_lines (
  id uuid primary key,
  tenant_id uuid not null,
  legal_entity_id uuid not null,
  requisition_id uuid not null,
  ordinal integer not null check (ordinal between 1 and 500),
  product_id uuid,
  description text not null check (length(trim(description)) between 1 and 1000),
  unit_id uuid not null,
  quantity numeric(20,6) not null check (quantity > 0),
  base_quantity numeric(20,6) not null check(base_quantity>0),
  conversion_numerator bigint not null check(conversion_numerator>0),
  conversion_denominator bigint not null check(conversion_denominator>0),
  conversion_id uuid,conversion_version bigint,
  estimated_unit_price numeric(20,6) not null check (estimated_unit_price >= 0),
  estimated_total numeric(20,6) not null check (estimated_total >= 0),
  unique (requisition_id,ordinal),
  foreign key (tenant_id,legal_entity_id,requisition_id)
    references procurement.requisitions(tenant_id,legal_entity_id,id),
  foreign key (tenant_id,legal_entity_id,product_id)
    references inventory.products(tenant_id,legal_entity_id,id),
  foreign key (tenant_id,unit_id) references inventory.units(tenant_id,id)
);
create index requisitions_scope_page on procurement.requisitions(tenant_id,legal_entity_id,branch_id,id);
create index requisitions_requester on procurement.requisitions(requester_id);
create index requisitions_branch on procurement.requisitions(tenant_id,branch_id);
create index requisition_lines_source on procurement.requisition_lines(tenant_id,legal_entity_id,requisition_id);
create index requisition_lines_product on procurement.requisition_lines(tenant_id,legal_entity_id,product_id);
create index requisition_lines_unit on procurement.requisition_lines(tenant_id,unit_id);
alter table procurement.requisitions enable row level security;
alter table procurement.requisitions force row level security;
alter table procurement.requisition_lines enable row level security;
alter table procurement.requisition_lines force row level security;
create policy requisitions_read on procurement.requisitions for select to authenticated
using (core.has_permission(tenant_id,'procurement.requisitions.manage',legal_entity_id,branch_id));
create policy requisition_lines_read on procurement.requisition_lines for select to authenticated
using (exists (select 1 from procurement.requisitions r where r.id=requisition_id
  and r.tenant_id=requisition_lines.tenant_id and r.legal_entity_id=requisition_lines.legal_entity_id));
revoke all on procurement.requisitions,procurement.requisition_lines from public,anon,authenticated;
grant usage on schema procurement to authenticated;
grant select on procurement.requisitions,procurement.requisition_lines to authenticated;

create view api.purchase_requisitions with (security_invoker=true) as
select r.tenant_id,r.legal_entity_id,r.branch_id,r.id,r.status,
  jsonb_build_object('id',r.id,'requester_id',r.requester_id,'need_by',r.need_by,
    'justification',r.justification,'currency_code',r.currency_code,
    'estimated_total',r.estimated_total::text,'status',r.status,'version',r.version,
    'lines',coalesce((select jsonb_agg(jsonb_build_object(
      'line_id',l.id,'product_id',l.product_id,'description',l.description,
      'unit_id',l.unit_id,'quantity',l.quantity::text,
      'estimated_unit_price',l.estimated_unit_price::text,
      'estimated_total',l.estimated_total::text,
      'base_quantity',l.base_quantity::text,'conversion_numerator',l.conversion_numerator::text,
      'conversion_denominator',l.conversion_denominator::text,'conversion_id',l.conversion_id,'conversion_version',l.conversion_version) order by l.ordinal)
      from procurement.requisition_lines l where l.requisition_id=r.id),'[]'::jsonb)) detail
from procurement.requisitions r;
grant select on api.purchase_requisitions to authenticated;

create function api.upsert_purchase_requisition(
  p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,
  p_command_id uuid,p_idempotency_key uuid,p_client_timestamp timestamptz,
  p_payload jsonb,p_expected_entity_version bigint default null
) returns jsonb language plpgsql security definer set search_path='' as $$
declare
  v_actor uuid := (select auth.uid());
  v_id uuid; v_hash text; v_replay jsonb; v_before jsonb; v_entity jsonb;
  v_old procurement.requisitions%rowtype;
  v_line jsonb; v_unit jsonb; v_quantity numeric; v_price numeric; v_total numeric := 0;
  v_ordinal integer := 0; v_need_by date; v_currency text;
begin
  perform core.wave3_require_scope(p_tenant_id,'procurement.requisitions.manage',p_legal_entity_id,p_branch_id);
  if p_branch_id is null or p_legal_entity_id is null or p_client_timestamp is null
    or jsonb_typeof(p_payload) is distinct from 'object' then
    raise exception using errcode='22023',message='INVALID_COMMAND';
  end if;
  v_hash := core.wave3_request_hash('procurement.requisition.upsert',p_command_id,
    p_tenant_id,p_legal_entity_id,p_branch_id,p_payload,p_expected_entity_version);
  v_replay := core.wave3_replay(p_tenant_id,'procurement.requisition.upsert',p_command_id,p_idempotency_key,v_hash);
  if v_replay is not null then return v_replay; end if;
  v_id := (p_payload->>'id')::uuid;
  if v_id is null then raise exception using errcode='22023',message='DOCUMENT_ID_REQUIRED'; end if;
  -- Serialize create/update for the same stable document identity, including different keys.
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('procurement.requisition:'||v_id::text,0));
  select * into v_old from procurement.requisitions where id=v_id
    and tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id for update;
  if found then
    select detail into v_before from api.purchase_requisitions where id=v_id;
    perform core.wave3_assert_expected_version(v_old.version,p_expected_entity_version,v_before);
    if v_old.status <> 'draft' then
      raise exception using errcode='55000',message='REQUISITION_NOT_EDITABLE';
    end if;
  elsif p_expected_entity_version is not null then
    raise exception using errcode='40001',message='VERSION_CONFLICT';
  end if;
  if jsonb_typeof(p_payload->'lines') is distinct from 'array' then
    raise exception using errcode='22023',message='LINES_REQUIRED';
  end if;
  if jsonb_array_length(p_payload->'lines') not between 1 and 500
    or length(trim(coalesce(p_payload->>'justification',''))) not between 1 and 4000 then
    raise exception using errcode='22023',message='INVALID_REQUISITION';
  end if;
  if coalesce(p_payload->>'need_by','') !~ '^\d{4}-\d{2}-\d{2}$' then
    raise exception using errcode='22023',message='NEED_BY_REQUIRED';
  end if;
  v_need_by := (p_payload->>'need_by')::date;
  select currency_code into v_currency from core.legal_entities
    where id=p_legal_entity_id and tenant_id=p_tenant_id;
  if p_payload->>'currency_code' is distinct from v_currency then
    raise exception using errcode='22023',message='ESTIMATE_BASE_CURRENCY_REQUIRED';
  end if;
  for v_line in select value from jsonb_array_elements(p_payload->'lines') loop
    v_quantity := sales.wave3_decimal_string(v_line->'quantity','quantity',6,true,0,null);
    v_price := sales.wave3_decimal_string(v_line->'estimated_unit_price','estimated_unit_price',6,true,0,null);
    if v_quantity <= 0 or v_quantity >= 100000000000000 or v_price >= 100000000000000 then
      raise exception using errcode='22023',message='BASE_UNIT_ESTIMATE_REQUIRED';
    end if;
    if not exists(select 1 from inventory.units u where u.id=(v_line->>'unit_id')::uuid
      and u.tenant_id=p_tenant_id and u.status='active'
      and round(v_quantity,u.precision)=v_quantity) then
      raise exception using errcode='22023',message='UNIT_INVALID';
    end if;
    if v_line->>'product_id' is not null and not exists(select 1 from inventory.products p
      where p.id=(v_line->>'product_id')::uuid and p.tenant_id=p_tenant_id
      and p.legal_entity_id=p_legal_entity_id and p.status='active' and p.can_purchase) then
      raise exception using errcode='22023',message='PRODUCT_INVALID';
    end if;
    v_total := v_total + round(v_quantity*v_price,6);
  end loop;
  if v_old.id is null then
    insert into procurement.requisitions(id,tenant_id,legal_entity_id,branch_id,requester_id,
      need_by,justification,currency_code,estimated_total,created_by,updated_by)
    values(v_id,p_tenant_id,p_legal_entity_id,p_branch_id,v_actor,v_need_by,
      trim(p_payload->>'justification'),v_currency,v_total,v_actor,v_actor);
  else
    update procurement.requisitions set need_by=v_need_by,justification=trim(p_payload->>'justification'),
      estimated_total=v_total,version=version+1,updated_by=v_actor,updated_at=clock_timestamp() where id=v_id;
    delete from procurement.requisition_lines where requisition_id=v_id;
  end if;
  for v_line in select value from jsonb_array_elements(p_payload->'lines') loop
    v_ordinal := v_ordinal+1;
    v_quantity := (v_line->>'quantity')::numeric; v_price := (v_line->>'estimated_unit_price')::numeric;
    v_unit:=inventory.resolve_product_unit(p_tenant_id,p_legal_entity_id,(v_line->>'product_id')::uuid,(v_line->>'unit_id')::uuid,
      v_line->'quantity',v_line->'conversion_numerator',v_line->'conversion_denominator');
    insert into procurement.requisition_lines(id,tenant_id,legal_entity_id,requisition_id,ordinal,
      product_id,description,unit_id,quantity,estimated_unit_price,estimated_total,base_quantity,conversion_numerator,conversion_denominator,conversion_id,conversion_version)
    values((v_line->>'line_id')::uuid,p_tenant_id,p_legal_entity_id,v_id,v_ordinal,
      (v_line->>'product_id')::uuid,trim(v_line->>'description'),(v_line->>'unit_id')::uuid,
      v_quantity,v_price,round(v_quantity*v_price,6),(v_unit->>'base_quantity')::numeric,(v_unit->>'conversion_numerator')::bigint,
      (v_unit->>'conversion_denominator')::bigint,(v_unit->>'conversion_id')::uuid,(v_unit->>'conversion_version')::bigint);
  end loop;
  select detail into v_entity from api.purchase_requisitions where id=v_id;
  return core.wave3_finish_command(p_tenant_id,'procurement.requisition.upsert',p_command_id,
    'purchase_requisition',v_id,p_idempotency_key,v_hash,v_before,v_entity,p_legal_entity_id,p_branch_id,
    '{}'::jsonb,null,jsonb_build_array(jsonb_build_object('topic','procurement.requisition.saved',
      'payload',jsonb_build_object('version',v_entity->'version'))));
end;
$$;
revoke all on function api.upsert_purchase_requisition(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) from public,anon;
grant execute on function api.upsert_purchase_requisition(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) to authenticated;

-- Unapplied candidate, AC-309 FR-336. Module-owned; no shared function replacement.
alter table procurement.requisitions
 add column document_number text,
 add column workflow_snapshot jsonb,
 add column submitted_by uuid references auth.users(id),
 add column submitted_at timestamptz,
 add constraint requisition_number_unique unique(tenant_id,legal_entity_id,branch_id,document_number);
create index requisitions_submitter on procurement.requisitions(submitted_by);
create index requisitions_creator on procurement.requisitions(created_by);
create index requisitions_editor on procurement.requisitions(updated_by);
create index requisitions_currency on procurement.requisitions(currency_code);

create table procurement.requisition_history (
 id uuid primary key default gen_random_uuid(),
 tenant_id uuid not null,
 legal_entity_id uuid not null,
 requisition_id uuid not null,
 version bigint not null,
 snapshot jsonb not null check(jsonb_typeof(snapshot)='object'),
 actor_id uuid not null references auth.users(id),
 created_at timestamptz not null default now(),
 unique(requisition_id,version),
 foreign key(tenant_id,legal_entity_id,requisition_id) references procurement.requisitions(tenant_id,legal_entity_id,id)
);
create index requisition_history_source on procurement.requisition_history(tenant_id,legal_entity_id,requisition_id);
create index requisition_history_actor on procurement.requisition_history(actor_id);
alter table procurement.requisition_history enable row level security;
alter table procurement.requisition_history force row level security;
create policy requisition_history_read on procurement.requisition_history for select to authenticated
using(exists(select 1 from procurement.requisitions r where r.id=requisition_id
 and r.tenant_id=requisition_history.tenant_id and r.legal_entity_id=requisition_history.legal_entity_id));
create trigger requisition_history_immutable before update or delete on procurement.requisition_history
for each row execute function workflow.reject_history_mutation();
revoke all on procurement.requisition_history from public,anon,authenticated;
grant select on procurement.requisition_history to authenticated;

-- Do not install a trigger on shared receipts: history is written by module-owned commands.
-- Wrap only this session's unpublished requisition function; signature remains stable.
alter function api.upsert_purchase_requisition(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint)
 set schema procurement;
alter function procurement.upsert_purchase_requisition(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint)
 rename to save_requisition_draft;
revoke all on function procurement.save_requisition_draft(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) from public,anon,authenticated;

create function procurement.record_requisition_history(p_result jsonb) returns void
language plpgsql security definer set search_path='' as $$begin
 insert into procurement.requisition_history(tenant_id,legal_entity_id,requisition_id,version,snapshot,actor_id)
 select r.tenant_id,r.legal_entity_id,r.id,(p_result#>>'{entity,version}')::bigint,p_result->'entity',auth.uid()
 from procurement.requisitions r where r.id=(p_result#>>'{entity,id}')::uuid
 on conflict(requisition_id,version) do nothing;
end $$;
create function api.upsert_purchase_requisition(
 p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_command_id uuid,p_idempotency_key uuid,
 p_client_timestamp timestamptz,p_payload jsonb,p_expected_entity_version bigint default null)
returns jsonb language plpgsql security definer set search_path='' as $$declare v_result jsonb;begin
 v_result:=procurement.save_requisition_draft(p_tenant_id,p_legal_entity_id,p_branch_id,p_command_id,p_idempotency_key,
 p_client_timestamp,p_payload,p_expected_entity_version);
 perform procurement.record_requisition_history(v_result);return v_result;end $$;

create or replace view api.purchase_requisitions with(security_invoker=true) as
select r.tenant_id,r.legal_entity_id,r.branch_id,r.id,r.status,
 jsonb_build_object('id',r.id,'requester_id',r.requester_id,'need_by',r.need_by,
 'justification',r.justification,'currency_code',r.currency_code,'document_number',r.document_number,
 'estimated_total',r.estimated_total::text,'status',r.status,'version',r.version,
 'workflow_snapshot',r.workflow_snapshot,'created_by',r.created_by,'updated_by',r.updated_by,
 'submitted_by',r.submitted_by,'submitted_at',r.submitted_at,'created_at',r.created_at,
 'lines',coalesce((select jsonb_agg(jsonb_build_object('line_id',l.id,'product_id',l.product_id,
 'description',l.description,'unit_id',l.unit_id,'quantity',l.quantity::text,
 'estimated_unit_price',l.estimated_unit_price::text,'estimated_total',l.estimated_total::text,
 'base_quantity',l.base_quantity::text,'conversion_numerator',l.conversion_numerator::text,
 'conversion_denominator',l.conversion_denominator::text,'conversion_id',l.conversion_id,'conversion_version',l.conversion_version) order by l.ordinal)
 from procurement.requisition_lines l where l.requisition_id=r.id),'[]'::jsonb)) detail
from procurement.requisitions r;

create function api.transition_purchase_requisition(
 p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_command_id uuid,p_idempotency_key uuid,
 p_client_timestamp timestamptz,p_payload jsonb,p_expected_entity_version bigint default null)
returns jsonb language plpgsql security definer set search_path='' as $$
declare
 v_actor uuid:=auth.uid();v_id uuid;v_action text:=p_payload->>'action';v_decision text:=p_payload->>'decision';
 v_command text:='procurement.requisition.transition';v_hash text;v_result jsonb;v_before jsonb;v_entity jsonb;
 v_doc procurement.requisitions%rowtype;v_workflow workflow.workflow_definitions%rowtype;
 v_ar workflow.approval_requests%rowtype;v_snapshot jsonb;v_step jsonb;v_first integer;v_to text;
 v_request uuid:=gen_random_uuid();v_reason text:=nullif(trim(coalesce(p_payload->>'reason',p_payload->>'note')),'');
begin
 perform core.wave3_require_scope(p_tenant_id,'procurement.requisitions.manage',p_legal_entity_id,p_branch_id);
 if p_legal_entity_id is null or p_branch_id is null or p_client_timestamp is null
 or jsonb_typeof(p_payload) is distinct from 'object' or (v_action is null)=(v_decision is null) then
 raise exception using errcode='22023',message='INVALID_COMMAND';end if;
 if v_decision is not null then
  perform core.require_permission(p_tenant_id,'workflow.approvals.decide',p_legal_entity_id,p_branch_id);
 end if;
 v_id:=(p_payload->>'document_id')::uuid;
 v_hash:=core.wave3_request_hash(v_command,p_command_id,p_tenant_id,p_legal_entity_id,p_branch_id,p_payload,p_expected_entity_version);
 v_result:=core.wave3_replay(p_tenant_id,v_command,p_command_id,p_idempotency_key,v_hash);
 if v_result is not null then return v_result;end if;
 select * into v_doc from procurement.requisitions where id=v_id and tenant_id=p_tenant_id
 and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id for update;
 if not found then raise exception using errcode='P0002',message='DOCUMENT_NOT_FOUND';end if;
 select detail into v_before from api.purchase_requisitions where id=v_id;
 perform core.wave3_assert_expected_version(v_doc.version,p_expected_entity_version,v_before);
 v_snapshot:=v_doc.workflow_snapshot;
 if v_action='submit' then
  if v_doc.status<>'draft' then raise exception using errcode='55000',message='REQUISITION_NOT_EDITABLE';end if;
  if not exists(select 1 from core.memberships where tenant_id=p_tenant_id and user_id=v_doc.requester_id and status='active')
  or exists(select 1 from procurement.requisition_lines l left join inventory.units u on u.id=l.unit_id and u.tenant_id=l.tenant_id
    left join inventory.products p on p.id=l.product_id and p.tenant_id=l.tenant_id and p.legal_entity_id=l.legal_entity_id
    where l.requisition_id=v_id and (u.status is distinct from 'active' or round(l.quantity,u.precision)<>l.quantity
    or (l.product_id is not null and (p.status is distinct from 'active' or not p.can_purchase)))) then
   raise exception using errcode='22023',message='REFERENCE_INVALID';end if;
  perform inventory.resolve_product_unit(p_tenant_id,p_legal_entity_id,l.product_id,l.unit_id,to_jsonb(l.quantity::text),
    to_jsonb(l.conversion_numerator::text),to_jsonb(l.conversion_denominator::text)) from procurement.requisition_lines l where l.requisition_id=v_id;
  select * into v_workflow from workflow.workflow_definitions where tenant_id=p_tenant_id
   and document_type='purchase_requisition' and status='active' and (legal_entity_id is null or legal_entity_id=p_legal_entity_id)
   order by (legal_entity_id is not null) desc,revision desc,id limit 1;
  if not found then raise exception using errcode='55000',message='WORKFLOW_CONFIGURATION_ERROR';end if;
  select jsonb_build_object('definition_id',v_workflow.id,'revision',v_workflow.revision,'lifecycle',v_workflow.lifecycle,
   'steps',coalesce(jsonb_agg(sales.flow_exact_json(to_jsonb(s)) order by s.step_order),'[]'::jsonb)) into v_snapshot
   from workflow.approval_matrix_steps s where s.tenant_id=p_tenant_id and s.workflow_definition_id=v_workflow.id and s.status='active'
   and (s.currency_code is null or s.currency_code=v_doc.currency_code)
   and (s.minimum_amount is null or s.minimum_amount<=v_doc.estimated_total)
   and (s.maximum_amount is null or s.maximum_amount>=v_doc.estimated_total);
  select min((x->>'step_order')::integer) into v_first from jsonb_array_elements(v_snapshot->'steps') x;
  if v_first is null and v_workflow.lifecycle->'requires_approval' is distinct from 'false'::jsonb then
   raise exception using errcode='55000',message='WORKFLOW_CONFIGURATION_ERROR';end if;
  perform sales.flow_assert_transition(v_workflow.lifecycle,'draft','submitted');
  v_to:=case when v_first is null then 'approved' else 'pending_approval' end;
  if v_first is null then perform sales.flow_assert_transition(v_workflow.lifecycle,'submitted','approved');end if;
  v_doc.document_number:=coalesce(v_doc.document_number,sales.wave3_reserve_document_number(p_tenant_id,p_legal_entity_id,
    p_branch_id,'purchase_requisition',(v_doc.created_at at time zone 'UTC')::date,v_actor));
  if v_first is not null then
   insert into workflow.approval_requests(tenant_id,legal_entity_id,branch_id,document_type,document_id,status,
    submitted_by,workflow_definition_id,workflow_revision,current_step,amount,currency_code,command_id,request_id,correlation_id)
   values(p_tenant_id,p_legal_entity_id,p_branch_id,'purchase_requisition',v_id,'submitted',v_actor,
    v_workflow.id,v_workflow.revision,v_first,v_doc.estimated_total,v_doc.currency_code,p_command_id,v_request,v_request);
  end if;
 elsif v_decision is not null then
  if v_doc.status<>'pending_approval' or v_decision not in ('approved','rejected') then
   raise exception using errcode='55000',message='APPROVAL_NOT_PENDING';end if;
  select * into v_ar from workflow.approval_requests where tenant_id=p_tenant_id and document_type='purchase_requisition'
   and document_id=v_id and status='submitted' for update;
  if not found then raise exception using errcode='55000',message='APPROVAL_REQUEST_NOT_FOUND';end if;
  if v_actor in(v_doc.requester_id,v_doc.created_by,v_doc.updated_by,v_doc.submitted_by) then
   raise exception using errcode='42501',message='SEGREGATION_OF_DUTIES_VIOLATION';end if;
  select x into v_step from jsonb_array_elements(v_snapshot->'steps') x where (x->>'step_order')::integer=v_ar.current_step;
  if v_step is null or not exists(select 1 from core.memberships m
   join core.role_assignments ra on ra.membership_id=m.id and ra.tenant_id=m.tenant_id
   join core.roles r on r.id=ra.role_id and r.tenant_id=m.tenant_id
   where m.tenant_id=p_tenant_id and m.user_id=v_actor and m.status='active' and ra.role_id=(v_step->>'role_id')::uuid
   and (ra.legal_entity_id is null or ra.legal_entity_id=p_legal_entity_id) and (ra.branch_id is null or ra.branch_id=p_branch_id)
   and (not r.requires_mfa or auth.jwt()->>'aal'='aal2')) then
   raise exception using errcode='42501',message='APPROVAL_ROLE_REQUIRED';end if;
  if v_decision='rejected' and v_reason is null then raise exception using errcode='22023',message='REASON_REQUIRED';end if;
  perform sales.flow_assert_transition(v_snapshot->'lifecycle','submitted',v_decision);
  insert into workflow.approval_decisions(tenant_id,approval_request_id,workflow_definition_id,workflow_revision,
   approval_matrix_step_id,step_order,actor_id,decision,note,amount,currency_code,request_id,command_id,correlation_id)
  values(p_tenant_id,v_ar.id,v_ar.workflow_definition_id,v_ar.workflow_revision,(v_step->>'id')::uuid,v_ar.current_step,
   v_actor,v_decision,v_reason,v_ar.amount,v_ar.currency_code,v_request,p_command_id,v_request);
  if v_decision='approved' then
   select min((x->>'step_order')::integer) into v_first from jsonb_array_elements(v_snapshot->'steps') x
    where (x->>'step_order')::integer>v_ar.current_step;
  end if;
  v_to:=case when v_decision='rejected' then 'rejected' when v_first is null then 'approved' else 'pending_approval' end;
  update workflow.approval_requests set current_step=coalesce(v_first,current_step),
   status=case when v_first is null then v_to else status end,
   decision_by=case when v_first is null then v_actor else decision_by end,
   decision_note=case when v_first is null then v_reason else decision_note end,
   decided_at=case when v_first is null then clock_timestamp() else decided_at end where id=v_ar.id;
 elsif v_action in('recall','cancel') then
  if v_reason is null then raise exception using errcode='22023',message='REASON_REQUIRED';end if;
  if v_snapshot is null then
   select jsonb_build_object('lifecycle',lifecycle) into v_snapshot from workflow.workflow_definitions
    where tenant_id=p_tenant_id and document_type='purchase_requisition' and status='active'
    and (legal_entity_id is null or legal_entity_id=p_legal_entity_id)
    order by (legal_entity_id is not null) desc,revision desc,id limit 1;
  end if;
  v_to:=case when v_action='recall' then 'draft' else 'cancelled' end;
  perform sales.flow_assert_transition(v_snapshot->'lifecycle',v_doc.status,v_to);
  update workflow.approval_requests set status='cancelled',decision_by=v_actor,decision_note=v_reason,decided_at=clock_timestamp()
   where tenant_id=p_tenant_id and document_type='purchase_requisition' and document_id=v_id and status='submitted';
  if v_action='recall' then v_snapshot:=null;end if;
 else raise exception using errcode='22023',message='INVALID_COMMAND';end if;
 update procurement.requisitions set status=v_to,version=version+1,updated_at=clock_timestamp(),updated_by=v_actor,
  workflow_snapshot=v_snapshot,document_number=v_doc.document_number,
  submitted_by=case when v_action='submit' then v_actor else submitted_by end,
  submitted_at=case when v_action='submit' then clock_timestamp() else submitted_at end where id=v_id;
 select detail into v_entity from api.purchase_requisitions where id=v_id;
 v_result:=core.wave3_finish_command(p_tenant_id,v_command,p_command_id,'purchase_requisition',v_id,
  p_idempotency_key,v_hash,v_before,v_entity,p_legal_entity_id,p_branch_id,'{}',
  case when v_doc.status=v_to then null else jsonb_build_object('from_status',v_doc.status,'to_status',v_to,'reason',v_reason) end,
  jsonb_build_array(jsonb_build_object('topic',v_command,'payload',jsonb_build_object('status',v_to))),'[]',v_request,v_request);
 perform procurement.record_requisition_history(v_result);return v_result;
end $$;
revoke all on function procurement.record_requisition_history(jsonb) from public,anon,authenticated;
revoke all on function api.upsert_purchase_requisition(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint),
 api.transition_purchase_requisition(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) from public,anon;
grant execute on function api.upsert_purchase_requisition(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint),
 api.transition_purchase_requisition(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) to authenticated;

-- AC-309 bounded reference reads. No role, membership or master-record mutations.
create function api.procurement_reference_options(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,
 p_resource text,p_after uuid default null,p_search text default '') returns jsonb
language plpgsql security definer set search_path='' as $$
declare v_items jsonb;v_more boolean;v_currency text;v_search text;
begin
 if core.has_permission(p_tenant_id,'procurement.requisitions.manage',p_legal_entity_id,p_branch_id) then
  perform core.wave3_require_scope(p_tenant_id,'procurement.requisitions.manage',p_legal_entity_id,p_branch_id);
 elsif core.has_permission(p_tenant_id,'procurement.rfq.manage',p_legal_entity_id,p_branch_id) then
  perform core.wave3_require_scope(p_tenant_id,'procurement.rfq.manage',p_legal_entity_id,p_branch_id);
 elsif core.has_permission(p_tenant_id,'inventory.catalog.manage',p_legal_entity_id,p_branch_id) then
  perform core.wave3_require_scope(p_tenant_id,'inventory.catalog.manage',p_legal_entity_id,p_branch_id);
 else perform core.wave3_require_scope(p_tenant_id,'procurement.orders.manage',p_legal_entity_id,p_branch_id);end if;
 if p_legal_entity_id is null or p_branch_id is null or length(coalesce(p_search,''))>100 then
  raise exception using errcode='22023',message='REFERENCE_SCOPE_INVALID';end if;
 v_search:=lower(trim(coalesce(p_search,'')));
 select currency_code into v_currency from core.legal_entities where id=p_legal_entity_id and tenant_id=p_tenant_id;
 if p_resource='units' then
  select jsonb_agg(jsonb_build_object('id',id,'code',code,'name',name,'precision',precision) order by id)
  into v_items from(select * from inventory.units where tenant_id=p_tenant_id and status='active'
   and (p_after is null or id>p_after) and (v_search='' or position(v_search in lower(code||' '||name))>0) order by id limit 51) x;
 elsif p_resource='unit_conversions' then
  perform core.require_permission(p_tenant_id,'inventory.catalog.manage',p_legal_entity_id,null);
  select jsonb_agg(jsonb_build_object('id',id,'code',code,'name',name,'detail',detail) order by id)
  into v_items from(select c.id,p.sku code,u.name,p.name||' · '||u.name label,
   c.detail||jsonb_build_object('_product_name',p.name,'_unit_name',u.name) detail
   from api.product_unit_conversions c join inventory.products p on p.id=c.product_id and p.tenant_id=c.tenant_id
   join inventory.units u on u.id=(c.detail->>'unit_id')::uuid and u.tenant_id=c.tenant_id
   where c.tenant_id=p_tenant_id and c.legal_entity_id=p_legal_entity_id and (p_after is null or c.id>p_after)
   and (v_search='' or position(v_search in lower(p.sku||' '||p.name||' '||u.name))>0) order by c.id limit 51) x;
 elsif p_resource like 'product_units:%' then
  select jsonb_agg(jsonb_build_object('id',id,'code',code,'name',name,'conversion_numerator',numerator::text,
    'conversion_denominator',denominator::text,'conversion_id',conversion_id,'conversion_version',version) order by id)
  into v_items from(select * from (
   select u.id,u.code,u.name,1::bigint numerator,1::bigint denominator,null::uuid conversion_id,null::bigint version
   from inventory.products p join inventory.units u on u.id=p.base_unit_id and u.tenant_id=p.tenant_id
   where p.id=substring(p_resource from 15)::uuid and p.tenant_id=p_tenant_id and p.legal_entity_id=p_legal_entity_id and p.status='active' and u.status='active'
   union all
   select u.id,u.code,u.name,c.numerator,c.denominator,c.id,c.version from inventory.product_unit_conversions c
   join inventory.units u on u.id=c.unit_id and u.tenant_id=c.tenant_id
   where c.product_id=substring(p_resource from 15)::uuid and c.tenant_id=p_tenant_id and c.legal_entity_id=p_legal_entity_id and c.status='active' and u.status='active'
  ) q where (p_after is null or id>p_after) and (v_search='' or position(v_search in lower(code||' '||name))>0) order by id limit 51) x;
 elsif p_resource='requisitions' then
  select jsonb_agg(jsonb_build_object('id',id,'code',detail->>'document_number','name',detail->>'justification','detail',detail) order by id)
  into v_items from(select * from api.purchase_requisitions where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id
   and branch_id=p_branch_id and status='approved' and (p_after is null or id>p_after)
   and (v_search='' or position(v_search in lower(detail->>'justification'))>0) order by id limit 51) x;
 elsif p_resource='selected_rfqs' then
  select jsonb_agg(jsonb_build_object('id',id,'code',detail->>'document_number','name',detail->>'title','detail',detail) order by id)
  into v_items from(select * from api.request_for_quotes where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id
   and branch_id=p_branch_id and status='selected' and (p_after is null or id>p_after)
   and (v_search='' or position(v_search in lower(detail->>'title'))>0) order by id limit 51) x;
 elsif p_resource='rates' then
  select jsonb_agg(jsonb_build_object('id',id,'code',source_currency_code,'name',effective_date::text||' · '||rate::text,
   'currency_code',source_currency_code,'exchange_rate',rate::text,'rate_date',effective_date) order by id)
  into v_items from(select * from finance.exchange_rates where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id
   and status='active' and target_currency_code=v_currency and (p_after is null or id>p_after)
   and (v_search='' or position(v_search in lower(source_currency_code))>0) order by id limit 51) x;
 elsif p_resource='taxes' then
  select jsonb_agg(jsonb_build_object('id',id,'code',code,'name',name,'rate',rate::text,'inclusive',inclusive) order by id)
  into v_items from(select * from finance.tax_definitions where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id
   and status='active' and kind in('input','zero','exempt') and (p_after is null or id>p_after)
   and (v_search='' or position(v_search in lower(code||' '||name))>0) order by id limit 51) x;
 elsif p_resource in('products','catalogue_products') then
  if p_resource='catalogue_products' then perform core.require_permission(p_tenant_id,'inventory.catalog.manage',p_legal_entity_id,null);end if;
  select jsonb_agg(jsonb_build_object('id',id,'code',sku,'name',name,'unit_id',base_unit_id) order by id)
  into v_items from(select * from inventory.products where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id
   and status='active' and (can_purchase or p_resource='catalogue_products') and (p_after is null or id>p_after)
   and (v_search='' or position(v_search in lower(sku||' '||name))>0) order by id limit 51) x;
 elsif p_resource='suppliers' then
  select jsonb_agg(jsonb_build_object('id',id,'code',code,'name',display_name) order by id)
  into v_items from(select * from crm.parties where tenant_id=p_tenant_id and status='active' and kind in('supplier','both')
   and (p_after is null or id>p_after) and (v_search='' or position(v_search in lower(code||' '||display_name))>0) order by id limit 51) x;
 elsif p_resource='warehouses' then
  select jsonb_agg(jsonb_build_object('id',id,'code',code,'name',name) order by id)
  into v_items from(select * from core.warehouses where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id
   and branch_id=p_branch_id and status='active' and (p_after is null or id>p_after)
   and (v_search='' or position(v_search in lower(code||' '||name))>0) order by id limit 51) x;
 else raise exception using errcode='22023',message='REFERENCE_RESOURCE_INVALID';end if;
 v_items:=coalesce(v_items,'[]');v_more:=jsonb_array_length(v_items)>50;
 if v_more then v_items:=v_items-50;end if;
 return jsonb_build_object('items',v_items,'next_cursor',case when v_more then v_items#>>'{49,id}' else null end,
  'base_currency',v_currency,'limit',50);
end $$;
revoke all on function api.procurement_reference_options(uuid,uuid,uuid,text,uuid,text) from public,anon;
grant execute on function api.procurement_reference_options(uuid,uuid,uuid,text,uuid,text) to authenticated;

-- AC-309 / FR-337. Unapplied candidate. Invitations record intent; no external messages.
create table procurement.rfqs (
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,branch_id uuid not null,
 requisition_id uuid not null,requisition_version bigint not null,
 invited_supplier_ids uuid[] not null check(cardinality(invited_supplier_ids) between 1 and 100),
 invited_suppliers jsonb not null,
 title text not null check(length(trim(title)) between 1 and 160),
 document_date date not null,close_date date not null,document_number text not null,
 status text not null default 'issued' check(status in('issued','selected','ordered','cancelled')),
 selected_quote_id uuid,selection_reason text,version bigint not null default 1,
 created_by uuid not null references auth.users(id),updated_by uuid not null references auth.users(id),
 created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
 unique(tenant_id,legal_entity_id,id),unique(tenant_id,legal_entity_id,branch_id,document_number),
 foreign key(tenant_id,legal_entity_id,requisition_id) references procurement.requisitions(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,branch_id) references core.branches(tenant_id,id),check(close_date>=document_date)
);
create table procurement.rfq_lines (
 id uuid primary key default gen_random_uuid(),tenant_id uuid not null,legal_entity_id uuid not null,
 rfq_id uuid not null,source_line_id uuid not null,source_snapshot jsonb not null,
 unique(rfq_id,source_line_id),
 foreign key(tenant_id,legal_entity_id,rfq_id) references procurement.rfqs(tenant_id,legal_entity_id,id)
);
create index rfq_scope_page on procurement.rfqs(tenant_id,legal_entity_id,branch_id,id);
create index rfq_scope_status on procurement.rfqs(tenant_id,legal_entity_id,branch_id,status,id);
create table procurement.supplier_quotes (
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,rfq_id uuid not null,
 supplier_id uuid not null,quote_date date not null,valid_until date not null,
 currency_code text not null references core.currencies(code),exchange_rate_id uuid,
 exchange_rate numeric(20,10) not null,rate_date date not null,
 payment_terms text not null,delivery_terms text not null,
 subtotal numeric(20,6) not null,tax_total numeric(20,6) not null,total numeric(20,6) not null,base_total numeric(20,6) not null,
 complete boolean not null,version bigint not null default 1,
 created_by uuid not null references auth.users(id),updated_by uuid not null references auth.users(id),
 created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
 unique(tenant_id,legal_entity_id,id),unique(rfq_id,supplier_id),
 foreign key(tenant_id,legal_entity_id,rfq_id) references procurement.rfqs(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,supplier_id) references crm.parties(tenant_id,id),
 foreign key(tenant_id,legal_entity_id,exchange_rate_id) references finance.exchange_rates(tenant_id,legal_entity_id,id),
 check(valid_until>=quote_date),check(exchange_rate>0),check(subtotal>=0 and tax_total>=0 and total>=0 and base_total>=0),
 check(length(trim(payment_terms)) between 1 and 1000 and length(trim(delivery_terms)) between 1 and 1000)
);
alter table procurement.rfqs add constraint rfq_selected_quote_fk foreign key(tenant_id,legal_entity_id,selected_quote_id)
 references procurement.supplier_quotes(tenant_id,legal_entity_id,id);
create table procurement.supplier_quote_lines (
 id uuid primary key default gen_random_uuid(),tenant_id uuid not null,legal_entity_id uuid not null,
 quote_id uuid not null,source_line_id uuid not null,detail jsonb not null,
 unique(quote_id,source_line_id),foreign key(tenant_id,legal_entity_id,quote_id) references procurement.supplier_quotes(tenant_id,legal_entity_id,id)
);
create table procurement.rfq_history (
 id uuid primary key default gen_random_uuid(),tenant_id uuid not null,legal_entity_id uuid not null,
 rfq_id uuid not null,version bigint not null,snapshot jsonb not null,actor_id uuid not null references auth.users(id),
 created_at timestamptz not null default now(),unique(rfq_id,version),
 foreign key(tenant_id,legal_entity_id,rfq_id) references procurement.rfqs(tenant_id,legal_entity_id,id)
);
create function procurement.rfq_read_allowed(p_tenant uuid,p_entity uuid,p_rfq uuid) returns boolean
language sql stable security definer set search_path='' as $$select exists(select 1 from procurement.rfqs r
 where r.id=p_rfq and r.tenant_id=p_tenant and r.legal_entity_id=p_entity
 and (core.has_permission(r.tenant_id,'procurement.rfq.manage',r.legal_entity_id,r.branch_id)
 or core.has_permission(r.tenant_id,'procurement.orders.manage',r.legal_entity_id,r.branch_id)))$$;
alter table procurement.rfqs enable row level security;alter table procurement.rfqs force row level security;
create policy rfq_read on procurement.rfqs for select to authenticated using(procurement.rfq_read_allowed(tenant_id,legal_entity_id,id));
do $$declare t text;begin
 foreach t in array array['rfq_lines','supplier_quotes','rfq_history'] loop
  execute format('alter table procurement.%I enable row level security',t);
  execute format('alter table procurement.%I force row level security',t);
  execute format('create policy rfq_read on procurement.%I for select to authenticated using(procurement.rfq_read_allowed(tenant_id,legal_entity_id,rfq_id))',t);
 end loop;
end $$;
alter table procurement.supplier_quote_lines enable row level security;alter table procurement.supplier_quote_lines force row level security;
create policy quote_lines_read on procurement.supplier_quote_lines for select to authenticated
using(exists(select 1 from procurement.supplier_quotes q where q.id=quote_id and q.tenant_id=supplier_quote_lines.tenant_id));
create trigger rfq_history_immutable before update or delete on procurement.rfq_history for each row execute function workflow.reject_history_mutation();
create trigger rfq_sources_immutable before update or delete on procurement.rfq_lines for each row execute function workflow.reject_history_mutation();
revoke all on procurement.rfqs,procurement.rfq_lines,procurement.supplier_quotes,procurement.supplier_quote_lines,procurement.rfq_history from public,anon,authenticated;
grant select on procurement.rfqs,procurement.rfq_lines,procurement.supplier_quotes,procurement.supplier_quote_lines,procurement.rfq_history to authenticated;
revoke all on function procurement.rfq_read_allowed(uuid,uuid,uuid) from public,anon;
grant execute on function procurement.rfq_read_allowed(uuid,uuid,uuid) to authenticated;

create view api.request_for_quotes with(security_invoker=true) as
select r.tenant_id,r.legal_entity_id,r.branch_id,r.id,r.status,
 sales.flow_exact_json(to_jsonb(r))||jsonb_build_object(
 'lines',coalesce((select jsonb_agg(l.source_snapshot||jsonb_build_object('source_line_id',l.source_line_id) order by l.id)
  from procurement.rfq_lines l where l.rfq_id=r.id),'[]'),
 'quotes',coalesce((select jsonb_agg(sales.flow_exact_json(to_jsonb(q))||jsonb_build_object(
  'supplier_name',(select x->>'name' from jsonb_array_elements(r.invited_suppliers) x where x->>'id'=q.supplier_id::text),
  'lines',coalesce((select jsonb_agg(l.detail order by l.id) from procurement.supplier_quote_lines l where l.quote_id=q.id),'[]'))
  order by q.base_total,q.id) from procurement.supplier_quotes q where q.rfq_id=r.id),'[]')) detail
from procurement.rfqs r;
grant select on api.request_for_quotes to authenticated;

create function api.upsert_request_for_quote(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,
 p_command_id uuid,p_idempotency_key uuid,p_client_timestamp timestamptz,p_payload jsonb,p_expected_entity_version bigint default null)
returns jsonb language plpgsql security definer set search_path='' as $$
declare
 v_id uuid:=(p_payload->>'id')::uuid;v_operation text:=p_payload->>'operation';v_hash text;v_result jsonb;v_before jsonb;v_entity jsonb;
 v_rfq procurement.rfqs%rowtype;v_req procurement.requisitions%rowtype;v_quote procurement.supplier_quotes%rowtype;
 v_supplier uuid;v_invites uuid[];v_sources uuid[];v_quote_id uuid;v_line jsonb;v_source jsonb;v_tax finance.tax_definitions%rowtype;
 v_lines jsonb:='[]';v_unit jsonb;v_seen uuid[]:='{}';v_line_id uuid;v_q numeric;v_price numeric;v_discount numeric;v_gross numeric;
 v_net numeric;v_tax_amount numeric;v_total numeric:=0;v_subtotal numeric:=0;v_tax_total numeric:=0;v_rate numeric;
 v_date date;v_valid date;v_rate_date date;v_currency text;v_base text;v_scale integer;v_rate_id uuid;v_complete boolean:=true;
begin
 perform core.wave3_require_scope(p_tenant_id,'procurement.rfq.manage',p_legal_entity_id,p_branch_id);
 if p_legal_entity_id is null or p_branch_id is null or p_client_timestamp is null or v_id is null
 or jsonb_typeof(p_payload) is distinct from 'object' or v_operation is null then raise exception using errcode='22023',message='INVALID_COMMAND';end if;
 v_hash:=core.wave3_request_hash('procurement.rfq.upsert',p_command_id,p_tenant_id,p_legal_entity_id,p_branch_id,p_payload,p_expected_entity_version);
 v_result:=core.wave3_replay(p_tenant_id,'procurement.rfq.upsert',p_command_id,p_idempotency_key,v_hash);
 if v_result is not null then return v_result;end if;
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('procurement.rfq:'||v_id::text,0));
 select * into v_rfq from procurement.rfqs where id=v_id and tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id for update;
 if found then
  select detail into v_before from api.request_for_quotes where id=v_id;
  perform core.wave3_assert_expected_version(v_rfq.version,p_expected_entity_version,v_before);
  if v_rfq.status<>'issued' then raise exception using errcode='55000',message='RFQ_NOT_EDITABLE';end if;
 elsif v_operation<>'issue' or p_expected_entity_version is not null then
  raise exception using errcode='40001',message='VERSION_CONFLICT';
 end if;
 select currency_code,rounding_scale into v_base,v_scale from core.legal_entities where id=p_legal_entity_id and tenant_id=p_tenant_id;
 if v_operation='issue' then
  if v_rfq.id is not null then raise exception using errcode='55000',message='RFQ_ALREADY_ISSUED';end if;
  select * into v_req from procurement.requisitions where id=(p_payload->>'requisition_id')::uuid and tenant_id=p_tenant_id
   and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id for share;
  if not found or v_req.status<>'approved' then raise exception using errcode='55000',message='APPROVED_REQUISITION_REQUIRED';end if;
  perform core.wave3_assert_expected_version(v_req.version,(p_payload->>'requisition_version')::bigint,'{}');
  if p_payload ? 'source_line_ids' then
   if jsonb_typeof(p_payload->'source_line_ids') is distinct from 'array' then raise exception using errcode='22023',message='RFQ_SOURCE_LINES_INVALID';end if;
   select array_agg(value::uuid) into v_sources from jsonb_array_elements_text(p_payload->'source_line_ids');
  else select array_agg(id) into v_sources from procurement.requisition_lines where requisition_id=v_req.id;end if;
  if coalesce(cardinality(v_sources),0) not between 1 and 500 or cardinality(v_sources)<>(select count(distinct x) from unnest(v_sources) x)
   or cardinality(v_sources)<>(select count(*) from procurement.requisition_lines where requisition_id=v_req.id and id=any(v_sources)) then
   raise exception using errcode='22023',message='RFQ_SOURCE_LINES_INVALID';end if;
  if jsonb_typeof(p_payload->'invited_supplier_ids') is distinct from 'array' then raise exception using errcode='22023',message='SUPPLIERS_REQUIRED';end if;
  select array_agg(value::uuid) into v_invites from jsonb_array_elements_text(p_payload->'invited_supplier_ids');
  if coalesce(cardinality(v_invites),0) not between 1 and 100 or
   cardinality(v_invites)<>(select count(distinct x) from unnest(v_invites) x) then raise exception using errcode='22023',message='SUPPLIERS_INVALID';end if;
  foreach v_supplier in array v_invites loop
   if not exists(select 1 from crm.parties where id=v_supplier and tenant_id=p_tenant_id and status='active' and kind in('supplier','both')) then
    raise exception using errcode='22023',message='SUPPLIER_INVALID';end if;
  end loop;
  v_date:=(p_payload->>'document_date')::date;
  insert into procurement.rfqs(id,tenant_id,legal_entity_id,branch_id,requisition_id,requisition_version,invited_supplier_ids,invited_suppliers,
   title,document_date,close_date,document_number,created_by,updated_by)
  values(v_id,p_tenant_id,p_legal_entity_id,p_branch_id,v_req.id,v_req.version,v_invites,
   (select jsonb_agg(jsonb_build_object('id',id,'code',code,'name',display_name) order by id) from crm.parties where id=any(v_invites)),trim(p_payload->>'title'),
   v_date,(p_payload->>'close_date')::date,sales.wave3_reserve_document_number(p_tenant_id,p_legal_entity_id,p_branch_id,'request_for_quote',v_date,auth.uid()),auth.uid(),auth.uid());
  insert into procurement.rfq_lines(tenant_id,legal_entity_id,rfq_id,source_line_id,source_snapshot)
  select p_tenant_id,p_legal_entity_id,v_id,l.id,sales.flow_exact_json(to_jsonb(l)) from procurement.requisition_lines l where l.requisition_id=v_req.id and l.id=any(v_sources);
 elsif v_operation='record_quote' then
  v_supplier:=(p_payload->>'supplier_id')::uuid;v_quote_id:=(p_payload->>'quote_id')::uuid;
  if v_quote_id is null or v_supplier is null or not(v_supplier=any(v_rfq.invited_supplier_ids))
   or not exists(select 1 from crm.parties where id=v_supplier and tenant_id=p_tenant_id and status='active' and kind in('supplier','both')) then
    raise exception using errcode='22023',message='INVITED_SUPPLIER_REQUIRED';end if;
  select * into v_quote from procurement.supplier_quotes where rfq_id=v_id and supplier_id=v_supplier;
  if found and v_quote.id<>v_quote_id then raise exception using errcode='22023',message='QUOTE_ID_MISMATCH';end if;
  v_date:=(p_payload->>'quote_date')::date;v_valid:=(p_payload->>'valid_until')::date;v_currency:=p_payload->>'currency_code';
  v_rate_date:=(p_payload->>'rate_date')::date;v_rate_id:=(p_payload->>'exchange_rate_id')::uuid;
  v_rate:=sales.wave3_decimal_string(p_payload->'exchange_rate','exchange_rate',10,true,0,null);
  if v_rate<=0 or not exists(select 1 from core.currencies where code=v_currency and active) then raise exception using errcode='22023',message='CURRENCY_INVALID';end if;
  if v_currency=v_base then
   if v_rate<>1 or v_rate_id is not null then raise exception using errcode='22023',message='BASE_RATE_MUST_BE_ONE';end if;
  elsif not exists(select 1 from finance.exchange_rates where id=v_rate_id and tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id
   and status='active' and source_currency_code=v_currency and target_currency_code=v_base and rate=v_rate and effective_date=v_rate_date) then
   raise exception using errcode='22023',message='RATE_SNAPSHOT_INVALID';end if;
  if jsonb_typeof(p_payload->'lines') is distinct from 'array' or jsonb_array_length(p_payload->'lines') not between 1 and 500 then
   raise exception using errcode='22023',message='QUOTE_LINES_REQUIRED';end if;
  for v_line in select value from jsonb_array_elements(p_payload->'lines') loop
   v_line_id:=(v_line->>'source_line_id')::uuid;
   if v_line_id is null or v_line_id=any(v_seen) then raise exception using errcode='22023',message='QUOTE_SOURCE_INVALID';end if;
   v_seen:=array_append(v_seen,v_line_id);
   select source_snapshot into v_source from procurement.rfq_lines where rfq_id=v_id and source_line_id=v_line_id;
   if not found then raise exception using errcode='22023',message='QUOTE_SOURCE_INVALID';end if;
   v_q:=sales.wave3_decimal_string(v_line->'quantity','quantity',6,true,0,null);
   v_price:=sales.wave3_decimal_string(v_line->'unit_price','unit_price',6,true,0,null);
   v_discount:=sales.wave3_decimal_string(coalesce(v_line->'discount_percent','"0"'),'discount_percent',6,true,0,100);
   if v_q<=0 then raise exception using errcode='22023',message='QUANTITY_INVALID';end if;
   v_unit:=inventory.resolve_product_unit(p_tenant_id,p_legal_entity_id,(v_source->>'product_id')::uuid,(v_source->>'unit_id')::uuid,
    v_line->'quantity',v_source->'conversion_numerator',v_source->'conversion_denominator');
   if v_q<>(v_source->>'quantity')::numeric then v_complete:=false;end if;
   v_gross:=round(v_q*v_price,v_scale);v_discount:=round(v_gross*v_discount/100,v_scale);v_net:=v_gross-v_discount;
   v_tax:=null;v_tax_amount:=0;
   if v_line->>'tax_definition_id' is not null then
    select * into v_tax from finance.tax_definitions where id=(v_line->>'tax_definition_id')::uuid and tenant_id=p_tenant_id
     and legal_entity_id=p_legal_entity_id and status='active' and kind in('input','zero','exempt')
     and v_date>=valid_from and (valid_to is null or v_date<=valid_to);
    if not found then raise exception using errcode='22023',message='INPUT_TAX_INVALID';end if;
    v_tax_amount:=round(v_net*v_tax.rate/(case when v_tax.inclusive then 100+v_tax.rate else 100 end),v_scale);
    if v_tax.inclusive then v_net:=v_net-v_tax_amount;end if;
   end if;
   v_subtotal:=v_subtotal+v_net;v_tax_total:=v_tax_total+v_tax_amount;v_total:=v_total+v_net+v_tax_amount;
   v_lines:=v_lines||jsonb_build_array(jsonb_build_object('source_line_id',v_line_id,'product_id',v_source->>'product_id',
    'description',v_source->>'description','unit_id',v_source->>'unit_id','quantity',v_q::text,'unit_price',v_price::text,
    'discount_percent',coalesce(v_line->>'discount_percent','0'),'discount_amount',v_discount::text,
    'tax_definition_id',v_tax.id,'tax_rate',coalesce(v_tax.rate,0)::text,'tax_inclusive',coalesce(v_tax.inclusive,false),
    'tax_definition_version',v_tax.version,'net_amount',v_net::text,'tax_amount',v_tax_amount::text,'line_total',(v_net+v_tax_amount)::text)||v_unit);
  end loop;
  v_complete:=v_complete and cardinality(v_seen)=(select count(*) from procurement.rfq_lines where rfq_id=v_id);
  insert into procurement.supplier_quotes(id,tenant_id,legal_entity_id,rfq_id,supplier_id,quote_date,valid_until,currency_code,
   exchange_rate_id,exchange_rate,rate_date,payment_terms,delivery_terms,subtotal,tax_total,total,base_total,complete,created_by,updated_by)
  values(v_quote_id,p_tenant_id,p_legal_entity_id,v_id,v_supplier,v_date,v_valid,v_currency,v_rate_id,v_rate,v_rate_date,
   trim(p_payload->>'payment_terms'),trim(p_payload->>'delivery_terms'),v_subtotal,v_tax_total,v_total,round(v_total*v_rate,v_scale),v_complete,auth.uid(),auth.uid())
  on conflict(id) do update set quote_date=excluded.quote_date,valid_until=excluded.valid_until,currency_code=excluded.currency_code,
   exchange_rate_id=excluded.exchange_rate_id,exchange_rate=excluded.exchange_rate,rate_date=excluded.rate_date,
   payment_terms=excluded.payment_terms,delivery_terms=excluded.delivery_terms,subtotal=excluded.subtotal,tax_total=excluded.tax_total,
   total=excluded.total,base_total=excluded.base_total,complete=excluded.complete,version=procurement.supplier_quotes.version+1,
   updated_by=auth.uid(),updated_at=clock_timestamp()
  where procurement.supplier_quotes.rfq_id=v_id and procurement.supplier_quotes.supplier_id=v_supplier and procurement.supplier_quotes.tenant_id=p_tenant_id;
  if not found then raise exception using errcode='22023',message='QUOTE_ID_MISMATCH';end if;
  delete from procurement.supplier_quote_lines where quote_id=v_quote_id;
  insert into procurement.supplier_quote_lines(tenant_id,legal_entity_id,quote_id,source_line_id,detail)
   select p_tenant_id,p_legal_entity_id,v_quote_id,(x->>'source_line_id')::uuid,x from jsonb_array_elements(v_lines) x;
  update procurement.rfqs set version=version+1,updated_by=auth.uid(),updated_at=clock_timestamp() where id=v_id;
 elsif v_operation='select' then
  select * into v_quote from procurement.supplier_quotes where id=(p_payload->>'quote_id')::uuid and rfq_id=v_id;
  if not found or not v_quote.complete or v_quote.valid_until<current_date then raise exception using errcode='55000',message='COMPLETE_VALID_QUOTE_REQUIRED';end if;
  if not exists(select 1 from crm.parties where id=v_quote.supplier_id and tenant_id=p_tenant_id and status='active' and kind in('supplier','both')) then
   raise exception using errcode='22023',message='SUPPLIER_INACTIVE';end if;
  if length(trim(coalesce(p_payload->>'selection_reason',''))) not between 1 and 1000 then raise exception using errcode='22023',message='SELECTION_REASON_REQUIRED';end if;
  update procurement.rfqs set status='selected',selected_quote_id=v_quote.id,selection_reason=trim(p_payload->>'selection_reason'),
   version=version+1,updated_by=auth.uid(),updated_at=clock_timestamp() where id=v_id;
 else raise exception using errcode='22023',message='RFQ_OPERATION_INVALID';end if;
 select detail into v_entity from api.request_for_quotes where id=v_id;
 v_result:=core.wave3_finish_command(p_tenant_id,'procurement.rfq.upsert',p_command_id,'request_for_quote',v_id,
  p_idempotency_key,v_hash,v_before,v_entity,p_legal_entity_id,p_branch_id,'{}',
  case when v_operation='record_quote' then null else jsonb_build_object('from_status',v_rfq.status,'to_status',v_entity->>'status') end,
  jsonb_build_array(jsonb_build_object('topic','procurement.rfq.updated','payload',jsonb_build_object('operation',v_operation))));
 insert into procurement.rfq_history(tenant_id,legal_entity_id,rfq_id,version,snapshot,actor_id)
 values(p_tenant_id,p_legal_entity_id,v_id,(v_entity->>'version')::bigint,v_entity,auth.uid());
 return v_result;
end $$;
revoke all on function api.upsert_request_for_quote(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) from public,anon;
grant execute on function api.upsert_request_for_quote(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) to authenticated;
-- Index every reference without changing indexes on shared tables.
do $$declare c record;begin
 for c in select con.conrelid::regclass tbl,con.conname,
  (select string_agg(quote_ident(a.attname),',' order by k.n) from unnest(con.conkey) with ordinality k(att,n)
   join pg_attribute a on a.attrelid=con.conrelid and a.attnum=k.att) cols
  from pg_constraint con join pg_class t on t.oid=con.conrelid join pg_namespace n on n.oid=t.relnamespace
  where con.contype='f' and n.nspname='procurement' and t.relname in('rfqs','rfq_lines','supplier_quotes','supplier_quote_lines','rfq_history')
 loop execute format('create index %I on %s(%s)',c.conname||'_idx',c.tbl,c.cols);end loop;
end $$;

-- AC-309 / FR-338–339. Additive development candidate; no posting effects.
create table procurement.purchase_orders(
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,branch_id uuid not null,
 supplier_id uuid not null,warehouse_id uuid not null,source_rfq_id uuid,source_quote_id uuid,source_requisition_id uuid,
 source_snapshot jsonb not null,document_date date not null,promised_date date not null,document_number text,
 currency_code text not null references core.currencies(code),exchange_rate_id uuid,exchange_rate numeric(20,10) not null,
 rate_date date not null,payment_terms text not null,delivery_terms text not null,
 subtotal numeric(20,6) not null,tax_total numeric(20,6) not null,total numeric(20,6) not null,base_total numeric(20,6) not null,
 status text not null default 'draft' check(status in('draft','pending_approval','approved','rejected','cancelled','closed')),
 version bigint not null default 1,revision integer not null default 1,revision_reason text,workflow_snapshot jsonb,
 submitted_by uuid references auth.users(id),submitted_at timestamptz,
 created_by uuid not null references auth.users(id),updated_by uuid not null references auth.users(id),
 commercial_editor_id uuid not null references auth.users(id),
 created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
 unique(tenant_id,legal_entity_id,id),unique(source_quote_id),unique(source_rfq_id),
 unique(tenant_id,legal_entity_id,branch_id,document_number),
 foreign key(tenant_id,legal_entity_id,source_rfq_id) references procurement.rfqs(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,legal_entity_id,source_quote_id) references procurement.supplier_quotes(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,legal_entity_id,source_requisition_id) references procurement.requisitions(tenant_id,legal_entity_id,id),
 check((source_rfq_id is not null and source_quote_id is not null and source_requisition_id is null)
  or (source_rfq_id is null and source_quote_id is null and source_requisition_id is not null)),
 foreign key(tenant_id,supplier_id) references crm.parties(tenant_id,id),
 foreign key(tenant_id,warehouse_id) references core.warehouses(tenant_id,id),
 foreign key(tenant_id,branch_id) references core.branches(tenant_id,id),
 foreign key(tenant_id,legal_entity_id,exchange_rate_id) references finance.exchange_rates(tenant_id,legal_entity_id,id),
 check(promised_date>=document_date),check(exchange_rate>0),check(subtotal>=0 and tax_total>=0 and total>=0 and base_total>=0),
 check(length(trim(payment_terms)) between 1 and 1000 and length(trim(delivery_terms)) between 1 and 1000)
);
create table procurement.purchase_order_lines(
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,order_id uuid not null,
 source_line_id uuid not null,product_id uuid,unit_id uuid not null,description text not null,
 quantity numeric(20,6) not null,unit_price numeric(20,6) not null,discount_percent numeric(9,6) not null,
 cancelled_quantity numeric(20,6) not null default 0,received_quantity numeric(20,6) not null default 0,
 billed_quantity numeric(20,6) not null default 0,detail jsonb not null,
 approved_extra_quantity numeric(20,6) not null default 0 check(approved_extra_quantity>=0),
 unique(tenant_id,legal_entity_id,id),unique(order_id,source_line_id),
 foreign key(tenant_id,legal_entity_id,order_id) references procurement.purchase_orders(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,legal_entity_id,product_id) references inventory.products(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,unit_id) references inventory.units(tenant_id,id),
 check(quantity>0 and unit_price>=0 and discount_percent between 0 and 100),
 check(cancelled_quantity>=0 and received_quantity>=0 and billed_quantity>=0),
 constraint purchase_order_lines_received_limit check(cancelled_quantity+received_quantity<=quantity+approved_extra_quantity)
);
create index purchase_orders_scope_page on procurement.purchase_orders(tenant_id,legal_entity_id,branch_id,id);
create index purchase_orders_scope_status on procurement.purchase_orders(tenant_id,legal_entity_id,branch_id,status,id);
create index purchase_orders_supplier on procurement.purchase_orders(tenant_id,legal_entity_id,supplier_id,status,id);
create table procurement.purchase_order_revisions(
 id uuid primary key default gen_random_uuid(),tenant_id uuid not null,legal_entity_id uuid not null,
 order_id uuid not null,version bigint not null,revision integer not null,snapshot jsonb not null,
 actor_id uuid not null references auth.users(id),created_at timestamptz not null default now(),
 unique(order_id,version),foreign key(tenant_id,legal_entity_id,order_id) references procurement.purchase_orders(tenant_id,legal_entity_id,id)
);
create function procurement.order_read_allowed(p_tenant uuid,p_entity uuid,p_order uuid) returns boolean
language sql stable security definer set search_path='' as $$select exists(select 1 from procurement.purchase_orders o
 where o.id=p_order and o.tenant_id=p_tenant and o.legal_entity_id=p_entity
 and core.has_permission(o.tenant_id,'procurement.orders.manage',o.legal_entity_id,o.branch_id))$$;
alter table procurement.purchase_orders enable row level security;alter table procurement.purchase_orders force row level security;
create policy order_read on procurement.purchase_orders for select to authenticated using(procurement.order_read_allowed(tenant_id,legal_entity_id,id));
do $$declare t text;begin
 foreach t in array array['purchase_order_lines','purchase_order_revisions'] loop
  execute format('alter table procurement.%I enable row level security',t);
  execute format('alter table procurement.%I force row level security',t);
  execute format('create policy order_read on procurement.%I for select to authenticated using(procurement.order_read_allowed(tenant_id,legal_entity_id,order_id))',t);
 end loop;
end $$;
create trigger order_revisions_immutable before update or delete on procurement.purchase_order_revisions
 for each row execute function workflow.reject_history_mutation();
revoke all on procurement.purchase_orders,procurement.purchase_order_lines,procurement.purchase_order_revisions from public,anon,authenticated;
grant select on procurement.purchase_orders,procurement.purchase_order_lines,procurement.purchase_order_revisions to authenticated;
revoke all on function procurement.order_read_allowed(uuid,uuid,uuid) from public,anon;
grant execute on function procurement.order_read_allowed(uuid,uuid,uuid) to authenticated;
create view api.purchase_orders with(security_invoker=true) as
select o.tenant_id,o.legal_entity_id,o.branch_id,o.id,o.status,
 sales.flow_exact_json(to_jsonb(o))||jsonb_build_object('lines',coalesce((select jsonb_agg(l.detail||jsonb_build_object(
  'line_id',l.id,'source_line_id',l.source_line_id,'quantity',l.quantity::text,'unit_price',l.unit_price::text,
  'cancelled_quantity',l.cancelled_quantity::text,'received_quantity',l.received_quantity::text,
  'billed_quantity',l.billed_quantity::text,'approved_extra_quantity',l.approved_extra_quantity::text,
  'remaining_quantity',greatest(0,l.quantity-l.cancelled_quantity-l.received_quantity)::text) order by l.id)
  from procurement.purchase_order_lines l where l.order_id=o.id),'[]')) detail from procurement.purchase_orders o;
grant select on api.purchase_orders to authenticated;
create function procurement.record_order_history(p_result jsonb) returns void language sql security definer set search_path='' as $$
 insert into procurement.purchase_order_revisions(tenant_id,legal_entity_id,order_id,version,revision,snapshot,actor_id)
 select (e->>'tenant_id')::uuid,(e->>'legal_entity_id')::uuid,(e->>'id')::uuid,(e->>'version')::bigint,
 (e->>'revision')::integer,e,auth.uid() from (select p_result->'entity' e) x
 on conflict(order_id,version) do nothing
$$;
revoke all on function procurement.record_order_history(jsonb) from public,anon,authenticated;

create function api.upsert_purchase_order(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,
 p_command_id uuid,p_idempotency_key uuid,p_client_timestamp timestamptz,p_payload jsonb,p_expected_entity_version bigint default null)
returns jsonb language plpgsql security definer set search_path='' as $$
declare
 v_id uuid:=(p_payload->>'id')::uuid;v_command text:='procurement.order.upsert';v_hash text;v_result jsonb;v_before jsonb;v_entity jsonb;
 v_doc procurement.purchase_orders%rowtype;v_rfq procurement.rfqs%rowtype;v_quote procurement.supplier_quotes%rowtype;v_req procurement.requisitions%rowtype;v_source procurement.requisition_lines%rowtype;
 v_line jsonb;v_unit jsonb;v_old procurement.purchase_order_lines%rowtype;v_lines jsonb;v_snapshot jsonb;v_seen uuid[]:='{}';v_line_id uuid;
 v_supplier uuid;v_currency text;v_rate numeric;v_rate_id uuid;v_rate_date date;v_date date;v_promised date;v_warehouse uuid;
 v_q numeric;v_price numeric;v_discount numeric;v_gross numeric;v_net numeric;v_tax_amount numeric;v_tax finance.tax_definitions%rowtype;
 v_subtotal numeric:=0;v_tax_total numeric:=0;v_total numeric:=0;v_base text;v_scale integer;v_terms text;v_delivery text;
begin
 perform core.wave3_require_scope(p_tenant_id,'procurement.orders.manage',p_legal_entity_id,p_branch_id);
 if p_legal_entity_id is null or p_branch_id is null or p_client_timestamp is null or v_id is null
 or jsonb_typeof(p_payload) is distinct from 'object' then raise exception using errcode='22023',message='INVALID_COMMAND';end if;
 v_hash:=core.wave3_request_hash(v_command,p_command_id,p_tenant_id,p_legal_entity_id,p_branch_id,p_payload,p_expected_entity_version);
 v_result:=core.wave3_replay(p_tenant_id,v_command,p_command_id,p_idempotency_key,v_hash);
 if v_result is not null then return v_result;end if;
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('procurement.order:'||v_id::text,0));
 select * into v_doc from procurement.purchase_orders where id=v_id and tenant_id=p_tenant_id
 and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id for update;
 if found then
  select detail into v_before from api.purchase_orders where id=v_id;
  perform core.wave3_assert_expected_version(v_doc.version,p_expected_entity_version,v_before);
  if v_doc.status<>'draft' then raise exception using errcode='55000',message='ORDER_NOT_EDITABLE';end if;
  if (p_payload->>'source_rfq_id')::uuid is distinct from v_doc.source_rfq_id or (p_payload->>'source_quote_id')::uuid is distinct from v_doc.source_quote_id
   or (p_payload->>'source_requisition_id')::uuid is distinct from v_doc.source_requisition_id then
   raise exception using errcode='22023',message='SOURCE_IMMUTABLE';end if;
  v_lines:=p_payload->'lines';v_supplier:=(p_payload->>'supplier_id')::uuid;v_currency:=p_payload->>'currency_code';
  v_rate:=sales.wave3_decimal_string(p_payload->'exchange_rate','exchange_rate',10,true,0,null);
  v_rate_id:=(p_payload->>'exchange_rate_id')::uuid;v_rate_date:=(p_payload->>'rate_date')::date;
  v_terms:=trim(p_payload->>'payment_terms');v_delivery:=trim(p_payload->>'delivery_terms');
 else
  if p_expected_entity_version is not null then raise exception using errcode='40001',message='VERSION_CONFLICT';end if;
  if p_payload->>'source_rfq_id' is null then
   select * into v_req from procurement.requisitions where id=(p_payload->>'source_requisition_id')::uuid and tenant_id=p_tenant_id
    and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id for share;
   if not found or v_req.status<>'approved' then raise exception using errcode='55000',message='APPROVED_REQUISITION_REQUIRED';end if;
   perform core.wave3_assert_expected_version(v_req.version,(p_payload->>'source_requisition_version')::bigint,'{}');
   select detail into v_snapshot from api.purchase_requisitions where id=v_req.id;
   v_lines:=p_payload->'lines';v_supplier:=(p_payload->>'supplier_id')::uuid;v_currency:=p_payload->>'currency_code';
   v_rate:=sales.wave3_decimal_string(p_payload->'exchange_rate','exchange_rate',10,true,0,null);
   v_rate_id:=(p_payload->>'exchange_rate_id')::uuid;v_rate_date:=(p_payload->>'rate_date')::date;
   v_terms:=trim(p_payload->>'payment_terms');v_delivery:=trim(p_payload->>'delivery_terms');
  else
  select * into v_rfq from procurement.rfqs where id=(p_payload->>'source_rfq_id')::uuid and tenant_id=p_tenant_id
   and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id for update;
  if v_rfq.status='ordered' then raise exception using errcode='55000',message='RFQ_ALREADY_ORDERED';end if;
  if v_rfq.id is null or v_rfq.status<>'selected' then raise exception using errcode='55000',message='SELECTED_RFQ_REQUIRED';end if;
  perform core.wave3_assert_expected_version(v_rfq.version,(p_payload->>'source_rfq_version')::bigint,'{}');
  select * into v_quote from procurement.supplier_quotes where id=v_rfq.selected_quote_id and rfq_id=v_rfq.id;
  if v_quote.id is distinct from (p_payload->>'source_quote_id')::uuid or not v_quote.complete or v_quote.valid_until<current_date then
   raise exception using errcode='55000',message='SELECTED_QUOTE_REQUIRED';end if;
  perform core.wave3_assert_expected_version(v_quote.version,(p_payload->>'source_quote_version')::bigint,'{}');
  select detail into v_snapshot from api.request_for_quotes where id=v_rfq.id;
  select jsonb_agg(detail||jsonb_build_object('line_id',gen_random_uuid())) into v_lines from procurement.supplier_quote_lines where quote_id=v_quote.id;
  v_supplier:=v_quote.supplier_id;v_currency:=v_quote.currency_code;v_rate:=v_quote.exchange_rate;v_rate_id:=v_quote.exchange_rate_id;
  v_rate_date:=v_quote.rate_date;v_terms:=v_quote.payment_terms;v_delivery:=v_quote.delivery_terms;
  end if;
 end if;
 v_warehouse:=(p_payload->>'warehouse_id')::uuid;v_date:=(p_payload->>'document_date')::date;v_promised:=(p_payload->>'promised_date')::date;
 if not exists(select 1 from core.warehouses where id=v_warehouse and tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id and status='active') then
  raise exception using errcode='22023',message='WAREHOUSE_INVALID';end if;
 if not exists(select 1 from crm.parties where id=v_supplier and tenant_id=p_tenant_id and status='active' and kind in('supplier','both')) then
  raise exception using errcode='22023',message='SUPPLIER_INVALID';end if;
 select currency_code,rounding_scale into v_base,v_scale from core.legal_entities where id=p_legal_entity_id and tenant_id=p_tenant_id;
 if v_rate<=0 or not exists(select 1 from core.currencies where code=v_currency and active) then raise exception using errcode='22023',message='CURRENCY_INVALID';end if;
 if v_currency=v_base then
  if v_rate<>1 or v_rate_id is not null then raise exception using errcode='22023',message='BASE_RATE_MUST_BE_ONE';end if;
 elsif not exists(select 1 from finance.exchange_rates where id=v_rate_id and tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id
  and status='active' and source_currency_code=v_currency and target_currency_code=v_base and rate=v_rate and effective_date=v_rate_date) then
  raise exception using errcode='22023',message='RATE_SNAPSHOT_INVALID';end if;
 if v_doc.id is not null and (v_doc.supplier_id<>v_supplier or v_doc.currency_code<>v_currency or v_doc.warehouse_id<>v_warehouse)
 and exists(select 1 from procurement.purchase_order_lines where order_id=v_id and (received_quantity>0 or billed_quantity>0)) then
  raise exception using errcode='55000',message='RECEIVED_ORDER_IDENTITY_IMMUTABLE';end if;
 if jsonb_typeof(v_lines) is distinct from 'array' or jsonb_array_length(v_lines) not between 1 and 500 then
  raise exception using errcode='22023',message='ORDER_LINES_REQUIRED';end if;
 if v_doc.id is null then
  insert into procurement.purchase_orders(id,tenant_id,legal_entity_id,branch_id,supplier_id,warehouse_id,source_rfq_id,source_quote_id,source_requisition_id,
   source_snapshot,document_date,promised_date,currency_code,exchange_rate_id,exchange_rate,rate_date,payment_terms,delivery_terms,
   subtotal,tax_total,total,base_total,created_by,updated_by,commercial_editor_id)
  values(v_id,p_tenant_id,p_legal_entity_id,p_branch_id,v_supplier,v_warehouse,v_rfq.id,v_quote.id,v_req.id,v_snapshot,v_date,v_promised,
   v_currency,v_rate_id,v_rate,v_rate_date,v_terms,v_delivery,0,0,0,0,auth.uid(),auth.uid(),auth.uid());
 end if;
 for v_line in select value from jsonb_array_elements(v_lines) loop
  if v_req.id is not null then
   select * into v_source from procurement.requisition_lines where requisition_id=v_req.id and id=(v_line->>'source_line_id')::uuid;
   if not found then raise exception using errcode='22023',message='REQUISITION_SOURCE_LINE_INVALID';end if;
   v_line:=v_line||jsonb_build_object('product_id',v_source.product_id,'unit_id',v_source.unit_id,'description',v_source.description,
    'conversion_numerator',v_source.conversion_numerator::text,'conversion_denominator',v_source.conversion_denominator::text);
  end if;
  v_line_id:=(v_line->>'line_id')::uuid;
  if v_line_id is null or v_line_id=any(v_seen) then raise exception using errcode='22023',message='ORDER_LINE_ID_INVALID';end if;
  v_seen:=array_append(v_seen,v_line_id);
  select * into v_old from procurement.purchase_order_lines where id=v_line_id and order_id=v_id for update;
  if v_doc.id is not null and not found then raise exception using errcode='22023',message='ORDER_LINE_ID_INVALID';end if;
  if v_old.id is not null and ((v_line->>'source_line_id')::uuid is distinct from v_old.source_line_id
   or (v_line->>'product_id')::uuid is distinct from v_old.product_id or (v_line->>'unit_id')::uuid is distinct from v_old.unit_id) then
   raise exception using errcode='22023',message='SOURCE_LINE_IMMUTABLE';end if;
  v_q:=sales.wave3_decimal_string(v_line->'quantity','quantity',6,true,0,null);
  v_price:=sales.wave3_decimal_string(v_line->'unit_price','unit_price',6,true,0,null);
  v_discount:=sales.wave3_decimal_string(v_line->'discount_percent','discount_percent',6,true,0,100);
  if v_q<=0 or v_q<coalesce(v_old.received_quantity,0)+coalesce(v_old.cancelled_quantity,0) or v_q<coalesce(v_old.billed_quantity,0) then
   raise exception using errcode='22023',message='ORDER_QUANTITY_INVALID';end if;
  if not exists(select 1 from inventory.units where id=(v_line->>'unit_id')::uuid and tenant_id=p_tenant_id and status='active' and round(v_q,precision)=v_q)
  or (v_line->>'product_id' is not null and not exists(select 1 from inventory.products where id=(v_line->>'product_id')::uuid
   and tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and status='active' and can_purchase)) then
   raise exception using errcode='22023',message='PRODUCT_UNIT_INVALID';end if;
  v_unit:=inventory.resolve_product_unit(p_tenant_id,p_legal_entity_id,(v_line->>'product_id')::uuid,(v_line->>'unit_id')::uuid,
    v_line->'quantity',coalesce(v_old.detail->'conversion_numerator',v_line->'conversion_numerator'),coalesce(v_old.detail->'conversion_denominator',v_line->'conversion_denominator'));
  v_gross:=round(v_q*v_price,v_scale);v_discount:=round(v_gross*v_discount/100,v_scale);v_net:=v_gross-v_discount;v_tax_amount:=0;v_tax:=null;
  if v_line->>'tax_definition_id' is not null then
   select * into v_tax from finance.tax_definitions where id=(v_line->>'tax_definition_id')::uuid and tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id
    and status='active' and kind in('input','zero','exempt') and v_date>=valid_from and (valid_to is null or v_date<=valid_to);
   if not found then raise exception using errcode='22023',message='INPUT_TAX_INVALID';end if;
   v_tax_amount:=round(v_net*v_tax.rate/(case when v_tax.inclusive then 100+v_tax.rate else 100 end),v_scale);
   if v_tax.inclusive then v_net:=v_net-v_tax_amount;end if;
  end if;
  v_subtotal:=v_subtotal+v_net;v_tax_total:=v_tax_total+v_tax_amount;v_total:=v_total+v_net+v_tax_amount;
  v_line:=v_line||jsonb_build_object('discount_amount',v_discount::text,'tax_rate',coalesce(v_tax.rate,0)::text,
   'tax_inclusive',coalesce(v_tax.inclusive,false),'tax_definition_version',v_tax.version,
   'net_amount',v_net::text,'tax_amount',v_tax_amount::text,'line_total',(v_net+v_tax_amount)::text)||v_unit;
  insert into procurement.purchase_order_lines(id,tenant_id,legal_entity_id,order_id,source_line_id,product_id,unit_id,description,quantity,unit_price,discount_percent,detail)
  values(v_line_id,p_tenant_id,p_legal_entity_id,v_id,(v_line->>'source_line_id')::uuid,(v_line->>'product_id')::uuid,(v_line->>'unit_id')::uuid,
   v_line->>'description',v_q,v_price,(v_line->>'discount_percent')::numeric,v_line)
  on conflict(id) do update set quantity=excluded.quantity,unit_price=excluded.unit_price,discount_percent=excluded.discount_percent,detail=excluded.detail
  where procurement.purchase_order_lines.order_id=v_id;
  if not found then raise exception using errcode='22023',message='ORDER_LINE_ID_INVALID';end if;
 end loop;
 if exists(select 1 from procurement.purchase_order_lines where order_id=v_id and not(id=any(v_seen))) then raise exception using errcode='22023',message='ORDER_LINES_MUST_BE_RETAINED';end if;
 update procurement.purchase_orders set supplier_id=v_supplier,warehouse_id=v_warehouse,document_date=v_date,promised_date=v_promised,
  currency_code=v_currency,exchange_rate_id=v_rate_id,exchange_rate=v_rate,rate_date=v_rate_date,payment_terms=v_terms,delivery_terms=v_delivery,
  subtotal=v_subtotal,tax_total=v_tax_total,total=v_total,base_total=round(v_total*v_rate,v_scale),
  version=case when v_doc.id is null then version else version+1 end,updated_at=clock_timestamp(),updated_by=auth.uid(),commercial_editor_id=auth.uid() where id=v_id;
 if v_doc.id is null and v_rfq.id is not null then
  update procurement.rfqs set status='ordered',version=version+1,updated_by=auth.uid(),updated_at=clock_timestamp() where id=v_rfq.id;
  insert into procurement.rfq_history(tenant_id,legal_entity_id,rfq_id,version,snapshot,actor_id)
  select tenant_id,legal_entity_id,id,(detail->>'version')::bigint,detail,auth.uid() from api.request_for_quotes where id=v_rfq.id;
 end if;
 select detail into v_entity from api.purchase_orders where id=v_id;
 v_result:=core.wave3_finish_command(p_tenant_id,v_command,p_command_id,'purchase_order',v_id,p_idempotency_key,v_hash,v_before,v_entity,
  p_legal_entity_id,p_branch_id,'{}',null,jsonb_build_array(jsonb_build_object('topic','procurement.order.saved','payload','{}'::jsonb)));
 perform procurement.record_order_history(v_result);return v_result;
end $$;
revoke all on function api.upsert_purchase_order(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) from public,anon;
grant execute on function api.upsert_purchase_order(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) to authenticated;

create function api.transition_purchase_order(
 p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_command_id uuid,p_idempotency_key uuid,
 p_client_timestamp timestamptz,p_payload jsonb,p_expected_entity_version bigint default null)
returns jsonb language plpgsql security definer set search_path='' as $$
declare
 v_actor uuid:=auth.uid();v_id uuid;v_action text:=p_payload->>'action';v_decision text:=p_payload->>'decision';
 v_command text:='procurement.order.transition';v_hash text;v_result jsonb;v_before jsonb;v_entity jsonb;
 v_doc procurement.purchase_orders%rowtype;v_workflow workflow.workflow_definitions%rowtype;
 v_ar workflow.approval_requests%rowtype;v_snapshot jsonb;v_step jsonb;v_first integer;v_to text;
 v_request uuid:=gen_random_uuid();v_reason text:=nullif(trim(coalesce(p_payload->>'reason',p_payload->>'note')),'');
begin
 perform core.wave3_require_scope(p_tenant_id,'procurement.orders.manage',p_legal_entity_id,p_branch_id);
 if p_legal_entity_id is null or p_branch_id is null or p_client_timestamp is null
 or jsonb_typeof(p_payload) is distinct from 'object' or (v_action is null)=(v_decision is null) then
 raise exception using errcode='22023',message='INVALID_COMMAND';end if;
 if v_decision is not null then
  perform core.require_permission(p_tenant_id,'workflow.approvals.decide',p_legal_entity_id,p_branch_id);
 end if;
 v_id:=(p_payload->>'document_id')::uuid;
 v_hash:=core.wave3_request_hash(v_command,p_command_id,p_tenant_id,p_legal_entity_id,p_branch_id,p_payload,p_expected_entity_version);
 v_result:=core.wave3_replay(p_tenant_id,v_command,p_command_id,p_idempotency_key,v_hash);
 if v_result is not null then return v_result;end if;
 select * into v_doc from procurement.purchase_orders where id=v_id and tenant_id=p_tenant_id
 and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id for update;
 if not found then raise exception using errcode='P0002',message='DOCUMENT_NOT_FOUND';end if;
 select detail into v_before from api.purchase_orders where id=v_id;
 perform core.wave3_assert_expected_version(v_doc.version,p_expected_entity_version,v_before);
 v_snapshot:=v_doc.workflow_snapshot;
 if v_action='submit' then
  if v_doc.status<>'draft' then raise exception using errcode='55000',message='ORDER_NOT_EDITABLE';end if;
  if not exists(select 1 from crm.parties where id=v_doc.supplier_id and tenant_id=p_tenant_id and status='active' and kind in('supplier','both'))
  or not exists(select 1 from core.warehouses where id=v_doc.warehouse_id and tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id and status='active')
  or exists(select 1 from procurement.purchase_order_lines l left join inventory.units u on u.id=l.unit_id and u.tenant_id=l.tenant_id
    left join inventory.products p on p.id=l.product_id and p.tenant_id=l.tenant_id and p.legal_entity_id=l.legal_entity_id
    where l.order_id=v_id and (u.status is distinct from 'active' or round(l.quantity,u.precision)<>l.quantity
    or (l.product_id is not null and (p.status is distinct from 'active' or not p.can_purchase)))) then
   raise exception using errcode='22023',message='REFERENCE_INVALID';end if;
  perform inventory.resolve_product_unit(p_tenant_id,p_legal_entity_id,l.product_id,l.unit_id,to_jsonb(l.quantity::text),
   l.detail->'conversion_numerator',l.detail->'conversion_denominator') from procurement.purchase_order_lines l where l.order_id=v_id;
  select * into v_workflow from workflow.workflow_definitions where tenant_id=p_tenant_id
   and document_type='purchase_order' and status='active' and (legal_entity_id is null or legal_entity_id=p_legal_entity_id)
   order by (legal_entity_id is not null) desc,revision desc,id limit 1;
  if not found then raise exception using errcode='55000',message='WORKFLOW_CONFIGURATION_ERROR';end if;
  select jsonb_build_object('definition_id',v_workflow.id,'revision',v_workflow.revision,'lifecycle',v_workflow.lifecycle,
   'steps',coalesce(jsonb_agg(sales.flow_exact_json(to_jsonb(s)) order by s.step_order),'[]'::jsonb)) into v_snapshot
   from workflow.approval_matrix_steps s where s.tenant_id=p_tenant_id and s.workflow_definition_id=v_workflow.id and s.status='active'
   and (s.currency_code is null or s.currency_code=v_doc.currency_code)
   and (s.minimum_amount is null or s.minimum_amount<=v_doc.total)
   and (s.maximum_amount is null or s.maximum_amount>=v_doc.total);
  select min((x->>'step_order')::integer) into v_first from jsonb_array_elements(v_snapshot->'steps') x;
  if v_first is null and v_workflow.lifecycle->'requires_approval' is distinct from 'false'::jsonb then
   raise exception using errcode='55000',message='WORKFLOW_CONFIGURATION_ERROR';end if;
  perform sales.flow_assert_transition(v_workflow.lifecycle,'draft','submitted');
  v_to:=case when v_first is null then 'approved' else 'pending_approval' end;
  if v_first is null then perform sales.flow_assert_transition(v_workflow.lifecycle,'submitted','approved');end if;
  v_doc.document_number:=coalesce(v_doc.document_number,sales.wave3_reserve_document_number(p_tenant_id,p_legal_entity_id,
    p_branch_id,'purchase_order',v_doc.document_date,v_actor));
  if v_first is not null then
   insert into workflow.approval_requests(tenant_id,legal_entity_id,branch_id,document_type,document_id,status,
    submitted_by,workflow_definition_id,workflow_revision,current_step,amount,currency_code,command_id,request_id,correlation_id)
   values(p_tenant_id,p_legal_entity_id,p_branch_id,'purchase_order',v_id,'submitted',v_actor,
    v_workflow.id,v_workflow.revision,v_first,v_doc.total,v_doc.currency_code,p_command_id,v_request,v_request);
  end if;
 elsif v_decision is not null then
  if v_doc.status<>'pending_approval' or v_decision not in ('approved','rejected') then
   raise exception using errcode='55000',message='APPROVAL_NOT_PENDING';end if;
  select * into v_ar from workflow.approval_requests where tenant_id=p_tenant_id and document_type='purchase_order'
   and document_id=v_id and status='submitted' for update;
  if not found then raise exception using errcode='55000',message='APPROVAL_REQUEST_NOT_FOUND';end if;
  if v_actor in(v_doc.created_by,v_doc.commercial_editor_id,v_doc.submitted_by) then
   raise exception using errcode='42501',message='SEGREGATION_OF_DUTIES_VIOLATION';end if;
  select x into v_step from jsonb_array_elements(v_snapshot->'steps') x where (x->>'step_order')::integer=v_ar.current_step;
  if v_step is null or not exists(select 1 from core.memberships m
   join core.role_assignments ra on ra.membership_id=m.id and ra.tenant_id=m.tenant_id
   join core.roles r on r.id=ra.role_id and r.tenant_id=m.tenant_id
   where m.tenant_id=p_tenant_id and m.user_id=v_actor and m.status='active' and ra.role_id=(v_step->>'role_id')::uuid
   and (ra.legal_entity_id is null or ra.legal_entity_id=p_legal_entity_id) and (ra.branch_id is null or ra.branch_id=p_branch_id)
   and (not r.requires_mfa or auth.jwt()->>'aal'='aal2')) then
   raise exception using errcode='42501',message='APPROVAL_ROLE_REQUIRED';end if;
  if v_decision='rejected' and v_reason is null then raise exception using errcode='22023',message='REASON_REQUIRED';end if;
  perform sales.flow_assert_transition(v_snapshot->'lifecycle','submitted',v_decision);
  insert into workflow.approval_decisions(tenant_id,approval_request_id,workflow_definition_id,workflow_revision,
   approval_matrix_step_id,step_order,actor_id,decision,note,amount,currency_code,request_id,command_id,correlation_id)
  values(p_tenant_id,v_ar.id,v_ar.workflow_definition_id,v_ar.workflow_revision,(v_step->>'id')::uuid,v_ar.current_step,
   v_actor,v_decision,v_reason,v_ar.amount,v_ar.currency_code,v_request,p_command_id,v_request);
  if v_decision='approved' then
   select min((x->>'step_order')::integer) into v_first from jsonb_array_elements(v_snapshot->'steps') x
    where (x->>'step_order')::integer>v_ar.current_step;
  end if;
  v_to:=case when v_decision='rejected' then 'rejected' when v_first is null then 'approved' else 'pending_approval' end;
  update workflow.approval_requests set current_step=coalesce(v_first,current_step),
   status=case when v_first is null then v_to else status end,
   decision_by=case when v_first is null then v_actor else decision_by end,
   decision_note=case when v_first is null then v_reason else decision_note end,
   decided_at=case when v_first is null then clock_timestamp() else decided_at end where id=v_ar.id;
 elsif v_action='revise' then
  if v_doc.status<>'approved' then raise exception using errcode='55000',message='APPROVED_ORDER_REQUIRED';end if;
  if v_reason is null or length(v_reason)>1000 then raise exception using errcode='22023',message='REVISION_REASON_REQUIRED';end if;
  v_to:='draft';v_snapshot:=null;
  update procurement.purchase_orders set revision=revision+1,revision_reason=v_reason,commercial_editor_id=v_actor where id=v_id;
 elsif v_action in('recall','cancel') then
  if v_reason is null then raise exception using errcode='22023',message='REASON_REQUIRED';end if;
  if v_action='recall' and v_doc.status not in('pending_approval','rejected') then
   raise exception using errcode='55000',message='ORDER_NOT_RECALLABLE';end if;
  if v_snapshot is null then
   select jsonb_build_object('lifecycle',lifecycle) into v_snapshot from workflow.workflow_definitions
    where tenant_id=p_tenant_id and document_type='purchase_order' and status='active'
    and (legal_entity_id is null or legal_entity_id=p_legal_entity_id)
    order by (legal_entity_id is not null) desc,revision desc,id limit 1;
  end if;
  v_to:=case when v_action='recall' then 'draft' else 'cancelled' end;
  perform sales.flow_assert_transition(v_snapshot->'lifecycle',v_doc.status,v_to);
  update workflow.approval_requests set status='cancelled',decision_by=v_actor,decision_note=v_reason,decided_at=clock_timestamp()
   where tenant_id=p_tenant_id and document_type='purchase_order' and document_id=v_id and status='submitted';
  if v_action='recall' then v_snapshot:=null;end if;
  if v_action='cancel' then
   update procurement.purchase_order_lines set cancelled_quantity=greatest(0,quantity-greatest(received_quantity,billed_quantity)) where order_id=v_id;
  end if;
 else raise exception using errcode='22023',message='INVALID_COMMAND';end if;
 update procurement.purchase_orders set status=v_to,version=version+1,updated_at=clock_timestamp(),updated_by=v_actor,
  workflow_snapshot=v_snapshot,document_number=v_doc.document_number,
  submitted_by=case when v_action='submit' then v_actor else submitted_by end,
  submitted_at=case when v_action='submit' then clock_timestamp() else submitted_at end where id=v_id;
 select detail into v_entity from api.purchase_orders where id=v_id;
 v_result:=core.wave3_finish_command(p_tenant_id,v_command,p_command_id,'purchase_order',v_id,
  p_idempotency_key,v_hash,v_before,v_entity,p_legal_entity_id,p_branch_id,'{}',
  case when v_doc.status=v_to then null else jsonb_build_object('from_status',v_doc.status,'to_status',v_to,'reason',v_reason) end,
  jsonb_build_array(jsonb_build_object('topic',v_command,'payload',jsonb_build_object('status',v_to))),'[]',v_request,v_request);
 perform procurement.record_order_history(v_result);return v_result;
end $$;
revoke all on function api.transition_purchase_order(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) from public,anon;
grant execute on function api.transition_purchase_order(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) to authenticated;

-- Reference indexes remain module-owned.
do $$declare c record;begin
 for c in select con.conrelid::regclass tbl,con.conname,
  (select string_agg(quote_ident(a.attname),',' order by k.n) from unnest(con.conkey) with ordinality k(att,n)
   join pg_attribute a on a.attrelid=con.conrelid and a.attnum=k.att) cols
  from pg_constraint con join pg_class t on t.oid=con.conrelid join pg_namespace n on n.oid=t.relnamespace
  where con.contype='f' and n.nspname='procurement' and t.relname in('purchase_orders','purchase_order_lines','purchase_order_revisions')
 loop execute format('create index %I on %s(%s)',c.conname||'_idx',c.tbl,c.cols);end loop;
end $$;


-- AC-310 candidate. Reuses established inventory and journal tables; no business seed data.
create table procurement.receipt_controls(
 tenant_id uuid not null,legal_entity_id uuid primary key,grni_account_id uuid not null,expense_account_id uuid not null,
 maximum_over_receipt_percent numeric(9,6) not null default 0 check(maximum_over_receipt_percent between 0 and 100),
 version bigint not null default 1,updated_by uuid not null references auth.users(id),updated_at timestamptz not null default now(),
 foreign key(tenant_id,legal_entity_id) references core.legal_entities(tenant_id,id),
 foreign key(tenant_id,legal_entity_id,grni_account_id) references finance.accounts(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,legal_entity_id,expense_account_id) references finance.accounts(tenant_id,legal_entity_id,id)
);
create table procurement.receipt_control_history(
 id uuid primary key default gen_random_uuid(),tenant_id uuid not null,legal_entity_id uuid not null,version bigint not null,
 snapshot jsonb not null,actor_id uuid not null references auth.users(id),created_at timestamptz not null default now(),
 unique(legal_entity_id,version),foreign key(tenant_id,legal_entity_id) references core.legal_entities(tenant_id,id)
);
create table procurement.goods_receipts(
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,branch_id uuid not null,order_id uuid not null,
 order_revision integer not null,warehouse_id uuid not null,document_date date not null,document_number text not null,
 reference text not null,source_snapshot jsonb not null,currency_code text not null,base_currency_code text not null,
 exchange_rate numeric(20,10) not null,net_amount numeric(20,6) not null,base_amount numeric(20,6) not null,
 stock_movement_id uuid,journal_entry_id uuid,request_id uuid not null,command_id uuid not null,
 created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),
 unique(tenant_id,id),unique(tenant_id,legal_entity_id,branch_id,document_number),
 foreign key(tenant_id,legal_entity_id,order_id) references procurement.purchase_orders(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,warehouse_id) references core.warehouses(tenant_id,id),
 foreign key(tenant_id,stock_movement_id) references inventory.stock_movements(tenant_id,id),
 foreign key(tenant_id,journal_entry_id) references finance.journal_entries(tenant_id,id)
);
create table procurement.receipt_allowances(
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,branch_id uuid not null,
 order_id uuid not null,order_line_id uuid not null,order_version bigint not null,
 maximum_received_quantity numeric(20,6) not null,control_version bigint not null,reason text not null,
 approved_by uuid not null references auth.users(id),created_at timestamptz not null default now(),
 unique(order_line_id,order_version),
 foreign key(tenant_id,legal_entity_id,order_id) references procurement.purchase_orders(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,legal_entity_id,order_line_id) references procurement.purchase_order_lines(tenant_id,legal_entity_id,id)
);
alter table procurement.receipt_allowances enable row level security;
alter table procurement.receipt_allowances force row level security;
create policy allowance_read on procurement.receipt_allowances for select to authenticated using(
 core.is_tenant_member(tenant_id) and core.has_permission(tenant_id,'procurement.receipts.post',legal_entity_id,branch_id));
create trigger allowance_immutable before update or delete on procurement.receipt_allowances
 for each row execute function workflow.reject_history_mutation();
revoke all on procurement.receipt_allowances from public,anon,authenticated;
grant select on procurement.receipt_allowances to authenticated;
create index receipt_allowances_order on procurement.receipt_allowances(tenant_id,legal_entity_id,order_id,order_version);
create function api.approve_receipt_allowance(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_command_id uuid,
 p_idempotency_key uuid,p_client_timestamp timestamptz,p_payload jsonb,p_expected_entity_version bigint default null)
returns jsonb language plpgsql security definer set search_path='' as $$
declare v_command text:='procurement.receipt_allowance.approve';v_hash text;v_result jsonb;v_po procurement.purchase_orders%rowtype;
 v_l procurement.purchase_order_lines%rowtype;v_c procurement.receipt_controls%rowtype;v_extra numeric;v_max numeric;v_id uuid:=(p_payload->>'id')::uuid;
begin
 perform core.wave3_require_scope(p_tenant_id,'procurement.receipts.post',p_legal_entity_id,p_branch_id);
 perform core.wave3_require_scope(p_tenant_id,'workflow.approvals.decide',p_legal_entity_id,p_branch_id);
 if v_id is null or p_client_timestamp is null or coalesce(length(trim(p_payload->>'reason')),0) not between 1 and 1000 then raise exception using errcode='22023',message='ALLOWANCE_REASON_REQUIRED';end if;
 v_hash:=core.wave3_request_hash(v_command,p_command_id,p_tenant_id,p_legal_entity_id,p_branch_id,p_payload,p_expected_entity_version);
 v_result:=core.wave3_replay(p_tenant_id,v_command,p_command_id,p_idempotency_key,v_hash);if v_result is not null then return v_result;end if;
 select * into v_po from procurement.purchase_orders where id=(p_payload->>'order_id')::uuid and tenant_id=p_tenant_id
  and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id for update;
 if not found then raise exception using errcode='P0002',message='ORDER_NOT_FOUND';end if;
 perform core.wave3_assert_expected_version(v_po.version,p_expected_entity_version,to_jsonb(v_po));
 if v_po.status<>'approved' then raise exception using errcode='55000',message='APPROVED_ORDER_REQUIRED';end if;
 if auth.uid() in(v_po.created_by,v_po.commercial_editor_id,v_po.submitted_by) then raise exception using errcode='42501',message='SEGREGATION_OF_DUTIES_VIOLATION';end if;
 select * into v_l from procurement.purchase_order_lines where id=(p_payload->>'order_line_id')::uuid and order_id=v_po.id for update;
 if not found then raise exception using errcode='22023',message='RECEIPT_SOURCE_INVALID';end if;
 select * into v_c from procurement.receipt_controls where legal_entity_id=p_legal_entity_id and tenant_id=p_tenant_id for share;
 if not found then raise exception using errcode='55000',message='RECEIPT_CONTROLS_REQUIRED';end if;
 v_extra:=sales.wave3_decimal_string(p_payload->'extra_quantity','extra_quantity',6,true,0,null);
 v_max:=v_l.quantity-v_l.cancelled_quantity+v_extra;
 if v_extra<=0 or v_c.maximum_over_receipt_percent<=0 or v_extra>v_l.quantity*v_c.maximum_over_receipt_percent/100
  or v_max<=v_l.received_quantity then raise exception using errcode='22023',message='ALLOWANCE_EXCEEDS_CONTROL';end if;
 insert into procurement.receipt_allowances(id,tenant_id,legal_entity_id,branch_id,order_id,order_line_id,order_version,maximum_received_quantity,control_version,reason,approved_by)
 values(v_id,p_tenant_id,p_legal_entity_id,p_branch_id,v_po.id,v_l.id,v_po.version,v_max,v_c.version,trim(p_payload->>'reason'),auth.uid());
 select sales.flow_exact_json(to_jsonb(a)) into v_result from procurement.receipt_allowances a where id=v_id;
 return core.wave3_finish_command(p_tenant_id,v_command,p_command_id,'receipt_allowance',v_id,p_idempotency_key,v_hash,null,v_result,p_legal_entity_id,p_branch_id,
  jsonb_build_object('purchase_order_id',v_po.id),null,jsonb_build_array(jsonb_build_object('topic','procurement.receipt.allowance','payload',jsonb_build_object('order_id',v_po.id))));
end $$;
revoke all on function api.approve_receipt_allowance(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) from public,anon;
grant execute on function api.approve_receipt_allowance(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) to authenticated;
create table procurement.goods_receipt_lines(
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,branch_id uuid not null,receipt_id uuid not null,
 order_line_id uuid not null,accepted_quantity numeric(20,6) not null,rejected_quantity numeric(20,6) not null,
 base_quantity numeric(20,6) not null,net_amount numeric(20,6) not null,base_amount numeric(20,6) not null,
 detail jsonb not null,unique(tenant_id,id),unique(receipt_id,order_line_id),
 foreign key(tenant_id,receipt_id) references procurement.goods_receipts(tenant_id,id) deferrable initially deferred,
 foreign key(tenant_id,legal_entity_id,order_line_id) references procurement.purchase_order_lines(tenant_id,legal_entity_id,id),
 check(accepted_quantity>=0 and rejected_quantity>=0 and accepted_quantity+rejected_quantity>0 and base_quantity>=0)
);
create table procurement.goods_receipt_reversals(
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,branch_id uuid not null,receipt_id uuid not null unique,
 document_date date not null,reason text not null,stock_movement_id uuid,journal_entry_id uuid,
 request_id uuid not null,command_id uuid not null,created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),
 foreign key(tenant_id,receipt_id) references procurement.goods_receipts(tenant_id,id),
 foreign key(tenant_id,stock_movement_id) references inventory.stock_movements(tenant_id,id),
 foreign key(tenant_id,journal_entry_id) references finance.journal_entries(tenant_id,id)
);
create index goods_receipts_scope_page on procurement.goods_receipts(tenant_id,legal_entity_id,branch_id,id);
create index goods_receipts_order on procurement.goods_receipts(tenant_id,legal_entity_id,order_id,order_revision,id);
create index goods_receipt_source_line on procurement.goods_receipt_lines(tenant_id,legal_entity_id,order_line_id,receipt_id);
create index receipt_reversals_scope on procurement.goods_receipt_reversals(tenant_id,legal_entity_id,branch_id,id);
create index receipt_control_grni_fk on procurement.receipt_controls(tenant_id,legal_entity_id,grni_account_id);
create index receipt_control_expense_fk on procurement.receipt_controls(tenant_id,legal_entity_id,expense_account_id);
do $$declare t text;begin
 foreach t in array array['goods_receipts','goods_receipt_lines','goods_receipt_reversals','receipt_control_history'] loop
  execute format('create trigger immutable_receipt before update or delete on procurement.%I for each row execute function workflow.reject_history_mutation()',t);
 end loop;
 foreach t in array array['goods_receipts','goods_receipt_lines','goods_receipt_reversals','receipt_controls','receipt_control_history'] loop
  execute format('alter table procurement.%I enable row level security',t);
  execute format('alter table procurement.%I force row level security',t);
  if t in('receipt_controls','receipt_control_history') then
   execute format('create policy receipt_read on procurement.%I for select to authenticated using(core.is_tenant_member(tenant_id) and (core.has_permission(tenant_id,''finance.setup.manage'',legal_entity_id,null) or core.has_permission(tenant_id,''procurement.receipts.post'',legal_entity_id,null)))',t);
  else
   execute format('create policy receipt_read on procurement.%I for select to authenticated using(core.is_tenant_member(tenant_id) and core.has_permission(tenant_id,''procurement.receipts.post'',legal_entity_id,branch_id))',t);
  end if;
  execute format('revoke all on procurement.%I from public,anon,authenticated',t);
  execute format('grant select on procurement.%I to authenticated',t);
 end loop;
end $$;
create view api.goods_receipts with(security_invoker=true) as select r.tenant_id,r.legal_entity_id,r.branch_id,r.id,
 sales.flow_exact_json(to_jsonb(r))||jsonb_build_object('status',case when x.id is null then 'posted' else 'reversed' end,
 'version',case when x.id is null then 1 else 2 end,'reversal',sales.flow_exact_json(to_jsonb(x)),
 'lines',coalesce((select jsonb_agg(l.detail order by l.id) from procurement.goods_receipt_lines l where l.receipt_id=r.id),'[]')) detail
 from procurement.goods_receipts r left join procurement.goods_receipt_reversals x on x.receipt_id=r.id;
grant select on api.goods_receipts to authenticated;
-- Additive constraint expansion preserves all existing permitted movement kinds.
alter table inventory.stock_movements drop constraint stock_movements_movement_kind_check;
alter table inventory.stock_movements add constraint stock_movements_movement_kind_check
 check(movement_kind in('opening','delivery','sales_return','goods_receipt','goods_receipt_reversal'));

create function api.upsert_receipt_controls(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_command_id uuid,
 p_idempotency_key uuid,p_client_timestamp timestamptz,p_payload jsonb,p_expected_entity_version bigint default null)
returns jsonb language plpgsql security definer set search_path='' as $$
declare v_command text:='procurement.receipt_controls.upsert';v_hash text;v_result jsonb;v_before jsonb;v_entity jsonb;v_base text;
 v_old procurement.receipt_controls%rowtype;v_grni uuid:=(p_payload->>'grni_account_id')::uuid;v_expense uuid:=(p_payload->>'expense_account_id')::uuid;v_percent numeric;
begin
 perform core.wave3_require_scope(p_tenant_id,'finance.setup.manage',p_legal_entity_id,p_branch_id);
 perform core.require_permission(p_tenant_id,'finance.setup.manage',p_legal_entity_id,null);
 if p_client_timestamp is null or (p_payload->>'id')::uuid is distinct from p_legal_entity_id then raise exception using errcode='22023',message='INVALID_COMMAND';end if;
 v_hash:=core.wave3_request_hash(v_command,p_command_id,p_tenant_id,p_legal_entity_id,p_branch_id,p_payload,p_expected_entity_version);
 v_result:=core.wave3_replay(p_tenant_id,v_command,p_command_id,p_idempotency_key,v_hash);if v_result is not null then return v_result;end if;
 perform pg_advisory_xact_lock(hashtextextended('receipt.controls:'||p_legal_entity_id::text,0));
 select * into v_old from procurement.receipt_controls where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id for update;
 if found then perform core.wave3_assert_expected_version(v_old.version,p_expected_entity_version,to_jsonb(v_old));
 elsif p_expected_entity_version is not null then raise exception using errcode='40001',message='VERSION_CONFLICT';end if;
 v_before:=to_jsonb(v_old);
 select currency_code into v_base from core.legal_entities where id=p_legal_entity_id and tenant_id=p_tenant_id;
 perform finance.flow_account(p_tenant_id,p_legal_entity_id,v_grni,'liability',v_base);
 perform finance.flow_account(p_tenant_id,p_legal_entity_id,v_expense,'expense',v_base);
 v_percent:=sales.wave3_decimal_string(coalesce(p_payload->'maximum_over_receipt_percent','"0"'),'maximum_over_receipt_percent',6,true,0,100);
 insert into procurement.receipt_controls(tenant_id,legal_entity_id,grni_account_id,expense_account_id,maximum_over_receipt_percent,updated_by)
 values(p_tenant_id,p_legal_entity_id,v_grni,v_expense,v_percent,auth.uid()) on conflict(legal_entity_id) do update set
 grni_account_id=excluded.grni_account_id,expense_account_id=excluded.expense_account_id,maximum_over_receipt_percent=excluded.maximum_over_receipt_percent,version=procurement.receipt_controls.version+1,updated_by=auth.uid(),updated_at=clock_timestamp();
 select sales.flow_exact_json(to_jsonb(c))||jsonb_build_object('id',c.legal_entity_id) into v_entity from procurement.receipt_controls c where legal_entity_id=p_legal_entity_id;
 insert into procurement.receipt_control_history(tenant_id,legal_entity_id,version,snapshot,actor_id)
 values(p_tenant_id,p_legal_entity_id,(v_entity->>'version')::bigint,v_entity,auth.uid());
 return core.wave3_finish_command(p_tenant_id,v_command,p_command_id,'receipt_controls',p_legal_entity_id,p_idempotency_key,v_hash,v_before,v_entity,p_legal_entity_id,p_branch_id);
end $$;

create function api.post_goods_receipt(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_command_id uuid,
 p_idempotency_key uuid,p_client_timestamp timestamptz,p_payload jsonb,p_expected_entity_version bigint default null)
returns jsonb language plpgsql security definer set search_path='' as $$
declare v_id uuid:=(p_payload->>'id')::uuid;v_request uuid:=gen_random_uuid();v_command text:='procurement.goods_receipt.post';
 v_hash text;v_result jsonb;v_po procurement.purchase_orders%rowtype;v_ol procurement.purchase_order_lines%rowtype;
 v_controls procurement.receipt_controls%rowtype;v_product inventory.products%rowtype;v_balance inventory.stock_balances%rowtype;
 v_input jsonb;v_lines jsonb;v_detail jsonb;v_source jsonb;v_jlines jsonb:='[]';v_seen uuid[]:='{}';v_line_id uuid;
 v_q numeric;v_reject numeric;v_base_q numeric;v_prior numeric;v_amount numeric;v_base_amount numeric;v_total numeric:=0;v_base_total numeric:=0;
 v_scale integer;v_base text;v_date date:=(p_payload->>'document_date')::date;v_warehouse uuid:=(p_payload->>'warehouse_id')::uuid;
 v_movement uuid;v_journal uuid;v_account uuid;v_lot uuid;v_serial uuid;v_serials uuid[];v_code text;v_product_id uuid;
 v_num numeric;v_den numeric;v_precision integer;v_ref text:=trim(p_payload->>'reference');
 v_allowance procurement.receipt_allowances%rowtype;
begin
 perform core.wave3_require_scope(p_tenant_id,'procurement.receipts.post',p_legal_entity_id,p_branch_id);
 if v_id is null or p_client_timestamp is null or p_legal_entity_id is null or p_branch_id is null or v_date is null
 or jsonb_typeof(p_payload->'lines') is distinct from 'array' or jsonb_array_length(p_payload->'lines') not between 1 and 500
 or coalesce(length(v_ref),0) not between 1 and 140 then raise exception using errcode='22023',message='INVALID_RECEIPT';end if;
 v_hash:=core.wave3_request_hash(v_command,p_command_id,p_tenant_id,p_legal_entity_id,p_branch_id,p_payload,p_expected_entity_version);
 v_result:=core.wave3_replay(p_tenant_id,v_command,p_command_id,p_idempotency_key,v_hash);if v_result is not null then return v_result;end if;
 select * into v_po from procurement.purchase_orders where id=(p_payload->>'order_id')::uuid and tenant_id=p_tenant_id
 and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id for update;
 if not found then raise exception using errcode='P0002',message='ORDER_NOT_FOUND';end if;
 perform core.wave3_assert_expected_version(v_po.version,p_expected_entity_version,to_jsonb(v_po));
 if v_po.status<>'approved' then raise exception using errcode='55000',message='APPROVED_ORDER_REQUIRED';end if;
 if v_warehouse is distinct from v_po.warehouse_id or not exists(select 1 from core.warehouses where id=v_warehouse and tenant_id=p_tenant_id
 and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id and status='active') then raise exception using errcode='22023',message='RECEIVING_WAREHOUSE_INVALID';end if;
 if v_date<v_po.document_date then raise exception using errcode='22023',message='RECEIPT_DATE_INVALID';end if;
 select currency_code,rounding_scale into v_base,v_scale from core.legal_entities where id=p_legal_entity_id and tenant_id=p_tenant_id;
 select * into v_controls from procurement.receipt_controls where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id for share;
 if not found then raise exception using errcode='55000',message='RECEIPT_CONTROLS_REQUIRED';end if;
 perform finance.flow_account(p_tenant_id,p_legal_entity_id,v_controls.grni_account_id,'liability',v_po.currency_code);
 perform finance.wave3_lock_open_period(p_tenant_id,p_legal_entity_id,v_date);
 select detail into v_source from api.purchase_orders where id=v_po.id;
 v_source:=v_source||jsonb_build_object('_prior_negative_quantities','{}'::jsonb);
 -- Lock all source lines, then all stock keys in deterministic order before mutation.
 perform 1 from procurement.purchase_order_lines where order_id=v_po.id order by id for update;
 for v_product_id in select distinct l.product_id from procurement.purchase_order_lines l
 join jsonb_array_elements(p_payload->'lines') x on (x->>'order_line_id')::uuid=l.id
 where l.order_id=v_po.id and l.product_id is not null order by 1 loop
  perform pg_advisory_xact_lock(hashtextextended(p_tenant_id::text||':'||v_warehouse::text||':'||v_product_id::text,0));
 end loop;
 for v_input in select value from jsonb_array_elements(p_payload->'lines') order by value->>'order_line_id' loop
  v_line_id:=(v_input->>'line_id')::uuid;
  if v_line_id is null or v_line_id=any(v_seen) then raise exception using errcode='22023',message='RECEIPT_LINE_ID_INVALID';end if;
  v_seen:=array_append(v_seen,v_line_id);
  select * into v_ol from procurement.purchase_order_lines where id=(v_input->>'order_line_id')::uuid and order_id=v_po.id;
  if not found then raise exception using errcode='22023',message='RECEIPT_SOURCE_INVALID';end if;
  v_q:=sales.wave3_decimal_string(v_input->'accepted_quantity','accepted_quantity',6,true,0,null);
  v_reject:=sales.wave3_decimal_string(v_input->'rejected_quantity','rejected_quantity',6,true,0,null);
  if v_q+v_reject<=0 then raise exception using errcode='22023',message='RECEIPT_QUANTITY_REQUIRED';end if;
  v_allowance:=null;
  if v_q>greatest(0,v_ol.quantity-v_ol.cancelled_quantity-v_ol.received_quantity) then
   select * into v_allowance from procurement.receipt_allowances where order_line_id=v_ol.id and order_version=v_po.version
    and control_version=v_controls.version and approved_by<>auth.uid()
    and maximum_received_quantity>=v_ol.received_quantity+v_q;
   if not found then raise exception using errcode='22023',message='RECEIPT_EXCEEDS_REMAINING';end if;
  end if;
  if v_reject>0 and coalesce(length(trim(v_input->>'rejection_reason')),0) not between 1 and 1000 then raise exception using errcode='22023',message='REJECTION_REASON_REQUIRED';end if;
  select precision into v_precision from inventory.units where id=v_ol.unit_id and tenant_id=p_tenant_id and status='active';
  if not found or round(v_q,v_precision)<>v_q or round(v_reject,v_precision)<>v_reject then raise exception using errcode='22023',message='RECEIPT_UNIT_PRECISION_INVALID';end if;
  v_num:=(v_ol.detail->>'conversion_numerator')::numeric;v_den:=(v_ol.detail->>'conversion_denominator')::numeric;
  if v_num is null or v_den is null or v_num<=0 or v_den<=0 or mod(v_q*1000000*v_num,v_den)<>0 then raise exception using errcode='22023',message='BASE_QUANTITY_PRECISION_INVALID';end if;
  v_base_q:=v_q*v_num/v_den;v_product:=null;v_lot:=null;v_serials:='{}';
  if v_ol.product_id is not null then
   select * into v_product from inventory.products where id=v_ol.product_id and tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and status='active' and can_purchase for share;
   if not found or v_product.base_unit_id is distinct from (v_ol.detail->>'base_unit_id')::uuid then raise exception using errcode='22023',message='RECEIPT_PRODUCT_INVALID';end if;
   select precision into v_precision from inventory.units where id=v_product.base_unit_id and tenant_id=p_tenant_id and status='active';
   if not found or round(v_base_q,v_precision)<>v_base_q then raise exception using errcode='22023',message='BASE_QUANTITY_PRECISION_INVALID';end if;
  end if;
  -- EC-320: keep the historical ratio, but never accept a changed/inactive master
  -- as implicit approval for a new stock quantity.
  if v_q>0 then
   perform inventory.resolve_product_unit(p_tenant_id,p_legal_entity_id,v_ol.product_id,v_ol.unit_id,
    v_input->'accepted_quantity',v_ol.detail->'conversion_numerator',v_ol.detail->'conversion_denominator');
  end if;
  select coalesce(sum(l.accepted_quantity),0) into v_prior from procurement.goods_receipt_lines l join procurement.goods_receipts r on r.id=l.receipt_id
   where l.order_line_id=v_ol.id and r.order_revision=v_po.revision and not exists(select 1 from procurement.goods_receipt_reversals x where x.receipt_id=r.id);
  v_amount:=round((v_ol.detail->>'net_amount')::numeric*(v_prior+v_q)/v_ol.quantity,v_scale)-round((v_ol.detail->>'net_amount')::numeric*v_prior/v_ol.quantity,v_scale);
  v_base_amount:=round(round((v_ol.detail->>'net_amount')::numeric*(v_prior+v_q)/v_ol.quantity,v_scale)*v_po.exchange_rate,v_scale)
    -round(round((v_ol.detail->>'net_amount')::numeric*v_prior/v_ol.quantity,v_scale)*v_po.exchange_rate,v_scale);
  v_account:=case when v_product.kind='stocked' then finance.flow_account(p_tenant_id,p_legal_entity_id,v_product.inventory_account_id,'asset',v_po.currency_code)
   else finance.flow_account(p_tenant_id,p_legal_entity_id,coalesce(v_product.expense_account_id,v_controls.expense_account_id),'expense',v_po.currency_code) end;
  if jsonb_typeof(coalesce(v_input->'serial_codes','[]'))<>'array' or jsonb_array_length(coalesce(v_input->'serial_codes','[]'))>1000 then raise exception using errcode='22023',message='SERIAL_LIST_INVALID';end if;
  if v_q>0 and v_product.kind='stocked' then
   -- Match delivery lock order: balance then valuation, before lot/serial rows.
   insert into inventory.stock_balances(tenant_id,legal_entity_id,branch_id,warehouse_id,product_id,on_hand_quantity,created_by,updated_by)
   values(p_tenant_id,p_legal_entity_id,p_branch_id,v_warehouse,v_product.id,0,auth.uid(),auth.uid())
   on conflict(tenant_id,legal_entity_id,branch_id,warehouse_id,product_id) do nothing;
   select * into v_balance from inventory.stock_balances where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id
    and branch_id=p_branch_id and warehouse_id=v_warehouse and product_id=v_product.id for update;
   insert into inventory.stock_valuations(tenant_id,legal_entity_id,branch_id,stock_balance_id,carrying_value,created_by,updated_by)
   values(p_tenant_id,p_legal_entity_id,p_branch_id,v_balance.id,0,auth.uid(),auth.uid()) on conflict(tenant_id,stock_balance_id) do nothing;
   perform 1 from inventory.stock_valuations where stock_balance_id=v_balance.id for update;
   if exists(select 1 from inventory.stock_movement_lines where tenant_id=p_tenant_id and warehouse_id=v_warehouse
    and product_id=v_product.id and posting_date>v_date) then raise exception using errcode='55000',message='BACKDATED_STOCK_RECEIPT_REQUIRES_REVIEW';end if;
   -- Immutable negative movement totals distinguish later consumption without
   -- relying on transaction-start timestamps or retaining an unbounded ID list.
   v_source:=jsonb_set(v_source,array['_prior_negative_quantities',v_product.id::text],
    to_jsonb((select coalesce(sum(-base_quantity),0)::text from inventory.stock_movement_lines
     where tenant_id=p_tenant_id and warehouse_id=v_warehouse and product_id=v_product.id and base_quantity<0)));
   if v_product.tracking_mode='lot' then
    if coalesce(length(trim(v_input->>'lot_code')),0) not between 1 and 100 or jsonb_array_length(coalesce(v_input->'serial_codes','[]'))<>0
     or (v_input->>'expiry_date')::date<v_date then raise exception using errcode='22023',message='LOT_IDENTITY_INVALID';end if;
    insert into inventory.lots(tenant_id,legal_entity_id,product_id,code,manufacture_date,expiry_date,created_by,updated_by)
    values(p_tenant_id,p_legal_entity_id,v_product.id,trim(v_input->>'lot_code'),(v_input->>'manufacture_date')::date,(v_input->>'expiry_date')::date,auth.uid(),auth.uid())
    on conflict(tenant_id,product_id,code) do nothing;
    select id into v_lot from inventory.lots where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and product_id=v_product.id
     and code=trim(v_input->>'lot_code') and status='saleable' and manufacture_date is not distinct from (v_input->>'manufacture_date')::date
     and expiry_date is not distinct from (v_input->>'expiry_date')::date for update;
    if not found then raise exception using errcode='22023',message='LOT_METADATA_CONFLICT';end if;
    insert into inventory.lot_balances(tenant_id,legal_entity_id,branch_id,warehouse_id,product_id,lot_id,on_hand_quantity,created_by,updated_by)
    values(p_tenant_id,p_legal_entity_id,p_branch_id,v_warehouse,v_product.id,v_lot,v_base_q,auth.uid(),auth.uid())
    on conflict(tenant_id,warehouse_id,lot_id) do update set on_hand_quantity=inventory.lot_balances.on_hand_quantity+excluded.on_hand_quantity,updated_by=auth.uid();
   elsif v_product.tracking_mode='serial' then
    if v_input->>'lot_code' is not null or trunc(v_base_q)<>v_base_q or jsonb_array_length(coalesce(v_input->'serial_codes','[]'))<>v_base_q then raise exception using errcode='22023',message='SERIAL_COUNT_INVALID';end if;
    for v_code in select value#>>'{}' from jsonb_array_elements(v_input->'serial_codes') where jsonb_typeof(value)='string' order by 1 loop
     if length(trim(v_code)) not between 1 and 100 or v_code<>trim(v_code) then raise exception using errcode='22023',message='SERIAL_IDENTITY_INVALID';end if;
     insert into inventory.serials(tenant_id,legal_entity_id,branch_id,warehouse_id,product_id,code,created_by,updated_by)
     values(p_tenant_id,p_legal_entity_id,p_branch_id,v_warehouse,v_product.id,v_code,auth.uid(),auth.uid()) returning id into v_serial;
     v_serials:=array_append(v_serials,v_serial);
    end loop;
    if cardinality(v_serials)<>v_base_q then raise exception using errcode='22023',message='SERIAL_IDENTITY_INVALID';end if;
   elsif v_input->>'lot_code' is not null or jsonb_array_length(coalesce(v_input->'serial_codes','[]'))<>0 then raise exception using errcode='22023',message='TRACKING_NOT_ALLOWED';end if;
   if v_movement is null then
    v_movement:=gen_random_uuid();
    insert into inventory.stock_movements(id,tenant_id,legal_entity_id,branch_id,source_type,source_id,warehouse_id,posting_date,movement_kind,request_id,command_id,correlation_id,created_by)
    values(v_movement,p_tenant_id,p_legal_entity_id,p_branch_id,'goods_receipt',v_id,v_warehouse,v_date,'goods_receipt',v_request,p_command_id,v_request,auth.uid());
   end if;
   insert into inventory.stock_balances(tenant_id,legal_entity_id,branch_id,warehouse_id,product_id,on_hand_quantity,created_by,updated_by)
   values(p_tenant_id,p_legal_entity_id,p_branch_id,v_warehouse,v_product.id,v_base_q,auth.uid(),auth.uid())
   on conflict(tenant_id,legal_entity_id,branch_id,warehouse_id,product_id) do update set on_hand_quantity=inventory.stock_balances.on_hand_quantity+excluded.on_hand_quantity,updated_by=auth.uid() returning * into v_balance;
   insert into inventory.stock_valuations(tenant_id,legal_entity_id,branch_id,stock_balance_id,carrying_value,created_by,updated_by)
   values(p_tenant_id,p_legal_entity_id,p_branch_id,v_balance.id,v_base_amount,auth.uid(),auth.uid())
   on conflict(tenant_id,stock_balance_id) do update set carrying_value=inventory.stock_valuations.carrying_value+excluded.carrying_value,updated_by=auth.uid();
   insert into inventory.stock_movement_lines(tenant_id,legal_entity_id,branch_id,stock_movement_id,warehouse_id,product_id,source_line_id,base_quantity,base_value,lot_id,serial_ids,posting_date,created_by)
   values(p_tenant_id,p_legal_entity_id,p_branch_id,v_movement,v_warehouse,v_product.id,v_line_id,v_base_q,v_base_amount,v_lot,v_serials,v_date,auth.uid());
  end if;
  v_detail:=jsonb_build_object('line_id',v_line_id,'order_line_id',v_ol.id,'product_id',v_ol.product_id,'description',v_ol.description,
   'unit_id',v_ol.unit_id,'conversion_numerator',v_num::text,'conversion_denominator',v_den::text,
   'accepted_quantity',v_q::text,'rejected_quantity',v_reject::text,'rejection_reason',v_input->>'rejection_reason',
   'base_quantity',v_base_q::text,'net_amount',v_amount::text,'base_amount',v_base_amount::text,'account_id',v_account,
   'lot_id',v_lot,'lot_code',v_input->>'lot_code','serial_ids',to_jsonb(v_serials),'serial_codes',coalesce(v_input->'serial_codes','[]'),'source_snapshot',v_ol.detail,
   'allowance',sales.flow_exact_json(to_jsonb(v_allowance)));
  insert into procurement.goods_receipt_lines(id,tenant_id,legal_entity_id,branch_id,receipt_id,order_line_id,accepted_quantity,rejected_quantity,base_quantity,net_amount,base_amount,detail)
  values(v_line_id,p_tenant_id,p_legal_entity_id,p_branch_id,v_id,v_ol.id,v_q,v_reject,v_base_q,v_amount,v_base_amount,v_detail);
  update procurement.purchase_order_lines set received_quantity=received_quantity+v_q,
   approved_extra_quantity=greatest(approved_extra_quantity,received_quantity+v_q+cancelled_quantity-quantity) where id=v_ol.id;
  if v_amount<>0 or v_base_amount<>0 then v_jlines:=v_jlines||jsonb_build_array(finance.flow_jline(v_account,v_amount,v_base_amount,v_line_id));end if;
  v_total:=v_total+v_amount;v_base_total:=v_base_total+v_base_amount;
 end loop;
 if v_total<>0 or v_base_total<>0 then v_jlines:=v_jlines||jsonb_build_array(finance.flow_jline(v_controls.grni_account_id,-v_total,-v_base_total));end if;
 v_journal:=finance.flow_post_journal(jsonb_build_object('tenant_id',p_tenant_id,'legal_entity_id',p_legal_entity_id,'branch_id',p_branch_id,
  'document_date',v_date,'currency_code',v_po.currency_code,'base_currency_code',v_base,'exchange_rate',v_po.exchange_rate::text,'customer_id',v_po.supplier_id),v_jlines,'goods_receipt',v_id,v_request,p_command_id);
 insert into procurement.goods_receipts(id,tenant_id,legal_entity_id,branch_id,order_id,order_revision,warehouse_id,document_date,document_number,reference,
  source_snapshot,currency_code,base_currency_code,exchange_rate,net_amount,base_amount,stock_movement_id,journal_entry_id,request_id,command_id,created_by)
 values(v_id,p_tenant_id,p_legal_entity_id,p_branch_id,v_po.id,v_po.revision,v_warehouse,v_date,
  sales.wave3_reserve_document_number(p_tenant_id,p_legal_entity_id,p_branch_id,'goods_receipt',v_date,auth.uid()),v_ref,v_source,v_po.currency_code,v_base,v_po.exchange_rate,v_total,v_base_total,v_movement,v_journal,v_request,p_command_id,auth.uid());
 update procurement.purchase_orders set version=version+1,updated_by=auth.uid(),updated_at=clock_timestamp() where id=v_po.id;
 perform procurement.record_order_history(jsonb_build_object('entity',(select detail from api.purchase_orders where id=v_po.id)));
 select detail into v_result from api.goods_receipts where id=v_id;
 return core.wave3_finish_command(p_tenant_id,v_command,p_command_id,'goods_receipt',v_id,p_idempotency_key,v_hash,null,v_result,p_legal_entity_id,p_branch_id,
  jsonb_build_object('purchase_order_id',v_po.id),jsonb_build_object('from_status','draft','to_status','posted'),
  jsonb_build_array(jsonb_build_object('topic','procurement.receipt.posted','payload',jsonb_build_object('receipt_id',v_id))),'[]',v_request,v_request);
end $$;

create function api.reverse_goods_receipt(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_command_id uuid,
 p_idempotency_key uuid,p_client_timestamp timestamptz,p_payload jsonb,p_expected_entity_version bigint default null)
returns jsonb language plpgsql security definer set search_path='' as $$
declare v_id uuid:=(p_payload->>'document_id')::uuid;v_reverse uuid:=gen_random_uuid();v_request uuid:=gen_random_uuid();
 v_command text:='procurement.goods_receipt.reverse';v_hash text;v_result jsonb;v_before jsonb;v_r procurement.goods_receipts%rowtype;
 v_po procurement.purchase_orders%rowtype;v_line procurement.goods_receipt_lines%rowtype;v_m inventory.stock_movement_lines%rowtype;
 v_balance inventory.stock_balances%rowtype;v_value inventory.stock_valuations%rowtype;v_movement uuid;v_journal uuid;v_jlines jsonb:='[]';
 v_date date:=(p_payload->>'document_date')::date;v_reason text:=trim(p_payload->>'reason');v_product uuid;v_serial uuid;
begin
 perform core.wave3_require_scope(p_tenant_id,'procurement.receipts.post',p_legal_entity_id,p_branch_id);
 if p_client_timestamp is null or v_id is null or v_date is null or coalesce(length(v_reason),0) not between 1 and 1000 then raise exception using errcode='22023',message='REVERSAL_REASON_DATE_REQUIRED';end if;
 v_hash:=core.wave3_request_hash(v_command,p_command_id,p_tenant_id,p_legal_entity_id,p_branch_id,p_payload,p_expected_entity_version);
 v_result:=core.wave3_replay(p_tenant_id,v_command,p_command_id,p_idempotency_key,v_hash);if v_result is not null then return v_result;end if;
 select * into v_r from procurement.goods_receipts where id=v_id and tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id;
 if not found then raise exception using errcode='P0002',message='RECEIPT_NOT_FOUND';end if;
 -- Same aggregate lock order as posting; a receipt row is immutable.
 select * into v_po from procurement.purchase_orders where id=v_r.order_id for update;
 select detail into v_before from api.goods_receipts where id=v_id;
 perform core.wave3_assert_expected_version((v_before->>'version')::bigint,p_expected_entity_version,v_before);
 if v_before->>'status'<>'posted' then raise exception using errcode='55000',message='RECEIPT_ALREADY_REVERSED';end if;
 if v_date<v_r.document_date then raise exception using errcode='22023',message='REVERSAL_DATE_INVALID';end if;
 perform 1 from procurement.purchase_order_lines where order_id=v_po.id order by id for update;
 if exists(select 1 from procurement.purchase_order_lines l join procurement.goods_receipt_lines r on r.order_line_id=l.id where r.receipt_id=v_id and l.billed_quantity>0)
 then raise exception using errcode='55000',message='BILLED_RECEIPT_REQUIRES_RETURN';end if;
 perform finance.wave3_lock_open_period(p_tenant_id,p_legal_entity_id,v_date);
 for v_product in select distinct product_id from inventory.stock_movement_lines where stock_movement_id=v_r.stock_movement_id order by 1 loop
  perform pg_advisory_xact_lock(hashtextextended(p_tenant_id::text||':'||v_r.warehouse_id::text||':'||v_product::text,0));
 end loop;
 for v_m in select * from inventory.stock_movement_lines where stock_movement_id=v_r.stock_movement_id order by product_id,id loop
  select * into v_balance from inventory.stock_balances where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id
   and warehouse_id=v_r.warehouse_id and product_id=v_m.product_id for update;
  select * into v_value from inventory.stock_valuations where stock_balance_id=v_balance.id for update;
  if v_balance.id is null or v_value.id is null or v_balance.on_hand_quantity-v_balance.allocated_quantity<v_m.base_quantity
   or v_value.carrying_value<v_m.base_value or (v_balance.on_hand_quantity=v_m.base_quantity and v_value.carrying_value<>v_m.base_value)
   or (select coalesce(sum(-base_quantity),0) from inventory.stock_movement_lines
      where tenant_id=p_tenant_id and warehouse_id=v_r.warehouse_id and product_id=v_m.product_id and base_quantity<0
       and (v_movement is null or stock_movement_id<>v_movement))
     is distinct from (v_r.source_snapshot#>>array['_prior_negative_quantities',v_m.product_id::text])::numeric
  then raise exception using errcode='55000',message='CONSUMED_RECEIPT_REQUIRES_RETURN';end if;
  if v_m.lot_id is not null then
   update inventory.lot_balances set on_hand_quantity=on_hand_quantity-v_m.base_quantity,updated_by=auth.uid()
   where tenant_id=p_tenant_id and warehouse_id=v_r.warehouse_id and lot_id=v_m.lot_id and on_hand_quantity>=v_m.base_quantity;
   if not found then raise exception using errcode='55000',message='RECEIPT_LOT_UNAVAILABLE';end if;
  end if;
  foreach v_serial in array v_m.serial_ids loop
   update inventory.serials set status='disposed',updated_by=auth.uid() where id=v_serial and tenant_id=p_tenant_id
    and warehouse_id=v_r.warehouse_id and status='available';
   if not found then raise exception using errcode='55000',message='RECEIPT_SERIAL_UNAVAILABLE';end if;
  end loop;
  update inventory.stock_balances set on_hand_quantity=on_hand_quantity-v_m.base_quantity,updated_by=auth.uid() where id=v_balance.id;
  update inventory.stock_valuations set carrying_value=carrying_value-v_m.base_value,updated_by=auth.uid() where id=v_value.id;
  if v_movement is null then
   v_movement:=gen_random_uuid();
   insert into inventory.stock_movements(id,tenant_id,legal_entity_id,branch_id,source_type,source_id,warehouse_id,posting_date,movement_kind,request_id,command_id,correlation_id,created_by)
   values(v_movement,p_tenant_id,p_legal_entity_id,p_branch_id,'goods_receipt_reversal',v_reverse,v_r.warehouse_id,v_date,'goods_receipt_reversal',v_request,p_command_id,v_request,auth.uid());
  end if;
  insert into inventory.stock_movement_lines(tenant_id,legal_entity_id,branch_id,stock_movement_id,warehouse_id,product_id,source_line_id,original_movement_line_id,base_quantity,base_value,lot_id,serial_ids,posting_date,created_by)
  values(p_tenant_id,p_legal_entity_id,p_branch_id,v_movement,v_r.warehouse_id,v_m.product_id,v_m.source_line_id,v_m.id,-v_m.base_quantity,-v_m.base_value,v_m.lot_id,v_m.serial_ids,v_date,auth.uid());
 end loop;
 for v_line in select * from procurement.goods_receipt_lines where receipt_id=v_id order by order_line_id loop
  update procurement.purchase_order_lines set received_quantity=received_quantity-v_line.accepted_quantity where id=v_line.order_line_id;
 end loop;
 select coalesce(jsonb_agg(finance.flow_jline(account_id,transaction_credit-transaction_debit,base_credit-base_debit,source_line_id) order by line_number),'[]')
 into v_jlines from finance.journal_lines where journal_entry_id=v_r.journal_entry_id;
 v_journal:=finance.flow_post_journal(to_jsonb(v_r)||jsonb_build_object('document_date',v_date,'customer_id',v_po.supplier_id),v_jlines,'goods_receipt_reversal',v_reverse,v_request,p_command_id);
 insert into procurement.goods_receipt_reversals(id,tenant_id,legal_entity_id,branch_id,receipt_id,document_date,reason,stock_movement_id,journal_entry_id,request_id,command_id,created_by)
 values(v_reverse,p_tenant_id,p_legal_entity_id,p_branch_id,v_id,v_date,v_reason,v_movement,v_journal,v_request,p_command_id,auth.uid());
 update procurement.purchase_orders set version=version+1,updated_by=auth.uid(),updated_at=clock_timestamp() where id=v_po.id;
 perform procurement.record_order_history(jsonb_build_object('entity',(select detail from api.purchase_orders where id=v_po.id)));
 select detail into v_result from api.goods_receipts where id=v_id;
 return core.wave3_finish_command(p_tenant_id,v_command,p_command_id,'goods_receipt',v_id,p_idempotency_key,v_hash,v_before,v_result,p_legal_entity_id,p_branch_id,'{}',
 jsonb_build_object('from_status','posted','to_status','reversed','reason',v_reason),jsonb_build_array(jsonb_build_object('topic','procurement.receipt.reversed','payload',jsonb_build_object('receipt_id',v_id))),'[]',v_request,v_request);
end $$;
revoke all on function api.upsert_receipt_controls(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint),
 api.post_goods_receipt(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint),api.reverse_goods_receipt(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) from public,anon;
grant execute on function api.upsert_receipt_controls(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint),
 api.post_goods_receipt(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint),api.reverse_goods_receipt(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) to authenticated;

create function api.goods_receipt_reference_options(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,
 p_resource text,p_after uuid default null,p_search text default '') returns jsonb
language plpgsql security definer set search_path='' as $$
declare v_items jsonb;v_search text:=lower(trim(coalesce(p_search,'')));v_next uuid;begin
 if p_resource='receipt_orders' then
  perform core.wave3_require_scope(p_tenant_id,'procurement.receipts.post',p_legal_entity_id,p_branch_id);
 else
  perform core.wave3_require_scope(p_tenant_id,'finance.setup.manage',p_legal_entity_id,p_branch_id);
  perform core.require_permission(p_tenant_id,'finance.setup.manage',p_legal_entity_id,null);
 end if;
 if p_legal_entity_id is null or p_branch_id is null or length(v_search)>100 then raise exception using errcode='22023',message='REFERENCE_SCOPE_INVALID';end if;
 if p_resource='receipt_orders' then
  select jsonb_agg(jsonb_build_object('id',id,'code',detail->>'document_number','name',detail->>'payment_terms','detail',detail) order by id)
  into v_items from(select * from api.purchase_orders where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id
   and status='approved' and (p_after is null or id>p_after) and (v_search='' or position(v_search in lower(detail->>'document_number'))>0) order by id limit 51) x;
 elsif p_resource='receipt_accounts' then
  select jsonb_agg(jsonb_build_object('id',id,'code',code,'name',name,'account_type',account_type) order by id)
  into v_items from(select * from finance.accounts where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and is_posting and status='active'
   and account_type in('expense','liability') and (p_after is null or id>p_after) and (v_search='' or position(v_search in lower(code||' '||name))>0) order by id limit 51) x;
 elsif p_resource='receipt_controls' then
  select jsonb_agg(sales.flow_exact_json(to_jsonb(c))||jsonb_build_object('id',c.legal_entity_id)) into v_items from procurement.receipt_controls c
  where c.tenant_id=p_tenant_id and c.legal_entity_id=p_legal_entity_id;
 else raise exception using errcode='22023',message='REFERENCE_RESOURCE_INVALID';end if;
 v_items:=coalesce(v_items,'[]');
 if p_resource='receipt_orders' then
  select coalesce(jsonb_agg(jsonb_set(item,'{detail,lines}',coalesce((select jsonb_agg(line||jsonb_build_object('_tracking_mode',coalesce(p.tracking_mode,'none'),
   '_allowance',coalesce((select sales.flow_exact_json(to_jsonb(a)) from procurement.receipt_allowances a
     join procurement.receipt_controls c on c.legal_entity_id=a.legal_entity_id and c.tenant_id=a.tenant_id
     where a.order_line_id=(line->>'line_id')::uuid and a.order_version=(item#>>'{detail,version}')::bigint and a.control_version=c.version),'null'::jsonb)) order by line->>'line_id')
   from jsonb_array_elements(item#>'{detail,lines}') line left join inventory.products p
    on p.id=(line->>'product_id')::uuid and p.tenant_id=p_tenant_id and p.legal_entity_id=p_legal_entity_id),'[]')) order by item->>'id'),'[]')
   into v_items from jsonb_array_elements(v_items) item;
 end if;
 if jsonb_array_length(v_items)>50 then v_next:=(v_items->49->>'id')::uuid;v_items:=v_items-50;end if;
 return jsonb_build_object('items',v_items,'next_cursor',v_next);
end $$;
revoke all on function api.goods_receipt_reference_options(uuid,uuid,uuid,text,uuid,text) from public,anon;
grant execute on function api.goods_receipt_reference_options(uuid,uuid,uuid,text,uuid,text) to authenticated;

-- AC-311 candidate: receipt matching and AP; no persistent setup or business fixtures.
create table procurement.supplier_bill_controls(
 tenant_id uuid not null,legal_entity_id uuid primary key,payable_account_id uuid not null,input_tax_account_id uuid not null,variance_account_id uuid not null,
 amount_tolerance numeric(20,6) not null default 0 check(amount_tolerance>=0),price_percent_tolerance numeric(9,6) not null default 0 check(price_percent_tolerance between 0 and 100),
 version bigint not null default 1,updated_by uuid not null references auth.users(id),updated_at timestamptz not null default now(),
 foreign key(tenant_id,legal_entity_id) references core.legal_entities(tenant_id,id),
 foreign key(tenant_id,legal_entity_id,payable_account_id) references finance.accounts(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,legal_entity_id,input_tax_account_id) references finance.accounts(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,legal_entity_id,variance_account_id) references finance.accounts(tenant_id,legal_entity_id,id)
);
create table procurement.supplier_bills(
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,branch_id uuid not null,supplier_id uuid not null,
 supplier_reference text not null check(length(trim(supplier_reference)) between 1 and 140),document_date date not null,due_date date not null,
 document_number text,currency_code text not null references core.currencies(code),base_currency_code text not null references core.currencies(code),
 exchange_rate_id uuid,exchange_rate numeric(20,10) not null,subtotal numeric(20,6) not null,tax_total numeric(20,6) not null,total numeric(20,6) not null,base_total numeric(20,6) not null,
 status text not null default 'draft' check(status in('draft','posted','cancelled')),version bigint not null default 1,
 match_result jsonb not null,journal_entry_id uuid,open_item_id uuid,created_by uuid not null references auth.users(id),updated_by uuid not null references auth.users(id),
 created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
 unique(tenant_id,id),unique(tenant_id,legal_entity_id,id),unique(tenant_id,legal_entity_id,branch_id,document_number),
 foreign key(tenant_id,supplier_id) references crm.parties(tenant_id,id),foreign key(tenant_id,branch_id) references core.branches(tenant_id,id),
 foreign key(tenant_id,legal_entity_id) references core.legal_entities(tenant_id,id),
 foreign key(tenant_id,legal_entity_id,exchange_rate_id) references finance.exchange_rates(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,journal_entry_id) references finance.journal_entries(tenant_id,id),foreign key(tenant_id,open_item_id) references finance.open_items(tenant_id,id),
 check(due_date>=document_date and total>=0 and base_total>=0 and exchange_rate>0)
);
create unique index supplier_reference_unique on procurement.supplier_bills(tenant_id,legal_entity_id,supplier_id,lower(trim(supplier_reference))) where status<>'cancelled';
create index supplier_bills_scope_page on procurement.supplier_bills(tenant_id,legal_entity_id,branch_id,id);
create index supplier_bills_party_date on procurement.supplier_bills(tenant_id,legal_entity_id,supplier_id,document_date,id);
create table procurement.supplier_bill_lines(
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,branch_id uuid not null,bill_id uuid not null,
 receipt_line_id uuid,quantity numeric(20,6) not null check(quantity>0),detail jsonb not null,
 unique(tenant_id,id),unique(bill_id,receipt_line_id),
 foreign key(tenant_id,bill_id) references procurement.supplier_bills(tenant_id,id),
 foreign key(tenant_id,receipt_line_id) references procurement.goods_receipt_lines(tenant_id,id)
);
create index supplier_bill_receipt_qty on procurement.supplier_bill_lines(tenant_id,receipt_line_id,bill_id);
create table procurement.supplier_bill_history(
 id uuid primary key default gen_random_uuid(),tenant_id uuid not null,legal_entity_id uuid not null,branch_id uuid not null,
 bill_id uuid not null,version bigint not null,snapshot jsonb not null,actor_id uuid not null references auth.users(id),created_at timestamptz not null default now(),
 unique(bill_id,version),foreign key(tenant_id,bill_id) references procurement.supplier_bills(tenant_id,id)
);
create table procurement.supplier_bill_match_approvals(
 id uuid primary key default gen_random_uuid(),tenant_id uuid not null,legal_entity_id uuid not null,branch_id uuid not null,bill_id uuid not null,
 bill_version bigint not null,match_hash text not null,control_version bigint not null,reason text not null,
 approved_by uuid not null references auth.users(id),created_at timestamptz not null default now(),unique(bill_id,bill_version,match_hash),
 foreign key(tenant_id,bill_id) references procurement.supplier_bills(tenant_id,id)
);
create table procurement.supplier_bill_control_history(
 id uuid primary key default gen_random_uuid(),tenant_id uuid not null,legal_entity_id uuid not null,version bigint not null,snapshot jsonb not null,
 actor_id uuid not null references auth.users(id),created_at timestamptz not null default now(),unique(legal_entity_id,version),
 foreign key(tenant_id,legal_entity_id) references core.legal_entities(tenant_id,id)
);
create function procurement.bill_read_allowed(p_tenant uuid,p_entity uuid,p_branch uuid) returns boolean language sql stable security definer set search_path='' as $$
 select core.is_tenant_member(p_tenant) and (core.has_permission(p_tenant,'procurement.bills.view',p_entity,p_branch)
 or core.has_permission(p_tenant,'procurement.bills.manage',p_entity,p_branch) or core.has_permission(p_tenant,'procurement.bills.post',p_entity,p_branch))$$;
revoke all on function procurement.bill_read_allowed(uuid,uuid,uuid) from public,anon;
grant execute on function procurement.bill_read_allowed(uuid,uuid,uuid) to authenticated;
do $$declare t text;begin
 foreach t in array array['supplier_bills','supplier_bill_lines','supplier_bill_history','supplier_bill_match_approvals','supplier_bill_controls','supplier_bill_control_history'] loop
  execute format('alter table procurement.%I enable row level security',t);execute format('alter table procurement.%I force row level security',t);
  if t in('supplier_bill_controls','supplier_bill_control_history') then
   execute format('create policy bill_read on procurement.%I for select to authenticated using(core.is_tenant_member(tenant_id) and core.has_permission(tenant_id,''finance.setup.manage'',legal_entity_id,null))',t);
  else execute format('create policy bill_read on procurement.%I for select to authenticated using(procurement.bill_read_allowed(tenant_id,legal_entity_id,branch_id))',t);end if;
  execute format('revoke all on procurement.%I from public,anon,authenticated',t);execute format('grant select on procurement.%I to authenticated',t);
  if t in('supplier_bill_history','supplier_bill_match_approvals','supplier_bill_control_history') then
   execute format('create trigger immutable before update or delete on procurement.%I for each row execute function workflow.reject_history_mutation()',t);end if;
 end loop;
end $$;
create trigger bill_immutable before update or delete on procurement.supplier_bills for each row execute function sales.flow_protect_document();
create function procurement.bill_line_guard() returns trigger language plpgsql security definer set search_path='' as $$begin
 if exists(select 1 from procurement.supplier_bills where id=coalesce((to_jsonb(new)->>'bill_id')::uuid,(to_jsonb(old)->>'bill_id')::uuid) and status<>'draft') then
 raise exception using errcode='55000',message='BILL_NOT_EDITABLE';end if;return coalesce(new,old);end $$;
create trigger bill_line_immutable before insert or update or delete on procurement.supplier_bill_lines for each row execute function procurement.bill_line_guard();
revoke all on function procurement.bill_line_guard() from public,anon,authenticated;
create view api.supplier_bills with(security_invoker=true) as select b.tenant_id,b.legal_entity_id,b.branch_id,b.id,b.status,
 sales.flow_exact_json(to_jsonb(b))||jsonb_build_object('lines',coalesce((select jsonb_agg(l.detail order by l.id) from procurement.supplier_bill_lines l where l.bill_id=b.id),'[]'),
 'match_approvals',coalesce((select jsonb_agg(sales.flow_exact_json(to_jsonb(a)) order by a.created_at) from procurement.supplier_bill_match_approvals a where a.bill_id=b.id and a.bill_version=b.version),'[]')) detail
 from procurement.supplier_bills b;
grant select on api.supplier_bills to authenticated;
-- Preserve AR predicates while preventing receivables-only users from reading AP.
alter policy permitted_read on finance.open_items using(core.is_tenant_member(tenant_id) and
 ((kind='AR' and core.has_permission(tenant_id,'finance.receivables.view',legal_entity_id,branch_id))
 or (kind='AP' and procurement.bill_read_allowed(tenant_id,legal_entity_id,branch_id))));
create or replace function finance.flow_visible_residual(p_tenant uuid,p_id uuid) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare v_o finance.open_items%rowtype;begin
 select * into v_o from finance.open_items where tenant_id=p_tenant and id=p_id and kind='AR';
 if not found or not core.is_tenant_member(p_tenant) or not core.has_permission(p_tenant,'finance.receivables.view',v_o.legal_entity_id,v_o.branch_id) then return null;end if;
 return finance.flow_residual(p_tenant,p_id);end $$;
create or replace view api.receivable_balances with(security_invoker=true) as
select o.id,o.tenant_id,o.legal_entity_id,o.branch_id,o.party_id,o.currency_code,o.source_type,o.source_id,o.posting_date,o.due_date,
 sales.flow_exact_json(to_jsonb(o))||finance.flow_visible_residual(o.tenant_id,o.id) as detail from finance.open_items o where o.kind='AR';

create function api.upsert_supplier_bill_controls(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_command_id uuid,p_idempotency_key uuid,
 p_client_timestamp timestamptz,p_payload jsonb,p_expected_entity_version bigint default null) returns jsonb language plpgsql security definer set search_path='' as $$
declare v_command text:='procurement.bill_controls.upsert';v_hash text;v_result jsonb;v_old procurement.supplier_bill_controls%rowtype;v_base text;
 v_ap uuid:=(p_payload->>'payable_account_id')::uuid;v_tax uuid:=(p_payload->>'input_tax_account_id')::uuid;v_var uuid:=(p_payload->>'variance_account_id')::uuid;
 v_amount numeric;v_percent numeric;begin
 perform core.wave3_require_scope(p_tenant_id,'finance.setup.manage',p_legal_entity_id,p_branch_id);
 perform core.require_permission(p_tenant_id,'finance.setup.manage',p_legal_entity_id,null);
 if (p_payload->>'id')::uuid is distinct from p_legal_entity_id or p_client_timestamp is null then raise exception using errcode='22023',message='INVALID_COMMAND';end if;
 v_hash:=core.wave3_request_hash(v_command,p_command_id,p_tenant_id,p_legal_entity_id,p_branch_id,p_payload,p_expected_entity_version);
 v_result:=core.wave3_replay(p_tenant_id,v_command,p_command_id,p_idempotency_key,v_hash);if v_result is not null then return v_result;end if;
 perform pg_advisory_xact_lock(hashtextextended('bill.controls:'||p_legal_entity_id::text,0));
 select * into v_old from procurement.supplier_bill_controls where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id for update;
 if found then perform core.wave3_assert_expected_version(v_old.version,p_expected_entity_version,to_jsonb(v_old));
 elsif p_expected_entity_version is not null then raise exception using errcode='40001',message='VERSION_CONFLICT';end if;
 select currency_code into v_base from core.legal_entities where tenant_id=p_tenant_id and id=p_legal_entity_id;
 perform finance.flow_account(p_tenant_id,p_legal_entity_id,v_ap,'liability',v_base);perform finance.flow_account(p_tenant_id,p_legal_entity_id,v_tax,'asset',v_base);
 perform finance.flow_account(p_tenant_id,p_legal_entity_id,v_var,'expense',v_base);
 v_amount:=sales.wave3_decimal_string(p_payload->'amount_tolerance','amount_tolerance',6,true,0,null);
 v_percent:=sales.wave3_decimal_string(p_payload->'price_percent_tolerance','price_percent_tolerance',6,true,0,100);
 insert into procurement.supplier_bill_controls(tenant_id,legal_entity_id,payable_account_id,input_tax_account_id,variance_account_id,amount_tolerance,price_percent_tolerance,updated_by)
 values(p_tenant_id,p_legal_entity_id,v_ap,v_tax,v_var,v_amount,v_percent,auth.uid()) on conflict(legal_entity_id) do update set
 payable_account_id=excluded.payable_account_id,input_tax_account_id=excluded.input_tax_account_id,variance_account_id=excluded.variance_account_id,
 amount_tolerance=excluded.amount_tolerance,price_percent_tolerance=excluded.price_percent_tolerance,version=procurement.supplier_bill_controls.version+1,updated_by=auth.uid(),updated_at=clock_timestamp();
 select sales.flow_exact_json(to_jsonb(c))||jsonb_build_object('id',c.legal_entity_id) into v_result from procurement.supplier_bill_controls c where legal_entity_id=p_legal_entity_id;
 insert into procurement.supplier_bill_control_history(tenant_id,legal_entity_id,version,snapshot,actor_id) values(p_tenant_id,p_legal_entity_id,(v_result->>'version')::bigint,v_result,auth.uid());
 return core.wave3_finish_command(p_tenant_id,v_command,p_command_id,'supplier_bill_controls',p_legal_entity_id,p_idempotency_key,v_hash,to_jsonb(v_old),v_result,p_legal_entity_id,p_branch_id);
end $$;

-- Private normalization is shared by save, match approval and posting.
create function procurement.normalize_bill(p_tenant uuid,p_entity uuid,p_branch uuid,p_payload jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare v_c procurement.supplier_bill_controls%rowtype;v_input jsonb;v_lines jsonb:='[]';v_exceptions jsonb:='[]';v_source jsonb;v_detail jsonb;
 v_rl procurement.goods_receipt_lines%rowtype;v_r procurement.goods_receipts%rowtype;v_tax finance.tax_definitions%rowtype;v_product inventory.products%rowtype;
 v_q numeric;v_price numeric;v_discount numeric;v_gross numeric;v_net numeric;v_tax_amount numeric;v_total numeric:=0;v_subtotal numeric:=0;v_tax_total numeric:=0;
 v_already numeric;v_available numeric;v_accrual numeric;v_accrual_base numeric;v_expected numeric;v_diff numeric;v_exception jsonb;
 v_currency text:=p_payload->>'currency_code';v_date date:=(p_payload->>'document_date')::date;v_due date:=(p_payload->>'due_date')::date;
 v_supplier uuid:=(p_payload->>'supplier_id')::uuid;v_id uuid:=(p_payload->>'id')::uuid;v_line_id uuid;v_seen uuid[]:='{}';v_receipts uuid[]:='{}';
 v_scale integer;v_base text;v_rate jsonb;v_account uuid;v_grni uuid;v_blocked boolean:=false;
begin
 if v_date is null or v_due is null or v_due<v_date or v_id is null or coalesce(length(trim(p_payload->>'supplier_reference')),0) not between 1 and 140
  or jsonb_typeof(p_payload->'lines') is distinct from 'array' or jsonb_array_length(p_payload->'lines') not between 1 and 500 then raise exception using errcode='22023',message='BILL_INPUT_INVALID';end if;
 if not exists(select 1 from crm.parties where id=v_supplier and tenant_id=p_tenant and status='active' and kind in('supplier','both')) then raise exception using errcode='22023',message='SUPPLIER_INVALID';end if;
 select * into v_c from procurement.supplier_bill_controls where tenant_id=p_tenant and legal_entity_id=p_entity;
 if not found then raise exception using errcode='55000',message='BILL_CONTROLS_REQUIRED';end if;
 select currency_code,rounding_scale into v_base,v_scale from core.legal_entities where id=p_entity and tenant_id=p_tenant;
 v_rate:=finance.flow_rate(p_tenant,p_entity,v_currency,v_date,(p_payload->>'exchange_rate_id')::uuid);
 for v_input in select value from jsonb_array_elements(p_payload->'lines') order by value->>'line_id' loop
  v_line_id:=(v_input->>'line_id')::uuid;
  if v_line_id is null or v_line_id=any(v_seen) then raise exception using errcode='22023',message='BILL_LINE_ID_INVALID';end if;
  v_seen:=array_append(v_seen,v_line_id);v_exception:='[]';v_rl:=null;v_r:=null;v_product:=null;v_source:='{}';v_account:=null;v_grni:=null;v_accrual:=0;v_accrual_base:=0;
  v_q:=sales.wave3_decimal_string(v_input->'quantity','quantity',6,true,0,null);if v_q<=0 then raise exception using errcode='22023',message='BILL_QUANTITY_INVALID';end if;
  v_price:=sales.wave3_decimal_string(v_input->'unit_price','unit_price',6,true,0,null);
  v_discount:=sales.wave3_decimal_string(v_input->'discount_percent','discount_percent',6,true,0,100);
  v_gross:=round(v_q*v_price,v_scale);v_net:=v_gross-round(v_gross*v_discount/100,v_scale);v_tax_amount:=0;v_tax:=null;
  if v_input->>'tax_definition_id' is not null then
   select * into v_tax from finance.tax_definitions where id=(v_input->>'tax_definition_id')::uuid and tenant_id=p_tenant and legal_entity_id=p_entity
    and status='active' and kind in('input','zero','exempt') and valid_from<=v_date and (valid_to is null or valid_to>=v_date);
   if not found then raise exception using errcode='22023',message='INPUT_TAX_INVALID';end if;
   v_tax_amount:=round(v_net*v_tax.rate/(case when v_tax.inclusive then 100+v_tax.rate else 100 end),v_scale);
   if v_tax.inclusive then v_net:=v_net-v_tax_amount;end if;
  end if;
  if v_input->>'receipt_line_id' is not null then
   if (v_input->>'receipt_line_id')::uuid=any(v_receipts) then raise exception using errcode='22023',message='DUPLICATE_RECEIPT_LINE';end if;
   v_receipts:=array_append(v_receipts,(v_input->>'receipt_line_id')::uuid);
   select * into v_rl from procurement.goods_receipt_lines where id=(v_input->>'receipt_line_id')::uuid and tenant_id=p_tenant and legal_entity_id=p_entity and branch_id=p_branch;
   if not found then raise exception using errcode='22023',message='RECEIPT_SOURCE_INVALID';end if;
   select * into v_r from procurement.goods_receipts where id=v_rl.receipt_id;
   if (v_r.source_snapshot->>'supplier_id')::uuid<>v_supplier then raise exception using errcode='22023',message='RECEIPT_SUPPLIER_MISMATCH';end if;
   v_source:=v_rl.detail->'source_snapshot';
   select coalesce(sum(l.quantity),0) into v_already from procurement.supplier_bill_lines l join procurement.supplier_bills b on b.id=l.bill_id
    where l.receipt_line_id=v_rl.id and b.status='posted' and b.id<>v_id;
   v_available:=v_rl.accepted_quantity-v_already;
   if v_r.document_date>v_date or exists(select 1 from procurement.goods_receipt_reversals where receipt_id=v_r.id) or v_q>v_available or v_rl.accepted_quantity<=0 then
    v_blocked:=true;v_exception:=v_exception||jsonb_build_array(jsonb_build_object('code','RECEIPT_QUANTITY_UNAVAILABLE','available_quantity',greatest(v_available,0)::text,'requested_quantity',v_q::text));
   else
    v_accrual_base:=round(v_rl.base_amount*(v_already+v_q)/v_rl.accepted_quantity,v_scale)-round(v_rl.base_amount*v_already/v_rl.accepted_quantity,v_scale);
    v_accrual:=round(v_rl.net_amount*(v_already+v_q)/v_rl.accepted_quantity,v_scale)-round(v_rl.net_amount*v_already/v_rl.accepted_quantity,v_scale);
   end if;
   if not exists(select 1 from inventory.units where id=(v_source->>'unit_id')::uuid and tenant_id=p_tenant and status='active' and round(v_q,precision)=v_q) then raise exception using errcode='22023',message='BILL_UNIT_PRECISION_INVALID';end if;
   select account_id into v_grni from finance.journal_lines where journal_entry_id=v_r.journal_entry_id and base_credit>0 and source_line_id is null;
   if v_rl.base_amount<>0 and v_grni is null then raise exception using errcode='55000',message='RECEIPT_ACCRUAL_LINK_INVALID';end if;
   v_diff:=abs(v_price-(v_source->>'unit_price')::numeric);
   if v_diff>abs((v_source->>'unit_price')::numeric)*v_c.price_percent_tolerance/100 then
    v_exception:=v_exception||jsonb_build_array(jsonb_build_object('code','PRICE_VARIANCE','expected',v_source->>'unit_price','actual',v_price::text,'difference',v_diff::text));end if;
   if v_discount<>(v_source->>'discount_percent')::numeric then v_exception:=v_exception||jsonb_build_array(jsonb_build_object('code','DISCOUNT_VARIANCE','expected',v_source->>'discount_percent','actual',v_discount::text));end if;
   if (v_input->>'tax_definition_id') is distinct from (v_source->>'tax_definition_id') or coalesce(v_tax.rate,0)<>coalesce((v_source->>'tax_rate')::numeric,0)
    or coalesce(v_tax.inclusive,false)<>coalesce((v_source->>'tax_inclusive')::boolean,false) then
    v_exception:=v_exception||jsonb_build_array(jsonb_build_object('code','TAX_MISMATCH','expected_rate',v_source->>'tax_rate','actual_rate',coalesce(v_tax.rate,0)::text));end if;
   if v_currency<>v_r.currency_code then v_exception:=v_exception||jsonb_build_array(jsonb_build_object('code','CURRENCY_MISMATCH','expected',v_r.currency_code,'actual',v_currency));end if;
   v_expected:=case when v_currency=v_r.currency_code then v_accrual else round(v_accrual_base/(v_rate->>'exchange_rate')::numeric,v_scale) end;
   if abs(v_net-v_expected)>v_c.amount_tolerance then v_exception:=v_exception||jsonb_build_array(jsonb_build_object('code','TOTAL_VARIANCE','expected',v_expected::text,'actual',v_net::text,'difference',(v_net-v_expected)::text));end if;
  else
   perform core.require_permission(p_tenant,'procurement.bills.post',p_entity,p_branch);
   if v_input->>'product_id' is not null then
    select * into v_product from inventory.products where id=(v_input->>'product_id')::uuid and tenant_id=p_tenant and legal_entity_id=p_entity and status='active' and can_purchase and kind in('non_stocked','service');
    if not found then raise exception using errcode='22023',message='DIRECT_BILL_NONSTOCK_REQUIRED';end if;
   end if;
   if coalesce(length(trim(v_input->>'description')),0) not between 1 and 500 then raise exception using errcode='22023',message='DIRECT_BILL_DESCRIPTION_REQUIRED';end if;
   v_account:=finance.flow_account(p_tenant,p_entity,coalesce(v_product.expense_account_id,(v_input->>'expense_account_id')::uuid),'expense',v_currency);
  end if;
  v_detail:=jsonb_build_object('line_id',v_line_id,'receipt_line_id',v_rl.id,'order_id',v_r.order_id,'order_line_id',v_rl.order_line_id,
   'description',coalesce(v_source->>'description',v_input->>'description'),'product_id',coalesce(v_source->>'product_id',v_input->>'product_id'),
   'quantity',v_q::text,'unit_price',v_price::text,'discount_percent',v_discount::text,'tax_definition_id',v_tax.id,'tax_rate',coalesce(v_tax.rate,0)::text,'tax_inclusive',coalesce(v_tax.inclusive,false),
   'net_amount',v_net::text,'tax_amount',v_tax_amount::text,'line_total',(v_net+v_tax_amount)::text,'expense_account_id',v_account,
   'accrual_amount',v_accrual::text,'accrual_base_amount',v_accrual_base::text,'grni_account_id',v_grni,'source_snapshot',v_source,'exceptions',v_exception);
  v_lines:=v_lines||jsonb_build_array(v_detail);
  if jsonb_array_length(v_exception)>0 then v_exceptions:=v_exceptions||jsonb_build_array(jsonb_build_object('line_id',v_line_id,'exceptions',v_exception));end if;
  v_subtotal:=v_subtotal+v_net;v_tax_total:=v_tax_total+v_tax_amount;v_total:=v_total+v_net+v_tax_amount;
 end loop;
 return jsonb_build_object('lines',v_lines,'subtotal',v_subtotal::text,'tax_total',v_tax_total::text,'total',v_total::text,
  'base_total',round(v_total*(v_rate->>'exchange_rate')::numeric,v_scale)::text,'rate',v_rate,
  'match',jsonb_build_object('blocked',v_blocked,'exceptions',v_exceptions,'control_version',v_c.version,'amount_tolerance',v_c.amount_tolerance::text,'price_percent_tolerance',v_c.price_percent_tolerance::text));
end $$;
revoke all on function procurement.normalize_bill(uuid,uuid,uuid,jsonb) from public,anon,authenticated;
create function procurement.bill_history(p_tenant uuid,p_id uuid) returns void language sql security definer set search_path='' as $$
 insert into procurement.supplier_bill_history(tenant_id,legal_entity_id,branch_id,bill_id,version,snapshot,actor_id)
 select tenant_id,legal_entity_id,branch_id,id,(detail->>'version')::bigint,detail,auth.uid() from api.supplier_bills where tenant_id=p_tenant and id=p_id$$;
revoke all on function procurement.bill_history(uuid,uuid) from public,anon,authenticated;

create function api.upsert_supplier_bill(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_command_id uuid,p_idempotency_key uuid,
 p_client_timestamp timestamptz,p_payload jsonb,p_expected_entity_version bigint default null) returns jsonb language plpgsql security definer set search_path='' as $$
declare v_id uuid:=(p_payload->>'id')::uuid;v_command text:='procurement.supplier_bill.upsert';v_hash text;v_result jsonb;v_before jsonb;v_normal jsonb;v_line jsonb;v_old procurement.supplier_bills%rowtype;
begin
 perform core.wave3_require_scope(p_tenant_id,'procurement.bills.manage',p_legal_entity_id,p_branch_id);
 if p_client_timestamp is null or p_legal_entity_id is null or p_branch_id is null or v_id is null then raise exception using errcode='22023',message='INVALID_COMMAND';end if;
 v_hash:=core.wave3_request_hash(v_command,p_command_id,p_tenant_id,p_legal_entity_id,p_branch_id,p_payload,p_expected_entity_version);
 v_result:=core.wave3_replay(p_tenant_id,v_command,p_command_id,p_idempotency_key,v_hash);if v_result is not null then return v_result;end if;
 perform pg_advisory_xact_lock(hashtextextended('supplier.bill:'||v_id::text,0));
 select * into v_old from procurement.supplier_bills where id=v_id and tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id for update;
 if found then
  if v_old.status<>'draft' then raise exception using errcode='55000',message='BILL_NOT_EDITABLE';end if;
  select detail into v_before from api.supplier_bills where id=v_id;
  perform core.wave3_assert_expected_version(v_old.version,p_expected_entity_version,v_before);
 elsif p_expected_entity_version is not null then raise exception using errcode='40001',message='VERSION_CONFLICT';end if;
 v_normal:=procurement.normalize_bill(p_tenant_id,p_legal_entity_id,p_branch_id,p_payload);
 insert into procurement.supplier_bills(id,tenant_id,legal_entity_id,branch_id,supplier_id,supplier_reference,document_date,due_date,currency_code,base_currency_code,exchange_rate_id,exchange_rate,
  subtotal,tax_total,total,base_total,match_result,created_by,updated_by)
 values(v_id,p_tenant_id,p_legal_entity_id,p_branch_id,(p_payload->>'supplier_id')::uuid,trim(p_payload->>'supplier_reference'),(p_payload->>'document_date')::date,(p_payload->>'due_date')::date,
  p_payload->>'currency_code',v_normal#>>'{rate,base_currency_code}',(p_payload->>'exchange_rate_id')::uuid,(v_normal#>>'{rate,exchange_rate}')::numeric,
  (v_normal->>'subtotal')::numeric,(v_normal->>'tax_total')::numeric,(v_normal->>'total')::numeric,(v_normal->>'base_total')::numeric,v_normal->'match',auth.uid(),auth.uid())
 on conflict(id) do update set supplier_id=excluded.supplier_id,supplier_reference=excluded.supplier_reference,document_date=excluded.document_date,due_date=excluded.due_date,
 currency_code=excluded.currency_code,base_currency_code=excluded.base_currency_code,exchange_rate_id=excluded.exchange_rate_id,exchange_rate=excluded.exchange_rate,
 subtotal=excluded.subtotal,tax_total=excluded.tax_total,total=excluded.total,base_total=excluded.base_total,match_result=excluded.match_result,
 version=procurement.supplier_bills.version+1,updated_by=auth.uid(),updated_at=clock_timestamp()
 where procurement.supplier_bills.tenant_id=p_tenant_id and procurement.supplier_bills.legal_entity_id=p_legal_entity_id and procurement.supplier_bills.branch_id=p_branch_id;
 if not found then raise exception using errcode='42501',message='BILL_SCOPE_INVALID';end if;
 delete from procurement.supplier_bill_lines where bill_id=v_id;
 for v_line in select value from jsonb_array_elements(v_normal->'lines') loop
  insert into procurement.supplier_bill_lines(id,tenant_id,legal_entity_id,branch_id,bill_id,receipt_line_id,quantity,detail)
  values((v_line->>'line_id')::uuid,p_tenant_id,p_legal_entity_id,p_branch_id,v_id,(v_line->>'receipt_line_id')::uuid,(v_line->>'quantity')::numeric,v_line);
 end loop;
 perform procurement.bill_history(p_tenant_id,v_id);select detail into v_result from api.supplier_bills where id=v_id;
 return core.wave3_finish_command(p_tenant_id,v_command,p_command_id,'supplier_bill',v_id,p_idempotency_key,v_hash,v_before,v_result,p_legal_entity_id,p_branch_id);
end $$;

create function procurement.bill_action(p_action text,p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_command_id uuid,p_idempotency_key uuid,
 p_client_timestamp timestamptz,p_payload jsonb,p_expected_entity_version bigint) returns jsonb language plpgsql security definer set search_path='' as $$
declare v_id uuid:=(p_payload->>'document_id')::uuid;v_command text:='procurement.supplier_bill.'||p_action;v_hash text;v_result jsonb;v_before jsonb;v_normal jsonb;v_match_hash text;
 v_b procurement.supplier_bills%rowtype;v_c procurement.supplier_bill_controls%rowtype;v_line jsonb;v_order uuid;v_jlines jsonb:='[]';v_request uuid:=gen_random_uuid();
 v_journal uuid;v_open uuid:=gen_random_uuid();v_number text;v_scale integer;v_net numeric;v_tax numeric;v_base_tax numeric;v_acc_base numeric;v_acc numeric;
 v_debits numeric:=0;v_base_debits numeric:=0;v_var numeric;v_base_var numeric;
begin
 perform core.wave3_require_scope(p_tenant_id,case when p_action='cancel' then 'procurement.bills.manage' else 'procurement.bills.post' end,p_legal_entity_id,p_branch_id);
 if p_action not in('post','approve','cancel') or v_id is null or p_client_timestamp is null or p_branch_id is null or p_legal_entity_id is null then raise exception using errcode='22023',message='INVALID_COMMAND';end if;
 if p_action='approve' then perform core.wave3_require_scope(p_tenant_id,'workflow.approvals.decide',p_legal_entity_id,p_branch_id);end if;
 v_hash:=core.wave3_request_hash(v_command,p_command_id,p_tenant_id,p_legal_entity_id,p_branch_id,p_payload,p_expected_entity_version);
 v_result:=core.wave3_replay(p_tenant_id,v_command,p_command_id,p_idempotency_key,v_hash);if v_result is not null then return v_result;end if;
 select * into v_b from procurement.supplier_bills where id=v_id and tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id for update;
 if not found then raise exception using errcode='P0002',message='BILL_NOT_FOUND';end if;
 select detail into v_before from api.supplier_bills where id=v_id;
 perform core.wave3_assert_expected_version(v_b.version,p_expected_entity_version,v_before);
 if v_b.status<>'draft' then raise exception using errcode='55000',message='BILL_NOT_EDITABLE';end if;
 if p_action='cancel' then
  if coalesce(length(trim(p_payload->>'reason')),0) not between 1 and 1000 then raise exception using errcode='22023',message='CANCELLATION_REASON_REQUIRED';end if;
  update procurement.supplier_bills set status='cancelled',version=version+1,updated_by=auth.uid(),updated_at=clock_timestamp() where id=v_id;
 else
  for v_order in select distinct (detail->>'order_id')::uuid from procurement.supplier_bill_lines where bill_id=v_id and detail->>'order_id' is not null order by 1 loop
   perform 1 from procurement.purchase_orders where id=v_order for update;
   perform 1 from procurement.purchase_order_lines where order_id=v_order order by id for update;
  end loop;
  select * into v_c from procurement.supplier_bill_controls where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id for share;
  v_normal:=procurement.normalize_bill(p_tenant_id,p_legal_entity_id,p_branch_id,v_before);
  if (v_normal#>>'{match,blocked}')::boolean then raise exception using errcode='55000',message='RECEIPT_QUANTITY_UNAVAILABLE';end if;
  if (v_normal->>'total')::numeric is distinct from v_b.total or (v_normal#>>'{rate,exchange_rate}')::numeric<>v_b.exchange_rate then
   raise exception using errcode='40001',message='BILL_PRICING_CHANGED';end if;
  v_match_hash:=encode(extensions.digest((v_normal->'match')::text||'|'||(v_normal->'lines')::text,'sha256'),'hex');
  if p_action='approve' then
   if auth.uid() in(v_b.created_by,v_b.updated_by) then raise exception using errcode='42501',message='SEGREGATION_OF_DUTIES_VIOLATION';end if;
   if coalesce(length(trim(p_payload->>'reason')),0) not between 1 and 1000 then raise exception using errcode='22023',message='MATCH_REASON_REQUIRED';end if;
   insert into procurement.supplier_bill_match_approvals(tenant_id,legal_entity_id,branch_id,bill_id,bill_version,match_hash,control_version,reason,approved_by)
   values(p_tenant_id,p_legal_entity_id,p_branch_id,v_id,v_b.version,v_match_hash,v_c.version,trim(p_payload->>'reason'),auth.uid());
  else
   if jsonb_array_length(v_normal#>'{match,exceptions}')>0 and not exists(select 1 from procurement.supplier_bill_match_approvals
    where bill_id=v_id and bill_version=v_b.version and match_hash=v_match_hash and control_version=v_c.version) then raise exception using errcode='55000',message='MATCH_APPROVAL_REQUIRED';end if;
   if v_b.total<=0 or v_b.base_total<=0 then raise exception using errcode='22023',message='POSITIVE_BILL_REQUIRED';end if;
   perform finance.wave3_lock_open_period(p_tenant_id,p_legal_entity_id,v_b.document_date);
   perform finance.flow_account(p_tenant_id,p_legal_entity_id,v_c.payable_account_id,'liability',v_b.currency_code);
   perform finance.flow_account(p_tenant_id,p_legal_entity_id,v_c.input_tax_account_id,'asset',v_b.currency_code);
   perform finance.flow_account(p_tenant_id,p_legal_entity_id,v_c.variance_account_id,'expense',v_b.currency_code);
   select rounding_scale into v_scale from core.legal_entities where id=p_legal_entity_id;
   for v_line in select value from jsonb_array_elements(v_normal->'lines') loop
    v_net:=(v_line->>'net_amount')::numeric;v_tax:=(v_line->>'tax_amount')::numeric;v_base_tax:=round(v_tax*v_b.exchange_rate,v_scale);
    if v_line->>'receipt_line_id' is not null then
     v_acc_base:=(v_line->>'accrual_base_amount')::numeric;
     v_acc:=round(v_acc_base/v_b.exchange_rate,v_scale);
     if v_acc_base<>0 then v_jlines:=v_jlines||jsonb_build_array(finance.flow_jline((v_line->>'grni_account_id')::uuid,v_acc,v_acc_base,(v_line->>'line_id')::uuid));end if;
     update procurement.purchase_order_lines set billed_quantity=billed_quantity+(v_line->>'quantity')::numeric where id=(v_line->>'order_line_id')::uuid;
    else
     v_acc:=v_net;v_acc_base:=round(v_net*v_b.exchange_rate,v_scale);
     if v_acc_base<>0 or v_acc<>0 then v_jlines:=v_jlines||jsonb_build_array(finance.flow_jline((v_line->>'expense_account_id')::uuid,v_acc,v_acc_base,(v_line->>'line_id')::uuid));end if;
    end if;
    if v_tax<>0 or v_base_tax<>0 then v_jlines:=v_jlines||jsonb_build_array(finance.flow_jline(v_c.input_tax_account_id,v_tax,v_base_tax,(v_line->>'line_id')::uuid));end if;
    v_debits:=v_debits+v_acc+v_tax;v_base_debits:=v_base_debits+v_acc_base+v_base_tax;
    update procurement.supplier_bill_lines set detail=v_line where id=(v_line->>'line_id')::uuid and bill_id=v_id;
   end loop;
   v_var:=v_b.total-v_debits;v_base_var:=v_b.base_total-v_base_debits;
   if v_var<>0 or v_base_var<>0 then v_jlines:=v_jlines||jsonb_build_array(finance.flow_jline(v_c.variance_account_id,v_var,v_base_var));end if;
   v_jlines:=v_jlines||jsonb_build_array(finance.flow_jline(v_c.payable_account_id,-v_b.total,-v_b.base_total));
   v_journal:=finance.flow_post_journal(to_jsonb(v_b)||jsonb_build_object('customer_id',v_b.supplier_id),v_jlines,'supplier_bill',v_id,v_request,p_command_id);
   v_number:=sales.wave3_reserve_document_number(p_tenant_id,p_legal_entity_id,p_branch_id,'supplier_bill',v_b.document_date,auth.uid());
   insert into finance.open_items(id,tenant_id,legal_entity_id,branch_id,kind,party_id,source_type,source_id,document_number,currency_code,base_currency_code,exchange_rate,
    original_amount,original_base_amount,posting_date,due_date,journal_entry_id,request_id,command_id,correlation_id,created_by)
   values(v_open,p_tenant_id,p_legal_entity_id,p_branch_id,'AP',v_b.supplier_id,'supplier_bill',v_id,v_number,v_b.currency_code,v_b.base_currency_code,v_b.exchange_rate,
    v_b.total,v_b.base_total,v_b.document_date,v_b.due_date,v_journal,v_request,p_command_id,v_request,auth.uid());
   update procurement.supplier_bills set status='posted',document_number=v_number,version=version+1,match_result=v_normal->'match',journal_entry_id=v_journal,open_item_id=v_open,updated_by=auth.uid(),updated_at=clock_timestamp() where id=v_id;
   for v_order in select distinct (detail->>'order_id')::uuid from procurement.supplier_bill_lines where bill_id=v_id and detail->>'order_id' is not null order by 1 loop
    update procurement.purchase_orders set version=version+1,updated_by=auth.uid(),updated_at=clock_timestamp() where id=v_order;
    perform procurement.record_order_history(jsonb_build_object('entity',(select detail from api.purchase_orders where id=v_order)));
   end loop;
  end if;
 end if;
 if p_action<>'approve' then perform procurement.bill_history(p_tenant_id,v_id);end if;
 select detail into v_result from api.supplier_bills where id=v_id;
 return core.wave3_finish_command(p_tenant_id,v_command,p_command_id,'supplier_bill',v_id,p_idempotency_key,v_hash,v_before,v_result,p_legal_entity_id,p_branch_id,'{}',
  case when p_action='approve' then null else jsonb_build_object('from_status','draft','to_status',v_result->>'status','reason',p_payload->>'reason') end,
  jsonb_build_array(jsonb_build_object('topic',v_command,'payload',jsonb_build_object('bill_id',v_id))),'[]',v_request,v_request);
end $$;
revoke all on function procurement.bill_action(text,uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) from public,anon,authenticated;
do $$declare v_name text;v_action text;begin
 for v_name,v_action in select * from(values('post_supplier_bill','post'),('approve_supplier_bill_match','approve'),('cancel_supplier_bill','cancel')) x loop
 execute format('create function api.%I(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_command_id uuid,p_idempotency_key uuid,p_client_timestamp timestamptz,p_payload jsonb,p_expected_entity_version bigint default null) returns jsonb language sql security definer set search_path='''' as $fn$select procurement.bill_action(%L,p_tenant_id,p_legal_entity_id,p_branch_id,p_command_id,p_idempotency_key,p_client_timestamp,p_payload,p_expected_entity_version)$fn$',v_name,v_action);
 execute format('revoke all on function api.%I(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) from public,anon',v_name);
 execute format('grant execute on function api.%I(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) to authenticated',v_name);
 end loop;
end $$;
revoke all on function api.upsert_supplier_bill(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint),api.upsert_supplier_bill_controls(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) from public,anon;
grant execute on function api.upsert_supplier_bill(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint),api.upsert_supplier_bill_controls(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) to authenticated;

create function api.supplier_bill_reference_options(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_resource text,p_after uuid default null,p_search text default '')
returns jsonb language plpgsql security definer set search_path='' as $$
declare v_items jsonb;v_next uuid;v_search text:=lower(trim(coalesce(p_search,'')));v_base text;begin
 if p_resource in('bill_controls','bill_accounts') then
  perform core.wave3_require_scope(p_tenant_id,'finance.setup.manage',p_legal_entity_id,p_branch_id);
  perform core.require_permission(p_tenant_id,'finance.setup.manage',p_legal_entity_id,null);
 else perform core.wave3_require_scope(p_tenant_id,'procurement.bills.manage',p_legal_entity_id,p_branch_id);end if;
 if p_legal_entity_id is null or p_branch_id is null or length(v_search)>100 then raise exception using errcode='22023',message='REFERENCE_SCOPE_INVALID';end if;
 select currency_code into v_base from core.legal_entities where id=p_legal_entity_id and tenant_id=p_tenant_id;
 if p_resource='bill_receipts' then
  select jsonb_agg(jsonb_build_object('id',id,'code',code,'name',name,'detail',detail) order by id) into v_items from (
   select l.id,r.document_number code,l.detail->>'description' name,l.detail||jsonb_build_object('receipt_line_id',l.id,
    'supplier_id',r.source_snapshot->>'supplier_id','currency_code',r.currency_code,'exchange_rate_id',r.source_snapshot->>'exchange_rate_id',
    'available_quantity',(l.accepted_quantity-coalesce((select sum(bl.quantity) from procurement.supplier_bill_lines bl join procurement.supplier_bills b on b.id=bl.bill_id
     where bl.receipt_line_id=l.id and b.status='posted'),0))::text) detail
   from procurement.goods_receipt_lines l join procurement.goods_receipts r on r.id=l.receipt_id
   where l.tenant_id=p_tenant_id and l.legal_entity_id=p_legal_entity_id and l.branch_id=p_branch_id and l.accepted_quantity>0
    and not exists(select 1 from procurement.goods_receipt_reversals x where x.receipt_id=r.id)
    and (p_after is null or l.id>p_after) and (v_search='' or position(v_search in lower(r.document_number||' '||(l.detail->>'description')))>0)
   order by l.id limit 51) x;
 elsif p_resource='bill_controls' then
  select jsonb_agg(sales.flow_exact_json(to_jsonb(c))||jsonb_build_object('id',c.legal_entity_id)) into v_items from procurement.supplier_bill_controls c
   where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id;
 elsif p_resource in('bill_accounts','bill_expenses') then
  select jsonb_agg(jsonb_build_object('id',id,'code',code,'name',name,'account_type',account_type) order by id) into v_items from (
   select * from finance.accounts where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and status='active' and is_posting
    and (p_resource='bill_accounts' or account_type='expense') and (p_after is null or id>p_after)
    and (v_search='' or position(v_search in lower(code||' '||name))>0) order by id limit 51) x;
 elsif p_resource='bill_suppliers' then
  select jsonb_agg(jsonb_build_object('id',id,'code',code,'name',display_name) order by id) into v_items from (
   select * from crm.parties where tenant_id=p_tenant_id and status='active' and kind in('supplier','both') and (p_after is null or id>p_after)
   and (v_search='' or position(v_search in lower(code||' '||display_name))>0) order by id limit 51) x;
 elsif p_resource='bill_taxes' then
  select jsonb_agg(jsonb_build_object('id',id,'code',code,'name',name,'rate',rate::text,'inclusive',inclusive) order by id) into v_items from (
   select * from finance.tax_definitions where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and status='active' and kind in('input','zero','exempt')
    and (p_after is null or id>p_after) and (v_search='' or position(v_search in lower(code||' '||name))>0) order by id limit 51) x;
 elsif p_resource='bill_rates' then
  select jsonb_agg(jsonb_build_object('id',id,'code',source_currency_code,'name',effective_date::text||' · '||rate::text,'currency_code',source_currency_code,'exchange_rate',rate::text) order by id) into v_items from (
   select * from finance.exchange_rates where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and status='active' and target_currency_code=v_base
    and (p_after is null or id>p_after) and (v_search='' or position(v_search in lower(source_currency_code))>0) order by id limit 51) x;
 else raise exception using errcode='22023',message='REFERENCE_RESOURCE_INVALID';end if;
 v_items:=coalesce(v_items,'[]');if jsonb_array_length(v_items)>50 then v_next:=(v_items->49->>'id')::uuid;v_items:=v_items-50;end if;
 return jsonb_build_object('items',v_items,'next_cursor',v_next,'base_currency',v_base);
end $$;
revoke all on function api.supplier_bill_reference_options(uuid,uuid,uuid,text,uuid,text) from public,anon;
grant execute on function api.supplier_bill_reference_options(uuid,uuid,uuid,text,uuid,text) to authenticated;

-- AC-312 candidate. Recorded settlement only; no external payment integration.
create function finance.payable_read_allowed(p_tenant uuid,p_entity uuid,p_branch uuid) returns boolean language sql stable security definer set search_path='' as $$
 select core.is_tenant_member(p_tenant) and (procurement.bill_read_allowed(p_tenant,p_entity,p_branch)
 or core.has_permission(p_tenant,'finance.payments.manage',p_entity,p_branch) or core.has_permission(p_tenant,'finance.payments.post',p_entity,p_branch))$$;
revoke all on function finance.payable_read_allowed(uuid,uuid,uuid) from public,anon;
grant execute on function finance.payable_read_allowed(uuid,uuid,uuid) to authenticated;
alter policy permitted_read on finance.open_items using(core.is_tenant_member(tenant_id) and
 ((kind='AR' and core.has_permission(tenant_id,'finance.receivables.view',legal_entity_id,branch_id))
 or (kind='AP' and finance.payable_read_allowed(tenant_id,legal_entity_id,branch_id))));
alter policy permitted_read on finance.open_item_allocations using(core.is_tenant_member(tenant_id) and exists(select 1 from finance.open_items o
 where o.id=source_open_item_id and o.tenant_id=open_item_allocations.tenant_id and
 ((o.kind='AR' and core.has_permission(o.tenant_id,'finance.receivables.view',o.legal_entity_id,o.branch_id))
 or (o.kind='AP' and finance.payable_read_allowed(o.tenant_id,o.legal_entity_id,o.branch_id)))));
create table procurement.payment_proposals(
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,branch_id uuid not null,supplier_id uuid not null,cash_bank_account_id uuid not null,
 document_date date not null,document_number text,currency_code text not null,base_currency_code text not null,exchange_rate_id uuid,exchange_rate numeric(20,10) not null,
 total numeric(20,6) not null check(total>0),base_total numeric(20,6) not null check(base_total>0),lines jsonb not null,
 status text not null default 'draft' check(status in('draft','pending_approval','approved','rejected','cancelled','posted')),
 version bigint not null default 1,workflow_snapshot jsonb,submitted_by uuid references auth.users(id),submitted_at timestamptz,
 created_by uuid not null references auth.users(id),prepared_by uuid not null references auth.users(id),updated_by uuid not null references auth.users(id),
 created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
 unique(tenant_id,id),unique(tenant_id,legal_entity_id,branch_id,document_number),
 foreign key(tenant_id,supplier_id) references crm.parties(tenant_id,id),foreign key(tenant_id,cash_bank_account_id) references finance.cash_bank_accounts(tenant_id,id),
 foreign key(tenant_id,branch_id) references core.branches(tenant_id,id),foreign key(tenant_id,legal_entity_id) references core.legal_entities(tenant_id,id),
 foreign key(tenant_id,legal_entity_id,exchange_rate_id) references finance.exchange_rates(tenant_id,legal_entity_id,id)
);
create table procurement.payment_proposal_history(
 id uuid primary key default gen_random_uuid(),tenant_id uuid not null,legal_entity_id uuid not null,branch_id uuid not null,
 proposal_id uuid not null,version bigint not null,snapshot jsonb not null,actor_id uuid not null references auth.users(id),created_at timestamptz not null default now(),
 unique(proposal_id,version),foreign key(tenant_id,proposal_id) references procurement.payment_proposals(tenant_id,id)
);
create table procurement.payment_claims(
 id uuid primary key default gen_random_uuid(),tenant_id uuid not null,legal_entity_id uuid not null,branch_id uuid not null,
 proposal_id uuid not null,open_item_id uuid not null,amount numeric(20,6) not null check(amount>0),active boolean not null default true,
 created_at timestamptz not null default now(),released_at timestamptz,
 foreign key(tenant_id,proposal_id) references procurement.payment_proposals(tenant_id,id),foreign key(tenant_id,open_item_id) references finance.open_items(tenant_id,id)
);
create unique index payment_claim_exclusive on procurement.payment_claims(tenant_id,open_item_id) where active;
create index payment_claim_proposal on procurement.payment_claims(tenant_id,proposal_id,active,open_item_id);
create table procurement.supplier_payments(
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,branch_id uuid not null,proposal_id uuid not null unique,supplier_id uuid not null,
 cash_bank_account_id uuid not null,document_date date not null,document_number text not null,reference text not null,
 currency_code text not null,base_currency_code text not null,exchange_rate numeric(20,10) not null,amount numeric(20,6) not null,base_amount numeric(20,6) not null,
 journal_entry_id uuid not null,open_item_id uuid not null,allocations jsonb not null,source_snapshot jsonb not null,
 request_id uuid not null,command_id uuid not null,created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),
 unique(tenant_id,id),foreign key(tenant_id,proposal_id) references procurement.payment_proposals(tenant_id,id),
 foreign key(tenant_id,journal_entry_id) references finance.journal_entries(tenant_id,id),foreign key(tenant_id,open_item_id) references finance.open_items(tenant_id,id),
 foreign key(tenant_id,cash_bank_account_id) references finance.cash_bank_accounts(tenant_id,id),foreign key(tenant_id,supplier_id) references crm.parties(tenant_id,id)
);
create index payment_proposals_scope on procurement.payment_proposals(tenant_id,legal_entity_id,branch_id,status,document_date,id);
create index supplier_payments_scope on procurement.supplier_payments(tenant_id,legal_entity_id,branch_id,document_date,id);
do $$declare t text;begin
 foreach t in array array['payment_proposals','payment_proposal_history','payment_claims','supplier_payments'] loop
 execute format('alter table procurement.%I enable row level security',t);execute format('alter table procurement.%I force row level security',t);
 execute format('create policy payment_read on procurement.%I for select to authenticated using(finance.payable_read_allowed(tenant_id,legal_entity_id,branch_id))',t);
 execute format('revoke all on procurement.%I from public,anon,authenticated',t);execute format('grant select on procurement.%I to authenticated',t);
 if t in('payment_proposal_history','supplier_payments') then execute format('create trigger immutable before update or delete on procurement.%I for each row execute function workflow.reject_history_mutation()',t);end if;
 end loop;
end $$;
create trigger proposal_posted_immutable before update or delete on procurement.payment_proposals for each row execute function sales.flow_protect_document();
create view api.payment_proposals with(security_invoker=true) as select p.tenant_id,p.legal_entity_id,p.branch_id,p.id,p.status,sales.flow_exact_json(to_jsonb(p)) detail from procurement.payment_proposals p;
create view api.supplier_payments with(security_invoker=true) as select p.tenant_id,p.legal_entity_id,p.branch_id,p.id,
 sales.flow_exact_json(to_jsonb(p))||jsonb_build_object('status','posted','reconciliation_status','pending') detail from procurement.supplier_payments p;
grant select on api.payment_proposals,api.supplier_payments to authenticated;
create function finance.payable_residual(p_tenant uuid,p_id uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare v_o finance.open_items%rowtype;begin select * into v_o from finance.open_items where tenant_id=p_tenant and id=p_id and kind='AP';
 if not found or not finance.payable_read_allowed(p_tenant,v_o.legal_entity_id,v_o.branch_id) then return null;end if;
 return finance.flow_residual(p_tenant,p_id);end $$;
revoke all on function finance.payable_residual(uuid,uuid) from public,anon;
grant execute on function finance.payable_residual(uuid,uuid) to authenticated;
create view api.payable_balances with(security_invoker=true) as select o.id,o.tenant_id,o.legal_entity_id,o.branch_id,o.party_id,o.currency_code,o.posting_date,o.due_date,
 sales.flow_exact_json(to_jsonb(o))||finance.payable_residual(o.tenant_id,o.id) detail from finance.open_items o where kind='AP';
grant select on api.payable_balances to authenticated;

create function procurement.normalize_payment_proposal(p_tenant uuid,p_entity uuid,p_branch uuid,p_payload jsonb,p_lock boolean default false)
returns jsonb language plpgsql security definer set search_path='' as $$
declare v_bank finance.cash_bank_accounts%rowtype;v_o finance.open_items%rowtype;v_line jsonb;v_lines jsonb:='[]';v_id uuid;v_seen uuid[]:='{}';
 v_amount numeric;v_total numeric:=0;v_residual jsonb;v_rate jsonb;v_scale integer;v_date date:=(p_payload->>'document_date')::date;
begin
 if jsonb_typeof(p_payload->'lines') is distinct from 'array' or jsonb_array_length(p_payload->'lines') not between 1 and 500 or v_date is null then raise exception using errcode='22023',message='PROPOSAL_INPUT_INVALID';end if;
 if p_lock then perform 1 from finance.cash_bank_accounts where id=(p_payload->>'cash_bank_account_id')::uuid and tenant_id=p_tenant for share;end if;
 select * into v_bank from finance.cash_bank_accounts where id=(p_payload->>'cash_bank_account_id')::uuid and tenant_id=p_tenant and legal_entity_id=p_entity and branch_id=p_branch and status='active';
 if not found then raise exception using errcode='22023',message='PAYMENT_BANK_INVALID';end if;
 perform finance.flow_account(p_tenant,p_entity,v_bank.account_id,'asset',v_bank.currency_code);
 if not exists(select 1 from crm.parties where id=(p_payload->>'supplier_id')::uuid and tenant_id=p_tenant and status='active' and kind in('supplier','both')) then raise exception using errcode='22023',message='SUPPLIER_INVALID';end if;
 v_rate:=finance.flow_rate(p_tenant,p_entity,v_bank.currency_code,v_date,(p_payload->>'exchange_rate_id')::uuid);
 select rounding_scale into v_scale from core.legal_entities where tenant_id=p_tenant and id=p_entity;
 for v_line in select value from jsonb_array_elements(p_payload->'lines') order by value->>'open_item_id' loop
  v_id:=(v_line->>'open_item_id')::uuid;
  if v_id is null or v_id=any(v_seen) then raise exception using errcode='22023',message='PROPOSAL_ITEM_DUPLICATE';end if;
  v_seen:=array_append(v_seen,v_id);
  if p_lock then perform 1 from finance.open_items where id=v_id and tenant_id=p_tenant for update;end if;
  select * into v_o from finance.open_items where id=v_id and tenant_id=p_tenant and legal_entity_id=p_entity and branch_id=p_branch and kind='AP'
   and party_id=(p_payload->>'supplier_id')::uuid and currency_code=v_bank.currency_code and posting_date<=v_date and (original_amount<0 or due_date<=v_date);
  if not found then raise exception using errcode='22023',message='PAYABLE_ITEM_INELIGIBLE';end if;
  if exists(select 1 from procurement.payment_claims where tenant_id=p_tenant and open_item_id=v_id and active and proposal_id<>(p_payload->>'id')::uuid) then raise exception using errcode='55000',message='PAYABLE_ITEM_ALREADY_SELECTED';end if;
  if exists(select 1 from finance.open_item_allocations where tenant_id=p_tenant and (source_open_item_id=v_id or target_open_item_id=v_id) and posting_date>v_date) then raise exception using errcode='22023',message='ALLOCATION_DATE_BEFORE_LATEST';end if;
  v_amount:=sales.wave3_decimal_string(v_line->'amount','amount',6,true,0,null);v_residual:=finance.flow_residual(p_tenant,v_id);
  if v_amount<=0 or round(v_amount,v_scale)<>v_amount or v_amount>abs((v_residual->>'amount')::numeric) then raise exception using errcode='22023',message='PROPOSAL_AMOUNT_EXCEEDED';end if;
  v_total:=v_total+case when v_o.original_amount>0 then v_amount else -v_amount end;
  v_lines:=v_lines||jsonb_build_array(jsonb_build_object('open_item_id',v_id,'document_number',v_o.document_number,'kind',case when v_o.original_amount>0 then 'bill' else 'credit' end,
   'amount',v_amount::text,'residual',v_residual,'due_date',v_o.due_date,'currency_code',v_o.currency_code));
 end loop;
 if v_total<=0 then raise exception using errcode='22023',message='POSITIVE_PAYMENT_REQUIRED';end if;
 return jsonb_build_object('lines',v_lines,'currency_code',v_bank.currency_code,'rate',v_rate,'total',v_total::text,'base_total',round(v_total*(v_rate->>'exchange_rate')::numeric,v_scale)::text);
end $$;
revoke all on function procurement.normalize_payment_proposal(uuid,uuid,uuid,jsonb,boolean) from public,anon,authenticated;
create function procurement.record_payment_proposal_history(p_result jsonb) returns void language sql security definer set search_path='' as $$
 insert into procurement.payment_proposal_history(tenant_id,legal_entity_id,branch_id,proposal_id,version,snapshot,actor_id)
 select (e->>'tenant_id')::uuid,(e->>'legal_entity_id')::uuid,(e->>'branch_id')::uuid,(e->>'id')::uuid,(e->>'version')::bigint,e,auth.uid()
 from(select p_result->'entity' e)x on conflict(proposal_id,version) do nothing$$;
revoke all on function procurement.record_payment_proposal_history(jsonb) from public,anon,authenticated;
create function api.upsert_payment_proposal(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_command_id uuid,p_idempotency_key uuid,p_client_timestamp timestamptz,
 p_payload jsonb,p_expected_entity_version bigint default null) returns jsonb language plpgsql security definer set search_path='' as $$
declare v_id uuid:=(p_payload->>'id')::uuid;v_command text:='procurement.payment_proposal.upsert';v_hash text;v_result jsonb;v_before jsonb;v_n jsonb;v_line jsonb;v_old procurement.payment_proposals%rowtype;
begin
 perform core.wave3_require_scope(p_tenant_id,'finance.payments.manage',p_legal_entity_id,p_branch_id);
 if v_id is null or p_legal_entity_id is null or p_branch_id is null or p_client_timestamp is null then raise exception using errcode='22023',message='INVALID_COMMAND';end if;
 v_hash:=core.wave3_request_hash(v_command,p_command_id,p_tenant_id,p_legal_entity_id,p_branch_id,p_payload,p_expected_entity_version);
 v_result:=core.wave3_replay(p_tenant_id,v_command,p_command_id,p_idempotency_key,v_hash);if v_result is not null then return v_result;end if;
 perform pg_advisory_xact_lock(hashtextextended('payment.proposal:'||v_id::text,0));
 select * into v_old from procurement.payment_proposals where id=v_id and tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id for update;
 if found then
  if v_old.status<>'draft' then raise exception using errcode='55000',message='PROPOSAL_NOT_EDITABLE';end if;
  select detail into v_before from api.payment_proposals where id=v_id;perform core.wave3_assert_expected_version(v_old.version,p_expected_entity_version,v_before);
 elsif p_expected_entity_version is not null then raise exception using errcode='40001',message='VERSION_CONFLICT';end if;
 v_n:=procurement.normalize_payment_proposal(p_tenant_id,p_legal_entity_id,p_branch_id,p_payload,true);
 insert into procurement.payment_proposals(id,tenant_id,legal_entity_id,branch_id,supplier_id,cash_bank_account_id,document_date,currency_code,base_currency_code,exchange_rate_id,exchange_rate,total,base_total,lines,created_by,prepared_by,updated_by)
 values(v_id,p_tenant_id,p_legal_entity_id,p_branch_id,(p_payload->>'supplier_id')::uuid,(p_payload->>'cash_bank_account_id')::uuid,(p_payload->>'document_date')::date,
 v_n->>'currency_code',v_n#>>'{rate,base_currency_code}',(p_payload->>'exchange_rate_id')::uuid,(v_n#>>'{rate,exchange_rate}')::numeric,(v_n->>'total')::numeric,(v_n->>'base_total')::numeric,v_n->'lines',auth.uid(),auth.uid(),auth.uid())
 on conflict(id) do update set supplier_id=excluded.supplier_id,cash_bank_account_id=excluded.cash_bank_account_id,document_date=excluded.document_date,currency_code=excluded.currency_code,
 base_currency_code=excluded.base_currency_code,exchange_rate_id=excluded.exchange_rate_id,exchange_rate=excluded.exchange_rate,total=excluded.total,base_total=excluded.base_total,
 lines=excluded.lines,version=procurement.payment_proposals.version+1,prepared_by=auth.uid(),updated_by=auth.uid(),updated_at=clock_timestamp()
 where procurement.payment_proposals.tenant_id=p_tenant_id and procurement.payment_proposals.legal_entity_id=p_legal_entity_id and procurement.payment_proposals.branch_id=p_branch_id;
 if not found then raise exception using errcode='42501',message='PROPOSAL_SCOPE_INVALID';end if;
 update procurement.payment_claims set active=false,released_at=clock_timestamp() where proposal_id=v_id and active;
 for v_line in select value from jsonb_array_elements(v_n->'lines') loop
  insert into procurement.payment_claims(tenant_id,legal_entity_id,branch_id,proposal_id,open_item_id,amount)
  values(p_tenant_id,p_legal_entity_id,p_branch_id,v_id,(v_line->>'open_item_id')::uuid,(v_line->>'amount')::numeric);
 end loop;
 select detail into v_result from api.payment_proposals where id=v_id;
 v_result:=core.wave3_finish_command(p_tenant_id,v_command,p_command_id,'payment_proposal',v_id,p_idempotency_key,v_hash,v_before,v_result,p_legal_entity_id,p_branch_id);
 perform procurement.record_payment_proposal_history(v_result);return v_result;
end $$;
revoke all on function api.upsert_payment_proposal(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) from public,anon;
grant execute on function api.upsert_payment_proposal(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) to authenticated;

create function finance.allocate_payable(p_source uuid,p_target uuid,p_tenant uuid,p_entity uuid,p_branch uuid,p_payload jsonb,p_date date,p_request uuid,p_command uuid,p_proposal uuid default null)
returns jsonb language plpgsql security definer set search_path='' as $$
declare v_s finance.open_items%rowtype;v_t finance.open_items%rowtype;v_sr jsonb;v_tr jsonb;v_rate finance.exchange_rates%rowtype;v_scale integer;
 v_source numeric;v_target numeric;v_sb numeric;v_tb numeric;v_prior numeric;v_fx numeric;v_conversion numeric:=1;v_id uuid:=gen_random_uuid();v_journal uuid;v_control uuid;v_doc jsonb;
begin
 perform 1 from finance.open_items where tenant_id=p_tenant and id in(p_source,p_target) order by id for update;
 select * into v_s from finance.open_items where tenant_id=p_tenant and legal_entity_id=p_entity and branch_id=p_branch and id=p_source;
 select * into v_t from finance.open_items where tenant_id=p_tenant and legal_entity_id=p_entity and branch_id=p_branch and id=p_target;
 if v_s.id is null or v_t.id is null or v_s.party_id<>v_t.party_id or v_s.kind<>'AP' or v_t.kind<>'AP' or v_s.original_amount>=0 or v_t.original_amount<=0
  or v_s.base_currency_code<>v_t.base_currency_code or p_date<greatest(v_s.posting_date,v_t.posting_date) then raise exception using errcode='22023',message='ALLOCATION_SOURCE_INVALID';end if;
 if exists(select 1 from procurement.payment_claims where tenant_id=p_tenant and open_item_id in(p_source,p_target) and active and proposal_id is distinct from p_proposal)
 then raise exception using errcode='55000',message='PAYABLE_ITEM_ALREADY_SELECTED';end if;
 if exists(select 1 from finance.open_item_allocations where tenant_id=p_tenant and (source_open_item_id in(p_source,p_target) or target_open_item_id in(p_source,p_target)) and posting_date>p_date)
 then raise exception using errcode='22023',message='ALLOCATION_DATE_BEFORE_LATEST';end if;
 select rounding_scale into v_scale from core.legal_entities where id=p_entity and tenant_id=p_tenant;
 v_source:=sales.wave3_decimal_string(p_payload->'source_amount','source_amount',6,true,0,null);v_target:=sales.wave3_decimal_string(p_payload->'transaction_amount','transaction_amount',6,true,0,null);
 if v_source<=0 or v_target<=0 or round(v_source,v_scale)<>v_source or round(v_target,v_scale)<>v_target then raise exception using errcode='22023',message='ALLOCATION_AMOUNT_INVALID';end if;
 if v_s.currency_code<>v_t.currency_code then
  select * into v_rate from finance.exchange_rates where id=(p_payload->>'exchange_rate_id')::uuid and tenant_id=p_tenant and legal_entity_id=p_entity
   and source_currency_code=v_s.currency_code and target_currency_code=v_t.currency_code and effective_date<=p_date and status='active';
  if not found then raise exception using errcode='22023',message='ALLOCATION_EXCHANGE_RATE_REQUIRED';end if;v_conversion:=v_rate.rate;
 elsif p_payload->>'exchange_rate_id' is not null then raise exception using errcode='22023',message='ALLOCATION_EXCHANGE_RATE_INVALID';end if;
 if round(v_source*v_conversion,v_scale)<>v_target then raise exception using errcode='22023',message='ALLOCATION_CURRENCY_MISMATCH';end if;
 v_sr:=finance.flow_residual(p_tenant,p_source);v_tr:=finance.flow_residual(p_tenant,p_target);
 if v_source>-(v_sr->>'amount')::numeric or v_target>(v_tr->>'amount')::numeric then raise exception using errcode='22023',message='ALLOCATION_EXCEEDED';end if;
 v_prior:=(v_sr->>'amount')::numeric-v_s.original_amount;
 v_sb:=round((-v_s.original_base_amount)*(v_prior+v_source)/(-v_s.original_amount),v_scale)-round((-v_s.original_base_amount)*v_prior/(-v_s.original_amount),v_scale);
 v_prior:=v_t.original_amount-(v_tr->>'amount')::numeric;
 v_tb:=round(v_t.original_base_amount*(v_prior+v_target)/v_t.original_amount,v_scale)-round(v_t.original_base_amount*v_prior/v_t.original_amount,v_scale);
 if v_sb<=0 or v_tb<=0 then raise exception using errcode='22023',message='AMOUNT_BELOW_BASE_PRECISION';end if;
 v_fx:=v_sb-v_tb;
 if v_fx<>0 then
  select payable_account_id into v_control from procurement.supplier_bill_controls where tenant_id=p_tenant and legal_entity_id=p_entity;
  v_control:=finance.flow_account(p_tenant,p_entity,v_control,'liability',v_s.base_currency_code);
  v_doc:=jsonb_build_object('tenant_id',p_tenant,'legal_entity_id',p_entity,'branch_id',p_branch,'document_date',p_date,'customer_id',v_s.party_id,
   'currency_code',v_s.base_currency_code,'base_currency_code',v_s.base_currency_code,'exchange_rate','1');
  v_journal:=finance.flow_post_journal(v_doc,jsonb_build_array(finance.flow_jline(v_control,-v_fx,-v_fx),
   finance.flow_jline(finance.flow_mapping(p_tenant,p_entity,case when v_fx>0 then 'exchange_loss' else 'exchange_gain' end,v_s.base_currency_code),v_fx,v_fx)),
   'supplier_allocation',v_id,p_request,p_command);
 end if;
 insert into finance.open_item_allocations(id,tenant_id,legal_entity_id,branch_id,source_open_item_id,target_open_item_id,source_amount,transaction_amount,
  source_base_amount,target_base_amount,exchange_difference,exchange_rate_id,conversion_rate,posting_date,reason,journal_entry_id,request_id,command_id,correlation_id,created_by)
 values(v_id,p_tenant,p_entity,p_branch,p_source,p_target,v_source,v_target,v_sb,v_tb,v_fx,v_rate.id,v_conversion,p_date,p_payload->>'reason',v_journal,p_request,p_command,p_request,auth.uid());
 return jsonb_build_object('allocation_id',v_id,'source_open_item_id',p_source,'target_open_item_id',p_target,'source_amount',v_source::text,'transaction_amount',v_target::text,
  'exchange_difference',v_fx::text,'journal_entry_id',v_journal,'source_residual',finance.flow_residual(p_tenant,p_source),'target_residual',finance.flow_residual(p_tenant,p_target));
end $$;
revoke all on function finance.allocate_payable(uuid,uuid,uuid,uuid,uuid,jsonb,date,uuid,uuid,uuid) from public,anon,authenticated;

create function api.post_supplier_payment(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_command_id uuid,p_idempotency_key uuid,p_client_timestamp timestamptz,
 p_payload jsonb,p_expected_entity_version bigint default null) returns jsonb language plpgsql security definer set search_path='' as $$
declare v_id uuid:=(p_payload->>'document_id')::uuid;v_command text:='procurement.supplier_payment.post';v_hash text;v_result jsonb;v_before jsonb;v_n jsonb;
 v_p procurement.payment_proposals%rowtype;v_bank finance.cash_bank_accounts%rowtype;v_control uuid;v_request uuid:=gen_random_uuid();v_open uuid:=gen_random_uuid();
 v_journal uuid;v_number text;v_line jsonb;v_target jsonb;v_sources jsonb:='[]';v_targets jsonb:='[]';v_remaining numeric;v_take numeric;v_target_remaining numeric;
 v_allocations jsonb:='[]';v_i integer;v_source uuid;v_ref text:=trim(p_payload->>'reference');
begin
 perform core.wave3_require_scope(p_tenant_id,'finance.payments.post',p_legal_entity_id,p_branch_id);
 if v_id is null or p_client_timestamp is null or p_legal_entity_id is null or p_branch_id is null or coalesce(length(v_ref),0) not between 1 and 140 then raise exception using errcode='22023',message='PAYMENT_REFERENCE_REQUIRED';end if;
 v_hash:=core.wave3_request_hash(v_command,p_command_id,p_tenant_id,p_legal_entity_id,p_branch_id,p_payload,p_expected_entity_version);
 v_result:=core.wave3_replay(p_tenant_id,v_command,p_command_id,p_idempotency_key,v_hash);if v_result is not null then return v_result;end if;
 select * into v_p from procurement.payment_proposals where id=v_id and tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id for update;
 if not found then raise exception using errcode='P0002',message='PROPOSAL_NOT_FOUND';end if;
 select detail into v_before from api.payment_proposals where id=v_id;perform core.wave3_assert_expected_version(v_p.version,p_expected_entity_version,v_before);
 if v_p.status<>'approved' then raise exception using errcode='55000',message='PAYMENT_APPROVAL_REQUIRED';end if;
 if v_p.document_date>(clock_timestamp() at time zone 'UTC')::date then raise exception using errcode='22023',message='FUTURE_POSTING_DATE';end if;
 perform sales.flow_assert_transition(v_p.workflow_snapshot->'lifecycle','approved','posted');
 v_n:=procurement.normalize_payment_proposal(p_tenant_id,p_legal_entity_id,p_branch_id,v_before,true);
 if (v_n->>'total')::numeric<>v_p.total or (v_n->>'base_total')::numeric<>v_p.base_total or (v_n#>>'{rate,exchange_rate}')::numeric<>v_p.exchange_rate or v_n->>'currency_code'<>v_p.currency_code then raise exception using errcode='40001',message='PAYMENT_REAPPROVAL_REQUIRED';end if;
 for v_line in select value from jsonb_array_elements(v_p.lines) loop
  if not exists(select 1 from procurement.payment_claims where tenant_id=p_tenant_id and proposal_id=v_id and open_item_id=(v_line->>'open_item_id')::uuid
   and active and amount=(v_line->>'amount')::numeric) then raise exception using errcode='55000',message='PAYMENT_CLAIM_REQUIRED';end if;
 end loop;
 perform finance.wave3_lock_open_period(p_tenant_id,p_legal_entity_id,v_p.document_date);
 select * into v_bank from finance.cash_bank_accounts where id=v_p.cash_bank_account_id and tenant_id=p_tenant_id for share;
 select payable_account_id into v_control from procurement.supplier_bill_controls where legal_entity_id=p_legal_entity_id and tenant_id=p_tenant_id for share;
 v_control:=finance.flow_account(p_tenant_id,p_legal_entity_id,v_control,'liability',v_p.currency_code);
 v_journal:=finance.flow_post_journal(to_jsonb(v_p)||jsonb_build_object('customer_id',v_p.supplier_id),
  jsonb_build_array(finance.flow_jline(v_control,v_p.total,v_p.base_total),finance.flow_jline(v_bank.account_id,-v_p.total,-v_p.base_total)),
  'supplier_payment',v_id,v_request,p_command_id);
 v_number:=sales.wave3_reserve_document_number(p_tenant_id,p_legal_entity_id,p_branch_id,'supplier_payment',v_p.document_date,auth.uid());
 insert into finance.open_items(id,tenant_id,legal_entity_id,branch_id,kind,party_id,source_type,source_id,document_number,currency_code,base_currency_code,exchange_rate,
  original_amount,original_base_amount,posting_date,due_date,journal_entry_id,request_id,command_id,correlation_id,created_by)
 values(v_open,p_tenant_id,p_legal_entity_id,p_branch_id,'AP',v_p.supplier_id,'supplier_payment',v_id,v_number,v_p.currency_code,v_p.base_currency_code,v_p.exchange_rate,
  -v_p.total,-v_p.base_total,v_p.document_date,v_p.document_date,v_journal,v_request,p_command_id,v_request,auth.uid());
 for v_line in select value from jsonb_array_elements(v_p.lines) loop
  if v_line->>'kind'='credit' then v_sources:=v_sources||jsonb_build_array(v_line);else v_targets:=v_targets||jsonb_build_array(v_line);end if;
 end loop;
 v_sources:=v_sources||jsonb_build_array(jsonb_build_object('open_item_id',v_open,'amount',v_p.total::text));
 for v_line in select value from jsonb_array_elements(v_sources) loop
  v_source:=(v_line->>'open_item_id')::uuid;v_remaining:=(v_line->>'amount')::numeric;
  for v_i in 0..jsonb_array_length(v_targets)-1 loop
   exit when v_remaining=0;v_target:=v_targets->v_i;v_target_remaining:=(v_target->>'amount')::numeric;v_take:=least(v_remaining,v_target_remaining);
   if v_take=0 then continue;end if;
   v_allocations:=v_allocations||jsonb_build_array(finance.allocate_payable(v_source,(v_target->>'open_item_id')::uuid,p_tenant_id,p_legal_entity_id,p_branch_id,
    jsonb_build_object('source_amount',v_take::text,'transaction_amount',v_take::text,'reason','Approved supplier payment'),v_p.document_date,v_request,p_command_id,v_id));
   v_remaining:=v_remaining-v_take;v_targets:=jsonb_set(v_targets,array[v_i::text,'amount'],to_jsonb((v_target_remaining-v_take)::text));
  end loop;
  if v_remaining<>0 then raise exception using errcode='23514',message='PAYMENT_ALLOCATION_UNBALANCED';end if;
 end loop;
 insert into procurement.supplier_payments(id,tenant_id,legal_entity_id,branch_id,proposal_id,supplier_id,cash_bank_account_id,document_date,document_number,reference,
  currency_code,base_currency_code,exchange_rate,amount,base_amount,journal_entry_id,open_item_id,allocations,source_snapshot,request_id,command_id,created_by)
 values(v_id,p_tenant_id,p_legal_entity_id,p_branch_id,v_id,v_p.supplier_id,v_p.cash_bank_account_id,v_p.document_date,v_number,v_ref,v_p.currency_code,v_p.base_currency_code,
  v_p.exchange_rate,v_p.total,v_p.base_total,v_journal,v_open,v_allocations,v_before,v_request,p_command_id,auth.uid());
 update procurement.payment_claims set active=false,released_at=clock_timestamp() where proposal_id=v_id and active;
 update procurement.payment_proposals set status='posted',version=version+1,updated_by=auth.uid(),updated_at=clock_timestamp() where id=v_id;
 perform procurement.record_payment_proposal_history(jsonb_build_object('entity',(select detail from api.payment_proposals where id=v_id)));
 select detail into v_result from api.supplier_payments where id=v_id;
 return core.wave3_finish_command(p_tenant_id,v_command,p_command_id,'supplier_payment',v_id,p_idempotency_key,v_hash,v_before,v_result,p_legal_entity_id,p_branch_id,'{}',
  jsonb_build_object('from_status','approved','to_status','posted'),jsonb_build_array(jsonb_build_object('topic','procurement.supplier_payment.recorded','payload',jsonb_build_object('payment_id',v_id))),'[]',v_request,v_request);
end $$;
revoke all on function api.post_supplier_payment(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) from public,anon;
grant execute on function api.post_supplier_payment(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) to authenticated;
create function api.transition_payment_proposal(
 p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_command_id uuid,p_idempotency_key uuid,
 p_client_timestamp timestamptz,p_payload jsonb,p_expected_entity_version bigint default null)
returns jsonb language plpgsql security definer set search_path='' as $$
declare
 v_actor uuid:=auth.uid();v_id uuid;v_action text:=p_payload->>'action';v_decision text:=p_payload->>'decision';
 v_command text:='procurement.payment_proposal.transition';v_hash text;v_result jsonb;v_before jsonb;v_entity jsonb;
 v_doc procurement.payment_proposals%rowtype;v_workflow workflow.workflow_definitions%rowtype;
 v_ar workflow.approval_requests%rowtype;v_snapshot jsonb;v_step jsonb;v_first integer;v_to text;
 v_normalized jsonb;v_line jsonb;v_request uuid:=gen_random_uuid();v_reason text:=nullif(trim(coalesce(p_payload->>'reason',p_payload->>'note')),'');
begin
 perform core.wave3_require_scope(p_tenant_id,'finance.payments.manage',p_legal_entity_id,p_branch_id);
 if p_legal_entity_id is null or p_branch_id is null or p_client_timestamp is null
 or jsonb_typeof(p_payload) is distinct from 'object' or (v_action is null)=(v_decision is null) then
 raise exception using errcode='22023',message='INVALID_COMMAND';end if;
 if v_decision is not null then
  perform core.require_permission(p_tenant_id,'workflow.approvals.decide',p_legal_entity_id,p_branch_id);
 end if;
 v_id:=(p_payload->>'document_id')::uuid;
 v_hash:=core.wave3_request_hash(v_command,p_command_id,p_tenant_id,p_legal_entity_id,p_branch_id,p_payload,p_expected_entity_version);
 v_result:=core.wave3_replay(p_tenant_id,v_command,p_command_id,p_idempotency_key,v_hash);
 if v_result is not null then return v_result;end if;
 select * into v_doc from procurement.payment_proposals where id=v_id and tenant_id=p_tenant_id
 and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id for update;
 if not found then raise exception using errcode='P0002',message='DOCUMENT_NOT_FOUND';end if;
 select detail into v_before from api.payment_proposals where id=v_id;
 perform core.wave3_assert_expected_version(v_doc.version,p_expected_entity_version,v_before);
 v_snapshot:=v_doc.workflow_snapshot;
 if v_action='submit' then
  if v_doc.status<>'draft' then raise exception using errcode='55000',message='PROPOSAL_NOT_EDITABLE';end if;
  v_normalized:=procurement.normalize_payment_proposal(p_tenant_id,p_legal_entity_id,p_branch_id,v_before,true);
  if (v_normalized->>'total')::numeric<>v_doc.total or (v_normalized->>'base_total')::numeric<>v_doc.base_total or (v_normalized#>>'{rate,exchange_rate}')::numeric<>v_doc.exchange_rate or v_normalized->>'currency_code'<>v_doc.currency_code then
   raise exception using errcode='40001',message='PAYMENT_REAPPROVAL_REQUIRED';end if;
  -- Recall/rejection release claims. Submission atomically reacquires every item.
  update procurement.payment_claims set active=false,released_at=clock_timestamp() where proposal_id=v_id and active;
  for v_line in select value from jsonb_array_elements(v_normalized->'lines') loop
   insert into procurement.payment_claims(tenant_id,legal_entity_id,branch_id,proposal_id,open_item_id,amount)
   values(p_tenant_id,p_legal_entity_id,p_branch_id,v_id,(v_line->>'open_item_id')::uuid,(v_line->>'amount')::numeric);
  end loop;
  select * into v_workflow from workflow.workflow_definitions where tenant_id=p_tenant_id
   and document_type='payment_proposal' and status='active' and (legal_entity_id is null or legal_entity_id=p_legal_entity_id)
   order by (legal_entity_id is not null) desc,revision desc,id limit 1;
  if not found then raise exception using errcode='55000',message='WORKFLOW_CONFIGURATION_ERROR';end if;
  select jsonb_build_object('definition_id',v_workflow.id,'revision',v_workflow.revision,'lifecycle',v_workflow.lifecycle,
   'steps',coalesce(jsonb_agg(sales.flow_exact_json(to_jsonb(s)) order by s.step_order),'[]'::jsonb)) into v_snapshot
   from workflow.approval_matrix_steps s where s.tenant_id=p_tenant_id and s.workflow_definition_id=v_workflow.id and s.status='active'
   and (s.currency_code is null or s.currency_code=v_doc.currency_code)
   and (s.minimum_amount is null or s.minimum_amount<=v_doc.total)
   and (s.maximum_amount is null or s.maximum_amount>=v_doc.total);
  select min((x->>'step_order')::integer) into v_first from jsonb_array_elements(v_snapshot->'steps') x;
  if v_first is null and v_workflow.lifecycle->'requires_approval' is distinct from 'false'::jsonb then
   raise exception using errcode='55000',message='WORKFLOW_CONFIGURATION_ERROR';end if;
  perform sales.flow_assert_transition(v_workflow.lifecycle,'draft','submitted');
  v_to:=case when v_first is null then 'approved' else 'pending_approval' end;
  if v_first is null then perform sales.flow_assert_transition(v_workflow.lifecycle,'submitted','approved');end if;
  v_doc.document_number:=coalesce(v_doc.document_number,sales.wave3_reserve_document_number(p_tenant_id,p_legal_entity_id,
    p_branch_id,'payment_proposal',v_doc.document_date,v_actor));
  if v_first is not null then
   insert into workflow.approval_requests(tenant_id,legal_entity_id,branch_id,document_type,document_id,status,
    submitted_by,workflow_definition_id,workflow_revision,current_step,amount,currency_code,command_id,request_id,correlation_id)
   values(p_tenant_id,p_legal_entity_id,p_branch_id,'payment_proposal',v_id,'submitted',v_actor,
    v_workflow.id,v_workflow.revision,v_first,v_doc.total,v_doc.currency_code,p_command_id,v_request,v_request);
  end if;
 elsif v_decision is not null then
  if v_doc.status<>'pending_approval' or v_decision not in ('approved','rejected') then
   raise exception using errcode='55000',message='APPROVAL_NOT_PENDING';end if;
  select * into v_ar from workflow.approval_requests where tenant_id=p_tenant_id and document_type='payment_proposal'
   and document_id=v_id and status='submitted' for update;
  if not found then raise exception using errcode='55000',message='APPROVAL_REQUEST_NOT_FOUND';end if;
  if v_actor in(v_doc.created_by,v_doc.prepared_by,v_doc.submitted_by) then
   raise exception using errcode='42501',message='SEGREGATION_OF_DUTIES_VIOLATION';end if;
  select x into v_step from jsonb_array_elements(v_snapshot->'steps') x where (x->>'step_order')::integer=v_ar.current_step;
  if v_step is null or not exists(select 1 from core.memberships m
   join core.role_assignments ra on ra.membership_id=m.id and ra.tenant_id=m.tenant_id
   join core.roles r on r.id=ra.role_id and r.tenant_id=m.tenant_id
   where m.tenant_id=p_tenant_id and m.user_id=v_actor and m.status='active' and ra.role_id=(v_step->>'role_id')::uuid
   and (ra.legal_entity_id is null or ra.legal_entity_id=p_legal_entity_id) and (ra.branch_id is null or ra.branch_id=p_branch_id)
   and (not r.requires_mfa or auth.jwt()->>'aal'='aal2')) then
   raise exception using errcode='42501',message='APPROVAL_ROLE_REQUIRED';end if;
  if v_decision='rejected' and v_reason is null then raise exception using errcode='22023',message='REASON_REQUIRED';end if;
  perform sales.flow_assert_transition(v_snapshot->'lifecycle','submitted',v_decision);
  insert into workflow.approval_decisions(tenant_id,approval_request_id,workflow_definition_id,workflow_revision,
   approval_matrix_step_id,step_order,actor_id,decision,note,amount,currency_code,request_id,command_id,correlation_id)
  values(p_tenant_id,v_ar.id,v_ar.workflow_definition_id,v_ar.workflow_revision,(v_step->>'id')::uuid,v_ar.current_step,
   v_actor,v_decision,v_reason,v_ar.amount,v_ar.currency_code,v_request,p_command_id,v_request);
  if v_decision='approved' then
   select min((x->>'step_order')::integer) into v_first from jsonb_array_elements(v_snapshot->'steps') x
    where (x->>'step_order')::integer>v_ar.current_step;
  end if;
  v_to:=case when v_decision='rejected' then 'rejected' when v_first is null then 'approved' else 'pending_approval' end;
  update workflow.approval_requests set current_step=coalesce(v_first,current_step),
   status=case when v_first is null then v_to else status end,
   decision_by=case when v_first is null then v_actor else decision_by end,
   decision_note=case when v_first is null then v_reason else decision_note end,
   decided_at=case when v_first is null then clock_timestamp() else decided_at end where id=v_ar.id;
 elsif v_action in('recall','cancel') then
  if v_reason is null then raise exception using errcode='22023',message='REASON_REQUIRED';end if;
  if v_action='recall' and v_doc.status not in('pending_approval','rejected','approved') then
   raise exception using errcode='55000',message='PROPOSAL_NOT_RECALLABLE';end if;
  if v_snapshot is null then
   select jsonb_build_object('lifecycle',lifecycle) into v_snapshot from workflow.workflow_definitions
    where tenant_id=p_tenant_id and document_type='payment_proposal' and status='active'
    and (legal_entity_id is null or legal_entity_id=p_legal_entity_id)
    order by (legal_entity_id is not null) desc,revision desc,id limit 1;
  end if;
  v_to:=case when v_action='recall' then 'draft' else 'cancelled' end;
  perform sales.flow_assert_transition(v_snapshot->'lifecycle',v_doc.status,v_to);
  update workflow.approval_requests set status='cancelled',decision_by=v_actor,decision_note=v_reason,decided_at=clock_timestamp()
   where tenant_id=p_tenant_id and document_type='payment_proposal' and document_id=v_id and status='submitted';
  if v_action='recall' then v_snapshot:=null;end if;
 else raise exception using errcode='22023',message='INVALID_COMMAND';end if;
 if v_to in('draft','rejected','cancelled') then
  update procurement.payment_claims set active=false,released_at=clock_timestamp() where proposal_id=v_id and active;
 end if;
 update procurement.payment_proposals set status=v_to,version=version+1,updated_at=clock_timestamp(),updated_by=v_actor,
  workflow_snapshot=v_snapshot,document_number=v_doc.document_number,
  submitted_by=case when v_action='submit' then v_actor else submitted_by end,
  submitted_at=case when v_action='submit' then clock_timestamp() else submitted_at end where id=v_id;
 select detail into v_entity from api.payment_proposals where id=v_id;
 v_result:=core.wave3_finish_command(p_tenant_id,v_command,p_command_id,'payment_proposal',v_id,
  p_idempotency_key,v_hash,v_before,v_entity,p_legal_entity_id,p_branch_id,'{}',
  case when v_doc.status=v_to then null else jsonb_build_object('from_status',v_doc.status,'to_status',v_to,'reason',v_reason) end,
  jsonb_build_array(jsonb_build_object('topic',v_command,'payload',jsonb_build_object('status',v_to))),'[]',v_request,v_request);
 perform procurement.record_payment_proposal_history(v_result);return v_result;
end $$;
revoke all on function api.transition_payment_proposal(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) from public,anon;
grant execute on function api.transition_payment_proposal(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) to authenticated;



create function api.supplier_payment_reference_options(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_resource text,p_after uuid default null,p_search text default '',
 p_supplier_id uuid default null,p_cash_bank_account_id uuid default null,p_date date default null,p_proposal_id uuid default null)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare v_items jsonb;v_next uuid;v_base text;v_search text:=lower(trim(coalesce(p_search,'')));begin
 perform core.wave3_require_scope(p_tenant_id,'finance.payments.manage',p_legal_entity_id,p_branch_id);
 if p_legal_entity_id is null or p_branch_id is null or length(v_search)>100 then raise exception using errcode='22023',message='REFERENCE_SCOPE_INVALID';end if;
 select currency_code into v_base from core.legal_entities where id=p_legal_entity_id and tenant_id=p_tenant_id;
 if p_resource='payment_items' then
  if p_supplier_id is null or p_cash_bank_account_id is null or p_date is null then raise exception using errcode='22023',message='PAYMENT_FILTER_REQUIRED';end if;
  select jsonb_agg(sales.flow_exact_json(to_jsonb(x)) order by id) into v_items from (
   select o.id,o.document_number,o.source_id,o.source_type,o.due_date,o.currency_code,
    case when o.original_amount<0 then 'credit' else 'bill' end kind,finance.flow_residual(p_tenant_id,o.id) residual,
    exists(select 1 from procurement.payment_claims c where c.tenant_id=p_tenant_id and c.open_item_id=o.id and c.active and c.proposal_id is distinct from p_proposal_id) claimed
   from finance.open_items o join finance.cash_bank_accounts b on b.id=p_cash_bank_account_id and b.tenant_id=o.tenant_id and b.legal_entity_id=o.legal_entity_id and b.branch_id=o.branch_id
   where o.tenant_id=p_tenant_id and o.legal_entity_id=p_legal_entity_id and o.branch_id=p_branch_id and o.kind='AP' and o.party_id=p_supplier_id
    and o.currency_code=b.currency_code and b.status='active' and o.posting_date<=p_date and (o.original_amount<0 or o.due_date<=p_date)
    and (p_after is null or o.id>p_after) and (v_search='' or position(v_search in lower(o.document_number))>0)
    and (finance.flow_residual(p_tenant_id,o.id)->>'amount')::numeric<>0
   order by o.id limit 51) x;
 elsif p_resource='payment_suppliers' then
  select jsonb_agg(jsonb_build_object('id',id,'code',code,'name',display_name) order by id) into v_items from (
   select * from crm.parties where tenant_id=p_tenant_id and status='active' and kind in('supplier','both') and (p_after is null or id>p_after)
    and (v_search='' or position(v_search in lower(code||' '||display_name))>0) order by id limit 51)x;
 elsif p_resource='payment_banks' then
  select jsonb_agg(jsonb_build_object('id',id,'code',code,'name',name||' · '||currency_code,'currency_code',currency_code) order by id) into v_items from (
   select * from finance.cash_bank_accounts where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id and status='active'
    and (p_after is null or id>p_after) and (v_search='' or position(v_search in lower(code||' '||name))>0) order by id limit 51)x;
 elsif p_resource='payment_rates' then
  select jsonb_agg(jsonb_build_object('id',id,'code',source_currency_code,'name',effective_date::text||' · '||rate::text,'currency_code',source_currency_code,'exchange_rate',rate::text) order by id) into v_items from (
   select * from finance.exchange_rates where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and status='active' and target_currency_code=v_base
    and (p_after is null or id>p_after) and (v_search='' or position(v_search in lower(source_currency_code))>0) order by id limit 51)x;
 else raise exception using errcode='22023',message='REFERENCE_RESOURCE_INVALID';end if;
 v_items:=coalesce(v_items,'[]');if jsonb_array_length(v_items)>50 then v_next:=(v_items->49->>'id')::uuid;v_items:=v_items-50;end if;
 return jsonb_build_object('items',v_items,'next_cursor',v_next,'base_currency',v_base);
end $$;
revoke all on function api.supplier_payment_reference_options(uuid,uuid,uuid,text,uuid,text,uuid,uuid,date,uuid) from public,anon;
grant execute on function api.supplier_payment_reference_options(uuid,uuid,uuid,text,uuid,text,uuid,uuid,date,uuid) to authenticated;
create function api.supplier_statement(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_supplier_id uuid,
 p_currency_code text,p_as_of date,p_buckets integer[] default array[30,60,90])
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare v_rows jsonb;v_amount numeric;v_base numeric;v_bucket jsonb;v_count integer;begin
 perform core.wave3_require_scope(p_tenant_id,'finance.payments.manage',p_legal_entity_id,p_branch_id);
 if p_branch_id is null or p_supplier_id is null or p_as_of is null or p_as_of>(now() at time zone 'UTC')::date
 or p_currency_code is null or p_currency_code!~'^[A-Z]{3}$'
 or p_buckets is null or cardinality(p_buckets) not between 1 and 12 or exists(select 1 from unnest(p_buckets) x where x is null or x<=0)
 or p_buckets<>(select array_agg(distinct x order by x) from unnest(p_buckets) x) then
 raise exception using errcode='22023',message='STATEMENT_FILTER_INVALID';end if;
 select count(*) into v_count from (select id from finance.open_items where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id
 and branch_id=p_branch_id and party_id=p_supplier_id and kind='AP' and currency_code=p_currency_code and posting_date<=p_as_of limit 10001) bounded;
 if v_count>10000 then raise exception using errcode='54000',message='LIMIT_EXCEEDED';end if;
 with items as (select o.*,finance.flow_residual(p_tenant_id,o.id,p_as_of) residual from finance.open_items o
 where o.tenant_id=p_tenant_id and o.legal_entity_id=p_legal_entity_id and o.branch_id=p_branch_id and o.party_id=p_supplier_id
 and o.kind='AP' and o.currency_code=p_currency_code and o.posting_date<=p_as_of), rows as (
 select id,source_type,source_id,document_number,currency_code,posting_date,due_date,original_amount::text,original_base_amount::text,
 residual->>'amount' as open_amount,residual->>'base_amount' as open_base_amount,
 case when original_amount<0 then -1 when due_date>=p_as_of then 0 else
 1+(select count(*) from unnest(p_buckets) b where p_as_of-due_date>b) end bucket from items)
 select coalesce(jsonb_agg(to_jsonb(rows) order by posting_date,id),'[]'),coalesce(sum(open_amount::numeric),0),coalesce(sum(open_base_amount::numeric),0)
 into v_rows,v_amount,v_base from rows;
 select coalesce(jsonb_agg(jsonb_build_object('bucket',bucket,'amount',amount::text,'base_amount',base_amount::text) order by bucket),'[]') into v_bucket
 from (select (x->>'bucket')::integer bucket,sum((x->>'open_amount')::numeric) amount,sum((x->>'open_base_amount')::numeric) base_amount
 from jsonb_array_elements(v_rows) x group by (x->>'bucket')::integer) b;
 return jsonb_build_object('supplier_id',p_supplier_id,'currency_code',p_currency_code,'as_of',p_as_of,
 'rows',v_rows,'aging',v_bucket,'bucket_days',p_buckets,'open_amount',v_amount::text,'open_base_amount',v_base::text,
 'basis','posting_date','unapplied_credits_separate',true);end $$;

revoke all on function api.supplier_statement(uuid,uuid,uuid,uuid,text,date,integer[]) from public,anon;
grant execute on function api.supplier_statement(uuid,uuid,uuid,uuid,text,date,integer[]) to authenticated;

-- Candidate only. Shared residual compatibility must be reviewed before application.
insert into core.permissions(code,module,description,privileged) values
 ('finance.payments.allocate','finance','Allocate existing supplier credits and payments.',true),
 ('finance.payments.reverse','finance','Reverse supplier allocations with retained history.',true)
on conflict(code) do nothing;
create or replace function finance.payable_read_allowed(p_tenant uuid,p_entity uuid,p_branch uuid) returns boolean language sql stable security definer set search_path='' as $$
 select core.is_tenant_member(p_tenant) and (procurement.bill_read_allowed(p_tenant,p_entity,p_branch)
 or core.has_permission(p_tenant,'finance.payments.manage',p_entity,p_branch) or core.has_permission(p_tenant,'finance.payments.post',p_entity,p_branch)
 or core.has_permission(p_tenant,'finance.payments.allocate',p_entity,p_branch) or core.has_permission(p_tenant,'finance.payments.reverse',p_entity,p_branch))$$;
create table finance.allocation_reversals(
 id uuid primary key default gen_random_uuid(),tenant_id uuid not null,legal_entity_id uuid not null,branch_id uuid not null,
 allocation_id uuid not null unique,posting_date date not null,reason text not null check(length(trim(reason)) between 1 and 1000),
 journal_entry_id uuid,source_snapshot jsonb not null,request_id uuid not null,command_id uuid not null,
 created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),unique(tenant_id,id),
 foreign key(tenant_id,allocation_id) references finance.open_item_allocations(tenant_id,id),
 foreign key(tenant_id,journal_entry_id) references finance.journal_entries(tenant_id,id),
 foreign key(tenant_id,legal_entity_id) references core.legal_entities(tenant_id,id),
 foreign key(tenant_id,branch_id) references core.branches(tenant_id,id)
);
create index allocation_reversal_scope on finance.allocation_reversals(tenant_id,legal_entity_id,branch_id,posting_date,id);
create index allocation_reversal_journal on finance.allocation_reversals(tenant_id,journal_entry_id);
create trigger immutable before update or delete on finance.allocation_reversals for each row execute function workflow.reject_history_mutation();
alter table finance.allocation_reversals enable row level security;
alter table finance.allocation_reversals force row level security;
revoke all on finance.allocation_reversals from public,anon,authenticated;
grant select on finance.allocation_reversals to authenticated;
create policy ap_read on finance.allocation_reversals for select to authenticated using(finance.payable_read_allowed(tenant_id,legal_entity_id,branch_id));

create or replace function finance.flow_residual(p_tenant uuid,p_id uuid,p_as_of date default null)
returns jsonb language sql stable security definer set search_path='' as $$
 with active_allocations as (
  select a.* from finance.open_item_allocations a where a.tenant_id=p_tenant
   and (a.source_open_item_id=p_id or a.target_open_item_id=p_id)
   and (p_as_of is null or a.posting_date<=p_as_of)
   and not exists(select 1 from finance.allocation_reversals r where r.tenant_id=a.tenant_id and r.allocation_id=a.id
    and (p_as_of is null or r.posting_date<=p_as_of))
 ) select jsonb_build_object('amount',(o.original_amount+
  coalesce((select sum(source_amount) from active_allocations where source_open_item_id=o.id),0)-
  coalesce((select sum(transaction_amount+write_off+discount_amount) from active_allocations where target_open_item_id=o.id),0))::text,
 'base_amount',(o.original_base_amount+
  coalesce((select sum(source_base_amount) from active_allocations where source_open_item_id=o.id),0)-
  coalesce((select sum(target_base_amount+adjustment_base_amount) from active_allocations where target_open_item_id=o.id),0))::text)
 from finance.open_items o where o.tenant_id=p_tenant and o.id=p_id and (p_as_of is null or o.posting_date<=p_as_of) $$;

create function api.allocate_supplier_credit(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_command_id uuid,p_idempotency_key uuid,
 p_client_timestamp timestamptz,p_payload jsonb,p_expected_entity_version bigint default null)
returns jsonb language plpgsql security definer set search_path='' as $$
declare v_command text:='finance.supplier_credit.allocate';v_hash text;v_result jsonb;v_source finance.open_items%rowtype;
 v_line jsonb;v_results jsonb:='[]';v_request uuid:=gen_random_uuid();v_date date:=(p_payload->>'posting_date')::date;v_reason text:=trim(p_payload->>'reason');
begin
 perform core.wave3_require_scope(p_tenant_id,'finance.payments.allocate',p_legal_entity_id,p_branch_id);
 if p_legal_entity_id is null or p_branch_id is null or p_client_timestamp is null or v_date is null or coalesce(length(v_reason),0) not between 1 and 1000
  or jsonb_typeof(p_payload->'allocations') is distinct from 'array' or jsonb_array_length(p_payload->'allocations') not between 1 and 500
  or p_expected_entity_version is not null then raise exception using errcode='22023',message='ALLOCATION_PAYLOAD_INVALID';end if;
 v_hash:=core.wave3_request_hash(v_command,p_command_id,p_tenant_id,p_legal_entity_id,p_branch_id,p_payload,p_expected_entity_version);
 v_result:=core.wave3_replay(p_tenant_id,v_command,p_command_id,p_idempotency_key,v_hash);if v_result is not null then return v_result;end if;
 if v_date>(clock_timestamp() at time zone 'UTC')::date then raise exception using errcode='22023',message='FUTURE_POSTING_DATE';end if;
 perform 1 from finance.open_items where tenant_id=p_tenant_id and (id=(p_payload->>'source_open_item_id')::uuid or id in
  (select (x->>'target_open_item_id')::uuid from jsonb_array_elements(p_payload->'allocations')x)) order by id for update;
 select * into v_source from finance.open_items where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id
  and id=(p_payload->>'source_open_item_id')::uuid and kind='AP' and original_amount<0;
 if not found then raise exception using errcode='22023',message='ALLOCATION_SOURCE_INVALID';end if;
 perform finance.wave3_lock_open_period(p_tenant_id,p_legal_entity_id,v_date);
 for v_line in select value from jsonb_array_elements(p_payload->'allocations') loop
  v_results:=v_results||jsonb_build_array(finance.allocate_payable(v_source.id,(v_line->>'target_open_item_id')::uuid,p_tenant_id,p_legal_entity_id,p_branch_id,
   v_line||jsonb_build_object('reason',v_reason),v_date,v_request,p_command_id));
 end loop;
 return core.wave3_finish_command(p_tenant_id,v_command,p_command_id,'supplier_allocation',p_command_id,p_idempotency_key,v_hash,null,
  jsonb_build_object('id',p_command_id,'source_open_item_id',v_source.id,'allocations',v_results,'source_residual',finance.flow_residual(p_tenant_id,v_source.id)),
  p_legal_entity_id,p_branch_id,'{}',jsonb_build_object('from_status','open','to_status','allocated','reason',v_reason),
  jsonb_build_array(jsonb_build_object('topic',v_command,'payload',jsonb_build_object('source_open_item_id',v_source.id))),'[]',v_request,v_request);
end $$;

create function api.reverse_supplier_allocation(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_command_id uuid,p_idempotency_key uuid,
 p_client_timestamp timestamptz,p_payload jsonb,p_expected_entity_version bigint default null)
returns jsonb language plpgsql security definer set search_path='' as $$
declare v_command text:='finance.supplier_allocation.reverse';v_hash text;v_result jsonb;v_a finance.open_item_allocations%rowtype;v_source finance.open_items%rowtype;
 v_id uuid:=gen_random_uuid();v_request uuid:=gen_random_uuid();v_date date:=(p_payload->>'posting_date')::date;v_reason text:=trim(p_payload->>'reason');
 v_journal uuid;v_original finance.journal_entries%rowtype;v_lines jsonb;
begin
 perform core.wave3_require_scope(p_tenant_id,'finance.payments.reverse',p_legal_entity_id,p_branch_id);
 if p_legal_entity_id is null or p_branch_id is null or p_client_timestamp is null or v_date is null or coalesce(length(v_reason),0) not between 1 and 1000
  or p_expected_entity_version is not null then raise exception using errcode='22023',message='ALLOCATION_REVERSAL_INVALID';end if;
 v_hash:=core.wave3_request_hash(v_command,p_command_id,p_tenant_id,p_legal_entity_id,p_branch_id,p_payload,p_expected_entity_version);
 v_result:=core.wave3_replay(p_tenant_id,v_command,p_command_id,p_idempotency_key,v_hash);if v_result is not null then return v_result;end if;
 select * into v_a from finance.open_item_allocations where id=(p_payload->>'allocation_id')::uuid and tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id;
 if not found then raise exception using errcode='P0002',message='ALLOCATION_NOT_FOUND';end if;
 perform 1 from finance.open_items where tenant_id=p_tenant_id and id in(v_a.source_open_item_id,v_a.target_open_item_id) order by id for update;
 select * into v_source from finance.open_items where id=v_a.source_open_item_id and tenant_id=p_tenant_id;
 if v_source.kind<>'AP' then raise exception using errcode='22023',message='AP_ALLOCATION_REQUIRED';end if;
 if exists(select 1 from finance.allocation_reversals where allocation_id=v_a.id) then raise exception using errcode='55000',message='ALLOCATION_ALREADY_REVERSED';end if;
 if v_date<v_a.posting_date or v_date>(clock_timestamp() at time zone 'UTC')::date then raise exception using errcode='22023',message='ALLOCATION_REVERSAL_DATE_INVALID';end if;
 if exists(select 1 from procurement.payment_claims where tenant_id=p_tenant_id and open_item_id in(v_a.source_open_item_id,v_a.target_open_item_id) and active)
  then raise exception using errcode='55000',message='PAYABLE_ITEM_ALREADY_SELECTED';end if;
 if exists(select 1 from finance.open_item_allocations a where a.tenant_id=p_tenant_id and (a.source_open_item_id in(v_a.source_open_item_id,v_a.target_open_item_id)
  or a.target_open_item_id in(v_a.source_open_item_id,v_a.target_open_item_id)) and a.posting_date>v_date)
  or exists(select 1 from finance.allocation_reversals r join finance.open_item_allocations a on a.id=r.allocation_id where r.tenant_id=p_tenant_id
   and (a.source_open_item_id in(v_a.source_open_item_id,v_a.target_open_item_id) or a.target_open_item_id in(v_a.source_open_item_id,v_a.target_open_item_id)) and r.posting_date>v_date)
  then raise exception using errcode='22023',message='ALLOCATION_DATE_BEFORE_LATEST';end if;
 perform finance.wave3_lock_open_period(p_tenant_id,p_legal_entity_id,v_date);
 if v_a.journal_entry_id is not null then
  select * into v_original from finance.journal_entries where id=v_a.journal_entry_id and tenant_id=p_tenant_id;
  select jsonb_agg(finance.flow_jline(account_id,transaction_credit-transaction_debit,base_credit-base_debit) order by line_number) into v_lines
   from finance.journal_lines where journal_entry_id=v_original.id and tenant_id=p_tenant_id;
  v_journal:=finance.flow_post_journal(to_jsonb(v_original)||jsonb_build_object('document_date',v_date,'customer_id',v_source.party_id),v_lines,
   'supplier_allocation_reversal',v_id,v_request,p_command_id);
 end if;
 insert into finance.allocation_reversals(id,tenant_id,legal_entity_id,branch_id,allocation_id,posting_date,reason,journal_entry_id,source_snapshot,request_id,command_id,created_by)
 values(v_id,p_tenant_id,p_legal_entity_id,p_branch_id,v_a.id,v_date,v_reason,v_journal,sales.flow_exact_json(to_jsonb(v_a)),v_request,p_command_id,auth.uid());
 return core.wave3_finish_command(p_tenant_id,v_command,p_command_id,'supplier_allocation_reversal',v_id,p_idempotency_key,v_hash,sales.flow_exact_json(to_jsonb(v_a)),
  jsonb_build_object('id',v_id,'allocation_id',v_a.id,'journal_entry_id',v_journal,'posting_date',v_date,'reason',v_reason,
   'source_residual',finance.flow_residual(p_tenant_id,v_a.source_open_item_id),'target_residual',finance.flow_residual(p_tenant_id,v_a.target_open_item_id)),
  p_legal_entity_id,p_branch_id,'{}',jsonb_build_object('from_status','allocated','to_status','reversed','reason',v_reason),
  jsonb_build_array(jsonb_build_object('topic',v_command,'payload',jsonb_build_object('allocation_id',v_a.id))),'[]',v_request,v_request);
end $$;
revoke all on function api.allocate_supplier_credit(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint),
 api.reverse_supplier_allocation(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) from public,anon;
grant execute on function api.allocate_supplier_credit(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint),
 api.reverse_supplier_allocation(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) to authenticated;
create or replace function finance.allocate_payable(p_source uuid,p_target uuid,p_tenant uuid,p_entity uuid,p_branch uuid,p_payload jsonb,p_date date,p_request uuid,p_command uuid,p_proposal uuid default null)
returns jsonb language plpgsql security definer set search_path='' as $$
declare v_s finance.open_items%rowtype;v_t finance.open_items%rowtype;v_sr jsonb;v_tr jsonb;v_rate finance.exchange_rates%rowtype;v_scale integer;
 v_source numeric;v_target numeric;v_sb numeric;v_tb numeric;v_prior numeric;v_fx numeric;v_conversion numeric:=1;v_id uuid:=gen_random_uuid();v_journal uuid;v_control uuid;v_doc jsonb;
begin
 perform 1 from finance.open_items where tenant_id=p_tenant and id in(p_source,p_target) order by id for update;
 select * into v_s from finance.open_items where tenant_id=p_tenant and legal_entity_id=p_entity and branch_id=p_branch and id=p_source;
 select * into v_t from finance.open_items where tenant_id=p_tenant and legal_entity_id=p_entity and branch_id=p_branch and id=p_target;
 if v_s.id is null or v_t.id is null or v_s.party_id<>v_t.party_id or v_s.kind<>'AP' or v_t.kind<>'AP' or v_s.original_amount>=0 or v_t.original_amount<=0
  or v_s.base_currency_code<>v_t.base_currency_code or p_date<greatest(v_s.posting_date,v_t.posting_date) then raise exception using errcode='22023',message='ALLOCATION_SOURCE_INVALID';end if;
 if exists(select 1 from procurement.payment_claims where tenant_id=p_tenant and open_item_id in(p_source,p_target) and active and proposal_id is distinct from p_proposal)
 then raise exception using errcode='55000',message='PAYABLE_ITEM_ALREADY_SELECTED';end if;
 if exists(select 1 from finance.open_item_allocations where tenant_id=p_tenant and (source_open_item_id in(p_source,p_target) or target_open_item_id in(p_source,p_target)) and posting_date>p_date)
 then raise exception using errcode='22023',message='ALLOCATION_DATE_BEFORE_LATEST';end if;
 if exists(select 1 from finance.allocation_reversals r join finance.open_item_allocations a on a.id=r.allocation_id where r.tenant_id=p_tenant
  and (a.source_open_item_id in(p_source,p_target) or a.target_open_item_id in(p_source,p_target)) and r.posting_date>p_date)
 then raise exception using errcode='22023',message='ALLOCATION_DATE_BEFORE_LATEST';end if;
 select rounding_scale into v_scale from core.legal_entities where id=p_entity and tenant_id=p_tenant;
 v_source:=sales.wave3_decimal_string(p_payload->'source_amount','source_amount',6,true,0,null);v_target:=sales.wave3_decimal_string(p_payload->'transaction_amount','transaction_amount',6,true,0,null);
 if v_source<=0 or v_target<=0 or round(v_source,v_scale)<>v_source or round(v_target,v_scale)<>v_target then raise exception using errcode='22023',message='ALLOCATION_AMOUNT_INVALID';end if;
 if v_s.currency_code<>v_t.currency_code then
  select * into v_rate from finance.exchange_rates where id=(p_payload->>'exchange_rate_id')::uuid and tenant_id=p_tenant and legal_entity_id=p_entity
   and source_currency_code=v_s.currency_code and target_currency_code=v_t.currency_code and effective_date<=p_date and status='active';
  if not found then raise exception using errcode='22023',message='ALLOCATION_EXCHANGE_RATE_REQUIRED';end if;v_conversion:=v_rate.rate;
 elsif p_payload->>'exchange_rate_id' is not null then raise exception using errcode='22023',message='ALLOCATION_EXCHANGE_RATE_INVALID';end if;
 if round(v_source*v_conversion,v_scale)<>v_target then raise exception using errcode='22023',message='ALLOCATION_CURRENCY_MISMATCH';end if;
 v_sr:=finance.flow_residual(p_tenant,p_source);v_tr:=finance.flow_residual(p_tenant,p_target);
 if v_source>-(v_sr->>'amount')::numeric or v_target>(v_tr->>'amount')::numeric then raise exception using errcode='22023',message='ALLOCATION_EXCEEDED';end if;
 -- Allocate from remaining carrying value: reversal can restore a different cent distribution.
 v_sb:=round(-(v_sr->>'base_amount')::numeric*v_source/(-(v_sr->>'amount')::numeric),v_scale);
 v_tb:=round((v_tr->>'base_amount')::numeric*v_target/(v_tr->>'amount')::numeric,v_scale);
 if v_sb<=0 or v_tb<=0 then raise exception using errcode='22023',message='AMOUNT_BELOW_BASE_PRECISION';end if;
 v_fx:=v_sb-v_tb;
 if v_fx<>0 then
  select payable_account_id into v_control from procurement.supplier_bill_controls where tenant_id=p_tenant and legal_entity_id=p_entity;
  v_control:=finance.flow_account(p_tenant,p_entity,v_control,'liability',v_s.base_currency_code);
  v_doc:=jsonb_build_object('tenant_id',p_tenant,'legal_entity_id',p_entity,'branch_id',p_branch,'document_date',p_date,'customer_id',v_s.party_id,
   'currency_code',v_s.base_currency_code,'base_currency_code',v_s.base_currency_code,'exchange_rate','1');
  v_journal:=finance.flow_post_journal(v_doc,jsonb_build_array(finance.flow_jline(v_control,-v_fx,-v_fx),
   finance.flow_jline(finance.flow_mapping(p_tenant,p_entity,case when v_fx>0 then 'exchange_loss' else 'exchange_gain' end,v_s.base_currency_code),v_fx,v_fx)),
   'supplier_allocation',v_id,p_request,p_command);
 end if;
 insert into finance.open_item_allocations(id,tenant_id,legal_entity_id,branch_id,source_open_item_id,target_open_item_id,source_amount,transaction_amount,
  source_base_amount,target_base_amount,exchange_difference,exchange_rate_id,conversion_rate,posting_date,reason,journal_entry_id,request_id,command_id,correlation_id,created_by)
 values(v_id,p_tenant,p_entity,p_branch,p_source,p_target,v_source,v_target,v_sb,v_tb,v_fx,v_rate.id,v_conversion,p_date,p_payload->>'reason',v_journal,p_request,p_command,p_request,auth.uid());
 return jsonb_build_object('allocation_id',v_id,'source_open_item_id',p_source,'target_open_item_id',p_target,'source_amount',v_source::text,'transaction_amount',v_target::text,
  'exchange_difference',v_fx::text,'journal_entry_id',v_journal,'source_residual',finance.flow_residual(p_tenant,p_source),'target_residual',finance.flow_residual(p_tenant,p_target));
end $$;
revoke all on function finance.allocate_payable(uuid,uuid,uuid,uuid,uuid,jsonb,date,uuid,uuid,uuid) from public,anon,authenticated;



create function api.payable_item_detail(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_item_id uuid,p_after uuid default null)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare v_item finance.open_items%rowtype;v_rows jsonb;v_next uuid;begin
 if p_legal_entity_id is null or p_branch_id is null or not finance.payable_read_allowed(p_tenant_id,p_legal_entity_id,p_branch_id) then raise exception using errcode='42501',message='PERMISSION_DENIED';end if;
 select * into v_item from finance.open_items where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id and kind='AP' and id=p_item_id;
 if not found then raise exception using errcode='P0002',message='PAYABLE_ITEM_NOT_FOUND';end if;
 select jsonb_agg(detail order by id) into v_rows from (
  select a.id,sales.flow_exact_json(to_jsonb(a))||jsonb_build_object('source_document_number',s.document_number,'target_document_number',t.document_number,
   'reversal',(select sales.flow_exact_json(to_jsonb(r)) from finance.allocation_reversals r where r.allocation_id=a.id)) detail
  from finance.open_item_allocations a join finance.open_items s on s.id=a.source_open_item_id join finance.open_items t on t.id=a.target_open_item_id
  where a.tenant_id=p_tenant_id and (a.source_open_item_id=p_item_id or a.target_open_item_id=p_item_id) and (p_after is null or a.id>p_after) order by a.id limit 51)x;
 v_rows:=coalesce(v_rows,'[]');if jsonb_array_length(v_rows)>50 then v_next:=(v_rows->49->>'id')::uuid;v_rows:=v_rows-50;end if;
 return jsonb_build_object('item',sales.flow_exact_json(to_jsonb(v_item))||finance.flow_residual(p_tenant_id,p_item_id),'allocations',v_rows,'next_cursor',v_next);
end $$;
revoke all on function api.payable_item_detail(uuid,uuid,uuid,uuid,uuid) from public,anon;
grant execute on function api.payable_item_detail(uuid,uuid,uuid,uuid,uuid) to authenticated;

create function api.payable_allocation_targets(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_source_id uuid,p_after uuid default null)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare v_source finance.open_items%rowtype;v_items jsonb;v_next uuid;begin
 perform core.wave3_require_scope(p_tenant_id,'finance.payments.allocate',p_legal_entity_id,p_branch_id);
 if p_legal_entity_id is null or p_branch_id is null then raise exception using errcode='22023',message='SCOPE_REQUIRED';end if;
 select * into v_source from finance.open_items where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id and id=p_source_id and kind='AP' and original_amount<0;
 if not found then raise exception using errcode='22023',message='ALLOCATION_SOURCE_INVALID';end if;
 select jsonb_agg(detail order by id) into v_items from (
  select o.id,sales.flow_exact_json(to_jsonb(o))||finance.flow_residual(p_tenant_id,o.id) detail from finance.open_items o
  where o.tenant_id=p_tenant_id and o.legal_entity_id=p_legal_entity_id and o.branch_id=p_branch_id and o.party_id=v_source.party_id
   and o.kind='AP' and o.original_amount>0 and (p_after is null or o.id>p_after)
   and (finance.flow_residual(p_tenant_id,o.id)->>'amount')::numeric>0
   and not exists(select 1 from procurement.payment_claims c where c.tenant_id=p_tenant_id and c.open_item_id=o.id and c.active)
  order by o.id limit 51)x;
 v_items:=coalesce(v_items,'[]');if jsonb_array_length(v_items)>50 then v_next:=(v_items->49->>'id')::uuid;v_items:=v_items-50;end if;
 return jsonb_build_object('items',v_items,'next_cursor',v_next);
end $$;
revoke all on function api.payable_allocation_targets(uuid,uuid,uuid,uuid,uuid) from public,anon;
grant execute on function api.payable_allocation_targets(uuid,uuid,uuid,uuid,uuid) to authenticated;
create or replace function api.supplier_statement(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_supplier_id uuid,
 p_currency_code text,p_as_of date,p_buckets integer[] default array[30,60,90])
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare v_rows jsonb;v_amount numeric;v_base numeric;v_bucket jsonb;v_count integer;begin
 if not finance.payable_read_allowed(p_tenant_id,p_legal_entity_id,p_branch_id) then raise exception using errcode='42501',message='PERMISSION_DENIED';end if;
 if p_branch_id is null or p_supplier_id is null or p_as_of is null or p_as_of>(now() at time zone 'UTC')::date
 or p_currency_code is null or p_currency_code!~'^[A-Z]{3}$'
 or p_buckets is null or cardinality(p_buckets) not between 1 and 12 or exists(select 1 from unnest(p_buckets) x where x is null or x<=0)
 or p_buckets<>(select array_agg(distinct x order by x) from unnest(p_buckets) x) then
 raise exception using errcode='22023',message='STATEMENT_FILTER_INVALID';end if;
 select count(*) into v_count from (select id from finance.open_items where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id
 and branch_id=p_branch_id and party_id=p_supplier_id and kind='AP' and currency_code=p_currency_code and posting_date<=p_as_of limit 10001) bounded;
 if v_count>10000 then raise exception using errcode='54000',message='LIMIT_EXCEEDED';end if;
 with items as (select o.*,finance.flow_residual(p_tenant_id,o.id,p_as_of) residual from finance.open_items o
 where o.tenant_id=p_tenant_id and o.legal_entity_id=p_legal_entity_id and o.branch_id=p_branch_id and o.party_id=p_supplier_id
 and o.kind='AP' and o.currency_code=p_currency_code and o.posting_date<=p_as_of), rows as (
 select id,source_type,source_id,document_number,currency_code,posting_date,due_date,original_amount::text,original_base_amount::text,
 residual->>'amount' as open_amount,residual->>'base_amount' as open_base_amount,
 case when original_amount<0 then -1 when due_date>=p_as_of then 0 else
 1+(select count(*) from unnest(p_buckets) b where p_as_of-due_date>b) end bucket from items)
 select coalesce(jsonb_agg(to_jsonb(rows) order by posting_date,id),'[]'),coalesce(sum(open_amount::numeric),0),coalesce(sum(open_base_amount::numeric),0)
 into v_rows,v_amount,v_base from rows;
 select coalesce(jsonb_agg(jsonb_build_object('bucket',bucket,'amount',amount::text,'base_amount',base_amount::text) order by bucket),'[]') into v_bucket
 from (select (x->>'bucket')::integer bucket,sum((x->>'open_amount')::numeric) amount,sum((x->>'open_base_amount')::numeric) base_amount
 from jsonb_array_elements(v_rows) x group by (x->>'bucket')::integer) b;
 return jsonb_build_object('supplier_id',p_supplier_id,'currency_code',p_currency_code,'as_of',p_as_of,
 'rows',v_rows,'aging',v_bucket,'bucket_days',p_buckets,'open_amount',v_amount::text,'open_base_amount',v_base::text,
 'basis','posting_date','unapplied_credits_separate',true);end $$;

revoke all on function api.supplier_statement(uuid,uuid,uuid,uuid,text,date,integer[]) from public,anon;
grant execute on function api.supplier_statement(uuid,uuid,uuid,uuid,text,date,integer[]) to authenticated;


create function api.payable_allocation_rates(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_source_currency text,p_target_currency text,p_date date,p_after uuid default null)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare v_items jsonb;v_next uuid;begin
 perform core.wave3_require_scope(p_tenant_id,'finance.payments.allocate',p_legal_entity_id,p_branch_id);
 if p_legal_entity_id is null or p_branch_id is null or p_date is null then raise exception using errcode='22023',message='RATE_FILTER_INVALID';end if;
 select jsonb_agg(jsonb_build_object('id',id,'rate',rate::text,'date',effective_date) order by id) into v_items from (
  select id,rate,effective_date from finance.exchange_rates where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and status='active'
   and source_currency_code=p_source_currency and target_currency_code=p_target_currency and effective_date<=p_date and (p_after is null or id>p_after) order by id limit 51)x;
 v_items:=coalesce(v_items,'[]');if jsonb_array_length(v_items)>50 then v_next:=(v_items->49->>'id')::uuid;v_items:=v_items-50;end if;
 return jsonb_build_object('items',v_items,'next_cursor',v_next);
end $$;
revoke all on function api.payable_allocation_rates(uuid,uuid,uuid,text,text,date,uuid) from public,anon;
grant execute on function api.payable_allocation_rates(uuid,uuid,uuid,text,text,date,uuid) to authenticated;
create or replace function api.supplier_payment_reference_options(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,p_resource text,p_after uuid default null,p_search text default '',
 p_supplier_id uuid default null,p_cash_bank_account_id uuid default null,p_date date default null,p_proposal_id uuid default null)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare v_items jsonb;v_next uuid;v_base text;v_search text:=lower(trim(coalesce(p_search,'')));begin
 if p_resource='payment_suppliers' then
  if not finance.payable_read_allowed(p_tenant_id,p_legal_entity_id,p_branch_id) then raise exception using errcode='42501',message='PERMISSION_DENIED';end if;
 else perform core.wave3_require_scope(p_tenant_id,'finance.payments.manage',p_legal_entity_id,p_branch_id);end if;
 if p_legal_entity_id is null or p_branch_id is null or length(v_search)>100 then raise exception using errcode='22023',message='REFERENCE_SCOPE_INVALID';end if;
 select currency_code into v_base from core.legal_entities where id=p_legal_entity_id and tenant_id=p_tenant_id;
 if p_resource='payment_items' then
  if p_supplier_id is null or p_cash_bank_account_id is null or p_date is null then raise exception using errcode='22023',message='PAYMENT_FILTER_REQUIRED';end if;
  select jsonb_agg(sales.flow_exact_json(to_jsonb(x)) order by id) into v_items from (
   select o.id,o.document_number,o.source_id,o.source_type,o.due_date,o.currency_code,
    case when o.original_amount<0 then 'credit' else 'bill' end kind,finance.flow_residual(p_tenant_id,o.id) residual,
    exists(select 1 from procurement.payment_claims c where c.tenant_id=p_tenant_id and c.open_item_id=o.id and c.active and c.proposal_id is distinct from p_proposal_id) claimed
   from finance.open_items o join finance.cash_bank_accounts b on b.id=p_cash_bank_account_id and b.tenant_id=o.tenant_id and b.legal_entity_id=o.legal_entity_id and b.branch_id=o.branch_id
   where o.tenant_id=p_tenant_id and o.legal_entity_id=p_legal_entity_id and o.branch_id=p_branch_id and o.kind='AP' and o.party_id=p_supplier_id
    and o.currency_code=b.currency_code and b.status='active' and o.posting_date<=p_date and (o.original_amount<0 or o.due_date<=p_date)
    and (p_after is null or o.id>p_after) and (v_search='' or position(v_search in lower(o.document_number))>0)
    and (finance.flow_residual(p_tenant_id,o.id)->>'amount')::numeric<>0
   order by o.id limit 51) x;
 elsif p_resource='payment_suppliers' then
  select jsonb_agg(jsonb_build_object('id',id,'code',code,'name',display_name) order by id) into v_items from (
   select * from crm.parties where tenant_id=p_tenant_id and status='active' and kind in('supplier','both') and (p_after is null or id>p_after)
    and (v_search='' or position(v_search in lower(code||' '||display_name))>0) order by id limit 51)x;
 elsif p_resource='payment_banks' then
  select jsonb_agg(jsonb_build_object('id',id,'code',code,'name',name||' · '||currency_code,'currency_code',currency_code) order by id) into v_items from (
   select * from finance.cash_bank_accounts where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id and status='active'
    and (p_after is null or id>p_after) and (v_search='' or position(v_search in lower(code||' '||name))>0) order by id limit 51)x;
 elsif p_resource='payment_rates' then
  select jsonb_agg(jsonb_build_object('id',id,'code',source_currency_code,'name',effective_date::text||' · '||rate::text,'currency_code',source_currency_code,'exchange_rate',rate::text) order by id) into v_items from (
   select * from finance.exchange_rates where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and status='active' and target_currency_code=v_base
    and (p_after is null or id>p_after) and (v_search='' or position(v_search in lower(source_currency_code))>0) order by id limit 51)x;
 else raise exception using errcode='22023',message='REFERENCE_RESOURCE_INVALID';end if;
 v_items:=coalesce(v_items,'[]');if jsonb_array_length(v_items)>50 then v_next:=(v_items->49->>'id')::uuid;v_items:=v_items-50;end if;
 return jsonb_build_object('items',v_items,'next_cursor',v_next,'base_currency',v_base);
end $$;
revoke all on function api.supplier_payment_reference_options(uuid,uuid,uuid,text,uuid,text,uuid,uuid,date,uuid) from public,anon;
grant execute on function api.supplier_payment_reference_options(uuid,uuid,uuid,text,uuid,text,uuid,uuid,date,uuid) to authenticated;


-- UNAPPLIED AC-320 financial-statement candidate. Verify only inside ROLLBACK.
-- This first slice freezes trial balance, P&L and balance-sheet evidence.
create table finance.financial_reports (
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,
 requested_branch_id uuid not null,kind text not null
  check(kind in('trial_balance','profit_loss','balance_sheet')),
 period_id uuid not null,comparative_period_id uuid,as_of date not null,
 generated_at timestamptz not null,summary jsonb not null,evidence jsonb not null,
 created_by uuid not null references auth.users(id),unique(tenant_id,id),
 foreign key(tenant_id,legal_entity_id) references core.legal_entities(tenant_id,id),
 foreign key(tenant_id,requested_branch_id) references core.branches(tenant_id,id),
 foreign key(tenant_id,legal_entity_id,period_id) references finance.fiscal_periods(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,legal_entity_id,comparative_period_id) references finance.fiscal_periods(tenant_id,legal_entity_id,id),
 check(jsonb_typeof(summary)='object' and jsonb_typeof(evidence)='object'
  and octet_length(evidence::text)<=16777216)
);
create index financial_reports_scope on finance.financial_reports(tenant_id,legal_entity_id,id);
create index financial_reports_period on finance.financial_reports(tenant_id,period_id,id);
create index financial_reports_actor on finance.financial_reports(created_by);
alter table finance.financial_reports enable row level security;
alter table finance.financial_reports force row level security;
revoke all on finance.financial_reports from public,anon,authenticated;
create trigger immutable before update or delete on finance.financial_reports
 for each row execute function workflow.reject_history_mutation();

create function finance.build_financial_statement(t uuid,e uuid,b uuid,p jsonb)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare k text:=p->>'kind';d date:=(p->>'as_of')::date;
 period finance.fiscal_periods%rowtype;comparison finance.fiscal_periods%rowtype;
 compare_end date;account_rows jsonb;journal_rows jsonb;summary jsonb;result jsonb;
 current_debit numeric;current_credit numeric;closing_debit numeric;closing_credit numeric;
 revenue numeric;expense numeric;assets numeric;liabilities numeric;equity numeric;earnings numeric;
 comp_revenue numeric;comp_expense numeric;comp_assets numeric;comp_liabilities numeric;comp_equity numeric;comp_earnings numeric;
begin
 perform core.wave3_require_scope(t,'finance.view',e,null);
 perform core.wave3_require_scope(t,'finance.view',e,b);
 if k not in('trial_balance','profit_loss','balance_sheet') or k is null or d is null
  or d>(clock_timestamp() at time zone 'UTC')::date then
  raise exception using errcode='22023',message='FINANCIAL_REPORT_INPUT_INVALID';end if;
 select * into period from finance.fiscal_periods where tenant_id=t and legal_entity_id=e
  and id=(p->>'period_id')::uuid and status='active';
 if not found or d not between period.start_date and period.end_date then
  raise exception using errcode='22023',message='FINANCIAL_REPORT_PERIOD_INVALID';end if;
 if p->>'comparative_period_id' is not null then
  select * into comparison from finance.fiscal_periods where tenant_id=t and legal_entity_id=e
   and id=(p->>'comparative_period_id')::uuid and status='active';
  if not found or comparison.id=period.id or comparison.end_date>=period.start_date then
   raise exception using errcode='22023',message='FINANCIAL_REPORT_COMPARISON_INVALID';end if;
  compare_end:=comparison.end_date;
 end if;
 with source_lines as (
  select l.account_id,j.posting_date,l.base_debit,l.base_credit from finance.journal_lines l
  join finance.journal_entries j on j.tenant_id=l.tenant_id and j.id=l.journal_entry_id
  where l.tenant_id=t and l.legal_entity_id=e and j.status='posted'
   and j.posting_date<=greatest(d,coalesce(compare_end,d))
 ), balances as (
  select a.id,a.code,a.name,a.account_type,a.normal_balance,a.parent_id,
   coalesce(sum(s.base_debit-s.base_credit) filter(where s.posting_date<period.start_date),0) opening_signed,
   coalesce(sum(s.base_debit) filter(where s.posting_date between period.start_date and d),0) period_debit,
   coalesce(sum(s.base_credit) filter(where s.posting_date between period.start_date and d),0) period_credit,
   coalesce(sum(s.base_debit-s.base_credit) filter(where s.posting_date<=d),0) closing_signed,
   coalesce(sum(s.base_debit-s.base_credit) filter(where compare_end is not null and s.posting_date<=compare_end),0) compare_closing,
   coalesce(sum(s.base_debit-s.base_credit) filter(where compare_end is not null
    and s.posting_date between comparison.start_date and compare_end),0) compare_movement
  from finance.accounts a left join source_lines s on s.account_id=a.id
  where a.tenant_id=t and a.legal_entity_id=e and a.is_posting
  group by a.id,a.code,a.name,a.account_type,a.normal_balance,a.parent_id
  order by a.code,a.id limit 5001
 )
 select coalesce(jsonb_agg(jsonb_build_object('id',id,'account_id',id,'code',code,'name',name,
  'account_type',account_type,'normal_balance',normal_balance,'parent_id',parent_id,
  'opening_balance',opening_signed::text,'period_debit',period_debit::text,
  'period_credit',period_credit::text,'closing_balance',closing_signed::text,
  'comparative_closing_balance',case when compare_end is null then null else compare_closing::text end,
  'amount',(case k when 'trial_balance' then closing_signed
   when 'profit_loss' then case account_type when 'revenue' then period_credit-period_debit
    when 'expense' then period_debit-period_credit else 0 end
   else case account_type when 'asset' then closing_signed
    when 'liability' then -closing_signed when 'equity' then -closing_signed else 0 end end)::text,
  'comparative_amount',(case when compare_end is null then null
   when k='trial_balance' then compare_closing
   when k='profit_loss' then case account_type when 'revenue' then -compare_movement
    when 'expense' then compare_movement else 0 end
   else case account_type when 'asset' then compare_closing
    when 'liability' then -compare_closing when 'equity' then -compare_closing else 0 end end)::text)
  order by code,id),'[]'::jsonb) into account_rows from balances;
 if jsonb_array_length(account_rows)>5000 then
  raise exception using errcode='54000',message='FINANCIAL_ACCOUNT_LIMIT';end if;

 select coalesce(jsonb_agg(to_jsonb(q) order by posting_date,id),'[]'::jsonb) into journal_rows from (
  select l.id,l.account_id,j.id journal_entry_id,j.document_number,j.source_type,j.source_id,
   j.command_id,j.posting_date,j.fiscal_period_id,l.line_number,l.source_line_id,l.party_id,
   l.branch_id,l.currency_code,l.transaction_debit::text transaction_debit,
   l.transaction_credit::text transaction_credit,l.base_debit::text base_debit,
   l.base_credit::text base_credit
  from finance.journal_lines l join finance.journal_entries j
   on j.tenant_id=l.tenant_id and j.id=l.journal_entry_id
  where l.tenant_id=t and l.legal_entity_id=e and j.status='posted'
   and j.posting_date<=greatest(d,coalesce(compare_end,d))
  order by j.posting_date,l.id limit 10001)q;
 if jsonb_array_length(journal_rows)>10000 then
  raise exception using errcode='54000',message='FINANCIAL_JOURNAL_LIMIT';end if;
 select coalesce(sum((x->>'period_debit')::numeric),0),
  coalesce(sum((x->>'period_credit')::numeric),0),
  coalesce(sum(greatest((x->>'closing_balance')::numeric,0)),0),
  coalesce(sum(greatest(-(x->>'closing_balance')::numeric,0)),0),
  coalesce(sum((x->>'amount')::numeric) filter(where x->>'account_type'='revenue'),0),
  coalesce(sum((x->>'amount')::numeric) filter(where x->>'account_type'='expense'),0),
  coalesce(sum((x->>'amount')::numeric) filter(where x->>'account_type'='asset'),0),
  coalesce(sum((x->>'amount')::numeric) filter(where x->>'account_type'='liability'),0),
  coalesce(sum((x->>'amount')::numeric) filter(where x->>'account_type'='equity'),0)
 into current_debit,current_credit,closing_debit,closing_credit,revenue,expense,
  assets,liabilities,equity from jsonb_array_elements(account_rows)x;
 if current_debit<>current_credit or closing_debit<>closing_credit then
  raise exception using errcode='23514',message='FINANCIAL_LEDGER_UNBALANCED';end if;
 if k='balance_sheet' then
  select coalesce(sum(-(x->>'closing_balance')::numeric) filter(where x->>'account_type'='revenue'),0)
   -coalesce(sum((x->>'closing_balance')::numeric) filter(where x->>'account_type'='expense'),0)
   into earnings from jsonb_array_elements(account_rows)x;
  select coalesce(sum((x->>'comparative_amount')::numeric) filter(where x->>'account_type'='asset'),0),
   coalesce(sum((x->>'comparative_amount')::numeric) filter(where x->>'account_type'='liability'),0),
   coalesce(sum((x->>'comparative_amount')::numeric) filter(where x->>'account_type'='equity'),0),
   coalesce(sum(-(x->>'comparative_closing_balance')::numeric) filter(where x->>'account_type'='revenue'),0)
    -coalesce(sum((x->>'comparative_closing_balance')::numeric) filter(where x->>'account_type'='expense'),0)
  into comp_assets,comp_liabilities,comp_equity,comp_earnings
  from jsonb_array_elements(account_rows)x;
 elsif k='profit_loss' then
  select coalesce(sum((x->>'comparative_amount')::numeric) filter(where x->>'account_type'='revenue'),0),
   coalesce(sum((x->>'comparative_amount')::numeric) filter(where x->>'account_type'='expense'),0)
  into comp_revenue,comp_expense from jsonb_array_elements(account_rows)x;
 end if;
 summary:=jsonb_build_object('id',p->>'id','version',1,'status','generated','kind',k,
  'tenant_id',t,'legal_entity_id',e,'branch_id',b,'period_id',period.id,
  'period_start',period.start_date,'period_end',period.end_date,'as_of',d,
  'comparative_period_id',comparison.id,'comparative_start',comparison.start_date,
  'comparative_end',compare_end,'base_currency_code',
  (select currency_code from core.legal_entities where tenant_id=t and id=e),
  'generated_at',statement_timestamp(),'account_count',jsonb_array_length(account_rows),
  'journal_count',jsonb_array_length(journal_rows),
  'period_debit',current_debit::text,'period_credit',current_credit::text,
  'closing_debit',closing_debit::text,'closing_credit',closing_credit::text,
  'revenue',case when k='profit_loss' then revenue::text end,
  'expenses',case when k='profit_loss' then expense::text end,
  'net_profit',case when k='profit_loss' then (revenue-expense)::text end,
  'assets',case when k='balance_sheet' then assets::text end,
  'liabilities',case when k='balance_sheet' then liabilities::text end,
  'equity',case when k='balance_sheet' then equity::text end,
  'current_earnings',case when k='balance_sheet' then earnings::text end,
  'difference',case when k='balance_sheet' then (assets-liabilities-equity-earnings)::text
   else (closing_debit-closing_credit)::text end,
  'comparative',case when compare_end is null then null
   when k='profit_loss' then jsonb_build_object('revenue',comp_revenue::text,
    'expenses',comp_expense::text,'net_profit',(comp_revenue-comp_expense)::text)
   when k='balance_sheet' then jsonb_build_object('assets',comp_assets::text,
    'liabilities',comp_liabilities::text,'equity',comp_equity::text,
    'current_earnings',comp_earnings::text,
    'difference',(comp_assets-comp_liabilities-comp_equity-comp_earnings)::text)
   else null end);
 if k='balance_sheet' and assets<>liabilities+equity+earnings then
  raise exception using errcode='23514',message='FINANCIAL_BALANCE_SHEET_UNBALANCED';end if;
 result:=jsonb_build_object('summary',summary,'accounts',account_rows,'journals',journal_rows);
 if octet_length(result::text)>16777216 then
  raise exception using errcode='54000',message='FINANCIAL_REPORT_EVIDENCE_LIMIT';end if;
 return result;
end$$;

create function api.generate_financial_statement(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,
 p_command_id uuid,p_idempotency_key uuid,p_client_timestamp timestamptz,p_payload jsonb,
 p_expected_entity_version bigint default null) returns jsonb
language plpgsql security definer set search_path='' as $$
declare id uuid:=(p_payload->>'id')::uuid;h text;r jsonb;data jsonb;summary jsonb;req uuid:=gen_random_uuid();begin
 perform core.wave3_require_scope(p_tenant_id,'finance.view',p_legal_entity_id,null);
 perform core.wave3_require_scope(p_tenant_id,'finance.view',p_legal_entity_id,p_branch_id);
 if id is null or p_client_timestamp is null then
  raise exception using errcode='22023',message='FINANCIAL_REPORT_INPUT_INVALID';end if;
 h:=core.wave3_request_hash('finance.statements.generate',p_command_id,p_tenant_id,
  p_legal_entity_id,p_branch_id,p_payload,p_expected_entity_version);
 r:=core.wave3_replay(p_tenant_id,'finance.statements.generate',p_command_id,p_idempotency_key,h);
 if r is not null then return r;end if;
 perform core.wave3_assert_expected_version(0,p_expected_entity_version,'{}');
 data:=finance.build_financial_statement(p_tenant_id,p_legal_entity_id,p_branch_id,p_payload);
 summary:=data->'summary';
 insert into finance.financial_reports values(id,p_tenant_id,p_legal_entity_id,p_branch_id,
  summary->>'kind',(summary->>'period_id')::uuid,(summary->>'comparative_period_id')::uuid,
  (summary->>'as_of')::date,(summary->>'generated_at')::timestamptz,summary,data,auth.uid());
 return core.wave3_finish_command(p_tenant_id,'finance.statements.generate',p_command_id,
  'financial_statement_report',id,p_idempotency_key,h,null,summary,p_legal_entity_id,p_branch_id,
  '{}',jsonb_build_object('to_status','generated'),
  jsonb_build_array(jsonb_build_object('topic','finance.statements.generated','payload',summary)),
  '[]',req,req);
end$$;

create function api.financial_statement_reports(p_tenant_id uuid,p_legal_entity_id uuid,
 p_branch_id uuid,p_after uuid default null) returns jsonb
language plpgsql stable security definer set search_path='' as $$declare rows jsonb;cursor uuid;begin
 perform core.wave3_require_scope(p_tenant_id,'finance.view',p_legal_entity_id,null);
 perform core.wave3_require_scope(p_tenant_id,'finance.view',p_legal_entity_id,p_branch_id);
 select coalesce(jsonb_agg(summary order by id),'[]') into rows from (
  select id,summary from finance.financial_reports where tenant_id=p_tenant_id
   and legal_entity_id=p_legal_entity_id and (p_after is null or id>p_after)
  order by id limit 51)q;
 if jsonb_array_length(rows)>50 then cursor:=(rows->49->>'id')::uuid;rows:=rows-50;end if;
 return jsonb_build_object('tenant_id',p_tenant_id,'legal_entity_id',p_legal_entity_id,
  'branch_id',p_branch_id,'items',rows,'next_cursor',cursor);
end$$;

create function api.financial_statement_page(p_tenant_id uuid,p_legal_entity_id uuid,
 p_branch_id uuid,p_report_id uuid,p_section text,p_offset integer default 0,
 p_account_id uuid default null) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare report finance.financial_reports%rowtype;rows jsonb;n integer;begin
 perform core.wave3_require_scope(p_tenant_id,'finance.view',p_legal_entity_id,null);
 perform core.wave3_require_scope(p_tenant_id,'finance.view',p_legal_entity_id,p_branch_id);
 if p_section not in('accounts','journals') or p_section is null or p_offset is null
  or p_offset<0 or p_offset>10000 then
  raise exception using errcode='22023',message='FINANCIAL_REPORT_PAGE_INVALID';end if;
 select * into report from finance.financial_reports where tenant_id=p_tenant_id
  and legal_entity_id=p_legal_entity_id and id=p_report_id;
 if not found then raise exception using errcode='42501',message='FINANCIAL_REPORT_SCOPE_REQUIRED';end if;
 select coalesce(jsonb_agg(value order by ord),'[]') into rows from (
  select value,ord from jsonb_array_elements(report.evidence->p_section) with ordinality x(value,ord)
  where p_account_id is null or value->>'account_id'=p_account_id::text
  order by ord offset p_offset limit 51)q;
 n:=jsonb_array_length(rows);if n>50 then rows:=rows-50;end if;
 return jsonb_build_object('summary',report.summary,'section',p_section,'account_id',p_account_id,
  'items',rows,'next_offset',case when n>50 then p_offset+50 end);
end$$;

revoke all on function finance.build_financial_statement(uuid,uuid,uuid,jsonb),
 api.generate_financial_statement(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint),
 api.financial_statement_reports(uuid,uuid,uuid,uuid),
 api.financial_statement_page(uuid,uuid,uuid,uuid,text,integer,uuid)
 from public,anon,authenticated;
grant execute on function api.generate_financial_statement(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint),
 api.financial_statement_reports(uuid,uuid,uuid,uuid),
 api.financial_statement_page(uuid,uuid,uuid,uuid,text,integer,uuid) to authenticated;
notify pgrst,'reload schema';

-- UNAPPLIED. Private saved evidence only; never arbitrary tables or client rows.
insert into core.permissions(code,module,description,privileged) values
 ('finance.reports.export','finance','Export scoped frozen financial and inventory evidence.',false) on conflict(code) do nothing;

create function finance.report_export_document(t uuid,e uuid,b uuid,resource text,i uuid,section text,filters jsonb) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare probe jsonb;data jsonb;rows jsonb;meta jsonb;allowed text[];k text;v jsonb;result jsonb;begin
 perform core.wave3_require_scope(t,'finance.reports.export',e,null);
 perform core.wave3_require_scope(t,'finance.reports.export',e,b);
 if i is null or jsonb_typeof(filters) is distinct from 'object' then raise exception using errcode='22023',message='REPORT_EXPORT_INPUT_INVALID';end if;
 allowed:=case resource when 'statement' then array['account_id'] when 'control' then array['evidence_key']
  when 'inventory' then array['evidence_key'] when 'tax' then array['account_id','evidence_key','source_line_id']
  when 'budget' then array['budget_line_id'] when 'close' then array['component_key'] else null end;
 if allowed is null then raise exception using errcode='22023',message='REPORT_EXPORT_SOURCE_INVALID';end if;
 for k,v in select * from jsonb_each(filters) loop
  if not k=any(allowed) or (v<>'null'::jsonb and (jsonb_typeof(v)<>'string' or length(v#>>'{}')>220)) then
   raise exception using errcode='22023',message='REPORT_EXPORT_FILTER_INVALID';end if;
 end loop;
 case resource
 when 'statement' then
  probe:=api.financial_statement_page(t,e,b,i,section,0,(filters->>'account_id')::uuid);
  select evidence into data from finance.financial_reports where tenant_id=t and legal_entity_id=e and id=i;
 when 'control' then
  probe:=api.control_reconciliation_report_page(t,e,b,i,section,0,filters->>'evidence_key');
  select evidence into data from finance.control_reports where tenant_id=t and legal_entity_id=e and branch_id=b and id=i;
 when 'inventory' then
  probe:=api.inventory_valuation_report_page(t,e,b,i,section,0,filters->>'evidence_key');
  select evidence into data from inventory.valuation_reports where tenant_id=t and legal_entity_id=e and branch_id=b and id=i;
 when 'tax' then
  if section='lines' then
   if filters->>'account_id' is not null or filters->>'evidence_key' is not null then raise exception using errcode='22023',message='REPORT_EXPORT_FILTER_INVALID';end if;
   probe:=api.tax_summary_page(t,e,b,i,0,(filters->>'source_line_id')::uuid);
  else
   if filters->>'source_line_id' is not null then raise exception using errcode='22023',message='REPORT_EXPORT_FILTER_INVALID';end if;
   probe:=api.tax_control_page(t,e,b,i,section,0,(filters->>'account_id')::uuid,filters->>'evidence_key');
  end if;
  select evidence into data from finance.tax_reports where tenant_id=t and legal_entity_id=e and requested_branch_id=b and id=i;
 when 'budget' then
  probe:=api.budget_variance_page(t,e,b,i,section,0,(filters->>'budget_line_id')::uuid);
  select evidence into data from finance.budget_variance_reports where tenant_id=t and legal_entity_id=e and requested_branch_id=b and id=i;
 when 'close' then
  probe:=api.close_control_review_page(t,e,b,i,section,0,filters->>'component_key');
  select evidence into data from finance.close_control_reviews where tenant_id=t and legal_entity_id=e and id=i;
 end case;
 if data is null or jsonb_typeof(data->section) is distinct from 'array' then raise exception using errcode='42501',message='REPORT_EXPORT_SCOPE_REQUIRED';end if;
 select coalesce(jsonb_agg(x order by ord),'[]') into rows from jsonb_array_elements(data->section) with ordinality q(x,ord)
 where (filters->>'account_id' is null or x->>'account_id'=filters->>'account_id')
  and (filters->>'evidence_key' is null or x->>'evidence_key'=filters->>'evidence_key')
  and (filters->>'source_line_id' is null or x->>'source_line_id'=filters->>'source_line_id')
  and (filters->>'component_key' is null or x->>'component_key'=filters->>'component_key')
  and (filters->>'budget_line_id' is null or (section='lines' and x->>'id'=filters->>'budget_line_id')
   or (section='journals' and x->>'budget_line_id'=filters->>'budget_line_id'));
 if jsonb_array_length(rows)>10000 then raise exception using errcode='54000',message='REPORT_EXPORT_ROW_LIMIT';end if;
 select coalesce(jsonb_object_agg(key,value),'{}') into meta from jsonb_each(data->'summary')
  where key in('id','version','tenant_id','legal_entity_id','branch_id','requested_branch_id','scope','entity_name','branch_name','kind','status',
   'currency_code','base_currency_code','as_of','generated_at','period_id','period_name','period_start','period_end','period_version','period_state',
   'comparative_period_id','budget_id','budget_version','budget_name','branch_filter_id','cost_centre_filter_id','project_filter_id','notice');
 result:=jsonb_build_object('version',1,'metadata',meta||jsonb_build_object('actor_id',auth.uid(),'working_branch_id',b,
  'source_type',resource,'source_id',i,'section',section,'filters',filters,'row_count',jsonb_array_length(rows)), 'rows',rows);
 if octet_length(result::text)>8388608 then raise exception using errcode='54000',message='REPORT_EXPORT_EVIDENCE_LIMIT';end if;
 return result;
end $$;
create function api.report_export_preview(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,
 p_source_type text,p_source_id uuid,p_section text,p_filters jsonb) returns jsonb
language plpgsql stable security definer set search_path='' as $$declare data jsonb;begin
 data:=finance.report_export_document(p_tenant_id,p_legal_entity_id,p_branch_id,p_source_type,p_source_id,p_section,p_filters);
 return jsonb_build_object('canonical_text',data::text,'source_hash',encode(extensions.digest(data::text,'sha256'),'hex'));
end $$;
create function api.record_report_export(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,
 p_command_id uuid,p_idempotency_key uuid,p_client_timestamp timestamptz,p_payload jsonb,p_expected_entity_version bigint default null) returns jsonb
language plpgsql security definer set search_path='' as $$
declare p jsonb:=p_payload;data jsonb;h text;r jsonb;id uuid:=(p->>'id')::uuid;req uuid:=gen_random_uuid();
 source_hash text;columns jsonb;filters jsonb;result jsonb;expected_columns jsonb;begin
 -- Current source permission and export permission precede every replay.
 data:=finance.report_export_document(p_tenant_id,p_legal_entity_id,p_branch_id,p->>'source_type',(p->>'source_id')::uuid,p->>'section',p->'filters');
 source_hash:=encode(extensions.digest(data::text,'sha256'),'hex');
 select jsonb_build_array('record_type')||
  (select jsonb_agg('report.'||key order by key) from (select jsonb_object_keys(data->'metadata') key
   union select unnest(array['export_id','export_prepared_at','source_hash','file_format']))q)||
  coalesce((select jsonb_agg('data.'||key order by key) from (select distinct key
   from jsonb_array_elements(data->'rows')x cross join lateral jsonb_object_keys(x)key)q),'[]'::jsonb)
 into expected_columns;
 if id is null or p_client_timestamp is null or p->>'source_hash' is distinct from source_hash
  or p->>'file_format' not in('csv','xlsx') or p->>'file_format' is null
  or coalesce(p->>'file_name','')!~ '^[a-zA-Z0-9][a-zA-Z0-9._-]{1,180}$'
  or right(p->>'file_name',length(p->>'file_format')+1)<>'.'||(p->>'file_format')
  or coalesce(p->>'file_sha256','')!~ '^[a-f0-9]{64}$' or (p->>'file_size')::bigint not between 1 and 10485760
  or p->>'file_size' is null or jsonb_typeof(p->'columns') is distinct from 'array'
  or jsonb_array_length(p->'columns') not between 1 and 256 or p->>'prepared_at' is null
  or p->'columns' is distinct from expected_columns then
  raise exception using errcode='22023',message='REPORT_EXPORT_METADATA_INVALID';end if;
 if exists(select 1 from jsonb_array_elements(p->'columns')x where jsonb_typeof(x)<>'string' or length(x#>>'{}') not between 1 and 100)
  or (select count(distinct x) from jsonb_array_elements_text(p->'columns')x)<>jsonb_array_length(p->'columns') then
  raise exception using errcode='22023',message='REPORT_EXPORT_METADATA_INVALID';end if;
 perform (p->>'prepared_at')::timestamptz;
 h:=core.wave3_request_hash('finance.report.export',p_command_id,p_tenant_id,p_legal_entity_id,p_branch_id,p,p_expected_entity_version);
 r:=core.wave3_replay(p_tenant_id,'finance.report.export',p_command_id,p_idempotency_key,h);if r is not null then return r;end if;
 perform core.wave3_assert_expected_version(0,p_expected_entity_version,'{}');
 filters:=data->'metadata'||jsonb_build_object('source_hash',source_hash,'file_sha256',p->>'file_sha256','prepared_at',p->>'prepared_at',
  'artifact_state','generated_local_delivery_unconfirmed');columns:=p->'columns';
 insert into core.export_jobs(id,tenant_id,actor_id,resource,file_format,filters,columns_json,status,row_count,file_name,file_size,request_id)
  values(id,p_tenant_id,auth.uid(),'wave3.'||(p->>'source_type'),p->>'file_format',filters,columns,'completed',
   jsonb_array_length(data->'rows'),p->>'file_name',(p->>'file_size')::bigint,req);
 result:=jsonb_build_object('id',id,'version',1,'tenant_id',p_tenant_id,'legal_entity_id',p_legal_entity_id,'branch_id',p_branch_id,
  'actor_id',auth.uid(),'status','registered','source_type',p->>'source_type','source_id',p->>'source_id',
  'section',p->>'section','filters',p->'filters','source_hash',source_hash,'file_sha256',p->>'file_sha256',
  'file_format',p->>'file_format','file_name',p->>'file_name','file_size',(p->>'file_size')::bigint,'row_count',jsonb_array_length(data->'rows'));
 return core.wave3_finish_command(p_tenant_id,'finance.report.export',p_command_id,'report_export',id,p_idempotency_key,h,null,result,
  p_legal_entity_id,p_branch_id,'{}',jsonb_build_object('to_status','registered'),
  jsonb_build_array(jsonb_build_object('topic','finance.report.exported','payload',result)),'[]',req,req);
end $$;
revoke all on function finance.report_export_document(uuid,uuid,uuid,text,uuid,text,jsonb),
 api.report_export_preview(uuid,uuid,uuid,text,uuid,text,jsonb),
 api.record_report_export(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) from public,anon,authenticated;
grant execute on function api.report_export_preview(uuid,uuid,uuid,text,uuid,text,jsonb),
 api.record_report_export(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) to authenticated;
notify pgrst,'reload schema';

-- W4-02A exact civil boundary resolution. Unapplied development candidate.
-- Existing employee/calendar migrations are immutable. No grants to roles/plans.

create function people.local_instant_candidates(p_timezone text,p_local timestamp)
returns jsonb language plpgsql stable set search_path = '' as $$
declare v_result jsonb;
begin
  if p_timezone is null or p_local is null or not isfinite(p_local)
    or p_local<'0001-01-01'::timestamp or p_local>='10000-01-01'::timestamp
    or not exists(select 1 from pg_catalog.pg_timezone_names where name=p_timezone) then
    raise exception using errcode='22023',message='CALENDAR_LOCAL_BOUNDARY_INVALID';
  end if;
  -- Sample both sides of all civil-date offset transitions, including 24-hour
  -- date-line jumps. Round-trip verification, not PostgreSQL's implicit fold/gap
  -- preference, determines whether a candidate is a valid local instant.
  with probes as (
    select (p_local at time zone 'UTC')+g*interval '1 hour' instant
    from pg_catalog.generate_series(-48,48) g
  ), offsets as (
    select distinct extract(epoch from
      (instant at time zone p_timezone)-(instant at time zone 'UTC'))::integer seconds
    from probes
  ), candidates as (
    select (p_local-seconds*interval '1 second') at time zone 'UTC' utc,seconds
    from offsets
  )
  select coalesce(jsonb_agg(jsonb_build_object('utc',
    to_char(utc at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'),'offset_seconds',seconds)
    order by utc),'[]'::jsonb) into v_result from candidates
    where utc at time zone p_timezone=p_local;
  return v_result;
end $$;

create function people.resolve_local_instant(
  p_timezone text,p_local timestamp,p_offset_seconds integer default null
) returns timestamptz language plpgsql stable set search_path = '' as $$
declare v_candidates jsonb; v_utc timestamptz;
begin
  v_candidates:=people.local_instant_candidates(p_timezone,p_local);
  if jsonb_array_length(v_candidates)=0 then
    raise exception using errcode='22023',message='CALENDAR_LOCAL_TIME_NONEXISTENT';
  end if;
  if jsonb_array_length(v_candidates)>1 and p_offset_seconds is null then
    raise exception using errcode='22023',message='CALENDAR_OFFSET_SELECTION_REQUIRED';
  end if;
  select (value->>'utc')::timestamptz into v_utc
    from jsonb_array_elements(v_candidates)
    where p_offset_seconds is null or (value->>'offset_seconds')::integer=p_offset_seconds;
  if v_utc is null then
    raise exception using errcode='22023',message='CALENDAR_OFFSET_INVALID';
  end if;
  return v_utc;
end $$;

create function api.people_calendar_local_candidates(
  p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,
  p_version_id uuid,p_date date,p_minute integer
) returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare v_version people.work_calendar_versions%rowtype; v_local timestamp;
begin
  perform people.require_access(p_tenant_id,p_legal_entity_id,p_branch_id,'people.calendars.view');
  select v.* into v_version from people.work_calendar_versions v
    where v.tenant_id=p_tenant_id and v.legal_entity_id=p_legal_entity_id and v.id=p_version_id;
  if not found then raise exception using errcode='P0002',message='CALENDAR_NOT_FOUND'; end if;
  if p_date is null or not isfinite(p_date) or p_minute is null
    or p_minute not between 0 and 1439
    or p_date<v_version.start_date or p_date>=v_version.end_date_exclusive then
    raise exception using errcode='22023',message='CALENDAR_LOCAL_BOUNDARY_INVALID';
  end if;
  v_local:=p_date::timestamp+p_minute*interval '1 minute';
  return jsonb_build_object('tenant_id',p_tenant_id,'legal_entity_id',p_legal_entity_id,
    'branch_id',p_branch_id,'resolution',jsonb_build_object(
    'calendar_version_id',v_version.id,'date',p_date,'minute',p_minute,
    'timezone',v_version.timezone,'local_datetime',to_char(v_local,'YYYY-MM-DD"T"HH24:MI:SS'),
    'algorithm','pg-iana-roundtrip-v1',
    'candidates',people.local_instant_candidates(v_version.timezone,v_local)));
end $$;

revoke all on function people.local_instant_candidates(text,timestamp),
  people.resolve_local_instant(text,timestamp,integer),
  api.people_calendar_local_candidates(uuid,uuid,uuid,uuid,date,integer)
  from public,anon,authenticated;
grant execute on function api.people_calendar_local_candidates(uuid,uuid,uuid,uuid,date,integer)
  to authenticated;

-- W4-02A dated organization. Unapplied, additive synthetic development candidate.
insert into core.permissions(code,module,description,privileged) values
('people.organization.view','people','Read scoped organization history.',false),
('people.organization.manage','people','Manage dated organization with MFA.',true)
on conflict(code) do nothing;

create table people.departments (
  id uuid primary key, tenant_id uuid not null, legal_entity_id uuid not null,
  code text not null check(code ~ '^[A-Z0-9][A-Z0-9_-]{0,31}$'),
  version bigint not null default 1 check(version between 1 and 9007199254740991),
  unique(tenant_id,legal_entity_id,id),unique(tenant_id,legal_entity_id,code),
  foreign key(tenant_id,legal_entity_id) references core.legal_entities(tenant_id,id)
);
create table people.department_revisions (
  id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,
  department_id uuid not null,parent_id uuid,name text not null check(length(btrim(name)) between 1 and 160),
  start_date date not null,end_date_exclusive date,
  reason text not null check(length(btrim(reason)) between 1 and 1000),
  recorded_by uuid not null references auth.users(id),recorded_at timestamptz not null default clock_timestamp(),
  supersedes_id uuid references people.department_revisions(id),superseded_at timestamptz,
  check(start_date>='0001-01-01'::date and start_date<='9999-12-31'::date
    and (end_date_exclusive is null or (end_date_exclusive>start_date and end_date_exclusive<='9999-12-31'::date))),
  unique(tenant_id,legal_entity_id,id),
  foreign key(tenant_id,legal_entity_id,department_id) references people.departments(tenant_id,legal_entity_id,id),
  foreign key(tenant_id,legal_entity_id,parent_id) references people.departments(tenant_id,legal_entity_id,id),
  exclude using gist(department_id extensions.gist_uuid_ops with =,
    daterange(start_date,end_date_exclusive,'[)') with &&) where(superseded_at is null)
);
create index department_revisions_scope_idx on people.department_revisions(tenant_id,legal_entity_id,department_id,id);
create index department_revisions_parent_idx on people.department_revisions(tenant_id,legal_entity_id,parent_id);
create index department_revisions_actor_idx on people.department_revisions(recorded_by);
create index department_revisions_supersedes_idx on people.department_revisions(supersedes_id);
create table people.organization_assignments (
  id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,branch_id uuid not null,
  employee_id uuid not null,spell_id uuid not null,department_id uuid not null,manager_id uuid,
  calendar_version_id uuid not null,role_title text not null check(length(btrim(role_title)) between 1 and 160),
  start_date date not null,end_date_exclusive date not null,
  reason text not null check(length(btrim(reason)) between 1 and 1000),
  recorded_by uuid not null references auth.users(id),recorded_at timestamptz not null default clock_timestamp(),
  supersedes_id uuid references people.organization_assignments(id),superseded_at timestamptz,
  check(start_date>='0001-01-01'::date and end_date_exclusive<='9999-12-31'::date
    and end_date_exclusive>start_date and end_date_exclusive-start_date<=1830),
  unique(tenant_id,legal_entity_id,id),
  foreign key(tenant_id,legal_entity_id,branch_id) references core.branches(tenant_id,legal_entity_id,id),
  foreign key(tenant_id,legal_entity_id,employee_id) references people.employees(tenant_id,legal_entity_id,id),
  foreign key(tenant_id,legal_entity_id,spell_id,employee_id) references people.employment_spells(tenant_id,legal_entity_id,id,employee_id),
  foreign key(tenant_id,legal_entity_id,department_id) references people.departments(tenant_id,legal_entity_id,id),
  foreign key(tenant_id,legal_entity_id,manager_id) references people.employees(tenant_id,legal_entity_id,id),
  foreign key(tenant_id,legal_entity_id,calendar_version_id) references people.work_calendar_versions(tenant_id,legal_entity_id,id),
  exclude using gist(employee_id extensions.gist_uuid_ops with =,
    daterange(start_date,end_date_exclusive,'[)') with &&) where(superseded_at is null)
);
create index organization_assignments_scope_idx on people.organization_assignments(tenant_id,legal_entity_id,branch_id,employee_id,id);
create index organization_assignments_employee_idx on people.organization_assignments(tenant_id,legal_entity_id,employee_id);
create index organization_assignments_spell_idx on people.organization_assignments(tenant_id,legal_entity_id,spell_id);
create index organization_assignments_department_idx on people.organization_assignments(tenant_id,legal_entity_id,department_id);
create index organization_assignments_manager_idx on people.organization_assignments(tenant_id,legal_entity_id,manager_id);
create index organization_assignments_calendar_idx on people.organization_assignments(tenant_id,legal_entity_id,calendar_version_id);
create index organization_assignments_actor_idx on people.organization_assignments(recorded_by);
create index organization_assignments_supersedes_idx on people.organization_assignments(supersedes_id);
create table people.organization_withdrawals (
  id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,branch_id uuid not null,
  employee_id uuid not null,revision_id uuid not null unique,
  reason text not null check(length(btrim(reason)) between 1 and 1000),
  recorded_by uuid not null references auth.users(id),recorded_at timestamptz not null default clock_timestamp(),
  foreign key(tenant_id,legal_entity_id,revision_id) references people.organization_assignments(tenant_id,legal_entity_id,id),
  foreign key(tenant_id,legal_entity_id,employee_id) references people.employees(tenant_id,legal_entity_id,id),
  foreign key(tenant_id,legal_entity_id,branch_id) references core.branches(tenant_id,legal_entity_id,id)
);
create index organization_withdrawals_scope_idx on people.organization_withdrawals(tenant_id,legal_entity_id,branch_id,employee_id,id);
create index organization_withdrawals_employee_idx on people.organization_withdrawals(tenant_id,legal_entity_id,employee_id);
create index organization_withdrawals_revision_idx on people.organization_withdrawals(tenant_id,legal_entity_id,revision_id);
create index organization_withdrawals_actor_idx on people.organization_withdrawals(recorded_by);

-- Only trusted module commands can seal dated organization inputs. A consumed
-- revision remains immutable even after an unchanged prefix is superseded.
create table people.organization_consumptions (
  id uuid primary key default gen_random_uuid(), tenant_id uuid not null,
  legal_entity_id uuid not null, revision_id uuid not null,
  source_type text not null check(source_type in ('attendance','leave','payroll','project_time','service_time')),
  source_id uuid not null, start_date date not null,end_date_exclusive date not null,
  recorded_at timestamptz not null default clock_timestamp(),
  check(end_date_exclusive>start_date),
  unique(tenant_id,legal_entity_id,source_type,source_id),
  foreign key(tenant_id,legal_entity_id,revision_id)
    references people.organization_assignments(tenant_id,legal_entity_id,id)
);
create index organization_consumptions_revision_idx on people.organization_consumptions(tenant_id,legal_entity_id,revision_id);
create function people.guard_organization_consumption() returns trigger language plpgsql set search_path='' as $$
begin raise exception using errcode='55000',message='ORGANIZATION_CONSUMPTION_IMMUTABLE'; end $$;
create trigger organization_consumption_immutable before update or delete on people.organization_consumptions
  for each row execute function people.guard_organization_consumption();
create trigger organization_withdrawal_immutable before update or delete on people.organization_withdrawals
  for each row execute function people.guard_organization_consumption();
create function people.consume_organization(p_tenant uuid,p_entity uuid,p_branch uuid,p_employee uuid,
  p_source_type text,p_source_id uuid,p_start date,p_end date) returns uuid
language plpgsql security definer set search_path='' as $$
declare v_id uuid;
begin
  perform id from people.employees where id=p_employee and tenant_id=p_tenant and legal_entity_id=p_entity for update;
  perform pg_advisory_xact_lock(hashtextextended('people.organization:'||p_tenant||':'||p_entity,0));
  select id into v_id from people.organization_assignments where employee_id=p_employee
    and tenant_id=p_tenant and legal_entity_id=p_entity and branch_id=p_branch and superseded_at is null
    and daterange(start_date,end_date_exclusive,'[)') @> daterange(p_start,p_end,'[)');
  if v_id is null or p_start is null or p_end is null or p_end<=p_start then
    raise exception using errcode='55000',message='ORGANIZATION_ASSIGNMENT_REQUIRED';
  end if;
  insert into people.organization_consumptions(tenant_id,legal_entity_id,revision_id,source_type,source_id,start_date,end_date_exclusive)
    values(p_tenant,p_entity,v_id,p_source_type,p_source_id,p_start,p_end) on conflict do nothing;
  if not exists(select 1 from people.organization_consumptions where tenant_id=p_tenant and legal_entity_id=p_entity
    and revision_id=v_id and source_type=p_source_type and source_id=p_source_id and start_date=p_start and end_date_exclusive=p_end) then
    raise exception using errcode='22023',message='ORGANIZATION_CONSUMPTION_MISMATCH';
  end if;
  return v_id;
end $$;

create function people.guard_organization_revision() returns trigger language plpgsql set search_path='' as $$
begin
  if tg_op='DELETE' or new.superseded_at is null or old.superseded_at is not null
    or (to_jsonb(new)-'superseded_at') is distinct from (to_jsonb(old)-'superseded_at') then
    raise exception using errcode='55000',message='ORGANIZATION_HISTORY_IMMUTABLE';
  end if;
  return new;
end $$;
create trigger department_history_immutable before update or delete on people.department_revisions
  for each row execute function people.guard_organization_revision();
create trigger organization_history_immutable before update or delete on people.organization_assignments
  for each row execute function people.guard_organization_revision();

create function people.assert_organization(p_tenant uuid,p_entity uuid) returns void
language plpgsql security definer set search_path='' as $$
begin
  if exists(select 1 from people.department_revisions d where d.tenant_id=p_tenant
    and d.legal_entity_id=p_entity and d.superseded_at is null and d.parent_id is not null
    and not coalesce(daterange(d.start_date,d.end_date_exclusive,'[)') <@
      (select range_agg(daterange(p.start_date,p.end_date_exclusive,'[)'))
       from people.department_revisions p where p.department_id=d.parent_id and p.superseded_at is null),false)) then
    raise exception using errcode='23514',message='DEPARTMENT_PARENT_COVERAGE_REQUIRED';
  end if;
  if exists(with recursive walk as (
    select d.department_id,d.parent_id,daterange(d.start_date,d.end_date_exclusive,'[)') span,
      array[d.department_id] path,false cycle from people.department_revisions d
      where d.tenant_id=p_tenant and d.legal_entity_id=p_entity and d.superseded_at is null
    union all select p.department_id,p.parent_id,w.span*daterange(p.start_date,p.end_date_exclusive,'[)'),
      w.path||p.department_id,p.department_id=any(w.path)
      from walk w join people.department_revisions p on p.department_id=w.parent_id
      and p.superseded_at is null and w.span && daterange(p.start_date,p.end_date_exclusive,'[)')
      where not w.cycle and cardinality(w.path)<=64
  ) select 1 from walk where cycle or cardinality(path)>64) then
    raise exception using errcode='23514',message='DEPARTMENT_CYCLE_OR_DEPTH';
  end if;
  if exists(select 1 from people.organization_assignments o
    where o.tenant_id=p_tenant and o.legal_entity_id=p_entity and o.superseded_at is null and (
      not exists(select 1 from people.employment_spells s where s.id=o.spell_id and s.employee_id=o.employee_id
        and daterange(s.start_date,s.end_date_exclusive,'[)') @> daterange(o.start_date,o.end_date_exclusive,'[)'))
      or not coalesce(daterange(o.start_date,o.end_date_exclusive,'[)') <@
        (select range_agg(daterange(a.start_date,a.end_date_exclusive,'[)')) from people.employment_assignments a
         where a.employee_id=o.employee_id and a.spell_id=o.spell_id and a.branch_id=o.branch_id),false)
      or not exists(select 1 from people.work_calendar_versions c where c.id=o.calendar_version_id
        and daterange(c.start_date,c.end_date_exclusive,'[)') @> daterange(o.start_date,o.end_date_exclusive,'[)'))
      or not coalesce(daterange(o.start_date,o.end_date_exclusive,'[)') <@
        (select range_agg(daterange(d.start_date,d.end_date_exclusive,'[)')) from people.department_revisions d
         where d.department_id=o.department_id and d.superseded_at is null),false)
      or (o.manager_id is not null and (o.manager_id=o.employee_id or not coalesce(
        daterange(o.start_date,o.end_date_exclusive,'[)') <@
        (select range_agg(daterange(s.start_date,s.end_date_exclusive,'[)')) from people.employment_spells s
          where s.employee_id=o.manager_id),false)))
    )) then raise exception using errcode='23514',message='ORGANIZATION_IMPACT_REQUIRED'; end if;
  if exists(with recursive walk as (
    select o.employee_id,o.manager_id,daterange(o.start_date,o.end_date_exclusive,'[)') span,
      array[o.employee_id] path,false cycle from people.organization_assignments o
      where o.tenant_id=p_tenant and o.legal_entity_id=p_entity and o.superseded_at is null
    union all select m.employee_id,m.manager_id,w.span*daterange(m.start_date,m.end_date_exclusive,'[)'),
      w.path||m.employee_id,m.employee_id=any(w.path) from walk w
      join people.organization_assignments m on m.employee_id=w.manager_id and m.superseded_at is null
        and w.span && daterange(m.start_date,m.end_date_exclusive,'[)')
      where not w.cycle and cardinality(w.path)<=64
  ) select 1 from walk where cycle or cardinality(path)>64) then
    raise exception using errcode='23514',message='MANAGER_CYCLE_OR_DEPTH';
  end if;
end $$;
create function people.check_organization_compatibility() returns trigger
language plpgsql security definer set search_path='' as $$
begin
  perform people.assert_organization(coalesce(new.tenant_id,old.tenant_id),
    coalesce(new.legal_entity_id,old.legal_entity_id));
  return null;
end $$;
create constraint trigger organization_after_employment_spell after insert or update or delete on people.employment_spells
  deferrable initially deferred for each row execute function people.check_organization_compatibility();
create constraint trigger organization_after_employment_assignment after insert or update or delete on people.employment_assignments
  deferrable initially deferred for each row execute function people.check_organization_compatibility();
create constraint trigger organization_assignment_compatible after insert or update on people.organization_assignments
  deferrable initially deferred for each row execute function people.check_organization_compatibility();
create constraint trigger department_revision_compatible after insert or update on people.department_revisions
  deferrable initially deferred for each row execute function people.check_organization_compatibility();

create function people.organization_assignment_payload(p_id uuid) returns jsonb
language sql stable security definer set search_path='' as $$
  select jsonb_build_object('id',o.id,'tenant_id',o.tenant_id,'legal_entity_id',o.legal_entity_id,
    'branch_id',o.branch_id,'employee_id',o.employee_id,'spell_id',o.spell_id,
    'department_id',o.department_id,'manager_id',o.manager_id,'calendar_version_id',o.calendar_version_id,
    'role_title',o.role_title,'start_date',o.start_date,'end_date_exclusive',o.end_date_exclusive,
    'reason',o.reason,'recorded_by',o.recorded_by,'recorded_at',o.recorded_at,
    'supersedes_id',o.supersedes_id,'superseded_at',o.superseded_at)
    ||jsonb_build_object('department_name_at_start',(select name from people.department_revisions d
      where d.department_id=o.department_id and d.superseded_at is null
        and daterange(d.start_date,d.end_date_exclusive,'[)') @> o.start_date),
      'manager_display_name',(select display_name from people.employees where id=o.manager_id),
      'withdrawal',(select jsonb_build_object('id',w.id,'reason',w.reason,'recorded_by',w.recorded_by,'recorded_at',w.recorded_at)
        from people.organization_withdrawals w where w.revision_id=o.id),
      'calendar_name',(select c.name from people.work_calendars c join people.work_calendar_versions v on v.calendar_id=c.id
        where v.id=o.calendar_version_id),'calendar_timezone',(select timezone from people.work_calendar_versions where id=o.calendar_version_id))
  from people.organization_assignments o where o.id=p_id
$$;
create function api.people_organization_department(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,
  p_department_id uuid,p_as_of date) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare v_item jsonb;
begin
  perform people.require_access(p_tenant_id,p_legal_entity_id,p_branch_id,'people.organization.view');
  if p_as_of is null or not isfinite(p_as_of) or p_as_of<'0001-01-01'::date or p_as_of>'9999-12-31'::date then
    raise exception using errcode='22023',message='ORGANIZATION_FILTER_INVALID';
  end if;
  select jsonb_build_object('id',d.id,'code',d.code,'version',d.version,'revision_id',r.id,'name',r.name,
    'parent_id',r.parent_id,'start_date',r.start_date,'end_date_exclusive',r.end_date_exclusive) into v_item
    from people.departments d join people.department_revisions r on r.department_id=d.id and r.superseded_at is null
      and daterange(r.start_date,r.end_date_exclusive,'[)') @> p_as_of
    where d.id=p_department_id and d.tenant_id=p_tenant_id and d.legal_entity_id=p_legal_entity_id;
  if v_item is null then raise exception using errcode='P0002',message='DEPARTMENT_NOT_FOUND'; end if;
  return jsonb_build_object('tenant_id',p_tenant_id,'legal_entity_id',p_legal_entity_id,'branch_id',p_branch_id,
    'as_of',p_as_of,'department',v_item);
end $$;
create function api.people_organization_departments(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,
  p_as_of date,p_search text default '',p_after uuid default null)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare v_items jsonb;
begin
  perform people.require_access(p_tenant_id,p_legal_entity_id,p_branch_id,'people.organization.view');
  if p_as_of is null or not isfinite(p_as_of) or p_as_of<'0001-01-01'::date
    or p_as_of>'9999-12-31'::date or length(coalesce(p_search,''))>160 then
    raise exception using errcode='22023',message='ORGANIZATION_FILTER_INVALID';
  end if;
  select coalesce(jsonb_agg(jsonb_build_object('id',q.id,'code',q.code,'version',q.version,
    'revision_id',q.revision_id,'name',q.name,'parent_id',q.parent_id,
    'start_date',q.start_date,'end_date_exclusive',q.end_date_exclusive) order by q.id),'[]') into v_items
  from (select d.id,d.code,d.version,r.id revision_id,r.name,r.parent_id,r.start_date,r.end_date_exclusive
    from people.departments d join people.department_revisions r on r.department_id=d.id
    and r.superseded_at is null and daterange(r.start_date,r.end_date_exclusive,'[)') @> p_as_of
    where d.tenant_id=p_tenant_id and d.legal_entity_id=p_legal_entity_id and (p_after is null or d.id>p_after)
    and (btrim(coalesce(p_search,''))='' or position(lower(btrim(p_search)) in lower(d.code||' '||r.name))>0)
    order by d.id limit 50) q;
  return jsonb_build_object('tenant_id',p_tenant_id,'legal_entity_id',p_legal_entity_id,
    'branch_id',p_branch_id,'as_of',p_as_of,'items',v_items);
end $$;
create function api.people_organization_employee(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,
  p_employee_id uuid,p_as_of date,p_after uuid default null)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare v_items jsonb; v_version bigint;
begin
  perform people.require_access(p_tenant_id,p_legal_entity_id,p_branch_id,'people.organization.view');
  perform api.people_employee_detail(p_tenant_id,p_legal_entity_id,p_branch_id,p_employee_id,p_as_of);
  select version into v_version from people.employees where id=p_employee_id;
  select coalesce(jsonb_agg(people.organization_assignment_payload(q.id) order by q.id),'[]') into v_items
    from (select id from people.organization_assignments where employee_id=p_employee_id and branch_id=p_branch_id
      and tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and (p_after is null or id>p_after)
      order by id limit 50) q;
  return jsonb_build_object('tenant_id',p_tenant_id,'legal_entity_id',p_legal_entity_id,'branch_id',p_branch_id,
    'employee_id',p_employee_id,'employee_version',v_version,'as_of',p_as_of,'items',v_items);
end $$;
create function api.people_organization_department_history(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,
  p_department_id uuid,p_after uuid default null)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare v_items jsonb;
begin
  perform people.require_access(p_tenant_id,p_legal_entity_id,p_branch_id,'people.organization.view');
  if not exists(select 1 from people.departments where id=p_department_id and tenant_id=p_tenant_id
    and legal_entity_id=p_legal_entity_id) then raise exception using errcode='P0002',message='DEPARTMENT_NOT_FOUND'; end if;
  select coalesce(jsonb_agg(jsonb_build_object('id',q.id,'name',q.name,'parent_id',q.parent_id,
    'start_date',q.start_date,'end_date_exclusive',q.end_date_exclusive,'reason',q.reason,
    'recorded_by',q.recorded_by,'recorded_at',q.recorded_at,'supersedes_id',q.supersedes_id,
    'superseded_at',q.superseded_at) order by q.id),'[]') into v_items
    from (select * from people.department_revisions where department_id=p_department_id
      and (p_after is null or id>p_after) order by id limit 50) q;
  return jsonb_build_object('tenant_id',p_tenant_id,'legal_entity_id',p_legal_entity_id,
    'branch_id',p_branch_id,'department_id',p_department_id,'items',v_items);
end $$;

create function api.people_organization_command(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,
  p_command_id uuid,p_idempotency_key uuid,p_client_timestamp timestamptz,p_payload jsonb,p_expected_version bigint)
returns jsonb language plpgsql security definer set search_path='' as $$
declare v_action text:=p_payload->>'action';v_actor uuid:=auth.uid();v_id uuid;v_revision uuid;
  v_employee uuid;v_manager uuid;v_start date;v_end date;v_hash text;v_replay jsonb;v_allowed text[];
  v_before jsonb:='{}';v_entity jsonb;v_current bigint;v_old people.department_revisions%rowtype;
  v_old_org people.organization_assignments%rowtype;v_name text;v_reason text;v_parent uuid;
begin
  if coalesce(jsonb_typeof(p_payload),'null')<>'object' or v_action is null
    or v_action not in ('department_create','department_revise','assign','replace','end_assignment','withdraw_assignment')
    or p_command_id is null or p_idempotency_key is null or p_client_timestamp is null
    or coalesce(p_payload->>'id','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    raise exception using errcode='22023',message='ORGANIZATION_COMMAND_INVALID';
  end if;
  v_allowed:=case v_action
    when 'department_create' then array['action','id','revision_id','code','name','parent_id','start_date','end_date_exclusive','reason']
    when 'department_revise' then array['action','id','revision_id','name','parent_id','start_date','end_date_exclusive','reason','replace_revision_id']
    when 'assign' then array['action','id','employee_id','spell_id','department_id','manager_id','calendar_version_id',
      'role_title','start_date','end_date_exclusive','reason']
    when 'replace' then array['action','id','employee_id','spell_id','department_id','manager_id','calendar_version_id',
      'role_title','start_date','end_date_exclusive','reason','replace_revision_id']
    else array['action','id','employee_id','start_date','end_date_exclusive','reason','replace_revision_id'] end;
  if exists(select 1 from jsonb_object_keys(p_payload) k where k<>all(v_allowed))
    or coalesce(jsonb_typeof(p_payload->'reason'),'null')<>'string'
    or length(btrim(p_payload->>'reason')) not between 1 and 1000
    or coalesce(p_payload->>'start_date','') !~ '^\d{4}-\d{2}-\d{2}$' then
    raise exception using errcode='22023',message='ORGANIZATION_COMMAND_FIELDS_INVALID';
  end if;
  v_id:=(p_payload->>'id')::uuid;v_start:=(p_payload->>'start_date')::date;
  v_end:=nullif(p_payload->>'end_date_exclusive','')::date;v_reason:=btrim(p_payload->>'reason');
  if v_start<'0001-01-01'::date or v_start>'9999-12-31'::date or not isfinite(v_start)
    or (v_end is not null and (not isfinite(v_end) or v_end<=v_start or v_end>'9999-12-31'::date)) then
    raise exception using errcode='22023',message='ORGANIZATION_DATES_INVALID';
  end if;
  perform people.require_access(p_tenant_id,p_legal_entity_id,p_branch_id,'people.organization.view');
  perform people.require_access(p_tenant_id,p_legal_entity_id,p_branch_id,'people.organization.manage');
  -- Hierarchy/manager changes can affect every branch: entity-wide management is required.
  perform core.require_permission(p_tenant_id,'people.organization.manage',p_legal_entity_id,null);
  if v_action in ('assign','replace','end_assignment','withdraw_assignment') then
    v_employee:=(p_payload->>'employee_id')::uuid;v_manager:=nullif(p_payload->>'manager_id','')::uuid;
    perform api.people_employee_detail(p_tenant_id,p_legal_entity_id,p_branch_id,v_employee,v_start);
    perform people.require_access(p_tenant_id,p_legal_entity_id,p_branch_id,'people.calendars.view');
    if v_employee is null or v_end is null or v_end-v_start>1830 or
      (v_action not in ('end_assignment','withdraw_assignment') and (coalesce(jsonb_typeof(p_payload->'role_title'),'null')<>'string'
      or length(btrim(p_payload->>'role_title')) not between 1 and 160)) then
      raise exception using errcode='22023',message='ORGANIZATION_ASSIGNMENT_INVALID';
    end if;
  end if;
  v_hash:=core.wave3_request_hash('people.organization.'||v_action,p_command_id,
    p_tenant_id,p_legal_entity_id,p_branch_id,p_payload,p_expected_version);
  v_replay:=core.wave3_replay(p_tenant_id,'people.organization.'||v_action,p_command_id,p_idempotency_key,v_hash);
  if v_replay is not null then return v_replay; end if;
  if v_employee is not null then
    perform id from people.employees where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id
      and id in (v_employee,v_manager) order by id for update;
  end if;
  perform pg_advisory_xact_lock(hashtextextended('people.organization:'||p_tenant_id||':'||p_legal_entity_id,0));
  if v_action like 'department_%' then
    v_name:=btrim(p_payload->>'name');v_parent:=nullif(p_payload->>'parent_id','')::uuid;
    v_revision:=(p_payload->>'revision_id')::uuid;
    if v_revision is null or coalesce(jsonb_typeof(p_payload->'name'),'null')<>'string'
      or length(v_name) not between 1 and 160 then
      raise exception using errcode='22023',message='DEPARTMENT_FIELDS_INVALID';
    end if;
    if v_action='department_create' then
      if p_expected_version is distinct from 0 or coalesce(p_payload->>'code','') !~ '^[A-Z0-9][A-Z0-9_-]{0,31}$'
        or (select count(*) from people.departments where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id)>=2000 then
        raise exception using errcode='22023',message='DEPARTMENT_CREATE_INVALID';
      end if;
      insert into people.departments(id,tenant_id,legal_entity_id,code)
      values(v_id,p_tenant_id,p_legal_entity_id,p_payload->>'code');
    else
      select version into v_current from people.departments where id=v_id
        and tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id for update;
      if not found then raise exception using errcode='P0002',message='DEPARTMENT_NOT_FOUND'; end if;
      perform core.wave3_assert_expected_version(v_current,p_expected_version,'{}');
      select * into v_old from people.department_revisions where id=(p_payload->>'replace_revision_id')::uuid
        and department_id=v_id and superseded_at is null;
      if not found or not daterange(v_old.start_date,v_old.end_date_exclusive,'[)') @> daterange(v_start,v_end,'[)') then
        raise exception using errcode='22023',message='DEPARTMENT_REPLACEMENT_INVALID';
      end if;
      v_before:=jsonb_build_object('id',v_id,'version',v_current,'revision_id',v_old.id);
      if exists(select 1 from people.organization_consumptions c join people.organization_assignments o on o.id=c.revision_id
        where o.department_id=v_id and daterange(c.start_date,c.end_date_exclusive,'[)') && daterange(v_start,v_end,'[)')) then
        raise exception using errcode='55000',message='ORGANIZATION_CONSUMED_IMPACT_REQUIRED';
      end if;
      update people.department_revisions set superseded_at=clock_timestamp() where id=v_old.id;
      if v_old.start_date<v_start then
        insert into people.department_revisions(id,tenant_id,legal_entity_id,department_id,parent_id,name,
          start_date,end_date_exclusive,reason,recorded_by,supersedes_id)
        values(gen_random_uuid(),p_tenant_id,p_legal_entity_id,v_id,v_old.parent_id,v_old.name,
          v_old.start_date,v_start,v_reason,v_actor,v_old.id);
      end if;
      if v_end is not null and (v_old.end_date_exclusive is null or v_end<v_old.end_date_exclusive) then
        insert into people.department_revisions(id,tenant_id,legal_entity_id,department_id,parent_id,name,
          start_date,end_date_exclusive,reason,recorded_by,supersedes_id)
        values(gen_random_uuid(),p_tenant_id,p_legal_entity_id,v_id,v_old.parent_id,v_old.name,
          v_end,v_old.end_date_exclusive,v_reason,v_actor,v_old.id);
      end if;
      update people.departments set version=version+1 where id=v_id;
    end if;
    insert into people.department_revisions(id,tenant_id,legal_entity_id,department_id,parent_id,name,
      start_date,end_date_exclusive,reason,recorded_by,supersedes_id)
    values(v_revision,p_tenant_id,p_legal_entity_id,v_id,v_parent,v_name,v_start,v_end,v_reason,v_actor,
      case when v_action='department_revise' then v_old.id end);
    select jsonb_build_object('id',id,'tenant_id',tenant_id,'legal_entity_id',legal_entity_id,
      'code',code,'version',version,'revision_id',v_revision)
      into v_entity from people.departments where id=v_id;
  else
    select version into v_current from people.employees where id=v_employee;
    perform core.wave3_assert_expected_version(v_current,p_expected_version,'{}');
    if v_action in ('replace','end_assignment','withdraw_assignment') then
      select * into v_old_org from people.organization_assignments where id=(p_payload->>'replace_revision_id')::uuid
        and employee_id=v_employee and tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id
        and branch_id=p_branch_id and superseded_at is null;
      -- Full revision replacement retains its original dates. Partial changes use
      -- explicit successor revisions rather than silently trimming original facts.
      if not found or v_start<>v_old_org.start_date
        or (v_action in ('replace','withdraw_assignment') and v_end<>v_old_org.end_date_exclusive)
        or (v_action='end_assignment' and v_end>=v_old_org.end_date_exclusive) then
        raise exception using errcode='22023',message='ORGANIZATION_REPLACEMENT_INVALID';
      end if;
      v_before:=people.organization_assignment_payload(v_old_org.id);
      if v_action='withdraw_assignment' and v_start <=
        (clock_timestamp() at time zone (select timezone from core.legal_entities where id=p_legal_entity_id))::date then
        raise exception using errcode='55000',message='ORGANIZATION_FUTURE_WITHDRAWAL_REQUIRED';
      end if;
      if exists(select 1 from people.organization_consumptions c where c.revision_id=v_old_org.id
        and (v_action in ('replace','withdraw_assignment') or c.end_date_exclusive>v_end)) then
        raise exception using errcode='55000',message='ORGANIZATION_CONSUMED_IMPACT_REQUIRED';
      end if;
      update people.organization_assignments set superseded_at=clock_timestamp() where id=v_old_org.id;
    end if;
    if v_action='withdraw_assignment' then
      insert into people.organization_withdrawals(id,tenant_id,legal_entity_id,branch_id,employee_id,revision_id,reason,recorded_by)
        values(v_id,p_tenant_id,p_legal_entity_id,p_branch_id,v_employee,v_old_org.id,v_reason,v_actor);
      update people.employees set version=version+1,updated_by=v_actor,updated_at=clock_timestamp() where id=v_employee;
      select jsonb_build_object('id',w.id,'tenant_id',w.tenant_id,'legal_entity_id',w.legal_entity_id,'branch_id',w.branch_id,
        'employee_id',w.employee_id,'revision_id',w.revision_id,'reason',w.reason,'recorded_by',w.recorded_by,
        'recorded_at',w.recorded_at,'employee_version',v_current+1) into v_entity from people.organization_withdrawals w where id=v_id;
    else
    insert into people.organization_assignments(id,tenant_id,legal_entity_id,branch_id,employee_id,spell_id,
      department_id,manager_id,calendar_version_id,role_title,start_date,end_date_exclusive,reason,recorded_by,supersedes_id)
    values(v_id,p_tenant_id,p_legal_entity_id,p_branch_id,v_employee,
      case when v_action='end_assignment' then v_old_org.spell_id else (p_payload->>'spell_id')::uuid end,
      case when v_action='end_assignment' then v_old_org.department_id else (p_payload->>'department_id')::uuid end,
      case when v_action='end_assignment' then v_old_org.manager_id else v_manager end,
      case when v_action='end_assignment' then v_old_org.calendar_version_id else (p_payload->>'calendar_version_id')::uuid end,
      case when v_action='end_assignment' then v_old_org.role_title else btrim(p_payload->>'role_title') end,
      v_start,v_end,v_reason,v_actor,case when v_action in ('replace','end_assignment') then v_old_org.id end);
    update people.employees set version=version+1,updated_by=v_actor,updated_at=clock_timestamp() where id=v_employee;
    v_entity:=people.organization_assignment_payload(v_id)||jsonb_build_object('employee_version',v_current+1);
    end if;
  end if;
  perform people.assert_organization(p_tenant_id,p_legal_entity_id);
  return core.wave3_finish_command(p_tenant_id,'people.organization.'||v_action,p_command_id,
    case when v_employee is null then 'people.department' else 'people.organization' end,
    v_id,p_idempotency_key,v_hash,v_before,v_entity,p_legal_entity_id,p_branch_id);
end $$;

alter table people.departments enable row level security;
alter table people.departments force row level security;
alter table people.department_revisions enable row level security;
alter table people.department_revisions force row level security;
alter table people.organization_assignments enable row level security;
alter table people.organization_assignments force row level security;
alter table people.organization_consumptions enable row level security;
alter table people.organization_consumptions force row level security;
alter table people.organization_withdrawals enable row level security;
alter table people.organization_withdrawals force row level security;
revoke all on people.departments,people.department_revisions,people.organization_assignments,people.organization_consumptions,
  people.organization_withdrawals from public,anon,authenticated;
revoke all on function people.guard_organization_revision(),people.assert_organization(uuid,uuid),
  people.guard_organization_consumption(),people.consume_organization(uuid,uuid,uuid,uuid,text,uuid,date,date),
  api.people_organization_department(uuid,uuid,uuid,uuid,date),
  people.check_organization_compatibility(),people.organization_assignment_payload(uuid),
  api.people_organization_departments(uuid,uuid,uuid,date,text,uuid),
  api.people_organization_employee(uuid,uuid,uuid,uuid,date,uuid),
  api.people_organization_department_history(uuid,uuid,uuid,uuid,uuid),
  api.people_organization_command(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) from public,anon,authenticated;
grant execute on function api.people_organization_departments(uuid,uuid,uuid,date,text,uuid),
  api.people_organization_department(uuid,uuid,uuid,uuid,date),
  api.people_organization_employee(uuid,uuid,uuid,uuid,date,uuid),
  api.people_organization_department_history(uuid,uuid,uuid,uuid,uuid),
  api.people_organization_command(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint) to authenticated;

-- W4-03A synthetic attendance and the shared payable interval arbiter.
-- Candidate only; depends on W4-02A organization and IANA resolver installation.
-- No existing role, plan, subscriber or employee/calendar fact is changed.
create extension if not exists btree_gist with schema extensions;

insert into core.permissions(code,module,description,privileged) values
 ('people.attendance.view','people','Read scoped attendance and work history',false),
 ('people.attendance.manage','people','Prepare scoped attendance revisions',true),
 ('people.attendance.import','people','Import immutable raw clock events',true),
 ('people.attendance.approve','people','Independently decide attendance',true),
 ('people.work_claims.view','people','Read authorized payable interval claims',false)
on conflict(code) do nothing;

create table people.raw_clock_events(
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,
 branch_id uuid not null,employee_id uuid not null,
 source_system text not null check(length(btrim(source_system)) between 1 and 80),
 source_key text not null check(length(btrim(source_key)) between 1 and 160),
 observed_utc timestamptz not null,checksum text not null check(checksum ~ '^[a-f0-9]{64}$'),
 imported_by uuid not null references auth.users(id),imported_at timestamptz not null default clock_timestamp(),
 unique(tenant_id,source_system,source_key),unique(tenant_id,legal_entity_id,employee_id,id),
 foreign key(tenant_id,legal_entity_id,employee_id) references people.employees(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,legal_entity_id,branch_id) references core.branches(tenant_id,legal_entity_id,id)
);
create index raw_clock_events_scope_idx on people.raw_clock_events(tenant_id,legal_entity_id,branch_id,employee_id,id);
create index raw_clock_events_actor_idx on people.raw_clock_events(imported_by);

create table people.attendance_entries(
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,
 branch_id uuid not null,employee_id uuid not null,
 version bigint not null default 1 check(version between 1 and 9007199254740991),
 current_revision_id uuid not null,
 status text not null check(status in ('draft','submitted','approved','rejected','cancelled')),
 submitted_by uuid references auth.users(id),decided_by uuid references auth.users(id),
 active_claim_id uuid,
 created_by uuid not null references auth.users(id),created_at timestamptz not null default clock_timestamp(),
 unique(tenant_id,legal_entity_id,id),unique(tenant_id,legal_entity_id,employee_id,id),
 foreign key(tenant_id,legal_entity_id,employee_id) references people.employees(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,legal_entity_id,branch_id) references core.branches(tenant_id,legal_entity_id,id)
);
create index attendance_entries_scope_idx on people.attendance_entries(tenant_id,legal_entity_id,branch_id,employee_id,id);
create index attendance_entries_creator_idx on people.attendance_entries(created_by);
create index attendance_entries_submitter_idx on people.attendance_entries(submitted_by);
create index attendance_entries_decider_idx on people.attendance_entries(decided_by);

create table people.attendance_revisions(
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,
 branch_id uuid not null,employee_id uuid not null,entry_id uuid not null,
 version bigint not null check(version between 1 and 9007199254740991),
 calendar_version_id uuid not null,
 start_local timestamp not null,start_offset_seconds integer not null,
 end_local timestamp not null,end_offset_seconds integer not null,
 start_utc timestamptz not null,end_utc timestamptz not null,
 breaks jsonb not null default '[]'::jsonb,
 gross_seconds bigint not null check(gross_seconds between 1 and 129600),
 break_seconds bigint not null check(break_seconds>=0),
 payable_seconds bigint not null check(payable_seconds>0 and payable_seconds<=129600),
 raw_start_id uuid,raw_end_id uuid,
 reason text not null check(length(btrim(reason)) between 1 and 1000),
 supersedes_revision_id uuid,
 recorded_by uuid not null references auth.users(id),recorded_at timestamptz not null default clock_timestamp(),
 unique(tenant_id,legal_entity_id,entry_id,version),
 unique(tenant_id,legal_entity_id,employee_id,entry_id,id),
 foreign key(tenant_id,legal_entity_id,employee_id,entry_id)
  references people.attendance_entries(tenant_id,legal_entity_id,employee_id,id),
 foreign key(tenant_id,legal_entity_id,calendar_version_id)
  references people.work_calendar_versions(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,legal_entity_id,employee_id,raw_start_id)
  references people.raw_clock_events(tenant_id,legal_entity_id,employee_id,id),
 foreign key(tenant_id,legal_entity_id,employee_id,raw_end_id)
  references people.raw_clock_events(tenant_id,legal_entity_id,employee_id,id),
 foreign key(supersedes_revision_id) references people.attendance_revisions(id),
 check(end_utc>start_utc and gross_seconds=extract(epoch from end_utc-start_utc)::bigint
   and gross_seconds=break_seconds+payable_seconds),
 check((raw_start_id is null and raw_end_id is null) or
   (raw_start_id is not null and raw_end_id is not null and raw_start_id<>raw_end_id))
);
create index attendance_revisions_entry_idx on people.attendance_revisions(tenant_id,legal_entity_id,entry_id,id);
create index attendance_revisions_calendar_idx on people.attendance_revisions(tenant_id,legal_entity_id,calendar_version_id);
create index attendance_revisions_raw_start_idx on people.attendance_revisions(raw_start_id);
create index attendance_revisions_raw_end_idx on people.attendance_revisions(raw_end_id);
create index attendance_revisions_actor_idx on people.attendance_revisions(recorded_by);
create index attendance_revisions_supersedes_idx on people.attendance_revisions(supersedes_revision_id);
alter table people.attendance_entries add foreign key(tenant_id,legal_entity_id,employee_id,id,current_revision_id)
 references people.attendance_revisions(tenant_id,legal_entity_id,employee_id,entry_id,id)
 deferrable initially deferred;

create table people.work_claims(
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,
 branch_id uuid not null,employee_id uuid not null,
 source_kind text not null check(source_kind in ('attendance','project','service','leave')),
 source_id uuid not null,
 start_utc timestamptz not null,end_utc timestamptz not null,
 gross_seconds bigint not null check(gross_seconds between 1 and 129600),
 break_seconds bigint not null check(break_seconds>=0),
 payable_seconds bigint not null check(payable_seconds>=0),
 calendar_version_id uuid not null,
 active boolean not null default true,revoked_at timestamptz,
 created_by uuid not null references auth.users(id),created_at timestamptz not null default clock_timestamp(),
 unique(tenant_id,legal_entity_id,employee_id,id),
 unique(tenant_id,legal_entity_id,source_kind,source_id),
 foreign key(tenant_id,legal_entity_id,employee_id) references people.employees(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,legal_entity_id,branch_id) references core.branches(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,legal_entity_id,calendar_version_id)
  references people.work_calendar_versions(tenant_id,legal_entity_id,id),
 check(end_utc>start_utc and gross_seconds=extract(epoch from end_utc-start_utc)::bigint),
 check((source_kind='leave' and break_seconds=0 and payable_seconds=0) or
   (source_kind<>'leave' and gross_seconds=break_seconds+payable_seconds)),
 check(active=(revoked_at is null)),
 check((source_kind='leave' and payable_seconds=0) or
   (source_kind<>'leave' and payable_seconds>0))
);
create index work_claims_scope_idx on people.work_claims(tenant_id,legal_entity_id,branch_id,employee_id,id);
create index work_claims_calendar_idx on people.work_claims(tenant_id,legal_entity_id,calendar_version_id);
create index work_claims_creator_idx on people.work_claims(created_by);
create table people.work_claim_segments(
 id uuid primary key default gen_random_uuid(),tenant_id uuid not null,legal_entity_id uuid not null,
 employee_id uuid not null,claim_id uuid not null,
 start_utc timestamptz not null,end_utc timestamptz not null,
 active boolean not null default true,
 foreign key(tenant_id,legal_entity_id,employee_id,claim_id)
  references people.work_claims(tenant_id,legal_entity_id,employee_id,id),
 check(end_utc>start_utc),
 exclude using gist(employee_id extensions.gist_uuid_ops with =,
   tstzrange(start_utc,end_utc,'[)') with &&) where(active)
);
create index work_claim_segments_claim_idx on people.work_claim_segments(claim_id);
create table people.work_allocations(
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,
 branch_id uuid not null,employee_id uuid not null,claim_id uuid not null,
 source_kind text not null check(source_kind in ('project','service')),
 source_id uuid not null,start_utc timestamptz not null,end_utc timestamptz not null,
 active boolean not null default true,revoked_at timestamptz,
 created_by uuid not null references auth.users(id),created_at timestamptz not null default clock_timestamp(),
 unique(tenant_id,legal_entity_id,source_kind,source_id),
 foreign key(tenant_id,legal_entity_id,employee_id,claim_id)
  references people.work_claims(tenant_id,legal_entity_id,employee_id,id),
 foreign key(tenant_id,legal_entity_id,branch_id) references core.branches(tenant_id,legal_entity_id,id),
 check(end_utc>start_utc and active=(revoked_at is null)),
 exclude using gist(employee_id extensions.gist_uuid_ops with =,
  tstzrange(start_utc,end_utc,'[)') with &&) where(active)
);
create index work_allocations_claim_idx on people.work_allocations(claim_id);
create index work_allocations_scope_idx on people.work_allocations(tenant_id,legal_entity_id,branch_id,employee_id,id);
create index work_allocations_actor_idx on people.work_allocations(created_by);
create table people.work_input_seals(
 id uuid primary key default gen_random_uuid(),tenant_id uuid not null,legal_entity_id uuid not null,
 employee_id uuid not null,run_id uuid not null,claim_id uuid not null,
 source_version bigint not null check(source_version>0),seconds bigint not null check(seconds>=0),
 digest text not null check(digest ~ '^[a-f0-9]{64}$'),sealed_at timestamptz not null default clock_timestamp(),
 unique(tenant_id,run_id,claim_id),
 foreign key(tenant_id,legal_entity_id,employee_id,claim_id)
  references people.work_claims(tenant_id,legal_entity_id,employee_id,id)
);
create index work_input_seals_claim_idx on people.work_input_seals(claim_id);

create table people.attendance_events(
 id uuid primary key default gen_random_uuid(),tenant_id uuid not null,legal_entity_id uuid not null,
 branch_id uuid not null,employee_id uuid not null,entry_id uuid not null,revision_id uuid not null,
 action text not null check(action in ('create','correct','submit','approve','reject','cancel')),
 before_status text,after_status text not null,
 reason text not null check(length(btrim(reason)) between 1 and 1000),
 actor_id uuid not null references auth.users(id),recorded_at timestamptz not null default clock_timestamp(),
 command_id uuid not null,unique(tenant_id,legal_entity_id,command_id),
 foreign key(tenant_id,legal_entity_id,employee_id,entry_id,revision_id)
  references people.attendance_revisions(tenant_id,legal_entity_id,employee_id,entry_id,id),
 foreign key(tenant_id,legal_entity_id,branch_id) references core.branches(tenant_id,legal_entity_id,id)
);
create index attendance_events_entry_idx on people.attendance_events(tenant_id,legal_entity_id,branch_id,entry_id,id);
create index attendance_events_actor_idx on people.attendance_events(actor_id);

do $$declare v_table regclass;begin
 foreach v_table in array array[
  'people.raw_clock_events'::regclass,'people.attendance_entries'::regclass,
  'people.attendance_revisions'::regclass,'people.work_claims'::regclass,
  'people.work_claim_segments'::regclass,'people.work_allocations'::regclass,
  'people.work_input_seals'::regclass,
  'people.attendance_events'::regclass] loop
  execute format('alter table %s enable row level security',v_table);
  execute format('alter table %s force row level security',v_table);
  execute format('revoke all on %s from public,anon,authenticated',v_table);
 end loop;
end $$;

create function people.work_history_guard() returns trigger language plpgsql set search_path='' as $$begin
 if tg_op='UPDATE' and tg_table_name='work_claims' then
  if old.active and not new.active and new.revoked_at is not null
   and (to_jsonb(new)-'active'-'revoked_at')=(to_jsonb(old)-'active'-'revoked_at') then
   return new;end if;
 elsif tg_op='UPDATE' and tg_table_name='work_claim_segments' then
  if old.active and not new.active
   and (to_jsonb(new)-'active')=(to_jsonb(old)-'active') then return new;end if;
 elsif tg_op='UPDATE' and tg_table_name='work_allocations' then
  if old.active and not new.active and new.revoked_at is not null
   and (to_jsonb(new)-'active'-'revoked_at')=(to_jsonb(old)-'active'-'revoked_at') then
   return new;end if;
 end if;
 raise exception using errcode='55000',message='WORK_HISTORY_IMMUTABLE';
end $$;
create trigger raw_clock_immutable before update or delete on people.raw_clock_events
 for each row execute function people.work_history_guard();
create trigger attendance_revision_immutable before update or delete on people.attendance_revisions
 for each row execute function people.work_history_guard();
create trigger attendance_event_immutable before update or delete on people.attendance_events
 for each row execute function people.work_history_guard();
create trigger work_claim_guard before update or delete on people.work_claims
 for each row execute function people.work_history_guard();
create trigger work_segment_guard before update or delete on people.work_claim_segments
 for each row execute function people.work_history_guard();
create trigger work_allocation_guard before update or delete on people.work_allocations
 for each row execute function people.work_history_guard();
create trigger work_seal_immutable before update or delete on people.work_input_seals
 for each row execute function people.work_history_guard();

create function people.work_break_seconds(p_start timestamptz,p_end timestamptz,p_breaks jsonb)
returns bigint language plpgsql immutable set search_path='' as $$
declare v jsonb;v_start timestamptz;v_end timestamptz;v_cursor timestamptz:=p_start;
 v_seconds bigint:=0;begin
 if p_start is null or p_end is null or p_end<=p_start
  or extract(epoch from p_start)%1<>0 or extract(epoch from p_end)%1<>0
  or p_end-p_start>interval '36 hours'
  or coalesce(jsonb_typeof(p_breaks),'null')<>'array'
  or jsonb_array_length(p_breaks)>16 then
  raise exception using errcode='22023',message='WORK_INTERVAL_INVALID';end if;
 for v in select value from jsonb_array_elements(p_breaks) loop
  if jsonb_typeof(v)<>'object' or not(v ? 'start_utc' and v ? 'end_utc')
   or (select count(*) from jsonb_object_keys(v))<>2
   or coalesce(v->>'start_utc','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z$'
   or coalesce(v->>'end_utc','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z$' then
   raise exception using errcode='22023',message='WORK_BREAK_INVALID';end if;
  v_start:=(v->>'start_utc')::timestamptz;v_end:=(v->>'end_utc')::timestamptz;
  if v_start<v_cursor or v_end<=v_start or v_end>p_end
   or extract(epoch from v_start)%1<>0 or extract(epoch from v_end)%1<>0 then
   raise exception using errcode='22023',message='WORK_BREAK_INVALID';end if;
  v_seconds:=v_seconds+extract(epoch from v_end-v_start)::bigint;
  v_cursor:=v_end;
 end loop;
 if v_seconds>=extract(epoch from p_end-p_start)::bigint then
  raise exception using errcode='22023',message='WORK_BREAK_INVALID';end if;
 return v_seconds;
end $$;

create function people.work_local_coverage(p_t uuid,p_e uuid,p_b uuid,p_employee uuid,
 p_calendar_version uuid,p_start_local timestamp,p_end_local timestamp)
returns void language plpgsql security definer set search_path='' as $$
declare v_start date;v_end date;begin
 if p_start_local is null or p_end_local is null
  or p_start_local<'0001-01-01'::timestamp or p_end_local>='10000-01-01'::timestamp then
  raise exception using errcode='22023',message='WORK_LOCAL_BOUNDARY_INVALID';end if;
 v_start:=p_start_local::date;
 v_end:=greatest((p_end_local-interval '1 microsecond')::date+1,v_start+1);
 if v_end-v_start>3 then raise exception using errcode='22023',message='WORK_LOCAL_BOUNDARY_INVALID';end if;
 if not exists(select 1 from people.organization_assignments o
  join people.work_calendar_versions c on c.id=o.calendar_version_id
  where o.tenant_id=p_t and o.legal_entity_id=p_e and o.branch_id=p_b
   and o.employee_id=p_employee and o.calendar_version_id=p_calendar_version
   and o.superseded_at is null
   and daterange(o.start_date,o.end_date_exclusive,'[)') @> daterange(v_start,v_end,'[)')
   and daterange(c.start_date,c.end_date_exclusive,'[)') @> daterange(v_start,v_end,'[)'))
  or not exists(select 1 from people.employment_assignments a
   join people.employment_spells s on s.id=a.spell_id
   where a.tenant_id=p_t and a.legal_entity_id=p_e and a.branch_id=p_b
    and a.employee_id=p_employee
    and daterange(a.start_date,a.end_date_exclusive,'[)') @> daterange(v_start,v_end,'[)')
    and daterange(s.start_date,s.end_date_exclusive,'[)') @> daterange(v_start,v_end,'[)')) then
  raise exception using errcode='55000',message='WORK_COVERAGE_REQUIRED';end if;
end $$;

create function people.make_work_claim(p_t uuid,p_e uuid,p_b uuid,p_employee uuid,
 p_kind text,p_source uuid,p_start timestamptz,p_end timestamptz,p_breaks jsonb,
 p_calendar_version uuid,p_actor uuid)
returns uuid language plpgsql security definer set search_path='' as $$
declare v_id uuid:=gen_random_uuid();v_break bigint;v_gross bigint;
 v jsonb;v_cursor timestamptz:=p_start;v_start timestamptz;v_end timestamptz;begin
 if p_kind not in ('attendance','project','service','leave') or p_source is null
  or p_actor is null or p_employee is null or p_calendar_version is null then
  raise exception using errcode='22023',message='WORK_CLAIM_INVALID';end if;
 v_break:=people.work_break_seconds(p_start,p_end,p_breaks);
 v_gross:=extract(epoch from p_end-p_start)::bigint;
 if p_kind='leave' and v_break<>0 then
  raise exception using errcode='22023',message='WORK_CLAIM_INVALID';end if;
 insert into people.work_claims(id,tenant_id,legal_entity_id,branch_id,employee_id,
  source_kind,source_id,start_utc,end_utc,gross_seconds,break_seconds,payable_seconds,
  calendar_version_id,created_by)
 values(v_id,p_t,p_e,p_b,p_employee,p_kind,p_source,p_start,p_end,v_gross,v_break,
  case when p_kind='leave' then 0 else v_gross-v_break end,p_calendar_version,p_actor);
 if p_kind='leave' then
  insert into people.work_claim_segments(tenant_id,legal_entity_id,employee_id,claim_id,start_utc,end_utc)
   values(p_t,p_e,p_employee,v_id,p_start,p_end);
 else
  for v in select value from jsonb_array_elements(p_breaks) loop
   v_start:=(v->>'start_utc')::timestamptz;v_end:=(v->>'end_utc')::timestamptz;
   if v_start>v_cursor then
    insert into people.work_claim_segments(tenant_id,legal_entity_id,employee_id,claim_id,start_utc,end_utc)
     values(p_t,p_e,p_employee,v_id,v_cursor,v_start);end if;
   v_cursor:=v_end;
  end loop;
  if v_cursor<p_end then
   insert into people.work_claim_segments(tenant_id,legal_entity_id,employee_id,claim_id,start_utc,end_utc)
    values(p_t,p_e,p_employee,v_id,v_cursor,p_end);end if;
 end if;
 return v_id;
end $$;

create function people.revoke_work_claim(p_t uuid,p_e uuid,p_employee uuid,p_claim uuid)
returns void language plpgsql security definer set search_path='' as $$begin
 if exists(select 1 from people.work_allocations where tenant_id=p_t and legal_entity_id=p_e
  and employee_id=p_employee and claim_id=p_claim and active) then
  raise exception using errcode='55000',message='WORK_ALLOCATION_IMPACT_REQUIRED';end if;
 if exists(select 1 from people.work_input_seals where tenant_id=p_t and legal_entity_id=p_e
  and employee_id=p_employee and claim_id=p_claim) then
  raise exception using errcode='55000',message='PAYROLL_INPUT_SEALED';end if;
 update people.work_claims set active=false,revoked_at=clock_timestamp()
 where tenant_id=p_t and legal_entity_id=p_e and employee_id=p_employee
  and id=p_claim and active;
 if not found then raise exception using errcode='55000',message='WORK_CLAIM_NOT_ACTIVE';end if;
 update people.work_claim_segments set active=false where claim_id=p_claim and active;
end $$;

create function people.allocate_work(p_t uuid,p_e uuid,p_b uuid,p_employee uuid,
 p_claim uuid,p_source_kind text,p_source uuid,p_start timestamptz,p_end timestamptz,p_actor uuid)
returns uuid language plpgsql security definer set search_path='' as $$
declare v_claim people.work_claims%rowtype;v_id uuid:=gen_random_uuid();begin
 if p_source_kind not in ('project','service') or p_source is null or p_actor is null
  or p_start is null or p_end is null or p_end<=p_start
  or extract(epoch from p_start)%1<>0 or extract(epoch from p_end)%1<>0 then
  raise exception using errcode='22023',message='WORK_ALLOCATION_INVALID';end if;
 perform id from people.employees where tenant_id=p_t and legal_entity_id=p_e
  and id=p_employee for update;
 select * into v_claim from people.work_claims where tenant_id=p_t and legal_entity_id=p_e
  and branch_id=p_b and employee_id=p_employee and id=p_claim and active for update;
 if v_claim.id is null or v_claim.source_kind='leave'
  or not exists(select 1 from people.work_claim_segments s where s.claim_id=p_claim and s.active
   and tstzrange(s.start_utc,s.end_utc,'[)') @> tstzrange(p_start,p_end,'[)')) then
  raise exception using errcode='55000',message='WORK_ALLOCATION_SOURCE_INVALID';end if;
 insert into people.work_allocations(id,tenant_id,legal_entity_id,branch_id,
  employee_id,claim_id,source_kind,source_id,start_utc,end_utc,created_by)
 values(v_id,p_t,p_e,p_b,p_employee,p_claim,p_source_kind,p_source,p_start,p_end,p_actor);
 return v_id;
end $$;
create function people.revoke_work_allocation(p_t uuid,p_e uuid,p_employee uuid,p_allocation uuid)
returns void language plpgsql security definer set search_path='' as $$begin
 update people.work_allocations set active=false,revoked_at=clock_timestamp()
 where tenant_id=p_t and legal_entity_id=p_e and employee_id=p_employee
  and id=p_allocation and active;
 if not found then raise exception using errcode='55000',message='WORK_ALLOCATION_NOT_ACTIVE';end if;
end $$;

alter table people.attendance_entries add foreign key(tenant_id,legal_entity_id,employee_id,active_claim_id)
 references people.work_claims(tenant_id,legal_entity_id,employee_id,id);

create function people.attendance_payload(p_id uuid) returns jsonb
language sql stable security definer set search_path='' as $$
 select jsonb_build_object('id',e.id,'tenant_id',e.tenant_id,'legal_entity_id',e.legal_entity_id,
  'branch_id',e.branch_id,'employee_id',e.employee_id,'version',e.version,
  'status',e.status,'submitted_by',e.submitted_by,'decided_by',e.decided_by,
  'active_claim_id',e.active_claim_id,'created_by',e.created_by,'created_at',e.created_at,
  'revision',jsonb_build_object('id',r.id,'version',r.version,
   'calendar_version_id',r.calendar_version_id,'start_local',r.start_local,
   'start_offset_seconds',r.start_offset_seconds,'end_local',r.end_local,
   'end_offset_seconds',r.end_offset_seconds,'start_utc',r.start_utc,'end_utc',r.end_utc,
   'breaks',r.breaks,'gross_seconds',r.gross_seconds,'break_seconds',r.break_seconds,
   'payable_seconds',r.payable_seconds,'raw_start_id',r.raw_start_id,'raw_end_id',r.raw_end_id,
   'reason',r.reason,'supersedes_revision_id',r.supersedes_revision_id,
   'recorded_by',r.recorded_by,'recorded_at',r.recorded_at))
 from people.attendance_entries e join people.attendance_revisions r on r.id=e.current_revision_id
 where e.id=p_id
$$;

create function api.people_attendance_entries(p_tenant_id uuid,p_legal_entity_id uuid,
 p_branch_id uuid,p_employee_id uuid,p_after uuid default null)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare v_items jsonb;begin
 perform people.require_access(p_tenant_id,p_legal_entity_id,p_branch_id,'people.attendance.view');
 if p_employee_id is null or not exists(select 1 from people.employment_assignments
  where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id
   and employee_id=p_employee_id) then
  raise exception using errcode='42501',message='ATTENDANCE_SCOPE_DENIED';end if;
 select coalesce(jsonb_agg(people.attendance_payload(q.id) order by q.id),'[]'::jsonb)
 into v_items from(select id from people.attendance_entries where tenant_id=p_tenant_id
  and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id and employee_id=p_employee_id
  and (p_after is null or id>p_after) order by id limit 51) q;
 return jsonb_build_object('tenant_id',p_tenant_id,'legal_entity_id',p_legal_entity_id,
  'branch_id',p_branch_id,'employee_id',p_employee_id,'items',v_items-50,
  'next_cursor',case when jsonb_array_length(v_items)>50 then v_items->49->>'id' end);
end $$;

create function api.people_attendance_detail(p_tenant_id uuid,p_legal_entity_id uuid,
 p_branch_id uuid,p_entry_id uuid,p_after uuid default null)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare v_entry people.attendance_entries%rowtype;v_items jsonb;begin
 perform people.require_access(p_tenant_id,p_legal_entity_id,p_branch_id,'people.attendance.view');
 select * into v_entry from people.attendance_entries where tenant_id=p_tenant_id
  and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id and id=p_entry_id;
 if not found then raise exception using errcode='P0002',message='ATTENDANCE_NOT_FOUND';end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',q.id,'version',q.version,
  'start_utc',q.start_utc,'end_utc',q.end_utc,'breaks',q.breaks,
  'payable_seconds',q.payable_seconds,'reason',q.reason,
  'supersedes_revision_id',q.supersedes_revision_id,'recorded_by',q.recorded_by,
  'recorded_at',q.recorded_at) order by q.id),'[]'::jsonb) into v_items
 from(select * from people.attendance_revisions where tenant_id=p_tenant_id
  and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id
  and entry_id=p_entry_id and (p_after is null or id>p_after) order by id limit 51) q;
 return jsonb_build_object('tenant_id',p_tenant_id,'legal_entity_id',p_legal_entity_id,
  'branch_id',p_branch_id,'entry',people.attendance_payload(p_entry_id),
  'history',v_items-50,'next_cursor',case when jsonb_array_length(v_items)>50 then v_items->49->>'id' end);
end $$;

create function api.people_attendance_raw_events(p_tenant_id uuid,p_legal_entity_id uuid,
 p_branch_id uuid,p_employee_id uuid,p_after uuid default null)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare v_items jsonb;begin
 perform people.require_access(p_tenant_id,p_legal_entity_id,p_branch_id,'people.attendance.view');
 if p_employee_id is null or not exists(select 1 from people.employment_assignments
  where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id
   and employee_id=p_employee_id) then
  raise exception using errcode='42501',message='ATTENDANCE_SCOPE_DENIED';end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',q.id,'source_system',q.source_system,
  'source_key',q.source_key,'observed_utc',q.observed_utc,'checksum',q.checksum,
  'imported_by',q.imported_by,'imported_at',q.imported_at) order by q.id),'[]'::jsonb)
 into v_items from(select * from people.raw_clock_events where tenant_id=p_tenant_id
  and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id and employee_id=p_employee_id
  and (p_after is null or id>p_after) order by id limit 51) q;
 return jsonb_build_object('tenant_id',p_tenant_id,'legal_entity_id',p_legal_entity_id,
  'branch_id',p_branch_id,'employee_id',p_employee_id,'items',v_items-50,
  'next_cursor',case when jsonb_array_length(v_items)>50 then v_items->49->>'id' end);
end $$;

create function api.people_work_claims(p_tenant_id uuid,p_legal_entity_id uuid,
 p_branch_id uuid,p_employee_id uuid,p_after uuid default null)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare v_items jsonb;begin
 perform people.require_access(p_tenant_id,p_legal_entity_id,p_branch_id,'people.work_claims.view');
 if p_employee_id is null then raise exception using errcode='22023',message='WORK_EMPLOYEE_REQUIRED';end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',q.id,'source_kind',q.source_kind,
  'source_id',q.source_id,'start_utc',q.start_utc,'end_utc',q.end_utc,
  'gross_seconds',q.gross_seconds,'break_seconds',q.break_seconds,
  'payable_seconds',q.payable_seconds,'active',q.active,'revoked_at',q.revoked_at,
  'calendar_version_id',q.calendar_version_id) order by q.id),'[]'::jsonb)
 into v_items from(select * from people.work_claims where tenant_id=p_tenant_id
  and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id and employee_id=p_employee_id
  and (p_after is null or id>p_after) order by id limit 51) q;
 return jsonb_build_object('tenant_id',p_tenant_id,'legal_entity_id',p_legal_entity_id,
  'branch_id',p_branch_id,'employee_id',p_employee_id,'items',v_items-50,
  'next_cursor',case when jsonb_array_length(v_items)>50 then v_items->49->>'id' end);
end $$;

create function api.people_attendance_command(p_tenant_id uuid,p_legal_entity_id uuid,p_branch_id uuid,
 p_command_id uuid,p_idempotency_key uuid,p_client_timestamp timestamptz,
 p_payload jsonb,p_expected_version bigint)
returns jsonb language plpgsql security definer set search_path='' as $$
declare v_actor uuid:=auth.uid();v_action text:=p_payload->>'action';v_id uuid;
 v_employee_id uuid;v_allowed text[];v_cap text;v_hash text;v_replay jsonb;
 v_entry people.attendance_entries%rowtype;v_rev people.attendance_revisions%rowtype;
 v_calendar people.work_calendar_versions%rowtype;v_reason text;v_before jsonb:='{}'::jsonb;
 v_after jsonb;v_start_local timestamp;v_end_local timestamp;
 v_start timestamptz;v_end timestamptz;v_breaks jsonb;v_break_seconds bigint;
 v_gross bigint;v_new_revision uuid;v_claim uuid;v_raw_start uuid;v_raw_end uuid;
 v_start_date date;v_end_date date;v_request uuid:=gen_random_uuid();begin
 if p_command_id is null or p_idempotency_key is null or p_client_timestamp is null
  or p_payload is null or jsonb_typeof(p_payload)<>'object'
  or p_expected_version is null or p_expected_version<0
  or p_expected_version>9007199254740991
  or v_action is null or v_action not in ('raw_import','create','correct','submit','approve','reject','cancel')
  or coalesce(p_payload->>'id','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  or coalesce(p_payload->>'employee_id','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
  raise exception using errcode='22023',message='ATTENDANCE_COMMAND_INVALID';end if;
 v_id:=(p_payload->>'id')::uuid;v_employee_id:=(p_payload->>'employee_id')::uuid;
 v_allowed:=case v_action
  when 'raw_import' then array['action','id','employee_id','source_system','source_key','observed_utc','checksum']
  when 'create' then array['action','id','employee_id','calendar_version_id','start_local',
   'start_offset_seconds','end_local','end_offset_seconds','breaks','raw_start_id','raw_end_id','reason']
  when 'correct' then array['action','id','employee_id','calendar_version_id','start_local',
   'start_offset_seconds','end_local','end_offset_seconds','breaks','raw_start_id','raw_end_id','reason']
  else array['action','id','employee_id','reason'] end;
 if exists(select 1 from jsonb_object_keys(p_payload) k where k<>all(v_allowed)) then
  raise exception using errcode='22023',message='ATTENDANCE_FIELDS_INVALID';end if;
 v_cap:=case when v_action='raw_import' then 'people.attendance.import'
  when v_action in ('approve','reject','cancel') then 'people.attendance.approve'
  else 'people.attendance.manage' end;
 perform people.require_access(p_tenant_id,p_legal_entity_id,p_branch_id,v_cap);
 if coalesce(auth.jwt()->>'aal','aal1')<>'aal2' then
  raise exception using errcode='42501',message='ATTENDANCE_MFA_REQUIRED';end if;
 if not exists(select 1 from people.employment_assignments where tenant_id=p_tenant_id
   and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id and employee_id=v_employee_id) then
  raise exception using errcode='42501',message='ATTENDANCE_SCOPE_DENIED';end if;
 v_hash:=core.wave3_request_hash('people.attendance.'||v_action,p_command_id,
  p_tenant_id,p_legal_entity_id,p_branch_id,p_payload,p_expected_version);
 v_replay:=core.wave3_replay(p_tenant_id,'people.attendance.'||v_action,
  p_command_id,p_idempotency_key,v_hash);
 if v_replay is not null then return v_replay;end if;
 perform id from people.employees where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id
  and id=v_employee_id for update;
 if not found then raise exception using errcode='P0002',message='ATTENDANCE_EMPLOYEE_NOT_FOUND';end if;
 if v_action='raw_import' then
  if p_expected_version<>0 or length(btrim(coalesce(p_payload->>'source_system',''))) not between 1 and 80
   or length(btrim(coalesce(p_payload->>'source_key',''))) not between 1 and 160
   or coalesce(p_payload->>'checksum','') !~ '^[a-f0-9]{64}$'
   or coalesce(p_payload->>'observed_utc','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z$' then
   raise exception using errcode='22023',message='ATTENDANCE_RAW_INVALID';end if;
  insert into people.raw_clock_events(id,tenant_id,legal_entity_id,branch_id,employee_id,
   source_system,source_key,observed_utc,checksum,imported_by)
  values(v_id,p_tenant_id,p_legal_entity_id,p_branch_id,v_employee_id,
   p_payload->>'source_system',p_payload->>'source_key',(p_payload->>'observed_utc')::timestamptz,
   p_payload->>'checksum',v_actor);
  v_after:=jsonb_build_object('id',v_id,'employee_id',v_employee_id,
   'source_system',p_payload->>'source_system','source_key',p_payload->>'source_key',
   'observed_utc',p_payload->>'observed_utc','checksum',p_payload->>'checksum');
 else
  if v_action<>'create' then
   select * into v_entry from people.attendance_entries where tenant_id=p_tenant_id
    and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id and employee_id=v_employee_id
    and id=v_id for update;
   if not found then raise exception using errcode='P0002',message='ATTENDANCE_NOT_FOUND';end if;
   v_before:=people.attendance_payload(v_id);
   perform core.wave3_assert_expected_version(v_entry.version,p_expected_version,v_before);
   select * into v_rev from people.attendance_revisions where id=v_entry.current_revision_id;
  elsif p_expected_version<>0 then
   raise exception using errcode='40001',message='VERSION_CONFLICT';end if;
  v_reason:=btrim(coalesce(p_payload->>'reason',''));
  if length(v_reason) not between 1 and 1000 then
   raise exception using errcode='22023',message='ATTENDANCE_REASON_REQUIRED';end if;
  if v_action in ('create','correct') then
   if v_action='correct' and v_entry.status not in ('draft','rejected','approved') then
    raise exception using errcode='55000',message='ATTENDANCE_STATE_INVALID';end if;
   if coalesce(p_payload->>'start_local','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}$'
    or coalesce(p_payload->>'end_local','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}$'
    or coalesce(p_payload->>'calendar_version_id','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    or coalesce(p_payload->>'start_offset_seconds','') !~ '^-?[0-9]{1,5}$'
    or coalesce(p_payload->>'end_offset_seconds','') !~ '^-?[0-9]{1,5}$' then
    raise exception using errcode='22023',message='ATTENDANCE_BOUNDARY_INVALID';end if;
   select * into v_calendar from people.work_calendar_versions where tenant_id=p_tenant_id
    and legal_entity_id=p_legal_entity_id and id=(p_payload->>'calendar_version_id')::uuid;
   if not found then raise exception using errcode='P0002',message='ATTENDANCE_CALENDAR_NOT_FOUND';end if;
   v_start_local:=(p_payload->>'start_local')::timestamp;
   v_end_local:=(p_payload->>'end_local')::timestamp;
   v_start:=people.resolve_local_instant(v_calendar.timezone,v_start_local,
    (p_payload->>'start_offset_seconds')::integer);
   v_end:=people.resolve_local_instant(v_calendar.timezone,v_end_local,
    (p_payload->>'end_offset_seconds')::integer);
   perform people.work_local_coverage(p_tenant_id,p_legal_entity_id,p_branch_id,v_employee_id,
    v_calendar.id,v_start_local,v_end_local);
   v_breaks:=coalesce(p_payload->'breaks','[]'::jsonb);
   v_break_seconds:=people.work_break_seconds(v_start,v_end,v_breaks);
   v_gross:=extract(epoch from v_end-v_start)::bigint;
   v_raw_start:=nullif(p_payload->>'raw_start_id','')::uuid;
   v_raw_end:=nullif(p_payload->>'raw_end_id','')::uuid;
   if (v_raw_start is null)<>(v_raw_end is null) or
    (v_raw_start is not null and
     (not exists(select 1 from people.raw_clock_events where id=v_raw_start
       and tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id
       and employee_id=v_employee_id and observed_utc=v_start)
      or not exists(select 1 from people.raw_clock_events where id=v_raw_end
       and tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id
       and employee_id=v_employee_id and observed_utc=v_end))) then
    raise exception using errcode='22023',message='ATTENDANCE_RAW_PAIR_INVALID';end if;
   if v_action='correct' and v_entry.active_claim_id is not null then
    perform people.revoke_work_claim(p_tenant_id,p_legal_entity_id,v_employee_id,v_entry.active_claim_id);
   end if;
   v_new_revision:=gen_random_uuid();
   if v_action='create' then
    insert into people.attendance_entries(id,tenant_id,legal_entity_id,branch_id,employee_id,
     current_revision_id,status,created_by)
    values(v_id,p_tenant_id,p_legal_entity_id,p_branch_id,v_employee_id,v_new_revision,'draft',v_actor);
   else
    update people.attendance_entries set version=version+1,current_revision_id=v_new_revision,
     status='draft',submitted_by=null,decided_by=null,active_claim_id=null where id=v_id;
   end if;
   insert into people.attendance_revisions(id,tenant_id,legal_entity_id,branch_id,employee_id,
    entry_id,version,calendar_version_id,start_local,start_offset_seconds,end_local,
    end_offset_seconds,start_utc,end_utc,breaks,gross_seconds,break_seconds,payable_seconds,
    raw_start_id,raw_end_id,reason,supersedes_revision_id,recorded_by)
   values(v_new_revision,p_tenant_id,p_legal_entity_id,p_branch_id,v_employee_id,v_id,
    case when v_action='create' then 1 else v_entry.version+1 end,v_calendar.id,
    v_start_local,(p_payload->>'start_offset_seconds')::integer,
    v_end_local,(p_payload->>'end_offset_seconds')::integer,v_start,v_end,
    v_breaks,v_gross,v_break_seconds,v_gross-v_break_seconds,
    v_raw_start,v_raw_end,v_reason,case when v_action='correct' then v_rev.id end,v_actor);
  elsif v_action='submit' then
   if v_entry.status not in ('draft','rejected') then
    raise exception using errcode='55000',message='ATTENDANCE_STATE_INVALID';end if;
   update people.attendance_entries set version=version+1,status='submitted',
    submitted_by=v_actor,decided_by=null where id=v_id;
  elsif v_action='approve' then
   if v_entry.status<>'submitted' or v_entry.submitted_by=v_actor or v_rev.recorded_by=v_actor then
    raise exception using errcode='55000',message='ATTENDANCE_INDEPENDENT_APPROVAL_REQUIRED';end if;
   perform people.work_local_coverage(p_tenant_id,p_legal_entity_id,p_branch_id,v_employee_id,
    v_rev.calendar_version_id,v_rev.start_local,v_rev.end_local);
   v_start_date:=v_rev.start_local::date;
   v_end_date:=greatest((v_rev.end_local-interval '1 microsecond')::date+1,v_start_date+1);
   perform people.consume_organization(p_tenant_id,p_legal_entity_id,p_branch_id,v_employee_id,
    'attendance',v_rev.id,v_start_date,v_end_date);
   begin
    v_claim:=people.make_work_claim(p_tenant_id,p_legal_entity_id,p_branch_id,v_employee_id,
     'attendance',v_rev.id,v_rev.start_utc,v_rev.end_utc,v_rev.breaks,
     v_rev.calendar_version_id,v_actor);
   exception when exclusion_violation then
    raise exception using errcode='23514',message='WORK_INTERVAL_CONFLICT';
   end;
   update people.attendance_entries set version=version+1,status='approved',
    decided_by=v_actor,active_claim_id=v_claim where id=v_id;
  elsif v_action='reject' then
   if v_entry.status<>'submitted' or v_entry.submitted_by=v_actor or v_rev.recorded_by=v_actor then
    raise exception using errcode='55000',message='ATTENDANCE_INDEPENDENT_APPROVAL_REQUIRED';end if;
   update people.attendance_entries set version=version+1,status='rejected',decided_by=v_actor
    where id=v_id;
  else
   if v_entry.status<>'approved' or v_entry.active_claim_id is null then
    raise exception using errcode='55000',message='ATTENDANCE_STATE_INVALID';end if;
   perform people.revoke_work_claim(p_tenant_id,p_legal_entity_id,v_employee_id,v_entry.active_claim_id);
   update people.attendance_entries set version=version+1,status='cancelled',
    active_claim_id=null,decided_by=v_actor where id=v_id;
  end if;
  select current_revision_id into v_new_revision from people.attendance_entries where id=v_id;
  v_after:=people.attendance_payload(v_id);
  insert into people.attendance_events(tenant_id,legal_entity_id,branch_id,employee_id,
   entry_id,revision_id,action,before_status,after_status,reason,actor_id,command_id)
  values(p_tenant_id,p_legal_entity_id,p_branch_id,v_employee_id,v_id,v_new_revision,
   v_action,v_before->>'status',v_after->>'status',v_reason,v_actor,p_command_id);
 end if;
 return core.wave3_finish_command(p_tenant_id,'people.attendance.'||v_action,p_command_id,
  case when v_action='raw_import' then 'people.raw_clock' else 'people.attendance' end,
  v_id,p_idempotency_key,v_hash,v_before,v_after,p_legal_entity_id,p_branch_id,
  p_source_context=>jsonb_build_object('employee_id',v_employee_id,'action',v_action),
  p_request_id=>v_request);
end $$;

revoke all on function people.work_history_guard(),people.work_break_seconds(timestamptz,timestamptz,jsonb),
 people.work_local_coverage(uuid,uuid,uuid,uuid,uuid,timestamp,timestamp),
 people.make_work_claim(uuid,uuid,uuid,uuid,text,uuid,timestamptz,timestamptz,jsonb,uuid,uuid),
 people.revoke_work_claim(uuid,uuid,uuid,uuid),people.attendance_payload(uuid),
 people.allocate_work(uuid,uuid,uuid,uuid,uuid,text,uuid,timestamptz,timestamptz,uuid),
 people.revoke_work_allocation(uuid,uuid,uuid,uuid),
 api.people_attendance_entries(uuid,uuid,uuid,uuid,uuid),
 api.people_attendance_detail(uuid,uuid,uuid,uuid,uuid),
 api.people_attendance_raw_events(uuid,uuid,uuid,uuid,uuid),
 api.people_work_claims(uuid,uuid,uuid,uuid,uuid),
 api.people_attendance_command(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint)
 from public,anon,authenticated;
grant execute on function api.people_attendance_entries(uuid,uuid,uuid,uuid,uuid),
 api.people_attendance_detail(uuid,uuid,uuid,uuid,uuid),
 api.people_attendance_raw_events(uuid,uuid,uuid,uuid,uuid),
 api.people_work_claims(uuid,uuid,uuid,uuid,uuid),
 api.people_attendance_command(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint)
 to authenticated;
notify pgrst,'reload schema';

-- W4-03B synthetic leave policy, append-only grants/effects and independent decisions.
-- Candidate only; depends on 20260928082234 and reviewed W4-02A prerequisites.
insert into core.permissions(code,module,description,privileged) values
 ('people.leave.view','people','Read scoped leave requests and balance',false),
 ('people.leave.manage','people','Prepare and submit scoped leave requests',true),
 ('people.leave.approve','people','Independently decide and cancel leave',true),
 ('people.leave.policy.manage','people','Publish synthetic leave policy versions',true),
 ('people.leave.adjust','people','Post reasoned synthetic leave grants',true)
on conflict(code) do nothing;

create table people.leave_policies(
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,
 code text not null check(code ~ '^[A-Z0-9][A-Z0-9_-]{0,31}$'),
 name text not null check(length(btrim(name)) between 1 and 160),
 version bigint not null default 1 check(version between 1 and 9007199254740991),
 created_by uuid not null references auth.users(id),created_at timestamptz not null default clock_timestamp(),
 unique(tenant_id,legal_entity_id,id),unique(tenant_id,legal_entity_id,code),
 foreign key(tenant_id,legal_entity_id) references core.legal_entities(tenant_id,id)
);
create index leave_policies_creator_idx on people.leave_policies(created_by);

create table people.leave_policy_versions(
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,
 policy_id uuid not null,version bigint not null check(version between 1 and 9007199254740991),
 start_date date not null,end_date_exclusive date not null,
 unit text not null check(unit in ('hours','days')),
 day_seconds integer not null check(day_seconds between 1 and 86400),
 accrual_frequency text not null check(accrual_frequency in ('monthly','once')),
 accrual_seconds bigint not null check(accrual_seconds between 1 and 9007199254740991),
 carry_cap_seconds bigint not null check(carry_cap_seconds between 0 and 9007199254740991),
 expiry_days integer not null check(expiry_days between 1 and 3650),
 eligible_types text[] not null check(cardinality(eligible_types) between 1 and 4
  and eligible_types <@ array['permanent','fixed_term','casual','contractor']::text[]),
 allow_unpaid boolean not null default false,
 reason text not null check(length(btrim(reason)) between 1 and 1000),
 published_by uuid not null references auth.users(id),published_at timestamptz not null default clock_timestamp(),
 check(end_date_exclusive>start_date and end_date_exclusive-start_date<=1830),
 unique(tenant_id,legal_entity_id,id),unique(tenant_id,legal_entity_id,policy_id,id),
 unique(tenant_id,legal_entity_id,policy_id,version),
 foreign key(tenant_id,legal_entity_id,policy_id) references people.leave_policies(tenant_id,legal_entity_id,id),
 exclude using gist(policy_id extensions.gist_uuid_ops with =,
  daterange(start_date,end_date_exclusive,'[)') with &&)
);
create index leave_versions_scope_idx on people.leave_policy_versions(tenant_id,legal_entity_id,policy_id,id);
create index leave_versions_publisher_idx on people.leave_policy_versions(published_by);

create table people.leave_grants(
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,
 branch_id uuid not null,employee_id uuid not null,
 policy_id uuid not null,policy_version_id uuid not null,
 source_kind text not null check(source_kind in ('accrual','adjustment','carry')),
 source_key text not null check(length(btrim(source_key)) between 1 and 160),
 effective_date date not null,expiry_date date not null,
 seconds bigint not null check(seconds between 1 and 9007199254740991),
 reason text not null check(length(btrim(reason)) between 1 and 1000),
 recorded_by uuid not null references auth.users(id),recorded_at timestamptz not null default clock_timestamp(),
 unique(tenant_id,legal_entity_id,employee_id,policy_id,source_kind,source_key),
 unique(tenant_id,legal_entity_id,employee_id,id),
 unique(tenant_id,legal_entity_id,employee_id,policy_id,id),
 foreign key(tenant_id,legal_entity_id,employee_id) references people.employees(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,legal_entity_id,branch_id) references core.branches(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,legal_entity_id,policy_id) references people.leave_policies(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,legal_entity_id,policy_id,policy_version_id)
  references people.leave_policy_versions(tenant_id,legal_entity_id,policy_id,id),
 check(expiry_date>effective_date)
);
create index leave_grants_balance_idx on people.leave_grants(tenant_id,legal_entity_id,employee_id,policy_id,expiry_date,id);
create index leave_grants_version_idx on people.leave_grants(policy_version_id);
create index leave_grants_actor_idx on people.leave_grants(recorded_by);

create table people.leave_accounts(
 tenant_id uuid not null,legal_entity_id uuid not null,employee_id uuid not null,
 policy_id uuid not null,version bigint not null default 0
  check(version between 0 and 9007199254740991),
 primary key(tenant_id,legal_entity_id,employee_id,policy_id),
 foreign key(tenant_id,legal_entity_id,employee_id) references people.employees(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,legal_entity_id,policy_id) references people.leave_policies(tenant_id,legal_entity_id,id)
);
create index leave_accounts_policy_idx on people.leave_accounts(tenant_id,legal_entity_id,policy_id);

create table people.leave_requests(
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,
 branch_id uuid not null,employee_id uuid not null,
 policy_id uuid not null,policy_version_id uuid not null,calendar_version_id uuid not null,
 version bigint not null default 1 check(version between 1 and 9007199254740991),
 start_local timestamp not null,start_offset_seconds integer not null,
 end_local timestamp not null,end_offset_seconds integer not null,
 start_utc timestamptz not null,end_utc timestamptz not null,
 charge_seconds bigint not null check(charge_seconds between 1 and 129600),
 unpaid_seconds bigint not null default 0 check(unpaid_seconds>=0 and unpaid_seconds<=charge_seconds),
 status text not null check(status in ('draft','submitted','approved','rejected','cancelled')),
 reason text not null check(length(btrim(reason)) between 1 and 1000),
 submitted_by uuid references auth.users(id),decided_by uuid references auth.users(id),
 active_claim_id uuid,
 created_by uuid not null references auth.users(id),created_at timestamptz not null default clock_timestamp(),
 unique(tenant_id,legal_entity_id,id),unique(tenant_id,legal_entity_id,employee_id,id),
 foreign key(tenant_id,legal_entity_id,employee_id) references people.employees(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,legal_entity_id,branch_id) references core.branches(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,legal_entity_id,policy_id) references people.leave_policies(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,legal_entity_id,policy_id,policy_version_id)
  references people.leave_policy_versions(tenant_id,legal_entity_id,policy_id,id),
 foreign key(tenant_id,legal_entity_id,calendar_version_id)
  references people.work_calendar_versions(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,legal_entity_id,employee_id,active_claim_id)
  references people.work_claims(tenant_id,legal_entity_id,employee_id,id),
 check(end_utc>start_utc and end_utc-start_utc<=interval '36 hours')
);
create index leave_requests_scope_idx on people.leave_requests(tenant_id,legal_entity_id,branch_id,employee_id,id);
create index leave_requests_policy_idx on people.leave_requests(policy_version_id);
create index leave_requests_claim_idx on people.leave_requests(active_claim_id);
create index leave_requests_creator_idx on people.leave_requests(created_by);
create index leave_requests_submitter_idx on people.leave_requests(submitted_by);
create index leave_requests_decider_idx on people.leave_requests(decided_by);

create table people.leave_adjustments(
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,
 branch_id uuid not null,employee_id uuid not null,policy_id uuid not null,
 policy_version_id uuid not null,source_key text not null check(length(btrim(source_key)) between 1 and 160),
 effective_date date not null,seconds bigint not null
  check(seconds<>0 and seconds between -9007199254740991 and 9007199254740991),
 reason text not null check(length(btrim(reason)) between 1 and 1000),
 recorded_by uuid not null references auth.users(id),recorded_at timestamptz not null default clock_timestamp(),
 unique(tenant_id,legal_entity_id,employee_id,policy_id,source_key),
 unique(tenant_id,legal_entity_id,employee_id,policy_id,id),
 foreign key(tenant_id,legal_entity_id,employee_id) references people.employees(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,legal_entity_id,branch_id) references core.branches(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,legal_entity_id,policy_id,policy_version_id)
  references people.leave_policy_versions(tenant_id,legal_entity_id,policy_id,id)
);
create index leave_adjustments_scope_idx on people.leave_adjustments(tenant_id,legal_entity_id,branch_id,employee_id,id);
create index leave_adjustments_actor_idx on people.leave_adjustments(recorded_by);

create table people.leave_carry_events(
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,
 branch_id uuid not null,employee_id uuid not null,policy_id uuid not null,
 prior_version_id uuid not null,new_version_id uuid not null,
 boundary_date date not null,source_seconds bigint not null check(source_seconds>=0),
 carried_seconds bigint not null check(carried_seconds>=0 and carried_seconds<=source_seconds),
 reason text not null check(length(btrim(reason)) between 1 and 1000),
 recorded_by uuid not null references auth.users(id),recorded_at timestamptz not null default clock_timestamp(),
 unique(tenant_id,legal_entity_id,employee_id,policy_id,boundary_date),
 foreign key(tenant_id,legal_entity_id,employee_id) references people.employees(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,legal_entity_id,branch_id) references core.branches(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,legal_entity_id,policy_id,prior_version_id)
  references people.leave_policy_versions(tenant_id,legal_entity_id,policy_id,id),
 foreign key(tenant_id,legal_entity_id,policy_id,new_version_id)
  references people.leave_policy_versions(tenant_id,legal_entity_id,policy_id,id)
);
create index leave_carry_scope_idx on people.leave_carry_events(tenant_id,legal_entity_id,branch_id,employee_id,id);
create index leave_carry_prior_idx on people.leave_carry_events(prior_version_id);
create index leave_carry_new_idx on people.leave_carry_events(new_version_id);
create index leave_carry_actor_idx on people.leave_carry_events(recorded_by);

create table people.leave_effects(
 id uuid primary key default gen_random_uuid(),tenant_id uuid not null,legal_entity_id uuid not null,
 employee_id uuid not null,policy_id uuid not null,grant_id uuid not null,
 request_id uuid,adjustment_id uuid,effective_date date not null,
 seconds bigint not null check(seconds<>0 and seconds between -9007199254740991 and 9007199254740991),
 reversal_of uuid unique,recorded_by uuid not null references auth.users(id),
 recorded_at timestamptz not null default clock_timestamp(),
 unique(tenant_id,legal_entity_id,employee_id,id),
 foreign key(tenant_id,legal_entity_id,employee_id,policy_id,grant_id)
  references people.leave_grants(tenant_id,legal_entity_id,employee_id,policy_id,id),
 foreign key(tenant_id,legal_entity_id,employee_id,request_id)
  references people.leave_requests(tenant_id,legal_entity_id,employee_id,id),
 foreign key(tenant_id,legal_entity_id,employee_id,policy_id,adjustment_id)
  references people.leave_adjustments(tenant_id,legal_entity_id,employee_id,policy_id,id),
 foreign key(tenant_id,legal_entity_id,employee_id,reversal_of)
  references people.leave_effects(tenant_id,legal_entity_id,employee_id,id),
 check((request_id is null)<>(adjustment_id is null)),
 check((reversal_of is null and seconds<0) or (reversal_of is not null and seconds>0))
);
create index leave_effects_grant_idx on people.leave_effects(tenant_id,legal_entity_id,employee_id,grant_id);
create index leave_effects_request_idx on people.leave_effects(tenant_id,legal_entity_id,employee_id,request_id);
create index leave_effects_actor_idx on people.leave_effects(recorded_by);

create table people.leave_events(
 id uuid primary key default gen_random_uuid(),tenant_id uuid not null,legal_entity_id uuid not null,
 branch_id uuid not null,employee_id uuid not null,request_id uuid not null,
 action text not null check(action in ('create','submit','approve','reject','cancel')),
 before_status text,after_status text not null,
 reason text not null check(length(btrim(reason)) between 1 and 1000),
 actor_id uuid not null references auth.users(id),recorded_at timestamptz not null default clock_timestamp(),
 command_id uuid not null,unique(tenant_id,legal_entity_id,command_id),
 foreign key(tenant_id,legal_entity_id,employee_id,request_id)
  references people.leave_requests(tenant_id,legal_entity_id,employee_id,id),
 foreign key(tenant_id,legal_entity_id,branch_id) references core.branches(tenant_id,legal_entity_id,id)
);
create index leave_events_request_idx on people.leave_events(tenant_id,legal_entity_id,branch_id,request_id,id);
create index leave_events_actor_idx on people.leave_events(actor_id);

do $$declare v_table regclass;begin
 foreach v_table in array array[
  'people.leave_policies'::regclass,'people.leave_policy_versions'::regclass,
  'people.leave_grants'::regclass,'people.leave_accounts'::regclass,
  'people.leave_requests'::regclass,
  'people.leave_adjustments'::regclass,'people.leave_carry_events'::regclass,
  'people.leave_effects'::regclass,
  'people.leave_events'::regclass] loop
  execute format('alter table %s enable row level security',v_table);
  execute format('alter table %s force row level security',v_table);
  execute format('revoke all on %s from public,anon,authenticated',v_table);
 end loop;
end $$;

create function people.leave_history_guard() returns trigger language plpgsql set search_path='' as $$begin
 raise exception using errcode='55000',message='LEAVE_HISTORY_IMMUTABLE';
end $$;
create trigger leave_version_immutable before update or delete on people.leave_policy_versions
 for each row execute function people.leave_history_guard();
create trigger leave_grant_immutable before update or delete on people.leave_grants
 for each row execute function people.leave_history_guard();
create trigger leave_adjustment_immutable before update or delete on people.leave_adjustments
 for each row execute function people.leave_history_guard();
create trigger leave_carry_immutable before update or delete on people.leave_carry_events
 for each row execute function people.leave_history_guard();
create trigger leave_effect_immutable before update or delete on people.leave_effects
 for each row execute function people.leave_history_guard();
create trigger leave_event_immutable before update or delete on people.leave_events
 for each row execute function people.leave_history_guard();
create function people.leave_effect_insert_guard() returns trigger
language plpgsql security definer set search_path='' as $$
declare v_original people.leave_effects%rowtype;begin
 if new.reversal_of is not null then
  select * into v_original from people.leave_effects where id=new.reversal_of;
  if v_original.id is null or v_original.tenant_id<>new.tenant_id
   or v_original.legal_entity_id<>new.legal_entity_id
   or v_original.employee_id<>new.employee_id or v_original.policy_id<>new.policy_id
   or v_original.grant_id<>new.grant_id or v_original.request_id is distinct from new.request_id
   or v_original.seconds>=0 or v_original.reversal_of is not null
   or new.seconds<>-v_original.seconds then
   raise exception using errcode='23514',message='LEAVE_REVERSAL_MISMATCH';end if;
 end if;
 return new;
end $$;
create trigger leave_effect_exact_reversal before insert on people.leave_effects
 for each row execute function people.leave_effect_insert_guard();

create function people.leave_slot_charge(p_t uuid,p_e uuid,p_b uuid,p_employee uuid,
 p_policy_version uuid,p_calendar_version uuid,p_start_local timestamp,p_end_local timestamp,
 p_start_utc timestamptz,p_end_utc timestamptz)
returns bigint language plpgsql stable security definer set search_path='' as $$
declare v_policy people.leave_policy_versions%rowtype;v_calendar people.work_calendar_versions%rowtype;
 v_slot jsonb;v_count integer;v_slot_start timestamp;v_slot_end timestamp;v_day date;
 v_type text;v_charge bigint;begin
 select * into v_policy from people.leave_policy_versions where tenant_id=p_t
  and legal_entity_id=p_e and id=p_policy_version;
 select * into v_calendar from people.work_calendar_versions where tenant_id=p_t
  and legal_entity_id=p_e and id=p_calendar_version;
 if v_policy.id is null or v_calendar.id is null or p_start_local is null or p_end_local is null
  or p_end_local<=p_start_local or p_end_utc<=p_start_utc
  or p_end_utc-p_start_utc>interval '36 hours' then
  raise exception using errcode='22023',message='LEAVE_SLOT_INVALID';end if;
 v_day:=p_start_local::date;
 if not daterange(v_policy.start_date,v_policy.end_date_exclusive,'[)') @>
  daterange(v_day,(p_end_local-interval '1 microsecond')::date+1,'[)') then
  raise exception using errcode='55000',message='LEAVE_POLICY_NOT_EFFECTIVE';end if;
 perform people.work_local_coverage(p_t,p_e,p_b,p_employee,p_calendar_version,p_start_local,p_end_local);
 if exists(select 1 from jsonb_array_elements(v_calendar.date_overrides) o
  where o->>'date'=v_day::text and (o->>'is_working_day')::boolean=false) then
  raise exception using errcode='55000',message='LEAVE_NONWORKING_DAY';end if;
 select count(*),jsonb_agg(value)->0 into v_count,v_slot
 from jsonb_array_elements(v_calendar.weekly_intervals) value
 where (value->>'day_of_week')::integer=extract(isodow from v_day)::integer;
 if v_count<>1 then
  raise exception using errcode='55000',message='LEAVE_SINGLE_WORK_SLOT_REQUIRED';end if;
 v_slot_start:=v_day::timestamp+(v_slot->>'start_minute')::integer*interval '1 minute';
 v_slot_end:=v_day::timestamp+(v_slot->>'end_day_offset')::integer*interval '1 day'
  +(v_slot->>'end_minute')::integer*interval '1 minute';
 if p_start_local<v_slot_start or p_end_local>v_slot_end then
  raise exception using errcode='22023',message='LEAVE_OUTSIDE_WORK_SLOT';end if;
 select a.employment_type into v_type from people.employment_assignments a
 where a.tenant_id=p_t and a.legal_entity_id=p_e and a.branch_id=p_b
  and a.employee_id=p_employee and daterange(a.start_date,a.end_date_exclusive,'[)') @> v_day;
 if v_type is null or not(v_type=any(v_policy.eligible_types)) then
  raise exception using errcode='42501',message='LEAVE_NOT_ELIGIBLE';end if;
 if v_policy.unit='days' then
  if p_start_local<>v_slot_start or p_end_local<>v_slot_end then
   raise exception using errcode='22023',message='LEAVE_FULL_DAY_REQUIRED';end if;
  v_charge:=v_policy.day_seconds;
 else v_charge:=extract(epoch from p_end_utc-p_start_utc)::bigint;end if;
 if v_charge<1 or v_charge>129600 then
  raise exception using errcode='22023',message='LEAVE_CHARGE_INVALID';end if;
 return v_charge;
end $$;

create function people.leave_policy_payload(p_id uuid) returns jsonb
language sql stable security definer set search_path='' as $$
 select jsonb_build_object('id',p.id,'code',p.code,'name',p.name,'version',p.version,
  'versions',coalesce((select jsonb_agg(jsonb_build_object('id',v.id,'version',v.version,
   'start_date',v.start_date,'end_date_exclusive',v.end_date_exclusive,
   'unit',v.unit,'day_seconds',v.day_seconds,'accrual_frequency',v.accrual_frequency,
   'accrual_seconds',v.accrual_seconds,'carry_cap_seconds',v.carry_cap_seconds,
   'expiry_days',v.expiry_days,'eligible_types',to_jsonb(v.eligible_types),
   'allow_unpaid',v.allow_unpaid,'reason',v.reason,'published_by',v.published_by,
   'published_at',v.published_at) order by v.version)
   from (select * from people.leave_policy_versions
    where policy_id=p.id order by version desc limit 1) v),'[]'::jsonb))
 from people.leave_policies p where p.id=p_id
$$;

create function api.people_leave_policies(p_tenant_id uuid,p_legal_entity_id uuid,
 p_branch_id uuid,p_after uuid default null) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare v_items jsonb;begin
 perform people.require_access(p_tenant_id,p_legal_entity_id,p_branch_id,'people.leave.view');
 select coalesce(jsonb_agg(people.leave_policy_payload(q.id) order by q.id),'[]'::jsonb)
 into v_items from(select id from people.leave_policies where tenant_id=p_tenant_id
  and legal_entity_id=p_legal_entity_id and (p_after is null or id>p_after)
  order by id limit 51) q;
 return jsonb_build_object('tenant_id',p_tenant_id,'legal_entity_id',p_legal_entity_id,
  'branch_id',p_branch_id,'items',v_items-50,
  'next_cursor',case when jsonb_array_length(v_items)>50 then v_items->49->>'id' end);
end $$;

create function api.people_leave_policy_versions(p_tenant_id uuid,p_legal_entity_id uuid,
 p_branch_id uuid,p_policy_id uuid,p_after uuid default null) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare v_items jsonb;begin
 perform people.require_access(p_tenant_id,p_legal_entity_id,p_branch_id,'people.leave.view');
 if p_policy_id is null or not exists(select 1 from people.leave_policies
  where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and id=p_policy_id) then
  raise exception using errcode='P0002',message='LEAVE_POLICY_NOT_FOUND';end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',q.id,'version',q.version,
  'start_date',q.start_date,'end_date_exclusive',q.end_date_exclusive,
  'unit',q.unit,'day_seconds',q.day_seconds,'accrual_frequency',q.accrual_frequency,
  'accrual_seconds',q.accrual_seconds,'carry_cap_seconds',q.carry_cap_seconds,
  'expiry_days',q.expiry_days,'eligible_types',to_jsonb(q.eligible_types),
  'allow_unpaid',q.allow_unpaid,'reason',q.reason,'published_by',q.published_by,
  'published_at',q.published_at) order by q.id),'[]'::jsonb) into v_items
 from(select * from people.leave_policy_versions where tenant_id=p_tenant_id
  and legal_entity_id=p_legal_entity_id and policy_id=p_policy_id
  and (p_after is null or id>p_after) order by id limit 51) q;
 return jsonb_build_object('tenant_id',p_tenant_id,'legal_entity_id',p_legal_entity_id,
  'branch_id',p_branch_id,'policy_id',p_policy_id,'items',v_items-50,
  'next_cursor',case when jsonb_array_length(v_items)>50 then v_items->49->>'id' end);
end $$;

create function api.people_leave_policy_for_version(p_tenant_id uuid,p_legal_entity_id uuid,
 p_branch_id uuid,p_version_id uuid) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare v_policy uuid;begin
 perform people.require_access(p_tenant_id,p_legal_entity_id,p_branch_id,'people.leave.view');
 select policy_id into v_policy from people.leave_policy_versions where tenant_id=p_tenant_id
  and legal_entity_id=p_legal_entity_id and id=p_version_id;
 if not found then raise exception using errcode='P0002',message='LEAVE_POLICY_VERSION_NOT_FOUND';end if;
 return jsonb_build_object('tenant_id',p_tenant_id,'legal_entity_id',p_legal_entity_id,
  'branch_id',p_branch_id,'policy_version_id',p_version_id,'policy',people.leave_policy_payload(v_policy));
end $$;

create function api.people_leave_policy_command(p_tenant_id uuid,p_legal_entity_id uuid,
 p_branch_id uuid,p_command_id uuid,p_idempotency_key uuid,p_client_timestamp timestamptz,
 p_payload jsonb,p_expected_version bigint) returns jsonb
language plpgsql security definer set search_path='' as $$
declare v_action text:=p_payload->>'action';v_actor uuid:=auth.uid();v_id uuid;v_version_id uuid;
 v_policy people.leave_policies%rowtype;v_before jsonb:='{}'::jsonb;v_after jsonb;
 v_hash text;v_replay jsonb;v_start date;v_end date;v_types text[];
 v_request uuid:=gen_random_uuid();begin
 if true=any(array[
  p_command_id is null,p_idempotency_key is null,p_client_timestamp is null,
  coalesce(jsonb_typeof(p_payload),'null')<>'object',
  v_action is null or v_action not in ('create','publish'),
  coalesce(p_payload->>'id','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$',
  coalesce(p_payload->>'version_id','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$',
  coalesce(p_payload->>'start_date','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$',
  coalesce(p_payload->>'end_date_exclusive','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$',
  coalesce(jsonb_typeof(p_payload->'eligible_types'),'null')<>'array',
  p_expected_version is null]) then
  raise exception using errcode='22023',message='LEAVE_POLICY_INVALID';end if;
 if exists(select 1 from jsonb_object_keys(p_payload) k where k<>all(
  case when v_action='create' then array['action','id','version_id','code','name',
   'start_date','end_date_exclusive','unit','day_seconds','accrual_frequency',
   'accrual_seconds','carry_cap_seconds','expiry_days','eligible_types','allow_unpaid','reason']
  else array['action','id','version_id','start_date','end_date_exclusive','unit',
   'day_seconds','accrual_frequency','accrual_seconds','carry_cap_seconds','expiry_days',
   'eligible_types','allow_unpaid','reason'] end)) then
  raise exception using errcode='22023',message='LEAVE_POLICY_FIELDS_INVALID';end if;
 perform people.require_access(p_tenant_id,p_legal_entity_id,p_branch_id,'people.leave.policy.manage');
 perform core.require_permission(p_tenant_id,'people.leave.policy.manage',p_legal_entity_id,null);
 if coalesce(auth.jwt()->>'aal','aal1')<>'aal2' then
  raise exception using errcode='42501',message='LEAVE_MFA_REQUIRED';end if;
 v_id:=(p_payload->>'id')::uuid;v_version_id:=(p_payload->>'version_id')::uuid;
 v_hash:=core.wave3_request_hash('people.leave.policy.'||v_action,p_command_id,
  p_tenant_id,p_legal_entity_id,p_branch_id,p_payload,p_expected_version);
 v_replay:=core.wave3_replay(p_tenant_id,'people.leave.policy.'||v_action,
  p_command_id,p_idempotency_key,v_hash);
 if v_replay is not null then return v_replay;end if;
 v_start:=(p_payload->>'start_date')::date;v_end:=(p_payload->>'end_date_exclusive')::date;
 if not isfinite(v_start) or not isfinite(v_end) or v_end<=v_start
  or v_end-v_start>1830 or length(btrim(coalesce(p_payload->>'reason',''))) not between 1 and 1000
  or p_payload->>'unit' not in ('hours','days')
  or p_payload->>'accrual_frequency' not in ('monthly','once')
  or coalesce(p_payload->>'day_seconds','') !~ '^[0-9]{1,5}$'
  or coalesce(p_payload->>'accrual_seconds','') !~ '^[0-9]{1,16}$'
  or coalesce(p_payload->>'carry_cap_seconds','') !~ '^[0-9]{1,16}$'
  or coalesce(p_payload->>'expiry_days','') !~ '^[0-9]{1,4}$'
  or jsonb_array_length(p_payload->'eligible_types') not between 1 and 4
  or coalesce(jsonb_typeof(p_payload->'allow_unpaid'),'null')<>'boolean' then
  raise exception using errcode='22023',message='LEAVE_POLICY_INVALID';end if;
 select array_agg(x order by x) into v_types
 from jsonb_array_elements_text(p_payload->'eligible_types') x;
 if v_types is null or cardinality(v_types)<>cardinality(array(select distinct unnest(v_types)))
  or not(v_types <@ array['permanent','fixed_term','casual','contractor']::text[])
  or (p_payload->>'day_seconds')::integer not between 1 and 86400
  or (p_payload->>'accrual_seconds')::bigint not between 1 and 9007199254740991
  or (p_payload->>'carry_cap_seconds')::bigint not between 0 and 9007199254740991
  or (p_payload->>'expiry_days')::integer not between 1 and 3650 then
  raise exception using errcode='22023',message='LEAVE_POLICY_INVALID';end if;
 perform pg_advisory_xact_lock(hashtextextended('people.leave.policy:'||p_tenant_id||':'||p_legal_entity_id,0));
 if v_action='create' then
  if p_expected_version<>0 or coalesce(p_payload->>'code','') !~ '^[A-Z0-9][A-Z0-9_-]{0,31}$'
   or length(btrim(coalesce(p_payload->>'name',''))) not between 1 and 160 then
   raise exception using errcode='22023',message='LEAVE_POLICY_INVALID';end if;
  insert into people.leave_policies(id,tenant_id,legal_entity_id,code,name,created_by)
   values(v_id,p_tenant_id,p_legal_entity_id,p_payload->>'code',p_payload->>'name',v_actor);
 else
  select * into v_policy from people.leave_policies where tenant_id=p_tenant_id
   and legal_entity_id=p_legal_entity_id and id=v_id for update;
  if not found then raise exception using errcode='P0002',message='LEAVE_POLICY_NOT_FOUND';end if;
  v_before:=people.leave_policy_payload(v_id);
  perform core.wave3_assert_expected_version(v_policy.version,p_expected_version,v_before);
  update people.leave_policies set version=version+1 where id=v_id;
 end if;
 insert into people.leave_policy_versions(id,tenant_id,legal_entity_id,policy_id,version,
  start_date,end_date_exclusive,unit,day_seconds,accrual_frequency,accrual_seconds,
  carry_cap_seconds,expiry_days,eligible_types,allow_unpaid,reason,published_by)
 values(v_version_id,p_tenant_id,p_legal_entity_id,v_id,
  case when v_action='create' then 1 else v_policy.version+1 end,
  v_start,v_end,p_payload->>'unit',(p_payload->>'day_seconds')::integer,
  p_payload->>'accrual_frequency',(p_payload->>'accrual_seconds')::bigint,
  (p_payload->>'carry_cap_seconds')::bigint,(p_payload->>'expiry_days')::integer,
  v_types,(p_payload->>'allow_unpaid')::boolean,btrim(p_payload->>'reason'),v_actor);
 v_after:=people.leave_policy_payload(v_id);
 return core.wave3_finish_command(p_tenant_id,'people.leave.policy.'||v_action,p_command_id,
  'people.leave.policy',v_id,p_idempotency_key,v_hash,v_before,v_after,
  p_legal_entity_id,p_branch_id,p_request_id=>v_request);
end $$;

create function people.leave_available(p_t uuid,p_e uuid,p_employee uuid,p_policy uuid,
 p_on date,p_recorded_before timestamptz default null)
returns bigint language plpgsql stable security definer set search_path='' as $$
declare v_total numeric;begin
 select coalesce(sum(g.seconds+coalesce((select sum(x.seconds) from people.leave_effects x
   where x.tenant_id=p_t and x.legal_entity_id=p_e and x.employee_id=p_employee
    and x.policy_id=p_policy and x.grant_id=g.id
    and x.effective_date<=p_on and (p_recorded_before is null or x.recorded_at<=p_recorded_before)),0)),0)
 into v_total from people.leave_grants g where g.tenant_id=p_t and g.legal_entity_id=p_e
  and g.employee_id=p_employee and g.policy_id=p_policy
  and g.effective_date<=p_on and g.expiry_date>p_on
  and (p_recorded_before is null or g.recorded_at<=p_recorded_before);
 if v_total<0 or v_total>9007199254740991 then
  raise exception using errcode='23514',message='LEAVE_BALANCE_INVALID';end if;
 return v_total::bigint;
end $$;

create function people.allocate_leave(p_t uuid,p_e uuid,p_employee uuid,p_policy uuid,
 p_request uuid,p_adjustment uuid,p_valid_on date,p_effective date,p_seconds bigint,
 p_actor uuid,p_allow_partial boolean default false)
returns bigint language plpgsql security definer set search_path='' as $$
declare v_grant people.leave_grants%rowtype;v_available numeric;v_take bigint;
 v_remaining bigint:=p_seconds;begin
 if (p_request is null)=(p_adjustment is null) or p_seconds is null or p_seconds<1
  or p_seconds>9007199254740991 or p_actor is null or p_valid_on is null
  or p_effective is null then
  raise exception using errcode='22023',message='LEAVE_ALLOCATION_INVALID';end if;
 -- The caller owns the employee row lock; grant row locks document and reinforce
 -- the same deterministic expiry/effective/ID allocation order.
 for v_grant in select * from people.leave_grants where tenant_id=p_t and legal_entity_id=p_e
  and employee_id=p_employee and policy_id=p_policy and effective_date<=p_valid_on
  and expiry_date>p_valid_on order by expiry_date,effective_date,id for update loop
  select v_grant.seconds+coalesce(sum(x.seconds),0) into v_available
   from people.leave_effects x where x.tenant_id=p_t and x.legal_entity_id=p_e
    and x.employee_id=p_employee and x.policy_id=p_policy and x.grant_id=v_grant.id;
  if v_available<0 or v_available>v_grant.seconds then
   raise exception using errcode='23514',message='LEAVE_GRANT_BALANCE_INVALID';end if;
  if v_available=0 then continue;end if;
  v_take:=least(v_remaining,v_available)::bigint;
  insert into people.leave_effects(tenant_id,legal_entity_id,employee_id,policy_id,grant_id,
   request_id,adjustment_id,effective_date,seconds,recorded_by)
  values(p_t,p_e,p_employee,p_policy,v_grant.id,p_request,p_adjustment,p_effective,-v_take,p_actor);
  v_remaining:=v_remaining-v_take;
  if v_remaining=0 then exit;end if;
 end loop;
 if v_remaining>0 and not p_allow_partial then
  raise exception using errcode='23514',message='LEAVE_BALANCE_INSUFFICIENT';end if;
 return v_remaining;
end $$;

create function api.people_leave_balance(p_tenant_id uuid,p_legal_entity_id uuid,
 p_branch_id uuid,p_employee_id uuid,p_policy_id uuid,p_as_of date,
 p_recorded_before timestamptz default null,p_after uuid default null)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare v_items jsonb;v_total bigint;begin
 perform people.require_access(p_tenant_id,p_legal_entity_id,p_branch_id,'people.leave.view');
 if p_employee_id is null or p_policy_id is null or p_as_of is null or not isfinite(p_as_of)
  or not exists(select 1 from people.employment_assignments where tenant_id=p_tenant_id
   and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id
   and employee_id=p_employee_id) then
  raise exception using errcode='42501',message='LEAVE_SCOPE_DENIED';end if;
 v_total:=people.leave_available(p_tenant_id,p_legal_entity_id,p_employee_id,p_policy_id,
  p_as_of,p_recorded_before);
 select coalesce(jsonb_agg(jsonb_build_object('id',q.id,'source_kind',q.source_kind,
  'source_key',q.source_key,'effective_date',q.effective_date,'expiry_date',q.expiry_date,
  'seconds',q.seconds,'remaining_seconds',q.remaining_seconds,
  'policy_version_id',q.policy_version_id,'recorded_at',q.recorded_at) order by q.id),'[]'::jsonb)
 into v_items from(select g.*,
  g.seconds+coalesce((select sum(x.seconds) from people.leave_effects x
   where x.grant_id=g.id and x.effective_date<=p_as_of
    and (p_recorded_before is null or x.recorded_at<=p_recorded_before)),0) remaining_seconds
  from people.leave_grants g where g.tenant_id=p_tenant_id and g.legal_entity_id=p_legal_entity_id
   and g.employee_id=p_employee_id and g.policy_id=p_policy_id
   and (p_after is null or g.id>p_after) and
   (p_recorded_before is null or g.recorded_at<=p_recorded_before)
  order by g.id limit 51) q;
 return jsonb_build_object('tenant_id',p_tenant_id,'legal_entity_id',p_legal_entity_id,
  'branch_id',p_branch_id,'employee_id',p_employee_id,'policy_id',p_policy_id,
  'as_of',p_as_of,'recorded_before',p_recorded_before,'available_seconds',v_total,
  'account_version',coalesce((select version from people.leave_accounts where
   tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id and employee_id=p_employee_id
   and policy_id=p_policy_id),0),
  'grants',v_items-50,'next_cursor',case when jsonb_array_length(v_items)>50 then v_items->49->>'id' end);
end $$;

create function api.people_leave_grant_command(p_tenant_id uuid,p_legal_entity_id uuid,
 p_branch_id uuid,p_command_id uuid,p_idempotency_key uuid,p_client_timestamp timestamptz,
 p_payload jsonb,p_expected_version bigint) returns jsonb
language plpgsql security definer set search_path='' as $$
declare v_action text:=p_payload->>'action';v_actor uuid:=auth.uid();v_id uuid;v_employee uuid;
 v_policy people.leave_policy_versions%rowtype;v_prior people.leave_policy_versions%rowtype;
 v_account people.leave_accounts%rowtype;
 v_hash text;v_replay jsonb;v_effective date;v_today date;v_type text;
 v_amount bigint;v_source_amount numeric;v_source text;v_before jsonb;v_after jsonb;
 v_request uuid:=gen_random_uuid();begin
 if p_command_id is null or p_idempotency_key is null or p_client_timestamp is null
  or coalesce(jsonb_typeof(p_payload),'null')<>'object'
  or v_action is null or v_action not in ('accrue','adjust','carry')
  or coalesce(p_payload->>'id','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  or coalesce(p_payload->>'employee_id','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  or coalesce(p_payload->>'policy_version_id','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  or p_expected_version is null then
  raise exception using errcode='22023',message='LEAVE_GRANT_INVALID';end if;
 if exists(select 1 from jsonb_object_keys(p_payload) k where k<>all(
  case when v_action='accrue' then array['action','id','employee_id','policy_version_id',
   'period_start','reason']
  when v_action='carry' then array['action','id','employee_id','policy_version_id',
   'prior_version_id','boundary_date','reason']
  else array['action','id','employee_id','policy_version_id',
   'effective_date','source_key','seconds','reason'] end)) then
  raise exception using errcode='22023',message='LEAVE_GRANT_FIELDS_INVALID';end if;
 perform people.require_access(p_tenant_id,p_legal_entity_id,p_branch_id,
  case when v_action in ('accrue','carry') then 'people.leave.policy.manage'
   else 'people.leave.adjust' end);
 if coalesce(auth.jwt()->>'aal','aal1')<>'aal2' then
  raise exception using errcode='42501',message='LEAVE_MFA_REQUIRED';end if;
 v_id:=(p_payload->>'id')::uuid;v_employee:=(p_payload->>'employee_id')::uuid;
 select * into v_policy from people.leave_policy_versions where tenant_id=p_tenant_id
  and legal_entity_id=p_legal_entity_id and id=(p_payload->>'policy_version_id')::uuid;
 if not found then raise exception using errcode='P0002',message='LEAVE_POLICY_NOT_FOUND';end if;
 if not exists(select 1 from people.employment_assignments where tenant_id=p_tenant_id
  and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id
  and employee_id=v_employee) then
  raise exception using errcode='42501',message='LEAVE_SCOPE_DENIED';end if;
 v_hash:=core.wave3_request_hash('people.leave.grant.'||v_action,p_command_id,
  p_tenant_id,p_legal_entity_id,p_branch_id,p_payload,p_expected_version);
 v_replay:=core.wave3_replay(p_tenant_id,'people.leave.grant.'||v_action,
  p_command_id,p_idempotency_key,v_hash);
 if v_replay is not null then return v_replay;end if;
 perform id from people.employees where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id
  and id=v_employee for update;
 if not found then raise exception using errcode='P0002',message='LEAVE_EMPLOYEE_NOT_FOUND';end if;
 insert into people.leave_accounts(tenant_id,legal_entity_id,employee_id,policy_id)
 values(p_tenant_id,p_legal_entity_id,v_employee,v_policy.policy_id) on conflict do nothing;
 select * into v_account from people.leave_accounts where tenant_id=p_tenant_id
  and legal_entity_id=p_legal_entity_id and employee_id=v_employee
  and policy_id=v_policy.policy_id for update;
 perform core.wave3_assert_expected_version(v_account.version,p_expected_version,
  jsonb_build_object('account_version',v_account.version));
 select timezone into v_type from core.legal_entities where tenant_id=p_tenant_id
  and id=p_legal_entity_id;
 v_today:=(now() at time zone v_type)::date;
 if v_action='accrue' then
  if coalesce(p_payload->>'period_start','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then
   raise exception using errcode='22023',message='LEAVE_ACCRUAL_PERIOD_INVALID';end if;
  v_effective:=(p_payload->>'period_start')::date;
  if (v_policy.accrual_frequency='monthly' and extract(day from v_effective)<>1)
   or (v_policy.accrual_frequency='once' and v_effective<>v_policy.start_date)
   or v_effective>=v_policy.end_date_exclusive
   or v_effective+interval '1 month'<=v_policy.start_date then
   raise exception using errcode='22023',message='LEAVE_ACCRUAL_PERIOD_INVALID';end if;
  v_source:=to_char(v_effective,'YYYY-MM');
  v_effective:=greatest(v_effective,v_policy.start_date);
  v_amount:=v_policy.accrual_seconds;
 elsif v_action='carry' then
  if coalesce(p_payload->>'prior_version_id','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
   or coalesce(p_payload->>'boundary_date','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then
   raise exception using errcode='22023',message='LEAVE_CARRY_INVALID';end if;
  select * into v_prior from people.leave_policy_versions where tenant_id=p_tenant_id
   and legal_entity_id=p_legal_entity_id and policy_id=v_policy.policy_id
   and id=(p_payload->>'prior_version_id')::uuid;
  v_effective:=(p_payload->>'boundary_date')::date;
  if v_prior.id is null or v_prior.id=v_policy.id
   or v_prior.end_date_exclusive<>v_effective or v_policy.start_date<>v_effective then
   raise exception using errcode='22023',message='LEAVE_CARRY_INVALID';end if;
  v_source:='carry:'||v_prior.id::text||':'||v_effective::text;
  select coalesce(sum(g.seconds+coalesce((select sum(x.seconds) from people.leave_effects x
   where x.tenant_id=p_tenant_id and x.legal_entity_id=p_legal_entity_id
    and x.employee_id=v_employee and x.policy_id=v_policy.policy_id and x.grant_id=g.id),0)),0)
  into v_source_amount from people.leave_grants g where g.tenant_id=p_tenant_id
   and g.legal_entity_id=p_legal_entity_id and g.employee_id=v_employee
   and g.policy_id=v_policy.policy_id and g.policy_version_id=v_prior.id
   and g.expiry_date=v_effective;
  if v_source_amount<0 or v_source_amount>9007199254740991 then
   raise exception using errcode='23514',message='LEAVE_CARRY_BALANCE_INVALID';end if;
  v_amount:=least(v_source_amount,v_policy.carry_cap_seconds)::bigint;
 else
  if coalesce(p_payload->>'effective_date','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
   or coalesce(p_payload->>'seconds','') !~ '^-?[0-9]{1,16}$'
   or length(btrim(coalesce(p_payload->>'source_key',''))) not between 1 and 160 then
   raise exception using errcode='22023',message='LEAVE_ADJUSTMENT_INVALID';end if;
  v_effective:=(p_payload->>'effective_date')::date;
  v_amount:=(p_payload->>'seconds')::bigint;
  v_source:=btrim(p_payload->>'source_key');
  if v_amount=0 or abs(v_amount)>9007199254740991 then
   raise exception using errcode='22023',message='LEAVE_ADJUSTMENT_INVALID';end if;
 end if;
 if v_effective<v_policy.start_date or v_effective>=v_policy.end_date_exclusive
  or v_effective>v_today or v_effective+v_policy.expiry_days>date '9999-12-31'
  or length(btrim(coalesce(p_payload->>'reason',''))) not between 1 and 1000 then
  raise exception using errcode='22023',message='LEAVE_GRANT_DATE_INVALID';end if;
 select a.employment_type into v_type from people.employment_assignments a
 where a.tenant_id=p_tenant_id and a.legal_entity_id=p_legal_entity_id
  and a.branch_id=p_branch_id and a.employee_id=v_employee
  and daterange(a.start_date,a.end_date_exclusive,'[)') @> v_effective;
 if v_type is null or not(v_type=any(v_policy.eligible_types)) then
  raise exception using errcode='42501',message='LEAVE_NOT_ELIGIBLE';end if;
 v_before:=jsonb_build_object('account_version',v_account.version,
  'available_seconds',people.leave_available(p_tenant_id,p_legal_entity_id,
   v_employee,v_policy.policy_id,v_today));
 if v_action='adjust' then
  insert into people.leave_adjustments(id,tenant_id,legal_entity_id,branch_id,
   employee_id,policy_id,policy_version_id,source_key,effective_date,seconds,reason,recorded_by)
  values(v_id,p_tenant_id,p_legal_entity_id,p_branch_id,v_employee,v_policy.policy_id,
   v_policy.id,v_source,v_effective,v_amount,btrim(p_payload->>'reason'),v_actor);
 elsif v_action='carry' then
  insert into people.leave_carry_events(id,tenant_id,legal_entity_id,branch_id,
   employee_id,policy_id,prior_version_id,new_version_id,boundary_date,
   source_seconds,carried_seconds,reason,recorded_by)
  values(v_id,p_tenant_id,p_legal_entity_id,p_branch_id,v_employee,v_policy.policy_id,
   v_prior.id,v_policy.id,v_effective,v_source_amount::bigint,v_amount,
   btrim(p_payload->>'reason'),v_actor);
 end if;
 if v_amount>0 then
  insert into people.leave_grants(id,tenant_id,legal_entity_id,branch_id,
   employee_id,policy_id,policy_version_id,source_kind,source_key,
   effective_date,expiry_date,seconds,reason,recorded_by)
  values(case when v_action='accrue' then v_id else gen_random_uuid() end,
   p_tenant_id,p_legal_entity_id,p_branch_id,v_employee,v_policy.policy_id,v_policy.id,
   case when v_action='accrue' then 'accrual'
    when v_action='carry' then 'carry' else 'adjustment' end,
   v_source,v_effective,v_effective+v_policy.expiry_days,v_amount,
   btrim(p_payload->>'reason'),v_actor);
 elsif v_amount<0 then
  perform people.allocate_leave(p_tenant_id,p_legal_entity_id,v_employee,v_policy.policy_id,
   null,v_id,v_effective,v_today,-v_amount,v_actor);
 end if;
 update people.leave_accounts set version=version+1 where tenant_id=p_tenant_id
  and legal_entity_id=p_legal_entity_id and employee_id=v_employee and policy_id=v_policy.policy_id;
 v_after:=jsonb_build_object('id',v_id,'employee_id',v_employee,'policy_id',v_policy.policy_id,
  'policy_version_id',v_policy.id,'source_kind',v_action,'source_key',v_source,
  'effective_date',v_effective,'seconds',v_amount,'account_version',v_account.version+1,
  'available_seconds',people.leave_available(p_tenant_id,p_legal_entity_id,
   v_employee,v_policy.policy_id,v_today));
 return core.wave3_finish_command(p_tenant_id,'people.leave.grant.'||v_action,p_command_id,
  'people.leave.grant',v_id,p_idempotency_key,v_hash,v_before,v_after,
  p_legal_entity_id,p_branch_id,p_request_id=>v_request);
end $$;

create function people.leave_request_summary(p_id uuid) returns jsonb
language sql stable security definer set search_path='' as $$
 select jsonb_build_object('id',r.id,'employee_id',r.employee_id,'policy_id',r.policy_id,
  'policy_version_id',r.policy_version_id,'calendar_version_id',r.calendar_version_id,
  'version',r.version,'status',r.status,'start_utc',r.start_utc,'end_utc',r.end_utc,
  'charge_seconds',r.charge_seconds,'unpaid_seconds',r.unpaid_seconds,
  'active_claim_id',r.active_claim_id,'created_by',r.created_by,
  'submitted_by',r.submitted_by,'decided_by',r.decided_by)
 from people.leave_requests r where r.id=p_id
$$;
create function people.leave_request_private(p_id uuid) returns jsonb
language sql stable security definer set search_path='' as $$
 select people.leave_request_summary(r.id)||jsonb_build_object(
  'tenant_id',r.tenant_id,'legal_entity_id',r.legal_entity_id,'branch_id',r.branch_id,
  'start_local',r.start_local,'start_offset_seconds',r.start_offset_seconds,
  'end_local',r.end_local,'end_offset_seconds',r.end_offset_seconds,
  'reason',r.reason,'created_at',r.created_at)
 from people.leave_requests r where r.id=p_id
$$;
create function api.people_leave_requests(p_tenant_id uuid,p_legal_entity_id uuid,
 p_branch_id uuid,p_employee_id uuid,p_after uuid default null) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare v_items jsonb;begin
 perform people.require_access(p_tenant_id,p_legal_entity_id,p_branch_id,'people.leave.view');
 if p_employee_id is null or not exists(select 1 from people.employment_assignments
  where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id
  and branch_id=p_branch_id and employee_id=p_employee_id) then
  raise exception using errcode='42501',message='LEAVE_SCOPE_DENIED';end if;
 select coalesce(jsonb_agg(people.leave_request_private(q.id) order by q.id),'[]'::jsonb)
 into v_items from(select id from people.leave_requests where tenant_id=p_tenant_id
  and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id and employee_id=p_employee_id
  and (p_after is null or id>p_after) order by id limit 51) q;
 return jsonb_build_object('tenant_id',p_tenant_id,'legal_entity_id',p_legal_entity_id,
  'branch_id',p_branch_id,'employee_id',p_employee_id,'items',v_items-50,
  'next_cursor',case when jsonb_array_length(v_items)>50 then v_items->49->>'id' end);
end $$;
create function api.people_leave_detail(p_tenant_id uuid,p_legal_entity_id uuid,
 p_branch_id uuid,p_request_id uuid,p_after uuid default null) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare v_request people.leave_requests%rowtype;v_items jsonb;begin
 perform people.require_access(p_tenant_id,p_legal_entity_id,p_branch_id,'people.leave.view');
 select * into v_request from people.leave_requests where tenant_id=p_tenant_id
  and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id and id=p_request_id;
 if not found then raise exception using errcode='P0002',message='LEAVE_NOT_FOUND';end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',q.id,'action',q.action,
  'before_status',q.before_status,'after_status',q.after_status,
  'reason',q.reason,'actor_id',q.actor_id,'recorded_at',q.recorded_at) order by q.id),'[]'::jsonb)
 into v_items from(select * from people.leave_events where tenant_id=p_tenant_id
  and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id and request_id=p_request_id
  and (p_after is null or id>p_after) order by id limit 51) q;
 return jsonb_build_object('tenant_id',p_tenant_id,'legal_entity_id',p_legal_entity_id,
  'branch_id',p_branch_id,'request',people.leave_request_private(p_request_id),
  'history',v_items-50,'next_cursor',case when jsonb_array_length(v_items)>50 then v_items->49->>'id' end);
end $$;

create function api.people_leave_request_command(p_tenant_id uuid,p_legal_entity_id uuid,
 p_branch_id uuid,p_command_id uuid,p_idempotency_key uuid,p_client_timestamp timestamptz,
 p_payload jsonb,p_expected_version bigint) returns jsonb
language plpgsql security definer set search_path='' as $$
declare v_action text:=p_payload->>'action';v_actor uuid:=auth.uid();v_id uuid;v_employee uuid;
 v_request people.leave_requests%rowtype;v_policy people.leave_policy_versions%rowtype;
 v_calendar people.work_calendar_versions%rowtype;v_account people.leave_accounts%rowtype;
 v_start_local timestamp;v_end_local timestamp;v_start timestamptz;v_end timestamptz;
 v_reason text;v_today date;v_timezone text;v_charge bigint;v_unpaid bigint;
 v_claim uuid;v_hash text;v_replay jsonb;v_before jsonb:='{}'::jsonb;v_after jsonb;
 v_request_id uuid:=gen_random_uuid();begin
 if p_command_id is null or p_idempotency_key is null or p_client_timestamp is null
  or coalesce(jsonb_typeof(p_payload),'null')<>'object'
  or v_action is null or v_action not in ('create','submit','approve','reject','cancel')
  or coalesce(p_payload->>'id','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  or coalesce(p_payload->>'employee_id','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  or p_expected_version is null then
  raise exception using errcode='22023',message='LEAVE_REQUEST_INVALID';end if;
 if exists(select 1 from jsonb_object_keys(p_payload) k where k<>all(
  case when v_action='create' then array['action','id','employee_id','policy_version_id',
   'calendar_version_id','start_local','start_offset_seconds','end_local',
   'end_offset_seconds','reason']
  when v_action in ('approve','cancel') then array['action','id','employee_id','balance_version','reason']
  else array['action','id','employee_id','reason'] end)) then
  raise exception using errcode='22023',message='LEAVE_REQUEST_FIELDS_INVALID';end if;
 perform people.require_access(p_tenant_id,p_legal_entity_id,p_branch_id,
  case when v_action in ('approve','reject','cancel') then 'people.leave.approve'
   else 'people.leave.manage' end);
 if coalesce(auth.jwt()->>'aal','aal1')<>'aal2' then
  raise exception using errcode='42501',message='LEAVE_MFA_REQUIRED';end if;
 v_id:=(p_payload->>'id')::uuid;v_employee:=(p_payload->>'employee_id')::uuid;
 if not exists(select 1 from people.employment_assignments where tenant_id=p_tenant_id
  and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id
  and employee_id=v_employee) then
  raise exception using errcode='42501',message='LEAVE_SCOPE_DENIED';end if;
 v_hash:=core.wave3_request_hash('people.leave.request.'||v_action,p_command_id,
  p_tenant_id,p_legal_entity_id,p_branch_id,p_payload,p_expected_version);
 v_replay:=core.wave3_replay(p_tenant_id,'people.leave.request.'||v_action,
  p_command_id,p_idempotency_key,v_hash);
 if v_replay is not null then return v_replay;end if;
 perform id from people.employees where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id
  and id=v_employee for update;
 if not found then raise exception using errcode='P0002',message='LEAVE_EMPLOYEE_NOT_FOUND';end if;
 v_reason:=btrim(coalesce(p_payload->>'reason',''));
 if length(v_reason) not between 1 and 1000 then
  raise exception using errcode='22023',message='LEAVE_REASON_REQUIRED';end if;
 select timezone into v_timezone from core.legal_entities where tenant_id=p_tenant_id
  and id=p_legal_entity_id;
 v_today:=(now() at time zone v_timezone)::date;
 if v_action='create' then
  if p_expected_version<>0
   or coalesce(p_payload->>'policy_version_id','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
   or coalesce(p_payload->>'calendar_version_id','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
   or coalesce(p_payload->>'start_local','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}$'
   or coalesce(p_payload->>'end_local','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}$'
   or coalesce(p_payload->>'start_offset_seconds','') !~ '^-?[0-9]{1,5}$'
   or coalesce(p_payload->>'end_offset_seconds','') !~ '^-?[0-9]{1,5}$' then
   raise exception using errcode='22023',message='LEAVE_BOUNDARY_INVALID';end if;
  select * into v_policy from people.leave_policy_versions where tenant_id=p_tenant_id
   and legal_entity_id=p_legal_entity_id and id=(p_payload->>'policy_version_id')::uuid;
  select * into v_calendar from people.work_calendar_versions where tenant_id=p_tenant_id
   and legal_entity_id=p_legal_entity_id and id=(p_payload->>'calendar_version_id')::uuid;
  if v_policy.id is null or v_calendar.id is null then
   raise exception using errcode='P0002',message='LEAVE_CONFIGURATION_NOT_FOUND';end if;
  v_start_local:=(p_payload->>'start_local')::timestamp;
  v_end_local:=(p_payload->>'end_local')::timestamp;
  v_start:=people.resolve_local_instant(v_calendar.timezone,v_start_local,
   (p_payload->>'start_offset_seconds')::integer);
  v_end:=people.resolve_local_instant(v_calendar.timezone,v_end_local,
   (p_payload->>'end_offset_seconds')::integer);
  v_charge:=people.leave_slot_charge(p_tenant_id,p_legal_entity_id,p_branch_id,v_employee,
   v_policy.id,v_calendar.id,v_start_local,v_end_local,v_start,v_end);
  insert into people.leave_requests(id,tenant_id,legal_entity_id,branch_id,employee_id,
   policy_id,policy_version_id,calendar_version_id,start_local,start_offset_seconds,
   end_local,end_offset_seconds,start_utc,end_utc,charge_seconds,status,reason,created_by)
  values(v_id,p_tenant_id,p_legal_entity_id,p_branch_id,v_employee,v_policy.policy_id,
   v_policy.id,v_calendar.id,v_start_local,(p_payload->>'start_offset_seconds')::integer,
   v_end_local,(p_payload->>'end_offset_seconds')::integer,v_start,v_end,v_charge,
   'draft',v_reason,v_actor);
 else
  select * into v_request from people.leave_requests where tenant_id=p_tenant_id
   and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id
   and employee_id=v_employee and id=v_id for update;
  if not found then raise exception using errcode='P0002',message='LEAVE_NOT_FOUND';end if;
  v_before:=people.leave_request_summary(v_id);
  perform core.wave3_assert_expected_version(v_request.version,p_expected_version,v_before);
  if v_action='submit' then
   if v_request.status not in ('draft','rejected') then
    raise exception using errcode='55000',message='LEAVE_STATE_INVALID';end if;
   update people.leave_requests set version=version+1,status='submitted',submitted_by=v_actor,
    decided_by=null where id=v_id;
  elsif v_action in ('approve','reject') then
   if v_request.status<>'submitted' or v_request.submitted_by=v_actor
    or v_request.created_by=v_actor then
    raise exception using errcode='55000',message='LEAVE_INDEPENDENT_DECISION_REQUIRED';end if;
   if v_action='reject' then
    update people.leave_requests set version=version+1,status='rejected',decided_by=v_actor
     where id=v_id;
   else
    select * into v_policy from people.leave_policy_versions where id=v_request.policy_version_id;
    v_charge:=people.leave_slot_charge(p_tenant_id,p_legal_entity_id,p_branch_id,v_employee,
     v_policy.id,v_request.calendar_version_id,v_request.start_local,v_request.end_local,
     v_request.start_utc,v_request.end_utc);
    if v_charge<>v_request.charge_seconds then
     raise exception using errcode='55000',message='LEAVE_INPUT_CHANGED';end if;
    insert into people.leave_accounts(tenant_id,legal_entity_id,employee_id,policy_id)
     values(p_tenant_id,p_legal_entity_id,v_employee,v_request.policy_id) on conflict do nothing;
    select * into v_account from people.leave_accounts where tenant_id=p_tenant_id
     and legal_entity_id=p_legal_entity_id and employee_id=v_employee
     and policy_id=v_request.policy_id for update;
    if coalesce(p_payload->>'balance_version','') !~ '^[0-9]{1,16}$' then
     raise exception using errcode='22023',message='LEAVE_BALANCE_VERSION_REQUIRED';end if;
    perform core.wave3_assert_expected_version(v_account.version,
     (p_payload->>'balance_version')::bigint,jsonb_build_object('account_version',v_account.version));
    perform people.consume_organization(p_tenant_id,p_legal_entity_id,p_branch_id,
     v_employee,'leave',v_id,v_request.start_local::date,
     (v_request.end_local-interval '1 microsecond')::date+1);
    begin
     v_claim:=people.make_work_claim(p_tenant_id,p_legal_entity_id,p_branch_id,v_employee,
      'leave',v_id,v_request.start_utc,v_request.end_utc,'[]'::jsonb,
      v_request.calendar_version_id,v_actor);
    exception when exclusion_violation then
     raise exception using errcode='23514',message='WORK_INTERVAL_CONFLICT';
    end;
    v_unpaid:=people.allocate_leave(p_tenant_id,p_legal_entity_id,v_employee,
     v_request.policy_id,v_id,null,v_request.start_local::date,v_today,
     v_request.charge_seconds,v_actor,v_policy.allow_unpaid);
    update people.leave_accounts set version=version+1 where tenant_id=p_tenant_id
     and legal_entity_id=p_legal_entity_id and employee_id=v_employee
     and policy_id=v_request.policy_id;
    update people.leave_requests set version=version+1,status='approved',decided_by=v_actor,
     active_claim_id=v_claim,unpaid_seconds=v_unpaid where id=v_id;
   end if;
  else
   if v_request.status<>'approved' or v_request.active_claim_id is null
    or v_request.submitted_by=v_actor or v_request.created_by=v_actor then
    raise exception using errcode='55000',message='LEAVE_CANCELLATION_INVALID';end if;
   if coalesce(p_payload->>'balance_version','') !~ '^[0-9]{1,16}$' then
    raise exception using errcode='22023',message='LEAVE_BALANCE_VERSION_REQUIRED';end if;
   select * into v_account from people.leave_accounts where tenant_id=p_tenant_id
    and legal_entity_id=p_legal_entity_id and employee_id=v_employee
    and policy_id=v_request.policy_id for update;
   perform core.wave3_assert_expected_version(v_account.version,
    (p_payload->>'balance_version')::bigint,jsonb_build_object('account_version',v_account.version));
   perform people.revoke_work_claim(p_tenant_id,p_legal_entity_id,v_employee,v_request.active_claim_id);
   insert into people.leave_effects(tenant_id,legal_entity_id,employee_id,policy_id,
    grant_id,request_id,effective_date,seconds,reversal_of,recorded_by)
   select x.tenant_id,x.legal_entity_id,x.employee_id,x.policy_id,x.grant_id,x.request_id,
    v_today,-x.seconds,x.id,v_actor from people.leave_effects x
    where x.tenant_id=p_tenant_id and x.legal_entity_id=p_legal_entity_id
     and x.employee_id=v_employee and x.request_id=v_id and x.seconds<0;
   update people.leave_accounts set version=version+1 where tenant_id=p_tenant_id
    and legal_entity_id=p_legal_entity_id and employee_id=v_employee
    and policy_id=v_request.policy_id;
   update people.leave_requests set version=version+1,status='cancelled',decided_by=v_actor,
    active_claim_id=null where id=v_id;
  end if;
 end if;
 v_after:=people.leave_request_summary(v_id);
 insert into people.leave_events(tenant_id,legal_entity_id,branch_id,employee_id,
  request_id,action,before_status,after_status,reason,actor_id,command_id)
 values(p_tenant_id,p_legal_entity_id,p_branch_id,v_employee,v_id,v_action,
  v_before->>'status',v_after->>'status',v_reason,v_actor,p_command_id);
 return core.wave3_finish_command(p_tenant_id,'people.leave.request.'||v_action,p_command_id,
  'people.leave.request',v_id,p_idempotency_key,v_hash,v_before,v_after,
  p_legal_entity_id,p_branch_id,p_source_context=>jsonb_build_object(
   'employee_id',v_employee,'action',v_action),p_request_id=>v_request_id);
end $$;

create function api.people_workforce_authorize(p_tenant_id uuid,p_legal_entity_id uuid,
 p_branch_id uuid,p_employee_id uuid,p_capability text) returns jsonb
language plpgsql stable security definer set search_path='' as $$begin
 if p_capability is null or p_capability not in (
  'people.attendance.view','people.attendance.manage','people.attendance.import',
  'people.attendance.approve','people.work_claims.view','people.leave.view',
  'people.leave.manage','people.leave.approve','people.leave.policy.manage','people.leave.adjust') then
  raise exception using errcode='22023',message='WORKFORCE_CAPABILITY_INVALID';end if;
 perform people.require_access(p_tenant_id,p_legal_entity_id,p_branch_id,p_capability);
 if p_employee_id is null and p_capability not in ('people.leave.view','people.leave.policy.manage')
  or p_employee_id is not null and not exists(select 1 from people.employment_assignments
   where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id
    and branch_id=p_branch_id and employee_id=p_employee_id) then
  raise exception using errcode='42501',message='WORKFORCE_SCOPE_DENIED';end if;
 return jsonb_build_object('authorized',true,'actor_id',auth.uid(),
  'employee_id',p_employee_id,'capability',p_capability);
end $$;

-- An expired encrypted draft keeps only its command identity locally. This
-- actor-scoped lookup permits reconciliation without retaining private reasons.
create function api.people_leave_own_receipt(p_tenant_id uuid,p_legal_entity_id uuid,
 p_branch_id uuid,p_command_id uuid) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare v_receipt core.command_receipts%rowtype;v_action text;v_employee uuid;begin
 perform people.require_access(p_tenant_id,p_legal_entity_id,p_branch_id,'people.leave.view');
 if p_command_id is null then raise exception using errcode='22023',message='LEAVE_COMMAND_REQUIRED';end if;
 select * into v_receipt from core.command_receipts where actor_id=auth.uid()
  and command_id=p_command_id and tenant_id=p_tenant_id
  and legal_entity_id=p_legal_entity_id and branch_id=p_branch_id
  and command_name like 'people.leave.request.%';
 if not found then return null;end if;
 v_action:=substr(v_receipt.command_name,length('people.leave.request.')+1);
 perform people.require_access(p_tenant_id,p_legal_entity_id,p_branch_id,
  case when v_action in ('approve','reject','cancel') then 'people.leave.approve'
   else 'people.leave.manage' end);
 v_employee:=(v_receipt.response->'entity'->>'employee_id')::uuid;
 if v_employee is null or not exists(select 1 from people.employment_assignments
  where tenant_id=p_tenant_id and legal_entity_id=p_legal_entity_id
   and branch_id=p_branch_id and employee_id=v_employee) then
  raise exception using errcode='42501',message='LEAVE_SCOPE_DENIED';end if;
 return v_receipt.response;
end $$;

revoke all on function people.leave_history_guard(),people.leave_effect_insert_guard(),
 people.leave_slot_charge(uuid,uuid,uuid,uuid,uuid,uuid,timestamp,timestamp,timestamptz,timestamptz),
 people.leave_available(uuid,uuid,uuid,uuid,date,timestamptz),
 people.allocate_leave(uuid,uuid,uuid,uuid,uuid,uuid,date,date,bigint,uuid,boolean),
 people.leave_policy_payload(uuid),
 people.leave_request_summary(uuid),people.leave_request_private(uuid),
 api.people_leave_policies(uuid,uuid,uuid,uuid),
 api.people_leave_policy_versions(uuid,uuid,uuid,uuid,uuid),
 api.people_leave_policy_for_version(uuid,uuid,uuid,uuid),
 api.people_leave_balance(uuid,uuid,uuid,uuid,uuid,date,timestamptz,uuid),
 api.people_leave_grant_command(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint),
 api.people_leave_requests(uuid,uuid,uuid,uuid,uuid),
 api.people_leave_detail(uuid,uuid,uuid,uuid,uuid),
 api.people_leave_request_command(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint),
 api.people_leave_own_receipt(uuid,uuid,uuid,uuid),
 api.people_workforce_authorize(uuid,uuid,uuid,uuid,text),
 api.people_leave_policy_command(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint)
 from public,anon,authenticated;
grant execute on function api.people_leave_policies(uuid,uuid,uuid,uuid),
 api.people_leave_policy_versions(uuid,uuid,uuid,uuid,uuid),
 api.people_leave_policy_for_version(uuid,uuid,uuid,uuid),
 api.people_leave_balance(uuid,uuid,uuid,uuid,uuid,date,timestamptz,uuid),
 api.people_leave_grant_command(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint),
 api.people_leave_requests(uuid,uuid,uuid,uuid,uuid),
 api.people_leave_detail(uuid,uuid,uuid,uuid,uuid),
 api.people_leave_request_command(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint),
 api.people_leave_own_receipt(uuid,uuid,uuid,uuid),
 api.people_workforce_authorize(uuid,uuid,uuid,uuid,text),
 api.people_leave_policy_command(uuid,uuid,uuid,uuid,uuid,timestamptz,jsonb,bigint)
 to authenticated;
notify pgrst,'reload schema';

-- W4-04. Unapplied synthetic development candidate, isolated private payroll.
-- Dependencies: installed employee/calendar/private-HR; candidate resolver,
-- organization, attendance and leave. No plan or role grants.
create schema people_payroll;
revoke all on schema people_payroll from public,anon,authenticated;
insert into core.permissions(code,module,description,privileged) values
 ('people.payroll.view','people','Read scoped synthetic payroll configuration/runs',false),
 ('people.payroll.configure','people','Publish synthetic payroll configuration with MFA',true),
 ('people.payroll.prepare','people','Prepare synthetic frozen payroll with MFA',true),
 ('people.payroll.approve','people','Independently approve exact payroll revision with MFA',true),
 ('people.payroll.post','people','Post synthetic payroll obligations/journal with MFA',true),
 ('people.payroll.reverse','people','Reverse original synthetic payroll effects with MFA',true),
 ('people.payroll.payslip.view','people','Read private scoped synthetic payslips',true),
 ('people.payroll.payslip.self','people','Read own synthetic payslips through an accepted employee link',true),
 ('people.payroll.export','people','Export exact private synthetic payslip revision',true),
 ('people.payroll.settle','people','Record synthetic payroll settlement evidence with MFA',true)
on conflict(code) do nothing;

create table people_payroll.components(
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,
 code text not null check(code ~ '^[A-Z0-9][A-Z0-9_-]{0,31}$'),
 name text not null check(length(btrim(name)) between 1 and 160),
 classification text not null check(classification in('earning','deduction','employer_cost')),
 version bigint not null default 1 check(version between 1 and 9007199254740991),
 unique(tenant_id,legal_entity_id,id),unique(tenant_id,legal_entity_id,code),
 foreign key(tenant_id,legal_entity_id) references core.legal_entities(tenant_id,id)
);
create table people_payroll.rule_versions(
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,component_id uuid not null,
 version bigint not null check(version between 1 and 9007199254740991),
 start_date date not null,end_date_exclusive date not null,
 currency_code text not null references core.currencies(code),
 basis text not null check(basis in('fixed','hourly','earnings_ratio')),
 proration text not null check(proration in('none','eligible_days','paid_seconds')),
 rounding text not null check(rounding in('half_away','half_even','truncate','floor')),
 precision integer not null check(precision between 0 and 6),
 amount numeric(20,6) not null check(amount>=0),
 ratio_numerator bigint not null check(ratio_numerator between 0 and 9007199254740991),
 ratio_denominator bigint not null check(ratio_denominator between 1 and 9007199254740991),
 cap numeric(20,6) check(cap>=0),expense_account_id uuid,liability_account_id uuid,
 reason text not null check(length(btrim(reason)) between 1 and 1000),
 published_by uuid not null references auth.users(id),published_at timestamptz not null default clock_timestamp(),
 check(start_date>='0001-01-01'::date and end_date_exclusive<='9999-12-31'::date
  and end_date_exclusive>start_date and end_date_exclusive-start_date<=1830),
 check((basis='fixed' or proration='none') and
  ((basis='earnings_ratio' and amount=0) or (basis<>'earnings_ratio' and ratio_numerator=1 and ratio_denominator=1))),
 check(cap is null or cap=round(cap,precision)),
 unique(tenant_id,legal_entity_id,id),unique(tenant_id,legal_entity_id,component_id,id),
 unique(tenant_id,legal_entity_id,component_id,version),
 foreign key(tenant_id,legal_entity_id,component_id) references people_payroll.components(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,legal_entity_id,expense_account_id) references finance.accounts(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,legal_entity_id,liability_account_id) references finance.accounts(tenant_id,legal_entity_id,id),
 exclude using gist(component_id extensions.gist_uuid_ops with =,daterange(start_date,end_date_exclusive,'[)') with &&)
);
create index payroll_rules_scope_idx on people_payroll.rule_versions(tenant_id,legal_entity_id,component_id,id);
create index payroll_rules_expense_idx on people_payroll.rule_versions(tenant_id,legal_entity_id,expense_account_id);
create index payroll_rules_liability_idx on people_payroll.rule_versions(tenant_id,legal_entity_id,liability_account_id);
create index payroll_rules_actor_idx on people_payroll.rule_versions(published_by);
create table people_payroll.component_assignments(
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,branch_id uuid not null,
 employee_id uuid not null,component_id uuid not null,start_date date not null,end_date_exclusive date not null,
 reason text not null check(length(btrim(reason)) between 1 and 1000),
 recorded_by uuid not null references auth.users(id),recorded_at timestamptz not null default clock_timestamp(),
 check(end_date_exclusive>start_date and end_date_exclusive-start_date<=1830),
 unique(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,legal_entity_id,employee_id) references people.employees(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,legal_entity_id,branch_id) references core.branches(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,legal_entity_id,component_id) references people_payroll.components(tenant_id,legal_entity_id,id),
 exclude using gist(employee_id extensions.gist_uuid_ops with =,component_id extensions.gist_uuid_ops with =,
  daterange(start_date,end_date_exclusive,'[)') with &&)
);
create index payroll_assignments_scope_idx on people_payroll.component_assignments(tenant_id,legal_entity_id,branch_id,employee_id,id);
create index payroll_assignments_component_idx on people_payroll.component_assignments(tenant_id,legal_entity_id,component_id);
create index payroll_assignments_actor_idx on people_payroll.component_assignments(recorded_by);
create table people_payroll.settings_versions(
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,
 version bigint not null check(version between 1 and 9007199254740991),
 net_account_id uuid not null,reason text not null check(length(btrim(reason)) between 1 and 1000),
 published_by uuid not null references auth.users(id),published_at timestamptz not null default clock_timestamp(),
 unique(tenant_id,legal_entity_id,id),unique(tenant_id,legal_entity_id,version),
 foreign key(tenant_id,legal_entity_id,net_account_id) references finance.accounts(tenant_id,legal_entity_id,id)
);
create index payroll_settings_account_idx on people_payroll.settings_versions(tenant_id,legal_entity_id,net_account_id);
create index payroll_settings_actor_idx on people_payroll.settings_versions(published_by);
create table people_payroll.runs(
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,branch_id uuid not null,
 name text not null check(length(btrim(name)) between 1 and 160),
 start_date date not null,end_date_exclusive date not null,posting_date date not null,
 currency_code text not null references core.currencies(code),
 version bigint not null default 1 check(version between 1 and 9007199254740991),
 status text not null default 'draft' check(status in('draft','prepared','submitted','approved','posted','cancelled','reversed')),
 current_revision_id uuid,approved_revision_id uuid,approved_digest text check(approved_digest ~ '^[a-f0-9]{64}$'),
 prepared_by uuid references auth.users(id),submitted_by uuid references auth.users(id),approved_by uuid references auth.users(id),
 posted_journal_id uuid,reversal_journal_id uuid,
 created_by uuid not null references auth.users(id),created_at timestamptz not null default clock_timestamp(),
 check(start_date>='0001-01-01'::date and end_date_exclusive<='9999-12-31'::date
  and end_date_exclusive>start_date and end_date_exclusive-start_date<=366),
 unique(tenant_id,legal_entity_id,id),unique(tenant_id,legal_entity_id,branch_id,id),
 foreign key(tenant_id,legal_entity_id,branch_id) references core.branches(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,posted_journal_id) references finance.journal_entries(tenant_id,id),
 foreign key(tenant_id,reversal_journal_id) references finance.journal_entries(tenant_id,id)
);
create index payroll_runs_scope_idx on people_payroll.runs(tenant_id,legal_entity_id,branch_id,id);
create index payroll_runs_creator_idx on people_payroll.runs(created_by);
create index payroll_runs_preparer_idx on people_payroll.runs(prepared_by);
create index payroll_runs_submitter_idx on people_payroll.runs(submitted_by);
create index payroll_runs_approver_idx on people_payroll.runs(approved_by);
create index payroll_runs_journal_idx on people_payroll.runs(tenant_id,posted_journal_id);
create index payroll_runs_reverse_idx on people_payroll.runs(tenant_id,reversal_journal_id);
create table people_payroll.run_employees(
 tenant_id uuid not null,legal_entity_id uuid not null,branch_id uuid not null,run_id uuid not null,employee_id uuid not null,
 primary key(tenant_id,legal_entity_id,run_id,employee_id),
 foreign key(tenant_id,legal_entity_id,branch_id,run_id) references people_payroll.runs(tenant_id,legal_entity_id,branch_id,id),
 foreign key(tenant_id,legal_entity_id,employee_id) references people.employees(tenant_id,legal_entity_id,id)
);
create index payroll_run_employee_idx on people_payroll.run_employees(tenant_id,legal_entity_id,employee_id);
create table people_payroll.run_revisions(
 id uuid primary key,tenant_id uuid not null,legal_entity_id uuid not null,run_id uuid not null,
 version bigint not null,settings_version_id uuid not null,digest text not null check(digest ~ '^[a-f0-9]{64}$'),
 employee_count integer not null check(employee_count between 1 and 200),
 prepared_by uuid not null references auth.users(id),prepared_at timestamptz not null default clock_timestamp(),
 unique(tenant_id,legal_entity_id,id),unique(tenant_id,legal_entity_id,run_id,id),
 foreign key(tenant_id,legal_entity_id,run_id) references people_payroll.runs(tenant_id,legal_entity_id,id),
 foreign key(tenant_id,legal_entity_id,settings_version_id) references people_payroll.settings_versions(tenant_id,legal_entity_id,id)
);
