insert into w5_runtime_tap select is((select x->>'amount' from dates_basis,jsonb_array_elements(data->'obligations') x where name='complete' and x->>'provider'='payroll' and x->>'inflow'='true'),'2.000002','cash basis includes signed recovery magnitude');
insert into w5_runtime_tap select is((select x->>'amount' from dates_basis,jsonb_array_elements(data->'obligations') x where name='complete' and x->>'provider'='project_reimbursements'),'4.000000','cash basis includes original project reimbursement');
insert into w5_runtime_tap select ok((select data::text not like '%PRIVATE RECEIPT%' and data::text not like '%employee_id%' from dates_basis where name='complete'),'cash manifest excludes employee and receipt bodies');
